internal val PACK_SV_QUIZ: Map<String, String> = mapOf(
    "q.l1#0.p" to "Vilket av följande är en objektiv fara?",
    "q.l1#0.o0" to "Stenfall och isfall",
    "q.l1#0.o1" to "Ett bedömningsfel",
    "q.l1#0.o2" to "Att energin tar slut",
    "q.l1#0.o3" to "Ett tävlingsinriktat tänkande",
    "q.l1#0.e" to "Objektiva faror är miljöfaktorer som inte ändras med din skicklighet eller inställning: stenfall, isfall, laviner, väder, sprickor. De tre andra är subjektiva faror som träning och självdisciplin kan kontrollera.",
    "q.l1#1.p" to "Hur ändras lufttemperaturen och syrgasets partialtryck när höjden ökar?",
    "q.l1#1.o0" to "Temperaturen stiger och partialtrycket faller",
    "q.l1#1.o1" to "Temperaturen faller cirka 6,5 °C per 1 000 m, och partialtrycket faller med den",
    "q.l1#1.o2" to "Ingendera ändras",
    "q.l1#1.o3" to "Temperaturen faller och partialtrycket stiger",
    "q.l1#1.e" to "För varje 1 000 m stigning kyls luften cirka 6,5 °C, medan lufttrycket och syrgasets partialtryck faller i takt. Därför kommer höjdsjuka och nedkylning ofta samtidigt.",
    "q.l1#2.p" to "Vilket påstående om träningens roll är korrekt?",
    "q.l1#2.o0" to "Bra träning tar bort alla objektiva faror",
    "q.l1#2.o1" to "Träning minskar subjektiva faror men kan inte ta bort objektiva",
    "q.l1#2.o2" to "Objektiva faror är bara tur eller otur",
    "q.l1#2.o3" to "Är man bara i form finns ingen fara",
    "q.l1#2.e" to "Teknisk träning förbättrar hur du bedömer och reagerar, men stenfall, laviner och väder försvinner inte för att du är erfaren. Rätt inställning till objektiva faror är att undvika dem och behålla en väg ut.",
    "q.l1#3.p" to "Varför betonar alpinister marginal i stället för att laga saker på plats?",
    "q.l1#3.o0" to "För att marginal höjer chansen att nå toppen",
    "q.l1#3.o1" to "För att marginal verkar tidigt i olyckskedjan, medan lagning sker vid sista länken",
    "q.l1#3.o2" to "För att marginal sparar pengar",
    "q.l1#3.o3" to "För att reglerna kräver reserv",
    "q.l1#3.e" to "Marginal har många former: tid, energi, proviant, ett väderfönster. Gemensamt är att du skapar utrymmet medan du fortfarande kan välja. Reparation börjar alltid efter att något redan gått fel, när få alternativ återstår.",
    "q.l1#4.p" to "Vad är det bästa måttet på ett klätterlags nivå?",
    "q.l1#4.o0" to "Den högsta höjd någon i laget bestigit",
    "q.l1#4.o1" to "Hur många turer laget gör per år",
    "q.l1#4.o2" to "Om laget kan retirera säkert när det behövs och hålla risken acceptabel",
    "q.l1#4.o3" to "Det sammanlagda värdet på utrustningen",
    "q.l1#4.e" to "Topprekord bevisar bara att något en gång fungerade; förmågan att retirera bevisar kontroll. I högfjällsklättring kommer nästa chans alltid, en allvarlig olycka gör det inte. Det som verkligen skiljer lag är hur väl de beslutar under ogynnsamma förhållanden.",
    "q.l1#5.p" to "Kinas inhemska bergsbestämmelser begränsar klättring till «självständiga toppar». Hur definieras en självständig topp på en topografisk karta?",
    "q.l1#5.o0" to "Varje massiv högre än 5 000 m",
    "q.l1#5.o1" to "En massiv som omsluts av en sluten höjdkurva",
    "q.l1#5.o2" to "En massiv med synlig glaciär",
    "q.l1#5.o3" to "En massiv som ingen bestigit",
    "q.l1#5.e" to "På en topografisk karta visas en självständig topp som en sluten höjdkurva, vilket betyder att massivet faller undan åt alla håll. Definitionen skiljer «bergsbestigning» från «att gå upp på en hög punkt» och ligger till grund för hur verksamheten administreras och räknas.",
    "q.l1#6.p" to "Vad är det vanligaste mönstret i olycksutredningar?",
    "q.l1#6.o0" to "Nästan varje olycka kommer från ett enda stort misstag",
    "q.l1#6.o1" to "Allvarliga olyckor är oftast flera små misstag staplade på varandra",
    "q.l1#6.o2" to "Olyckor har ingen koppling till erfarenhet",
    "q.l1#6.o3" to "Utrustningsfel är huvudorsaken",
    "q.l1#6.e" to "En typisk olycka är en kedja: ett överoptimistiskt ruttval, sedan försening mot planen, sedan förenklad säkring för att spara tid, sedan trötthet som försämrar rörelserna. Bryt en enda länk och olyckan sker inte — och det är precis därför marginal slår reparation.",
    "q.l1#7.p" to "[Flerval] Vilka av dessa är objektiva faror i bergen?",
    "q.l1#7.o0" to "Stenfall och isfall",
    "q.l1#7.o1" to "Lavin",
    "q.l1#7.o2" to "Ett plötsligt väderomslag",
    "q.l1#7.o3" to "Sprickor",
    "q.l1#7.o4" to "Ett tävlingsinriktat tänkande",
    "q.l1#7.e" to "De fyra första ändras inte med din skicklighet eller inställning, de är miljöns egenskaper. Mot objektiva faror kan du bara undvika, välja timing och behålla en väg ut. Subjektiva faror — felbedömning, dålig förberedelse, jämförelse med andra — är den del träningen faktiskt kan minska.",
    "q.l1#8.p" to "Före en högfjällstur, vilka tre saker bör du bekräfta först?",
    "q.l1#8.o0" to "Form, utrustning, reseplan och försäkring",
    "q.l1#8.o1" to "Kamraternas rykte, bergets kändisskap, utrustningens märken",
    "q.l1#8.o2" to "Foton, video och din plan för sociala medier",
    "q.l1#8.o3" to "Prognosen, flygen och hotellet",
    "q.l1#8.e" to "Formen avgör om du kan fullföra, utrustningen avgör om du överlever dåliga förhållanden, och reseplan plus försäkring avgör om hjälp finns när något går fel. Alla tre ligger helt i din kontroll före avfärd — och just därför finns ingen ursäkt när de brister.",
    "q.l1#9.p" to "Varför kan erfarna klättrare ändå råka illa ut?",
    "q.l1#9.o0" to "För att erfarenhet gradvis höjer vad du accepterar som normal risk",
    "q.l1#9.o1" to "För att erfarna försöker sig på svårare rutter",
    "q.l1#9.o2" to "För att erfarenhet inte har med säkerhet att göra",
    "q.l1#9.o3" to "För att erfarna blir trötta lättare",
    "q.l1#9.e" to "Det kallas risknormalisering: efter att många gånger ha passerat samma förhållanden utan problem omklassificerar du dem omedvetet som «säkra» och vidgar standarden lite i taget. Ju mer erfaren du är, desto mer behöver du uttalade regler — en vändtid till exempel — som håller din bedömning i schack.",
    "q.l2#0.p" to "Vad används en isyxa av typ T (teknisk) huvudsakligen till?",
    "q.l2#0.o0" to "Att promenera uppför flacka snösluttningar",
    "q.l2#0.o1" to "Branta isväggar och teknisk klättring",
    "q.l2#0.o2" to "Bara fotografering",
    "q.l2#0.o3" to "Bara snöläger",
    "q.l2#0.e" to "Skaftet på en typ T kan planteras i isen och ta drag, vilket passar brant is. Skaftet på typ B är svagare: det är dimensionerat för gång och självstopp och får inte användas som teknisk förankring.",
    "q.l2#1.p" to "Vilken stegjärnsklass hör ihop med en helt styv B3-känga?",
    "q.l2#1.o0" to "C1, hel rem",
    "q.l2#1.o1" to "C2, rem fram och bygel bak",
    "q.l2#1.o2" to "C3, hel bygel",
    "q.l2#1.o3" to "Vilken klass som helst går bra",
    "q.l2#1.e" to "En B3-känga har skåror fram och bak, och ett C3-stegjärn med hel bygel är den säkraste kombinationen. B1 med C1, B2 med C2 och B3 med C3 är grundregeln för matchning.",
    "q.l2#2.p" to "Vad händer om du sätter C3-stegjärn med hel bygel på en mjuk vandringskänga?",
    "q.l2#2.o0" to "Inga problem alls, och det går snabbare att ta på",
    "q.l2#2.o1" to "Kängan deformeras under last, byglarna tappar grepp och stegjärnet kan lossna — en farlig kombination",
    "q.l2#2.o2" to "Du går snabbare",
    "q.l2#2.o3" to "Det ser bara illa ut",
    "q.l2#2.e" to "Stegjärn med hel bygel förlitar sig på att kängan är styv och behåller formen. På en mjuk känga böjs den, byglarna tappar fäste och stegjärnet kan lossna i en brant sluttning. Det är en tydligt farlig kombination.",
    "q.l2#3.p" to "Isyxans längd väljs oftast efter kroppslängd. Vad rekommenderas för en klättrare på cirka 173–180 cm?",
    "q.l2#3.o0" to "50 cm",
    "q.l2#3.o1" to "55 cm",
    "q.l2#3.o2" to "60 cm",
    "q.l2#3.o3" to "70 cm",
    "q.l2#3.e" to "En vanlig referens: under cirka 157 cm ta 50 cm; 157–170 cm ta 55 cm; 173–180 cm ta 60 cm; över 183 cm ta 65–70 cm. Bara rätt längd gör att du effektivt kan driva udden i snön vid självstopp.",
    "q.l2#4.p" to "Vad är det mest grundläggande och viktigaste kravet när du väljer stegjärn?",
    "q.l2#4.o0" to "Så lätta som möjligt",
    "q.l2#4.o1" to "De måste passa kängan, helst tolvpunkts stål med antiklossplattor",
    "q.l2#4.o2" to "Färgen bör matcha övrig utrustning",
    "q.l2#4.o3" to "Fler piggar är alltid bättre — 20 eller fler",
    "q.l2#4.e" to "Ett stegjärn är bara så bra som sin koppling till kängan. Fler piggar är inte automatiskt bättre; passform och antiklossplattor (som hindrar snö att klumpa under foten) är det som avgör. Dålig passform är det klassiska sättet att tappa ett stegjärn i en brant sluttning.",
    "q.l2#5.p" to "[Scenario] För en teknisk toppdag på hög höjd med stegjärn, isyxa, extra värmelager, mat, vatten och nödutrustning, vilken nettovolym på ryggsäcken rekommenderas?",
    "q.l2#5.o0" to "15–25 liter",
    "q.l2#5.o1" to "35–50 liter",
    "q.l2#5.o2" to "60–75 liter",
    "q.l2#5.o3" to "90 liter eller mer",
    "q.l2#5.e" to "För «egen teknisk utrustning + extra värmelager + nödutrustning» är 35–50 liter det vanliga intervallet, helst med egen ficka för stegjärn.\nMen volymen är inte fast: på en väl trafikerad snösluttning med grupputrustning buren av personal och stabilt väder kan en toppryggsäck på 15–25 liter vara helt tillräcklig; måste du bära tält eller rep själv behövs mer.\nKriteriet är alltid vad du faktiskt måste bära, inte en universell siffra.",
    "q.l2#6.p" to "Vad är huvudsyftet med en isyxas fångrem?",
    "q.l2#6.o0" to "Dekoration och lagidentifiering",
    "q.l2#6.o1" to "Att du inte tappar yxan, så att du fortfarande kan bromsa efter ett halk",
    "q.l2#6.o2" to "Att lägga till vikt så yxan trycker hårdare",
    "q.l2#6.o3" to "Att hänga yxan på ryggsäcken",
    "q.l2#6.e" to "Fångremmen är avgörande i själva halkögonblicket: när yxan lämnar handen har du tappat det enda som kan bromsa. Remmen håller den kvar hos dig genom våldsamma rörelser — därför insisterar så många manualer på att den ska sitta på.",
    "q.l2#7.p" to "[Flerval] Vilka faktorer spelar roll när du väljer stegjärn?",
    "q.l2#7.o0" to "Hur de fästs på kängan (rem / halvbygel / hel bygel)",
    "q.l2#7.o1" to "Om antalet och formen på piggarna passar terrängen",
    "q.l2#7.o2" to "Om de har antiklossplattor",
    "q.l2#7.o3" to "Pålitligheten hos bindningar och remmar",
    "q.l2#7.o4" to "Om färgen matchar ryggsäcken",
    "q.l2#7.e" to "Alla fyra spelar roll. Fästet avgör om de alls går på, piggformen avgör om de passar terrängen (framåtriktade piggar för brant is, platta för flack snö), plattorna avgör om snö klumpar under fötterna, och bindningarna avgör om de sitter kvar.",
    "q.l2#8.p" to "Varför kontrollera stegjärnens remmar och bindningar före varje avfärd?",
    "q.l2#8.o0" to "För att hålla utrustningen ordnad",
    "q.l2#8.o1" to "För att ett stegjärn som lossnar i en brant sluttning är ett direkt hot mot livet",
    "q.l2#8.o2" to "För att remmar åldras och byter färg",
    "q.l2#8.o3" to "För att lagdisciplinen kräver det",
    "q.l2#8.e" to "Stegjärn tenderar att svikta i värsta möjliga ögonblick: i en brant vägg, under en travers, på första belastade steget. Tappar du greppet under ena foten flyttas tyngdpunkten omedelbart. Kontrollen kostar nästan inget; konsekvensen är helt oproportionerlig.",
    "q.l2#9.p" to "Vilket påstående om isyxans uddform är korrekt?",
    "q.l2#9.o0" to "Alla isyxor har rak udd",
    "q.l2#9.o1" to "En krökt udd går lättare in i isen och hoppar mindre ofta ut, därför är den vanlig på tekniska isverktyg",
    "q.l2#9.o2" to "En krökt udd är bara för att gå på snö",
    "q.l2#9.o3" to "Uddens form har inget med användningen att göra",
    "q.l2#9.e" to "En lång alpin isyxa har oftast en udd som kröker nedåt, så att den biter vid slag eller bromsning och inte lätt dras ut. Isklätterverktyg har vassare och brantare uddar för snabb placering och enkel borttagning i brant is. Användningen bestämmer formen.",
    "q.l3#0.p" to "Vilken är den främsta fördelen med dubbelkängor jämfört med enkelkängor?",
    "q.l3#0.o0" to "Lättare",
    "q.l3#0.o1" to "Varmare, och innerkängan kan tas ut och torkas",
    "q.l3#0.o2" to "Billigare",
    "q.l3#0.o3" to "Lättare att ta på och av",
    "q.l3#0.e" to "Innerkängan tas ut och kan torkas mot kroppen eller i sovsäcken över natten utan att frysa — avgörande på flerdagsturer på hög höjd. Priset är vikt och kostnad.",
    "q.l3#1.p" to "Vilken är den viktigaste specifikationen för snöglasögon?",
    "q.l3#1.o0" to "Hur mörkt glaset är",
    "q.l3#1.o1" to "UV400 ultraviolett skydd",
    "q.l3#1.o2" to "Bågens märke",
    "q.l3#1.o3" to "Om glaset är speglat",
    "q.l3#1.e" to "Snö reflekterar mycket ultraviolett ljus. UV400 betyder nästan fullständigt UV-skydd och är nyckeln till att förebygga snöblindhet; glasets ton påverkar bara synkomforten.",
    "q.l3#2.p" to "Vad är viktigt när du väljer storlek på alpin känga?",
    "q.l3#2.o0" to "Tajtare är bättre, så foten inte glider",
    "q.l3#2.o1" to "Tårna får inte ta i framkanten, lite utrymme så att nedstigningen inte skadar dem",
    "q.l3#2.o2" to "Större är bättre, så det får plats tjockare sockor",
    "q.l3#2.o3" to "Exakt samma som din vanliga skostorlek",
    "q.l3#2.e" to "På nedstigningen glider foten framåt. Tar tårna i framkanten kan en lång nedstigning ge blåmärken eller till och med tappa en nagel. Lämna lite utrymme och lås hälen med snörningen.",
    "q.l3#3.p" to "Vilken är den viktigaste konstruktionsdetaljen på en 8 000 m toppkänga?",
    "q.l3#3.o0" to "Så lätt som möjligt",
    "q.l3#3.o1" to "Ett löstagbart isolerat innerfoder med vattentätt, vindtätt och nötningsbeständigt övermaterial",
    "q.l3#3.o2" to "Den måste vara enskiktad",
    "q.l3#3.o3" to "Ju mjukare sula, desto skönare",
    "q.l3#3.e" to "Ett löstagbart foder kan tas ut på natten för att torka eller hållas varmt mot kroppen, så det aldrig fryser — nyckeln till att behålla fungerande fötter på flerdagsturer på hög höjd. Övermaterialet är oftast ett trelagers laminat för vattentäthet, vindtäthet och hållbarhet.",
    "q.l3#4.p" to "Varför ska ett baslager aldrig vara bomull?",
    "q.l3#4.o0" to "Bomull är för dyrt",
    "q.l3#4.o1" to "Bomull håller kvar svett och torkar långsamt, så fuktigt tyg mot huden påskyndar värmeförlusten",
    "q.l3#4.o2" to "Bomull ger allergi",
    "q.l3#4.o3" to "Bomull andas inte, så det känns kallare",
    "q.l3#4.e" to "Baslagrets uppgift är att flytta svett bort från huden. Bomull suger upp vatten och släpper det knappt, så fuktigt kallt tyg fortsätter dra värme. Välj polyester eller merinoull, som transporterar fukt snabbt.",
    "q.l3#5.p" to "Vilket material rekommenderas för en 6 000 m känga?",
    "q.l3#5.o0" to "Vanligt läder",
    "q.l3#5.o1" to "Ett vattentätt, andande material som GORE-TEX",
    "q.l3#5.o2" to "Ren bomullsväv",
    "q.l3#5.o3" to "Ett hårt plasthölje",
    "q.l3#5.e" to "En 6 000 m känga värderar lätthet, komfort och grepp och måste dessutom gå bra i timmar. Ett vattentätt och andande membran som GORE-TEX håller vatten ute och släpper ut ånga — vattentätt utan andning låser bara in svett, och du blir blöt och kall ändå.",
    "q.l3#6.p" to "Vilket material bör alpinistiska strumpor undvika?",
    "q.l3#6.o0" to "Merinoull",
    "q.l3#6.o1" to "Syntetfibrer som polyester",
    "q.l3#6.o2" to "Bomull",
    "q.l3#6.o3" to "Nylon",
    "q.l3#6.e" to "Samma logik som baslagret: bomull suger svett och släpper det knappt, så fuktigt kallt tyg fortsätter dränera värme och risken för skavblåsor ökar kraftigt. Välj syntet (utan bomull) eller merino, i knälång modell som balanserar värme och cirkulation.",
    "q.l3#7.p" to "Hur bör du tänka när du väljer damasker?",
    "q.l3#7.o0" to "Använd samma korta damasker på alla turer",
    "q.l3#7.o1" to "För höga toppar, föredra längre damasker som håller snön ute ur kängan",
    "q.l3#7.o2" to "Damasker är bara för regn",
    "q.l3#7.o3" to "Kortare och lättare är alltid bättre",
    "q.l3#7.e" to "Damasker är en tygtub över kängan som håller snö och skräp ute. I djup högfjällssnö begravs ett kort par snabbt och blir värdelöst, så längre rekommenderas; korta passar välkända vandringsleder och grund alpinstil snö.",
    "q.l3#8.p" to "Vad används lägerkängor och tofflor till, och vad behöver de?",
    "q.l3#8.o0" to "För toppen; de måste vara mycket styva",
    "q.l3#8.o1" to "För att röra sig i lägret; de måste vara varma, vattentäta och halkfria",
    "q.l3#8.o2" to "För teknisk klättring; de behöver frontpigg",
    "q.l3#8.o3" to "Bara dekoration; valfritt",
    "q.l3#8.e" to "De låter huvudkängorna vila: byt till lägerkängor eller tofflor i tältet så att fodren kan torka och fötterna inte pressas hela dagen. De har ingen teknisk funktion, men påverkar direkt hur fötterna mår nästa morgon.",
    "q.l3#9.p" to "Vad bidrar en knälång strumpa med på en lång expedition?",
    "q.l3#9.o0" to "Det ser mer professionellt ut",
    "q.l3#9.o1" to "Den håller foten varm samtidigt som den stödjer cirkulationen",
    "q.l3#9.o2" to "Den är lättare att ta på",
    "q.l3#9.o3" to "Den ger extra dämpning",
    "q.l3#9.e" to "Under långa dagar svullnar fötterna och cirkulationen försämras. En knälång strumpa täcker vaden, värmer den och hjälper genom jämnt tryck venöst återflöde — vilket på en flerdagstur avgör om fötterna fortfarande fungerar på tredje dagen.",
    "q.l4#0.p" to "Hur trampar man korrekt steg?",
    "q.l4#0.o0" to "Ta långa kliv för att använda färre steg",
    "q.l4#0.o1" to "Trampa små steg i jämn rytm och håll tyngdpunkten stabil",
    "q.l4#0.o2" to "Använd bara tåspetsarna",
    "q.l4#0.o3" to "Driv hälen i snön hela vägen",
    "q.l4#0.e" to "Små steg i jämn rytm håller tyngdpunkten stabil och slösar mindre energi. Långa kliv svänger kroppen sida till sida, vilket är det enklaste sättet att tappa balansen i en snösluttning.",
    "q.l4#1.p" to "Vilken hand ska bära isyxan under förflyttning?",
    "q.l4#1.o0" to "Den nedre handen",
    "q.l4#1.o1" to "Den övre handen, redo att gå direkt in i självstopp",
    "q.l4#1.o2" to "Ingen hand",
    "q.l4#1.o3" to "På utsidan av ryggsäcken",
    "q.l4#1.e" to "Bär den i den övre handen i piolet canne-läge, udden bakåt och huvudet framåt. Om du halkar kan du trycka ned i självstopp utan att byta hand — och de få sekunderna av handbyte är ofta hela olycksfönstret.",
    "q.l4#2.p" to "Vilken teknik lindrar andnöden på höjd under uppstigningen?",
    "q.l4#2.o0" to "Hålla andan medan du rör dig",
    "q.l4#2.o1" to "Tryckandning: en djup inandning och en kraftfull utandning, synkroniserad med stegtakten",
    "q.l4#2.o2" to "Snabb ytlig andning",
    "q.l4#2.o3" to "Andas genom en handske",
    "q.l4#2.e" to "Tryckandning höjer det positiva trycket i lungorna genom aktiv utandning, vilket förbättrar gasutbytet. Parad med stegtakten — till exempel ett andetag varannat eller var tredje steg — minskar det kvävande höjdkänslan märkbart.",
    "q.l4#3.p" to "När ett replag rör sig uppför en snösluttning, hur trampar man steg?",
    "q.l4#3.o0" to "Alla trampar sin egen linje",
    "q.l4#3.o1" to "Förste man trampar en jämn trappa och alla bakom använder samma steg",
    "q.l4#3.o2" to "Var och en trampar som de vill",
    "q.l4#3.o3" to "Trampa så djupt och brett som möjligt",
    "q.l4#3.e" to "En enda stegslinga minskar arbetet kraftigt för alla bakom och håller laget på en linje och i en rytm. En jämn trappa med jämnt avstånd är i sig ett tecken på lagets effektivitet och säkerhet.",
    "q.l4#4.p" to "Vad är kärnprincipen för tempo på höjd?",
    "q.l4#4.o0" to "Gå så fort som möjligt och vila tidigare",
    "q.l4#4.o1" to "Håll ett hållbart jämnt tempo och undvik upprepade explosiva ansträngningar",
    "q.l4#4.o2" to "Växla snabbt och långsamt för att spara energi",
    "q.l4#4.o3" to "Följ bara partnern och strunta i ditt eget tillstånd",
    "q.l4#4.e" to "Syreupptaget är begränsat på höjd, så upprepade explosiva ansträngningar staplar laktat och fördjupar hypoxin. Ett jämnt tempo med tryckandning tar dig längre och hindrar att hela laget störs av att en person sprinter.",
    "q.l4#5.p" to "Vem ska sätta tempot för ett lag i en snösluttning?",
    "q.l4#5.o0" to "Den starkaste i laget",
    "q.l4#5.o1" to "Det ska följa den långsammaste så att laget håller ihop",
    "q.l4#5.o2" to "Ledaren, låst till tidtabellen",
    "q.l4#5.o3" to "Alla i sitt eget tempo",
    "q.l4#5.e" to "När luckor öppnas i en snösluttning förlorar de bakom både säkring och stöd; och ett för högt tempo tröttar ut de svagare innan de ens når den farliga terrängen. Att gå i den långsammastes tempo behåller säkerhetsmarginalen hos hela laget.",
    "q.l4#6.p" to "Vad rekommenderar manualen vid passage av en isluttning med tydlig lutning?",
    "q.l4#6.o0" to "Rör dig som ett vanligt replag",
    "q.l4#6.o1" to "Sätt fasta rep eller använd alternerande säkring; rör dig i allmänhet inte samtidigt",
    "q.l4#6.o2" to "Skynda dig över så fort som möjligt",
    "q.l4#6.o3" to "Ta av stegjärnen för mer friktion",
    "q.l4#6.e" to "Bromsning på is är långt mindre tillförlitlig än på snö, och ett replag på is kan dra hela gruppen med sig. Rätt metod på lutande is är fasta rep eller alternerande säkring — skydd från systemet, inte från individuell bromsförmåga.",
    "q.l4#7.p" to "Vad är den främsta fördelen med att sikta uppför en snösluttning i sicksack i stället för rakt upp?",
    "q.l4#7.o0" to "Kortare väg",
    "q.l4#7.o1" to "Det minskar den effektiva lutningen i varje avsnitt och sparar energi",
    "q.l4#7.o2" to "Bättre utsikt",
    "q.l4#7.o3" to "Du behöver inte isyxan",
    "q.l4#7.e" to "Sicksack delar upp en brant sluttning i flera flackare avsnitt, vilket kraftigt minskar belastningen på vader och vrister och passar den franska (plattfots) tekniken. Priset är längre väg, så justera tidsbudgeten — ett skäl till att behålla marginal i vändtiden.",
    "q.l5#0.p" to "Vad är kärnan i den franska tekniken (plattfotstekniken)?",
    "q.l5#0.o0" to "Sticka isen med bara frontpiggarna",
    "q.l5#0.o1" to "Lägga alla stegjärnets undersidor platt mot sluttningen, med foten platt",
    "q.l5#0.o2" to "Hoppa upp på en fot",
    "q.l5#0.o3" to "Kanta kängans sida in i isen",
    "q.l5#0.e" to "Den franska tekniken handlar om platt: alla tolv undersidor griper och lasten sprids genom låret och hela kroppen, så den är minst tröttande. Därför passar den på långa sträckor flack snö.",
    "q.l5#1.p" to "Varför är frontpiggstekniken (den tyska tekniken) mest tröttande?",
    "q.l5#1.o0" to "För att den använder armarna",
    "q.l5#1.o1" to "För att lasten hamnar på frontpiggarna och vaden måste arbeta oavbrutet",
    "q.l5#1.o2" to "För att du måste hålla andan",
    "q.l5#1.o3" to "För att friktionen är högre",
    "q.l5#1.e" to "Frontpiggsteknik lägger vikten på två eller tre punkter, så vaden håller en ihållande kontraktion för att behålla positionen. Den är extremt tröttande och kan inte hållas länge — därför är den reserverad för brant terräng.",
    "q.l5#2.p" to "Vilken fotteknik ska du använda vid skrågång i en snösluttning?",
    "q.l5#2.o0" to "Frontpiggsteknik, sparka in piggarna rakt",
    "q.l5#2.o1" to "Ankkastget: hälarna ihop, tårna utåt, så att hela stegjärnet ligger mot sluttningen",
    "q.l5#2.o2" to "Sidohopp",
    "q.l5#2.o3" to "Krypa på knäna",
    "q.l5#2.e" to "Ankkastget låter sidopiggarna och undersidorna bita samtidigt, så vikten inte koncentreras på de inre piggarna där den kan glida. Luta dig lätt in mot sluttningen när du skråar.",
    "q.l5#3.p" to "Vilken terräng passar den franska (plattfots) tekniken bäst?",
    "q.l5#3.o0" to "Vertikal is",
    "q.l5#3.o1" to "Hård snö med låg till måttlig lutning, där du går i timmar",
    "q.l5#3.o2" to "Överhängande tak",
    "q.l5#3.o3" to "Bara plan mark",
    "q.l5#3.e" to "Den franska tekniken sprider lasten genom hela kroppen och låret, så den är minst tröttande och arbetshästen vid låg till måttlig lutning och långa snösluttningar. Brant terräng kräver frontpigg, men frontpigg kan inte hållas länge.",
    "q.l5#4.p" to "Vad händer om du står på frontpigg länge i en brant sluttning?",
    "q.l5#4.o0" to "Det blir lättare efter hand",
    "q.l5#4.o1" to "Vaden tröttas snabbt ut tills du inte längre kan hålla positionen",
    "q.l5#4.o2" to "Stegjärnen lossnar av sig själva",
    "q.l5#4.o3" to "Ingenting alls",
    "q.l5#4.e" to "Frontpigg koncentrerar vikten på två eller tre punkter och håller vaden i ihållande kontraktion, så tröttheten kommer snabbt. Därför passar den bara korta branta avsnitt — och därför måste energibudgeten räkna med den när du planerar en rutt.",
    "q.l5#5.p" to "I den blandade (amerikanska) tekniken, hur delar fötterna arbetet?",
    "q.l5#5.o0" to "Båda fötterna ligger platt mot sluttningen",
    "q.l5#5.o1" to "Båda fötterna använder frontpiggarna",
    "q.l5#5.o2" to "En fot platt för stöd, den andra driver på frontpiggarna, växelvis",
    "q.l5#5.o3" to "En fot gör allt arbete medan den andra vilar",
    "q.l5#5.e" to "Den blandade tekniken bygger bro mellan fransk och tysk: den platta foten ger stabilitet och en stunds vila, frontpiggfoten ger driv. På måttligt till brant underlag håller den dig effektiv utan att trötta ut vaderna som ren frontpiggsteknik gör.",
    "q.l5#6.p" to "[Matchning] Para ihop varje stegjärnsklass med rätt känga.",
    "q.l5#6.l0" to "C1, hel rem",
    "q.l5#6.r0" to "B1 mjuk känga",
    "q.l5#6.l1" to "C2, rem fram och bygel bak",
    "q.l5#6.r1" to "B2 halvstyv känga",
    "q.l5#6.l2" to "C3, hel bygel",
    "q.l5#6.r2" to "B3 helt styv känga",
    "q.l5#6.e" to "Känga och stegjärn måste matcha: mjuka kängor med C1, halvstyva med C2, styva med C3. Stegjärn med hel bygel på en mjuk känga låter kängan böjas, byglarna tappar fäste och stegjärnet kan lossna i en brant sluttning — en tydligt farlig kombination.",
    "q.l5#7.p" to "Vilka är de två mest grundläggande teknikerna för att röra sig på is?",
    "q.l5#7.o0" to "Plattfot och sidosteg",
    "q.l5#7.o1" to "Platt stegjärnsteknik (fransk) och frontpiggteknik (tysk)",
    "q.l5#7.o2" to "Hopp och glid",
    "q.l5#7.o3" to "Uppstigningsteknik och nedstigningsteknik",
    "q.l5#7.e" to "Platt stegjärnsteknik använder alla upprätta piggar utom frontpiggarna; frontpiggtekniken driver frontpiggarna rakt in i isen. Komplex terräng blandar oftast de två — därför bemästrar du båda innan du går vidare till den blandade tekniken.",
    "q.l5#8.p" to "Med platt stegjärnsteknik (fransk), vilka muskler tar lasten?",
    "q.l5#8.o0" to "Vaderna",
    "q.l5#8.o1" to "Låren",
    "q.l5#8.o2" to "Underarmarna",
    "q.l5#8.o3" to "Korsryggen",
    "q.l5#8.e" to "Eftersom foten hålls platt bär låren och hela kroppen lasten, så den är ekonomisk och kan hållas i timmar. Frontpigg är motsatsen: lasten ligger på två eller tre punkter och vaden gör allt arbete — två helt olika energikonton.",
    "q.l5#9.p" to "Platt stegjärnsteknik (fransk) passar särskilt vilken lutning?",
    "q.l5#9.o0" to "0°–30°",
    "q.l5#9.o1" to "30°–50°",
    "q.l5#9.o2" to "50°–70°",
    "q.l5#9.o3" to "Över 70°",
    "q.l5#9.e" to "Manualerna anger uttryckligen 0°–30°. Brantare än så kan foten inte längre hållas platt, och du måste växla till frontpigg. Att kunna lutningsintervallet för varje teknik är i praktiken att veta när du ska byta teknik.",
    "q.l6#0.p" to "Var ska fötterna vara under ett självstopp?",
    "q.l6#0.o0" to "Drivna i snön för att bromsa",
    "q.l6#0.o1" to "Lyfta från snön, tårna uppåt, så att hela vikten går genom yxan",
    "q.l6#0.o2" to "Tårna nedstuckna i snön som ankare",
    "q.l6#0.o3" to "Ihop och platt mot snön",
    "q.l6#0.e" to "I samma stund en fot nuddar snön tar den vikt från yxan, bromseffekten kollapsar och du riskerar vrist- och knäskador. Lyft båda fötterna så att hela kroppsvikten går genom udden ned i snön.",
    "q.l6#1.p" to "Du glider med huvudet före och fötterna uppåt. Vad gör du först?",
    "q.l6#1.o0" to "Försöker gripa repet",
    "q.l6#1.o1" to "Rullar omedelbart till magläge med fötterna nedåt och etablerar sedan stoppet",
    "q.l6#1.o2" to "Fortsätter glida och väntar på att farten ska minska",
    "q.l6#1.o3" to "Kastar ryggsäcken först",
    "q.l6#1.e" to "Med huvudet före kan udden inte tryckas effektivt i snön, och en kollision med huvudet före är extremt farlig. Använd bål och bäcken för att rulla in i magläget först, tryck sedan i udden.",
    "q.l6#2.p" to "Vad är rätt sätt att lära sig självstopp?",
    "q.l6#2.o0" to "Det räcker att titta på en video",
    "q.l6#2.o1" to "Läsa manualen och memorera nyckelpunkterna",
    "q.l6#2.o2" to "Öva upprepade gånger i en säker mjuk snösluttning med instruktör på säkring, tills det blir instinkt",
    "q.l6#2.o3" to "Lära sig genom att krascha en gång i en riktig brant sluttning",
    "q.l6#2.e" to "Självstopp är en reflexfärdighet: det krävs hundratals repetitioner under kontrollerade former för att bli tillförlitligt. Öva i en flack sluttning med fri utlöpning, mjuk snö och instruktör på säkring.",
    "q.l6#3.p" to "Vad är det mest effektiva sättet att applicera kraft i ett självstopp?",
    "q.l6#3.o0" to "Trycka hårt nedåt med armarna",
    "q.l6#3.o1" to "Trycka udden nedåt med kroppsvikten, vertikalt",
    "q.l6#3.o2" to "Dra skaftet i sidled över snön",
    "q.l6#3.o3" to "Svepa udden snabbt över ytan",
    "q.l6#3.e" to "Armstyrka sviker under trötthet och panik; bara kroppsvikten driver udden djupare. Därför betyder positionen — magläge, lyfta fötter — mer än rå styrka.",
    "q.l6#4.p" to "På hård snö eller is, hur bra fungerar ett självstopp?",
    "q.l6#4.o0" to "Bättre — det stannar direkt",
    "q.l6#4.o1" to "Stoppsträckan blir mycket längre och det kan misslyckas helt",
    "q.l6#4.o2" to "Ingen skillnad mot mjuk snö",
    "q.l6#4.o3" to "Det blir automatiskt en glidtur",
    "q.l6#4.e" to "Udden har svårt att bita i hård snö och is. Därför går du inte ut på en brant hårdsnösluttning utan säkring — teknik kan inte ersätta undvikande, och att känna till en tekniks gränser är lika viktigt.",
    "q.l6#5.p" to "I ett självstopp, hur ska händerna dela arbetet?",
    "q.l6#5.o0" to "Båda händerna på skaftet",
    "q.l6#5.o1" to "Båda händerna trycker på huvudet",
    "q.l6#5.o2" to "En hand trycker på huvudet nära udden för nedåtkraft, den andra på skaftet för riktning och stabilitet",
    "q.l6#5.o3" to "En hand räcker; håll den andra fri",
    "q.l6#5.e" to "Handen på huvudet för kroppsvikten till udden; handen på skaftet stabiliserar och korrigerar riktningen. Med tydliga roller blir stoppet både kraftfullt och rakt.",
    "q.l6#6.p" to "[Ordning] Sätt stegen i ett fallstopp i rätt ordning.",
    "q.l6#6.o0" to "Greppa yxan stadigt och tryck huvudet under kroppen i stoppgreppet",
    "q.l6#6.o1" to "Rulla till magläge, huvudet uppåt och ansiktet mot snön",
    "q.l6#6.o2" to "Tryck udden i snön och isen med kroppsvikten, benen isär, knäna mot ytan",
    "q.l6#6.o3" to "Lyft båda fötterna så att stegjärnen inte kan hugga och slå över dig",
    "q.l6#6.e" to "Steget som oftast glöms är det sista: att lyfta fötterna. I samma stund en fot nuddar snön stjäl den vikt från yxan, och stegjärnen kan plötsligt hugga och vända dig — vilket avbryter själva stoppet.",
    "q.l6#7.p" to "Var ska yxhuvudets flata sida (adzen) sitta under ett självstopp?",
    "q.l6#7.o0" to "Utanför knäet",
    "q.l6#7.o1" to "I axelhålan",
    "q.l6#7.o2" to "Vid höften",
    "q.l6#7.o3" to "Långt ut på sidan av huvudet",
    "q.l6#7.e" to "Med adzen i axelhålan ligger skaftet nära kroppens mittlinje och lasten centreras under bålen, där nedåtkraften fungerar bäst. Längre ut sprids lasten, udden vandrar och stoppsträckan blir märkbart längre.",
    "q.l6#8.p" to "[Flerval] Vad avgör huvudsakligen om ett fallstopp lyckas?",
    "q.l6#8.o0" to "Lutningen på snön eller isen",
    "q.l6#8.o1" to "Hårdheten i snön eller isen",
    "q.l6#8.o2" to "Den fallande klättrarens position",
    "q.l6#8.o3" to "Reaktionssnabbhet",
    "q.l6#8.o4" to "Utrustningens märke och pris",
    "q.l6#8.e" to "Manualerna är uppriktiga: förutom reaktionssnabbhet beror framgången på lutning, hårdhet och position — «ibland kan inte ens den mest inövade handlingen stoppa fallet». Att acceptera den gränsen är det som gör det klart varför det är viktigare att inte falla än att stoppa.",
    "q.l6#9.p" to "Vilken position ska benen och knäna ha under ett stopp?",
    "q.l6#9.o0" to "Benen ihop, knäna från marken",
    "q.l6#9.o1" to "Benen isär, knäna tryckta mot snön och isen",
    "q.l6#9.o2" to "Ena benet rakt, det andra böjt",
    "q.l6#9.o3" to "Båda benen lyfta från snön",
    "q.l6#9.e" to "Benen isär ger sidostabilitet och hindrar dig från att rulla; knäna mot ytan ger en stödpunkt som hjälper att hålla vikten på yxan. Notera skillnaden: knäna får nudda lätt, medan fötterna — och stegjärnen — måste upp.",
    "q.l7#0.p" to "Vad är det mest effektiva sättet att förebygga ett halk under förflyttning?",
    "q.l7#0.o0" to "Gå snabbare",
    "q.l7#0.o1" to "Använda yxan som självsäkring och ge dig en tillfällig förankring vid varje steg",
    "q.l7#0.o2" to "Lägga undan yxan i ryggsäcken",
    "q.l7#0.o3" to "Förlita sig bara på repet",
    "q.l7#0.e" to "Självsäkring är den mest direkta försvarslinjen under rörelse: yxhanden planterar skaftet i snön vid varje steg och skapar en tredje kontaktpunkt. Överväldigande majoritet av halk inträffar just i det ögonblick då stödet saknas.",
    "q.l7#1.p" to "Din partner faller plötsligt medan ni rör er samtidigt. Vad gör du först?",
    "q.l7#1.o0" to "Springer ned och griper tag",
    "q.l7#1.o1" to "Går rakt in i stoppositionen och tar in rep för att hålla",
    "q.l7#1.o2" to "Knyter upp så du inte dras med",
    "q.l7#1.o3" to "Ropar på hjälp och väntar",
    "q.l7#1.e" to "Ett replag fungerar för att du håller dig själv först, sedan förmedlar repet stoppet. Att springa ned eller knyta upp får hela laget att glida — den klassiska kedjekollapsen i glaciärolyckor.",
    "q.l7#2.p" to "I det ögonblick du tappar fästet, vad är den första handlingen?",
    "q.l7#2.o0" to "Ordna utrustningen",
    "q.l7#2.o1" to "Ropa en varning och rulla omedelbart till magläge för stopp",
    "q.l7#2.o2" to "Uppskatta sluttningens lutning",
    "q.l7#2.o3" to "Titta på det som ligger nedanför",
    "q.l7#2.e" to "De första två sekunderna avgör. Varningen får dina kamrater i skyddsställning samtidigt som du rullar till magläge — den rullningen är kärnan i att begränsa skadan.",
    "q.l7#3.p" to "När du rör dig som replag, i vilket tillstånd ska repet vara?",
    "q.l7#3.o0" to "Så slackt som möjligt för rörelsefrihet",
    "q.l7#3.o1" to "Måttligt spänt, utan stora hängande bukter",
    "q.l7#3.o2" to "Helt stramt",
    "q.l7#3.o3" to "Hur det än känns bekvämt",
    "q.l7#3.e" to "Stora bukter gör att den fallande först faller fritt innan repet tar last, vilket mångdubblar stöten och låter repet såga i snön. Måttlig spänning låter stoppet verka tidigare.",
    "q.l7#4.p" to "Varför är «halka inte» mer grundläggande än «lär dig stoppa»?",
    "q.l7#4.o0" to "För att stoppteknik är värdelös",
    "q.l7#4.o1" to "För att stoppet kan misslyckas på hård snö och branta sluttningar, medan att inte tappa fästet är det tillförlitliga skyddet",
    "q.l7#4.o2" to "För att stoppa är för tröttande",
    "q.l7#4.o3" to "För att instruktörer förbjuder att öva det",
    "q.l7#4.e" to "Självstopp är nödvändigt men har tydliga gränser. Den tillförlitliga strategin är att inte gå in i terräng där du kan glida utan säkring. Teknik är sista försvarslinjen, inte den första.",
    "q.l7#5.p" to "Under ett stopp studsar udden på hård snö och biter inte. Vad gör du?",
    "q.l7#5.o0" to "Lyfter den och slår igen",
    "q.l7#5.o1" to "Ligger kvar i magläge och fortsätter trycka med kroppsvikten så udden gradvis biter",
    "q.l7#5.o2" to "Drar skaftet i sidled över snön",
    "q.l7#5.o3" to "Ger upp stoppet och skyddar huvudet",
    "q.l7#5.e" to "Att lyfta yxan upphäver stoppet helt och kostar dig den tryckposition du byggt upp. Ligg kvar och tryck; udden biter djupare när du glider. Stopp är en progressiv process, inte en enda handling.",
    "q.l7#6.p" to "Varför sägs stopp på is vara mycket svårt?",
    "q.l7#6.o0" to "För att is är för kall",
    "q.l7#6.o1" to "För att udden har svårt att bita i is, så på isluttningar sätter du fasta rep i stället för att lita på stoppet",
    "q.l7#6.o2" to "För att friktionen på is är för hög",
    "q.l7#6.o3" to "För att is går lätt sönder",
    "q.l7#6.e" to "Stoppet beror på att udden biter, och is är den svåraste ytan att bita i. Manualerna svarar systemiskt: på lutande is sätter du fasta rep eller använder alternerande säkring och rör dig i allmänhet inte samtidigt — lös det med systemet, inte med hopp om individuell teknik.",
    "q.l7#7.p" to "[Ordning] Din partner faller medan ni rör er samtidigt. Vilken är rätt sekvens?",
    "q.l7#7.o0" to "Gå omedelbart in i stoppositionen och håll dig själv",
    "q.l7#7.o1" to "Ta in rep för att stoppa fallet",
    "q.l7#7.o2" to "Bygg en oberoende förankring (snöankare, nedgrävd yxa och liknande)",
    "q.l7#7.o3" to "Flytta lasten till förankringen och starta sedan räddningen",
    "q.l7#7.e" to "De fyra stegen kan inte byta ordning: du måste hålla dig själv innan du kan göra något annat, och räddning utan förankring lägger bådas vikt på dig. I verkligheten tar stegen minuter, så de måste vara inövade i förväg.",
    "q.l7#8.p" to "Stoppet fungerade och glidningen har upphört. Vad händer sedan?",
    "q.l7#8.o0" to "Resa sig och fortsätta",
    "q.l7#8.o1" to "Behålla stoppet, bygga säkring steg för steg och flytta vikten till förankringen",
    "q.l7#8.o2" to "Knyta upp repet",
    "q.l7#8.o3" to "Kontrollera om utrustningen är skadad",
    "q.l7#8.e" to "En stoppad glidning är inte säkerhet — du står fortfarande i en osäkrad position och skulle ha svårt att stoppa igen. Håll stoppet medan du bygger tillförlitlig säkring, frigör dig, och ta först därefter hand om skador och rutten.",
    "q.l7#9.p" to "[Flerval] Vilka av dessa förebygger effektivt halk?",
    "q.l7#9.o0" to "Självsäkra med yxan kontinuerligt under rörelse",
    "q.l7#9.o1" to "Sätta fasta rep på hård snö eller isluttningar",
    "q.l7#9.o2" to "Hålla ett hållbart jämnt tempo och undvika plötsliga ansträngningar som bryter balansen",
    "q.l7#9.o3" to "Gå i den långsammastes tempo så laget inte sträcks ut",
    "q.l7#9.o4" to "Gå snabbare för att förkorta exponeringen",
    "q.l7#9.e" to "De fyra verkar på olika nivåer: personlig teknik, systemsäkring, tempo och lagkohesion. Halkförebyggande är aldrig en handling, utan alla dessa lager samtidigt.",
    "q.l8#0.p" to "Varför är olyckor vanligare under nedstigningen?",
    "q.l8#0.o0" to "För att terrängen nedåt är svårare",
    "q.l8#0.o1" to "För att trötthet försämrar uppmärksamhet och rörelsekvalitet",
    "q.l8#0.o2" to "För att vädret alltid är sämre på väg ned",
    "q.l8#0.o3" to "För att utrustningen sviker",
    "q.l8#0.e" to "När toppen är nådd sjunker vaksamheten medan kroppen redan är nästan tom. En stor del av alpina olyckor sker på nedstigningen — därav talesättet att toppen bara är halva resan.",
    "q.l8#1.p" to "Under vilka förutsättningar får du glida nedför (glissad)?",
    "q.l8#1.o0" to "När sluttningen är brant nog",
    "q.l8#1.o1" to "Inga sprickor, ingen stenfallsrisk, fri utlöpning nedanför och förmåga att stoppa när som helst",
    "q.l8#1.o2" to "På vilken snösluttning som helst",
    "q.l8#1.o3" to "När kamraterna håller med",
    "q.l8#1.e" to "En glissad är en oåterkallelig acceleration — när den börjat är den svår att stoppa. Du måste utesluta sprickor, stenfall och folk nedanför och vara säker på att du kan rulla in i ett stopp när som helst. Annars klättrar du ned ordentligt.",
    "q.l8#2.p" to "Vilket är det föredragna sättet att ta sig nedför teknisk terräng?",
    "q.l8#2.o0" to "Klättra ned vänd mot sluttningen med tre kontaktpunkter",
    "q.l8#2.o1" to "Springa ned vänd utåt",
    "q.l8#2.o2" to "Glissad",
    "q.l8#2.o3" to "Sitta och glida",
    "q.l8#2.e" to "Vänd mot sluttningen ser du dina fotsteg, håller tyngdpunkten nära ytan och har båda händerna fria för stöd. Vänd utåt döljer fotstegen — ett mycket vanligt misstag.",
    "q.l8#3.p" to "Vad är det farligaste och vanligaste felet på nedstigningen?",
    "q.l8#3.o0" to "Vänd mot sluttningen och klättra ned på tre punkter",
    "q.l8#3.o1" to "Luta sig framåt och klättra ned vänd utåt",
    "q.l8#3.o2" to "Hålla en jämn rytm",
    "q.l8#3.o3" to "Självsäkra med yxan",
    "q.l8#3.e" to "Vänd utåt ser du inte fotstegen, och att luta sig framåt gör dig ännu mindre stabil. Lägg till trötthet som försämrar benkontrollen och du har den verkliga orsaken till att nedstigningar är så olycksdrabbade.",
    "q.l8#4.p" to "Vad måste göras innan en glissad påbörjas?",
    "q.l8#4.o0" to "Lägga undan yxan i ryggsäcken",
    "q.l8#4.o1" to "Bekräfta att ingen är nedanför, att det inte finns sprickor eller stenfall på linjen, och hålla yxan redo för stopp",
    "q.l8#4.o2" to "Dra åt ryggsäckens remmar",
    "q.l8#4.o3" to "Berätta reseplanen för familjen",
    "q.l8#4.e" to "En glissad är en oåterkallelig acceleration. Innan du börjar måste du utesluta folk nedanför, sprickor och stenfall, och hålla yxan i handen — annars har du inget sätt att sakta ned om något går fel.",
    "q.l8#5.p" to "Hur hanterar du lagets trötthet på en lång nedstigning?",
    "q.l8#5.o0" to "Gå rakt igenom med så få stopp som möjligt",
    "q.l8#5.o1" to "Ta korta planerade pauser, drick och ät, och omvärdera lagets tillstånd",
    "q.l8#5.o2" to "Öka farten för att förkorta exponeringen",
    "q.l8#5.o3" to "Stanna bara om någon är skadad",
    "q.l8#5.e" to "Nedstigningen är den högriskhalvan och tröttheten är huvuddrivaren. Regelbundna korta pauser återställer energi och låter dig läsa av väder, rutt och kamrater igen — bedömningar som är det första som försvinner på en lång ansträngning.",
    "q.l8#6.p" to "[Ordning] Sätt stegen för att förbereda en nedstigning i rimlig ordning.",
    "q.l8#6.o0" to "Bekräfta nedstigningslinjen och landningen, och få bort folk nedanför",
    "q.l8#6.o1" to "Kontrollera att rep, säkringsdon, karbiner och sling finns",
    "q.l8#6.o2" to "Bygg en tillförlitlig förankring, eller bekräfta den befintliga standplatsen",
    "q.l8#6.o3" to "Sortera repet för att undvika knutar och trassel, och börja sedan nedstigningen",
    "q.l8#6.e" to "En nedstigning lägger ditt liv i en enda punkt, så ordningen är: bestäm vart du ska, bekräfta utrustningen, sedan satsa. Repsorteringen är lika viktig — en knut eller trassel lämnar dig hängande länge på repet.",
    "q.l8#7.p" to "Vad avgör huvudsakligen valet mellan firning och nedklättring?",
    "q.l8#7.o0" to "Ju kortare nedstigning, desto mer bör du fira",
    "q.l8#7.o1" to "Terrängens svårighet, tillgängliga förankringar och lagets förmåga",
    "q.l8#7.o2" to "Vädret",
    "q.l8#7.o3" to "Hur ny utrustningen är",
    "q.l8#7.e" to "Firning är snabb men beroende av förankringar och utförande; nedklättring är långsammare men självständig. Terräng, förankringarnas tillförlitlighet och lagets skicklighet avgör tillsammans. Kom ihåg att firning har hög olycksfrekvens eftersom marginalen för handhavandefel är så liten.",
    "q.l8#8.p" to "Vilken teknisk utrustning kräver en firning normalt?",
    "q.l8#8.o0" to "En karbin och en sling",
    "q.l8#8.o1" to "Flera karbiner, en lång sling eller personlig ankarlina, prusikslinga och liknande",
    "q.l8#8.o2" to "Bara ett rep",
    "q.l8#8.o3" to "Bara ett säkringsdon",
    "q.l8#8.e" to "Manualerna listar flera karbiner, en lång sling eller daisy chain och prusikslinga. En nedstigning innebär ofta att du plockar förankringar medan du går och ändå behåller en backup — för lite utrustning tvingar dig improvisera högt över marken, vilket är precis där olyckor föds.",
    "q.l8#9.p" to "[Flerval] Vilka är huvudriskerna under en nedstigning?",
    "q.l8#9.o0" to "Förankringen sviker",
    "q.l8#9.o1" to "Att fira av repänden för att ändarna inte knutits",
    "q.l8#9.o2" to "Att repet fastnar eller trasslar",
    "q.l8#9.o3" to "Stenfall och folk nedanför",
    "q.l8#9.o4" to "Nedstigning är mindre riskabel än uppstigning eftersom gravitationen hjälper",
    "q.l8#9.e" to "De fyra första är de vanliga orsakerna till firningsolyckor. Det mest förbisedda är den oknutna repänden: är repet för kort och ändarna fria glider du av utan att märka det och faller. Det felet är särskilt vanligt på en trött nedstigning.",
    "q.l9#0.p" to "Vilken knut fäster repet i selen och är det vanliga valet på glaciärrutter?",
    "q.l9#0.o0" to "Åttaknut med efterföljande",
    "q.l9#0.o1" to "Råbandsknop",
    "q.l9#0.o2" to "Överhandsknop",
    "q.l9#0.o3" to "Pålstek",
    "q.l9#0.e" to "Åttaknut med efterföljande är stark, lätt att läsa och lätt för andra att kontrollera, och går fortfarande att lösa efter belastning. En råbandsknop kan glida eller fastna under last och får aldrig användas i en livsbärande koppling.",
    "q.l9#1.p" to "Vilken knut låter dig justera längden med en hand för att fästa repet i en karbin?",
    "q.l9#1.o0" to "Dubbelt fiskarknut",
    "q.l9#1.o1" to "Skotstek",
    "q.l9#1.o2" to "Fjärilsknut",
    "q.l9#1.o3" to "Vattenknop",
    "q.l9#1.e" to "Ett skotstek kan skjutas och dras till rätt längd på en karbin med en hand, och är standard för självsäkring vid en standplats. Dubbelt fiskarknut fogar samman två rep; fjärilsknuten skapar en fästpunkt mitt på repet.",
    "q.l9#2.p" to "Vad är den viktigaste egenskapen hos en friktionsknut som prusik?",
    "q.l9#2.o0" to "Den greppar repet under last och glider längs repet när den avlastas",
    "q.l9#2.o1" to "Den kan permanent ersätta huvudrepet",
    "q.l9#2.o2" to "Den är bara dekorativ",
    "q.l9#2.o3" to "Den knyter upp sig själv under last",
    "q.l9#2.e" to "Enkelriktat grepp är det som gör friktionsknutar användbara för uppstigning, som backup och i system med mekanisk fördel. Och eftersom tillförlitligheten beror på linans diameter i förhållande till repet och antalet varv måste du testa den i fält innan du litar på den.",
    "q.l9#3.p" to "Hur mycket ände bör lämnas efter en avslutad knut?",
    "q.l9#3.o0" to "Cirka 1 cm räcker",
    "q.l9#3.o1" to "Minst tio repdiametrar",
    "q.l9#3.o2" to "Ingen ände behövs",
    "q.l9#3.o3" to "Så lång som möjligt — minst 1 m",
    "q.l9#3.e" to "Tillräcklig ände är grundskyddet mot att knuten glider under last eller går upp när den skakas. Bygg också vanan att kontrollera varandra — knutarna är den enda delen av säkerhetssystemet som görs helt för hand, utan fabrikskontroll.",
    "q.l9#4.p" to "Vilken knut fogar samman två rep eller gör en prusikögla?",
    "q.l9#4.o0" to "Råbandsknop",
    "q.l9#4.o1" to "Dubbelt fiskarknut",
    "q.l9#4.o2" to "Överhandsknop",
    "q.l9#4.o3" to "Pålstek",
    "q.l9#4.e" to "Dubbelt fiskarknut är extremt stabilt och vill inte gå upp, men är svårt att lösa efter belastning — vilket passar för att foga samman rep och sluta linor till öglor. En råbandsknop kan glida under last och får aldrig bära vikt.",
    "q.l9#5.p" to "Varför beror en friktionsknuts tillförlitlighet på linans diameter?",
    "q.l9#5.o0" to "Diametern har ingen betydelse",
    "q.l9#5.o1" to "Om linan är mycket tunnare än repet blir kontaktytan och klämkraften för liten för att greppa",
    "q.l9#5.o2" to "Ju tunnare lina, desto bättre grepp",
    "q.l9#5.o3" to "Ju tjockare lina, desto bättre grepp",
    "q.l9#5.e" to "En friktionsknut greppar genom att klämma runt huvudrepet. För tunn och både kontaktyta och klämkraft räcker inte; för tjock och den lindar inte tätt. Kontrollera därför kombinationen varje gång och testa den på en säker plats innan du förlitar dig på den.",
    "q.l9#6.p" to "Vad används fjärilsknuten huvudsakligen till?",
    "q.l9#6.o0" to "Att foga samman två rep",
    "q.l9#6.o1" to "Att skapa en fast ögla mitt på repet som kan ta last i flera riktningar",
    "q.l9#6.o2" to "Att ersätta åttaknuten vid inknytning i selen",
    "q.l9#6.o3" to "Att göra en prusikögla",
    "q.l9#6.e" to "Fjärilsknuten bildar en ögla mitt på repet som håller last från båda håll, vilket är därför den förekommer i replag, glaciärgång och räddningssystem. Den knyts också mellan klättrare för att öka friktionen där repet löper över snö.",
    "q.l9#7.p" to "[Matchning] Para ihop varje knut med dess huvudsakliga användning.",
    "q.l9#7.l0" to "Åttaknut",
    "q.l9#7.r0" to "Vanlig inknytning till förankring eller sele",
    "q.l9#7.l1" to "Dubbelt fiskarknut",
    "q.l9#7.r1" to "Foga samman två rep, eller sluta en lina till ögla",
    "q.l9#7.l2" to "Friktionsknut (prusik)",
    "q.l9#7.r2" to "Friktionsknut: greppar under last, glider när den är fri",
    "q.l9#7.l3" to "Pålstek",
    "q.l9#7.r3" to "Fästa i en förankring; även vanlig vid förtöjning av båt",
    "q.l9#7.e" to "Dessa fyra täcker det mesta av glaciärgång och grundsäkring. Manualerna grupperar dem efter funktion — fästa i en förankring, foga rep, friktionsknut. Att lära sig dem efter funktion fastnar mycket bättre än efter form.",
    "q.l9#8.p" to "Vilket påstående om knutar och repstyrka är korrekt?",
    "q.l9#8.o0" to "Knutar påverkar inte repets styrka",
    "q.l9#8.o1" to "Varje knut minskar repets styrka på den punkten, olika mycket",
    "q.l9#8.o2" to "Knutar gör repet starkare",
    "q.l9#8.o3" to "En väl knuten knut påverkar inte styrkan",
    "q.l9#8.e" to "I en knut böjs repet, och under last bär fibrerna ojämnt, så styrkan sjunker alltid — bara hur mycket varierar. Därför trycker manualerna en tabell över styrkeförlust per knut: välj knut efter hur den fungerar och vad den kostar i styrka.",
    "q.l9#9.p" to "Manualen sammanfattar knutarnas poäng i en rad: «En knut ger repet ( ).»",
    "q.l9#9.a0" to "liv",
    "q.l9#9.a1" to "sitt liv",
    "q.l9#9.e" to "Originalet lyder «en knut ger repet liv». Det fångar kärnan: ett rep i sig är bara en lina, och bara genom knutar — kopplade till säkring, förankringar och andra rep — blir det ett system som kan bära ett liv.",
    "q.l10#0.p" to "Vilken är den ideala lagstorleken för glaciärgång på rep?",
    "q.l10#0.o0" to "2",
    "q.l10#0.o1" to "3",
    "q.l10#0.o2" to "6 eller fler",
    "q.l10#0.o3" to "En person ensam",
    "q.l10#0.e" to "Ett replag på tre har tillräckligt många för att bygga en förankring och driva ett räddningssystem när någon faller i en spricka. Med två måste den andre, om en går i, stoppa, bygga och hissa samtidigt — nästan ingen marginal.",
    "q.l10#1.p" to "Vilket repavstånd är vanligt vid glaciärgång?",
    "q.l10#1.o0" to "2–3 m",
    "q.l10#1.o1" to "8–12 m",
    "q.l10#1.o2" to "Mer än 30 m",
    "q.l10#1.o3" to "Så kort som möjligt",
    "q.l10#1.e" to "8–12 m ger kamraterna tid och distans att reagera och stoppa, samtidigt som kommunikation och samarbete fungerar. För kort och det finns nästan inget rep kvar att absorbera stöten.",
    "q.l10#2.p" to "Vad krävs av ett replag innan det faktiskt ger skydd?",
    "q.l10#2.o0" to "Att bara vara inknyten gör dig säker",
    "q.l10#2.o1" to "Kamrater som kan stoppa effektivt och bygga säkring",
    "q.l10#2.o2" to "Ett tillräckligt långt rep",
    "q.l10#2.o3" to "Ett tillräckligt stort lag",
    "q.l10#2.e" to "Säkerheten i ett replag kommer från två handlingar som görs tillförlitligt: stoppa och förankra. Ett lag utan stoppförmåga eller förankringsteknik är bara flera personer sammanknutna som faller i samma hål.",
    "q.l10#3.p" to "Varför knyts knutar (som fjärilsknuten) mellan klättrare på en glaciär?",
    "q.l10#3.o0" to "Enbart dekoration",
    "q.l10#3.o1" to "För att öka friktionen där repet löper över snön och begränsa hur långt en fallande klättrare faller",
    "q.l10#3.o2" to "För att känna igen sina kamrater",
    "q.l10#3.o3" to "För att göra repet lättare",
    "q.l10#3.e" to "Varje knut skapar en extra bromspunkt mot snöytan, vilket märkbart förkortar fallet och ger kamraterna ovanför tid att bygga säkring. Det är en mycket billig och mycket effektiv broms.",
    "q.l10#4.p" to "Var ska räddningsutrustningen bäras under glaciärgång?",
    "q.l10#4.o0" to "Längst ned i ryggsäcken",
    "q.l10#4.o1" to "Inom räckhåll, redo att användas i varje ögonblick",
    "q.l10#4.o2" to "Kvar i tältet vid lägret",
    "q.l10#4.o3" to "Lämnad till en kamrat att bära",
    "q.l10#4.e" to "Det gyllene fönstret vid sprickräddning är några minuter. Om prusiklinor, karbiner och snöankare ligger begravda längst ned i ryggsäcken kan kamraten vara nedkyld eller repet ha skurit genom kanten innan du grävt fram dem.",
    "q.l10#5.p" to "Vad är huvudrisken med ett replag på två jämfört med tre?",
    "q.l10#5.o0" to "Det rör sig långsammare",
    "q.l10#5.o1" to "Om en faller kan den kvarvarande inte både hålla stoppet och driva räddningen",
    "q.l10#5.o2" to "Repet är inte tillräckligt långt",
    "q.l10#5.o3" to "Du behöver bära mer utrustning",
    "q.l10#5.e" to "Med två måste den andre, om en går i en spricka, hålla stoppet, bygga en förankring och arbeta med hissystemet samtidigt — nästan ingen marginal. Måste du gå två, välj en mer konservativ rutt och planera längre framåt.",
    "q.l10#6.p" to "Varför ska du inte knyta upp på måfå under glaciärgång?",
    "q.l10#6.o0" to "För att det är besvärligt att knyta upp och igen",
    "q.l10#6.o1" to "För att risken i sprickterräng är kontinuerlig — i samma stund du knyter upp har du inget skydd",
    "q.l10#6.o2" to "För att repet kan tappas",
    "q.l10#6.o3" to "För att kamraterna kommer att klaga",
    "q.l10#6.e" to "Risken på en glaciär är ojämnt fördelad och svår att förutse, och folk knyter oftast upp på felbedömningen «den här biten är okej». Måste du verkligen knyta upp, stanna först, bekräfta terräng och snö och agera sedan som lag.",
    "q.l10#7.p" to "[Matchning] Para ihop de internationella klätterropen med deras betydelse.",
    "q.l10#7.l0" to "On belay",
    "q.l10#7.r0" to "Säkringen är klar, du kan börja",
    "q.l10#7.l1" to "Climbing",
    "q.l10#7.r1" to "Jag börjar klättra",
    "q.l10#7.l2" to "Falling",
    "q.l10#7.r2" to "Jag faller (varning)",
    "q.l10#7.l3" to "Off belay",
    "q.l10#7.r3" to "Säkringen är släppt, skyddet är över",
    "q.l10#7.e" to "Ropssystemet fungerar för att det inte kräver förklaring. På höjd är vinden stark och avstånden långa, så korta ord med samma betydelse på båda sidor tar bort otydlighet. Det farligaste ögonblicket vid säkring är när var och en antar att den andra vet. Manualerna listar de internationella ropen eftersom de är minimiöverenskommelsen mellan lag och språk.",
    "q.l10#8.p" to "Vilken grundläggande teknisk utrustning behöver en säkrare?",
    "q.l10#8.o0" to "En sele, en karbin, ett säkringsdon, ett par handskar, en hjälm",
    "q.l10#8.o1" to "Bara ett säkringsdon och en karbin",
    "q.l10#8.o2" to "En hjälm och solglasögon",
    "q.l10#8.o3" to "En sele och ett rep",
    "q.l10#8.e" to "Listan ser enkel ut, men varje saknad del har en konkret konsekvens: utan handskar bränner du händerna och tappar kontrollen över repet; utan hjälm har du inget svar på stenfall. Säkraren är den som fångar andra, så den egna utrustningen måste vara komplett först.",
    "q.l10#9.p" to "Varför göra en kamratkontroll innan klättringen börjar?",
    "q.l10#9.o0" to "För att lagdisciplinen kräver det",
    "q.l10#9.o1" to "För att fel i sele, knut och säkringsdon ofta är osynliga för den som bär dem",
    "q.l10#9.o2" to "För att dokumentera framsteg",
    "q.l10#9.o3" to "För att värma upp",
    "q.l10#9.e" to "När du kontrollerar dig själv ser du det du tror att du knöt. En kamrat ser bakifrån och från sidan, in i de platser du inte ser. Manualerna sätter kamratkontrollen först i säkringskommunikationen — den använder någon annans ögon för att täcka din blinda fläck.",
    "q.l11#0.p" to "I SRENE-principerna, vad står R för?",
    "q.l11#0.o0" to "Rapid",
    "q.l11#0.o1" to "Redundant",
    "q.l11#0.o2" to "Rope",
    "q.l11#0.o3" to "Rigid",
    "q.l11#0.e" to "Redundant betyder att systemet har flera oberoende säkringspunkter, så att om en sviker bär de andra fortfarande lasten. Det är det viktigaste enskilda elementet i förankringens säkerhet.",
    "q.l11#1.p" to "Vad innebär principen No Extension (ingen förlängning)?",
    "q.l11#1.o0" to "Ju längre rep, desto bättre",
    "q.l11#1.o1" to "Om en punkt sviker får systemet inte förlängas och stötbelasta de övriga",
    "q.l11#1.o2" to "Förankringar bör inte byggas lågt",
    "q.l11#1.o3" to "Ingen reservutrustning behövs",
    "q.l11#1.e" to "Finns det slack mellan punkterna faller lasten på de kvarvarande som en plötslig stöt vid ett haveri, långt större än statisk last. No Extension betyder utjämning och förspänning så att stöten aldrig kommer in i systemet.",
    "q.l11#2.p" to "Vad är kärnidén bakom att bygga en förankring?",
    "q.l11#2.o0" to "Använda så lite utrustning som möjligt",
    "q.l11#2.o1" to "Att en enda punkt sviker får inte kollapsa hela systemet",
    "q.l11#2.o2" to "Bygga så högt som möjligt",
    "q.l11#2.o3" to "Använda bara det tjockaste repet",
    "q.l11#2.e" to "Berg- och snöförankringar kan aldrig vara absolut säkra, så systemet byggs för att tåla fel: inget enskilt haveri får vara dödligt, vilket ger klättraren tid att reagera och en backup att falla tillbaka på.",
    "q.l11#3.p" to "Vilka två dimensioner lägger EARNEST till SRENE?",
    "q.l11#3.o0" to "Efficient och Timely",
    "q.l11#3.o1" to "Easy och Tight",
    "q.l11#3.o2" to "Equal och Nice",
    "q.l11#3.o3" to "Empty och True",
    "q.l11#3.e" to "En förankring måste inte bara vara säker, den måste sitta snabbt och vara enkel att hantera — för tiden du bygger den är tid du är exponerad. Det är precis här EARNEST kommer närmare verklig terräng än SRENE.",
    "q.l11#4.p" to "Vad beror en snöförankrings tillförlitlighet huvudsakligen på?",
    "q.l11#4.o0" to "Utrustningens märke",
    "q.l11#4.o1" to "Snökvaliteten och hur väl den är nedgrävd",
    "q.l11#4.o2" to "Repets färg",
    "q.l11#4.o3" to "Höjden",
    "q.l11#4.e" to "Samma snöankare eller deadman bär helt olika laster i djup snö, blöt snö och vid kanten av en snöbrygga. Snöförankringar kräver att du läser snötäcket på plats — en fast procedur fungerar inte.",
    "q.l11#5.p" to "Varför behöver en förankring utjämnad last?",
    "q.l11#5.o0" to "För att förankringen ska se prydlig ut",
    "q.l11#5.o1" to "För att lasten fördelas mellan punkterna som planerat och ingen punkt överbelastas",
    "q.l11#5.o2" to "För att spara utrustning",
    "q.l11#5.o3" to "För att göra den lättare att riva",
    "q.l11#5.e" to "Utjämning betyder att varje punkt bär nära sin dimensionerade last i stället för att en tar allt. Når en punkt sin gräns och sviker hoppar lasten plötsligt till de andra och kan utlösa ett kedjehaveri.",
    "q.l11#6.p" to "Vilket av dessa bryter mot redundansprincipen?",
    "q.l11#6.o0" to "Att använda delar med olika styrka",
    "q.l11#6.o1" to "Två säkringspunkter som i praktiken beror på samma spricka eller samma block",
    "q.l11#6.o2" to "Att koppla ihop punkterna med sling",
    "q.l11#6.o3" to "Att sätta tre säkringspunkter",
    "q.l11#6.e" to "Redundans kräver att varje punkt sviker oberoende. Delar två punkter en spricka tar sprickans öppning båda på en gång — det ser ut som två men fungerar som en. Sådan falsk redundans är vanlig och dödlig.",
    "q.l11#7.p" to "[Matchning] Para ihop varje bedömningsterm för förankring med dess innebörd.",
    "q.l11#7.l0" to "S (Solid)",
    "q.l11#7.r0" to "Stark: varje punkt kan bära förväntad last",
    "q.l11#7.l1" to "R (Redundant)",
    "q.l11#7.r1" to "Redundans: flera oberoende säkringspunkter",
    "q.l11#7.l2" to "E (Equalized)",
    "q.l11#7.r2" to "Utjämnad: lasten delas förnuftigt mellan punkterna",
    "q.l11#7.l3" to "No Extension",
    "q.l11#7.r3" to "Ingen förlängning: ett haveri skapar ingen stötbelastande förlängning",
    "q.l11#7.e" to "Dessa fyra bildar grundramverket, förkortat SRENE. Ordningen är värd att minnas: fråga först om varje punkt är solid, sedan om systemet är redundant — är en enskild punkt otillförlitlig är det meningslöst att diskutera redundans.",
    "q.l11#8.p" to "Utifrån lastvärdena, vilken vinkel mellan slingbenen bör du sikta på?",
    "q.l11#8.o0" to "Inom 60°",
    "q.l11#8.o1" to "Inom 90°",
    "q.l11#8.o2" to "Inom 120°",
    "q.l11#8.o3" to "Vinkeln påverkar inte lasten",
    "q.l11#8.e" to "Vid 0° bär varje punkt cirka 50 %, vid 60° cirka 58 %, vid 90° cirka 71 % — ju bredare vinkel, desto större last lägger en persons vikt på varje punkt. Tumregeln «håll det inom 60°» kommer direkt från dessa siffror.",
    "q.l11#9.p" to "Varför är effektivitet och timing en del av förankringsbedömningen?",
    "q.l11#9.o0" to "För att arbetet ska se bättre ut",
    "q.l11#9.o1" to "För att byggandet av förankringen i sig är tid under risk",
    "q.l11#9.o2" to "För att spara utrustning",
    "q.l11#9.o3" to "För att göra undervisningen lättare",
    "q.l11#9.e" to "Medan du bygger en förankring är du ofta osäkrad eller dåligt säkrad. Ju kortare den exponeringen är, desto lägre risk — så «snabb att bygga, enkel att hantera» är inte lathet, det är en del av säkerhetsmåttet.",
    "q.l11#10.p" to "[Flerval] Hur ser en tillräcklig förankring ut?",
    "q.l11#10.o0" to "Varje säkringspunkt är stark i sig",
    "q.l11#10.o1" to "Punkterna sviker oberoende av varandra",
    "q.l11#10.o2" to "Lasten delas förnuftigt mellan punkterna",
    "q.l11#10.o3" to "Systemet lämnas med slack för att absorbera stöt",
    "q.l11#10.e" to "De tre första är krav; den sista är motsatsen. En förankring ska ha ingen förlängning, inte reserverad slack — slack låter en punkts haveri stötbelasta de andra, och stötlaster är långt större än statiska.",
    "q.l11#11.p" to "Om förhållandena bara tillåter en enda säkringspunkt, vad är rätt?",
    "q.l11#11.o0" to "Avbryta klättringen och gå tillbaka samma väg",
    "q.l11#11.o1" to "Göra den så tillförlitlig du kan och minimera tiden systemet hänger på den",
    "q.l11#11.o2" to "Lägga till vilken andra punkt som helst, för att få två",
    "q.l11#11.o3" to "Knyta repet direkt i selen",
    "q.l11#11.e" to "Situationer med en punkt förekommer verkligen — en bra isskruv till exempel. Den ärliga hållningen är att erkänna att det inte finns marginal: gör den punkten så bra den kan bli och få folk förbi snabbt, i stället för att lägga till en meningslös andra punkt som skapar falsk trygghet.",
    "q.l12#0.p" to "Din kamrat faller i en spricka. Vad är första steget?",
    "q.l12#0.o0" to "Hoppa efter",
    "q.l12#0.o1" to "Gå in i självstopp, bygg en förankring och flytta lasten dit",
    "q.l12#0.o2" to "Larma först",
    "q.l12#0.o3" to "Skära av repet",
    "q.l12#0.e" to "Den fallandes hela vikt ligger på dig just nu. Stoppa först för att hålla dig själv, bygg sedan en oberoende förankring och flytta lasten — först då har du händerna fria för räddningssystemet. Att hoppa efter eller skära repet gör allt värre omedelbart.",
    "q.l12#1.p" to "Vilket är det vanligaste systemet med mekanisk fördel för räddningshissning?",
    "q.l12#1.o0" to "Direkt 1:1-drag",
    "q.l12#1.o1" to "3:1-systemet Z (Z-pulley)",
    "q.l12#1.o2" to "Ett 10:1-system",
    "q.l12#1.o3" to "Ingen fördel behövs",
    "q.l12#1.e" to "3:1-systemet Z använder en prusik och en trissa för att få tre gånger kraften. Det är enkelt, snabbt att bygga och kräver lite utrustning, därför är det standard vid sprickräddning.",
    "q.l12#2.p" to "Varför är snöbryggor särskilt farliga?",
    "q.l12#2.o0" to "För att de alltid låter",
    "q.l12#2.o1" to "För att de under nysnö ser ut som vanlig mark och är svåra att identifiera",
    "q.l12#2.o2" to "För att de bara finns nattetid",
    "q.l12#2.o3" to "För att de alltid är tunna",
    "q.l12#2.e" to "En snöbrygga är glaciärens mest dolda fara: ytan ser jämn och tjock ut medan utrymmet under är tomt. Att bedöma en betyder att läsa spricklinjer, snötäckets struktur och säsongen — och det är just därför du går i replag.",
    "q.l12#3.p" to "I vilket tillstånd ska repet vara vid passage av sprickterräng?",
    "q.l12#3.o0" to "Helt slackt för rörelsefrihet",
    "q.l12#3.o1" to "Måttligt spänt, utan stora hängande bukter",
    "q.l12#3.o2" to "Så stramt som möjligt",
    "q.l12#3.o3" to "Replag är onödigt",
    "q.l12#3.e" to "Slack låter den fallande falla fritt innan repet tar last, vilket mångdubblar stöten och ökar risken att repet skär in i kanten. Måttlig spänning aktiverar stoppet tidigare och minskar den risken.",
    "q.l12#4.p" to "Vad är det säkraste sättet att passera en snöbrygga?",
    "q.l12#4.o0" to "Springa över ensam och snabbt",
    "q.l12#4.o1" to "Gå i replag med spänt rep, en person i taget medan de andra står redo att stoppa",
    "q.l12#4.o2" to "Undvika varje snöbrygga",
    "q.l12#4.o3" to "Trampa hårt för att testa, sedan gå över",
    "q.l12#4.e" to "En snöbrygga kan du inte bedöma genom att titta på den. Replag och beredskap att stoppa förvandlar osäkerhet till hanterad risk. Att trampa hårt för att testa kan helt enkelt få den att kollapsa under dig.",
    "q.l12#5.p" to "Medan en kamrat hänger på repet inne i en spricka, vad är den största faran?",
    "q.l12#5.o0" to "Att kamraten somnar där nere",
    "q.l12#5.o1" to "Att det belastade repet sågar genom snökanten tills det plötsligt brister",
    "q.l12#5.o2" to "Att utrustning faller av",
    "q.l12#5.o3" to "Ett plötsligt väderomslag",
    "q.l12#5.e" to "Ett belastat rep skär fram och tillbaka över kanten och gräver en allt djupare ränna. Det är huvudkällan till tidspress i en räddning — du måste hissa eller flytta lasten till en säker förankring innan kanten är genomskuren.",
    "q.l12#6.p" to "Varför behövs en backup när du bygger ett Z-system med prusikar?",
    "q.l12#6.o0" to "För att systemet ska se komplett ut",
    "q.l12#6.o1" to "Om huvudprusiken sviker tappar du omedelbart fördelen och klättraren faller igen",
    "q.l12#6.o2" to "För att öka friktionen",
    "q.l12#6.o3" to "För att spara rep",
    "q.l12#6.e" to "En prusik greppar genom friktion, och is, smuts eller repslitage kan besegra den. En backup-prusik fångar lasten om huvudprusiken sviker och undviker ett andra fall med extra skador och fördröjning.",
    "q.l12#7.p" to "[Ordning] Sätt standardsekvensen för sprickräddning i ordning.",
    "q.l12#7.o0" to "Stoppa omedelbart och håll dig själv",
    "q.l12#7.o1" to "Bygg en oberoende förankring",
    "q.l12#7.o2" to "Flytta vikten från din kropp till förankringen",
    "q.l12#7.o3" to "Hissa med 3:1-systemet",
    "q.l12#7.e" to "De fyra stegen kan inte byta ordning. Steg tre är det som oftast hoppas över: utan lastöverföring måste du fortsätta hålla kamraten med kroppen och har inga händer till systemet — den vanligaste orsaken till att räddningar misslyckas.",
    "q.l12#8.p" to "Vad ska personen i sprickan göra?",
    "q.l12#8.o0" to "Skaka repet kraftigt för att påkalla uppmärksamhet",
    "q.l12#8.o1" to "Hålla sig lugn, försöka prusika upp och undvika att repet fortsätter skära in i kanten",
    "q.l12#8.o2" to "Knyta upp omedelbart",
    "q.l12#8.o3" to "Klättra ned för att leta efter en väg ut",
    "q.l12#8.e" to "Den fallandes samarbete gör räddningen mycket lättare. Att skaka repet förvärrar sågningen, och att knyta upp bryter din enda förbindelse. Ligg stilla, minska skärandet och ta om möjligt en del av vikten på en prusik.",
    "q.l12#9.p" to "[Flerval] Vilken räddningsutrustning ska bäras på kroppen och inom räckhåll på en glaciär?",
    "q.l12#9.o0" to "Prusiklina",
    "q.l12#9.o1" to "Karbiner och en trissa",
    "q.l12#9.o2" to "Snöankare eller isskruv",
    "q.l12#9.o3" to "Sling",
    "q.l12#9.o4" to "Vandringsstavar",
    "q.l12#9.e" to "Tillsammans bildar dessa fyra det improviserade systemet: prusiklina för enkelriktat grepp, karbiner och trissa för mekanisk fördel, snöankare eller skruv för förankringen, sling för koppling och förlängning. Det avgörande är inom räckhåll — utrustning i botten av ryggsäcken kan lika gärna inte finnas.",
    "q.l12#10.p" to "Varför måste lasten flyttas till förankringen innan hissning?",
    "q.l12#10.o0" to "För att fördela lasten jämnare på repet",
    "q.l12#10.o1" to "För att du annars har händerna upptagna med att hålla stoppet och inte kan arbeta med systemet",
    "q.l12#10.o2" to "För att spara energi",
    "q.l12#10.o3" to "För att skydda repet",
    "q.l12#10.e" to "Med den fallandes hela vikt på dig måste du hålla stoppet och kan varken frigöra händerna eller arbeta stadigt. Att lämna lasten till förankringen är enda sättet att sluta vara en mänsklig förankring och bli operatör.",
    "q.l12#11.p" to "Vilken roll spelar prusiken i ett räddningssystem?",
    "q.l12#11.o0" to "Dekoration",
    "q.l12#11.o1" to "Enkelriktat grepp — den håller under last och glider längs repet när den är fri",
    "q.l12#11.o2" to "Den ökar repets styrka",
    "q.l12#11.o3" to "Vattentätning",
    "q.l12#11.e" to "Enkelriktat grepp är precis det som gör ett system med mekanisk fördel möjligt: prusiken flyttar fram längs repet men går inte tillbaka under last. Tillförlitligheten beror på linans diameter och antalet varv, så testa den innan du litar på den.",
    "q.l13#0.p" to "Enligt Lake Louise-kriterierna, vilket symtom måste finnas för diagnosen AMS?",
    "q.l13#0.o0" to "Huvudvärk plus minst ett av illamående, yrsel, trötthet eller sömnlöshet",
    "q.l13#0.o1" to "Bara hosta",
    "q.l13#0.o2" to "Bara ömma ben",
    "q.l13#0.o3" to "Bara förbättrad aptit",
    "q.l13#0.e" to "Huvudvärk är kärnsymtomet vid AMS. Trötthet eller sömnlöshet räcker inte var för sig; de måste komma tillsammans med huvudvärk. Kriteriernas praktiska värde är att du kan poängsätta dig själv i lägret och agera på det.",
    "q.l13#1.p" to "Vad är rätt reaktion när AMS-symtom uppträder?",
    "q.l13#1.o0" to "Ta ett smärtstillande och fortsätt upp enligt planen",
    "q.l13#1.o1" to "Sluta stiga; gå ner omedelbart om symtomen förvärras",
    "q.l13#1.o2" to "Drick mer kaffe för energi och fortsätt gå",
    "q.l13#1.o3" to "Ignorera det och pressa på",
    "q.l13#1.e" to "AMS kan utvecklas till dödliga HACE eller HAPE. Att sluta stiga ger kroppen tid att anpassa sig; när symtomen förvärras är nedstigning den enda definitiva behandlingen. Varje plan att pressa på är ett vad om ditt liv.",
    "q.l13#2.p" to "Huvudvärken är borta efter ett smärtstillande. Kan du fortsätta stiga?",
    "q.l13#2.o0" to "Ja, symtomet är borta",
    "q.l13#2.o1" to "Nej — att dölja ett symtom betyder inte att kroppen acklimatiserat sig",
    "q.l13#2.o2" to "Ja, men gå långsammare",
    "q.l13#2.o3" to "Ja, bara du dricker mer vatten",
    "q.l13#2.e" to "Ett smärtstillande dämpar signalen; den fysiologiska påfrestningen på höjd fortsätter. Att stiga under det skyddet kan låta AMS utvecklas till HACE eller HAPE utan varning.",
    "q.l13#3.p" to "Hur lång tid efter ankomsten till höjd kommer AMS-symtomen oftast?",
    "q.l13#3.o0" to "Omedelbart",
    "q.l13#3.o1" to "6–12 timmar",
    "q.l13#3.o2" to "Efter tre dagar",
    "q.l13#3.o3" to "Efter en vecka",
    "q.l13#3.e" to "Tajmingen spelar roll: symtomen börjar ofta efter att du nått lägret, ätit kvällsmat och gjort dig klar för sänggåendet — och natten är precis då de är lättast att förbise och mest sannolikt förvärras.",
    "q.l13#4.p" to "Hur hanterar man lindrig AMS i fält på rätt sätt?",
    "q.l13#4.o0" to "Fortsätta stiga enligt planen",
    "q.l13#4.o1" to "Sluta vinna höjd, vila på nuvarande höjd och gå ner om symtomen kvarstår eller förvärras",
    "q.l13#4.o2" to "Ta ett smärtstillande och fortsätta stiga",
    "q.l13#4.o3" to "Gå ner 2 000 m omedelbart",
    "q.l13#4.e" to "Vid lindrig AMS är första valet att sluta stiga och ge kroppen tid. Ett smärtstillande lindrar huvudvärken men påverkar inte acklimatiseringen. Kvarstår eller förvärras symtomen efter vila är nedstigning den definitiva behandlingen.",
    "q.l13#5.p" to "Varför förbättrar «klättra högt, sov lågt» acklimatiseringen?",
    "q.l13#5.o0" to "För att det är varmare på dagen",
    "q.l13#5.o1" to "Dagshypoxin ger stimulansen, medan återgången till lägre höjd för att sova skyddar sömnkvaliteten",
    "q.l13#5.o2" to "För att du bär mindre utrustning",
    "q.l13#5.o3" to "För att det är säkrare att gå på natten",
    "q.l13#5.e" to "Acklimatisering behöver hypoxisk stress, men sömnkvaliteten är också ett krav — svår nattlig hypoxi förvärrar periodisk andning och symtom. Klättra högt, sov lågt förenar de två, och därför fungerar det bättre än att stanna högt hela tiden.",
    "q.l13#6.p" to "Vad är den värsta konsekvensen av att fortsätta stiga med AMS?",
    "q.l13#6.o0" to "Du känner dig lite tröttare",
    "q.l13#6.o1" to "Utveckling till HACE eller HAPE, som kan vara livshotande inom timmar",
    "q.l13#6.o2" to "Sämre aptit",
    "q.l13#6.o3" to "Sämre sömn",
    "q.l13#6.e" to "AMS brukar gå över med vila eller nedstigning, men kan vara förebud till ett kritiskt tillstånd. Därför upprepas «stig inte med symtom» så ofta — det bryter första länken i hela försämringskedjan.",
    "q.l13#7.p" to "När du bedömer om AMS förvärras, vad ska du följa mest?",
    "q.l13#7.o0" to "Om huvudvärken försvunnit",
    "q.l13#7.o1" to "Om symtomen gradvis förvärras, särskilt medvetande, gång och andning",
    "q.l13#7.o2" to "Om kroppstemperaturen är normal",
    "q.l13#7.o3" to "Om syrevärdet stigit",
    "q.l13#7.e" to "Vändningen från AMS till HACE/HAPE syns i tre dimensioner: medvetande, gång och andning. Att följa dessa tre är mer tillförlitligt än att följa ett enskilt symtom eller en siffra på pulsoximetern.",
    "q.l13#8.p" to "Vad är typiskt för huvudvärken vid AMS?",
    "q.l13#8.o0" to "Den är oftast det första symtomet",
    "q.l13#8.o1" to "Den kommer bara på natten",
    "q.l13#8.o2" to "Den kommer bara vid ansträngning",
    "q.l13#8.o3" to "Den är oftast det sista symtomet",
    "q.l13#8.e" to "Huvudvärk är ofta den tidigaste signalen och ett obligatoriskt element i Lake Louise-kriterierna. Eftersom den är så vanlig avfärdas den lätt som vanlig trötthet — därför är sammanhanget avgörande: den kom efter höjdökningen.",
    "q.l13#9.p" to "När acetazolamid används för att förebygga höjdsjuka, vilken regim rekommenderar manualen?",
    "q.l13#9.o0" to "250 mg tre gånger dagligen",
    "q.l13#9.o1" to "125 mg två gånger dagligen, med start cirka en dag före uppstigningen och avslut cirka två dagar efter",
    "q.l13#9.o2" to "500 mg en gång dagligen",
    "q.l13#9.o3" to "Bara efter att symtom uppträtt",
    "q.l13#9.e" to "Enligt nyare medicinska riktlinjer är dosen 125 mg två gånger dagligen, lägre än de äldre 250 mg tre gånger dagligen. Den lägre dosen fungerar och ger mindre risk för svåra biverkningar. Det är receptbelagt och måste följa läkarordination.",
    "q.l13#10.p" to "Varför är symtomlindring efter läkemedel inte ett skäl att fortsätta stiga?",
    "q.l13#10.o0" to "För att läkemedlet skapar en illusion",
    "q.l13#10.o1" to "För att läkemedlet lindrar symtom men inte förbättrar acklimatiseringen till hypoxi",
    "q.l13#10.o2" to "För att läkemedlet slutar verka",
    "q.l13#10.o3" to "För att dosen måste ökas hela tiden",
    "q.l13#10.e" to "Detta är den viktigaste tanken i handläggningen av höjdsjuka: symtomet är larmet, inte sjukdomen. Läkemedlet tystar larmet medan den fysiologiska hypoxiska påfrestningen fortsätter att ackumuleras — att stiga under det skyddet låter sjukdomen fortskrida tyst.",
    "q.l13#11.p" to "[Flerval] Vilka tillstånd förväxlas lätt med AMS och kräver noggrann åtskillnad?",
    "q.l13#11.o0" to "Utorkning",
    "q.l13#11.o1" to "Övre luftvägsinfektioner som förkylning",
    "q.l13#11.o2" to "Överträning",
    "q.l13#11.o3" to "Sömnbrist",
    "q.l13#11.o4" to "Snöblindhet (ultraviolett keratit)",
    "q.l13#11.e" to "Alla fyra ger huvudvärk, trötthet, illamående eller dålig sömn — stort överlapp med AMS. De användbara skillnaderna är om symtomen kom med höjdökningen, om de förbättras av vila och om gång eller medvetande förändrats.",
    "q.l13#12.p" to "Enligt kliniska källor och guideunderlag, ungefär hur stor andel av dem över 4 000 m får akut höjdsjuka?",
    "q.l13#12.o0" to "5–10 %",
    "q.l13#12.o1" to "20–30 %",
    "q.l13#12.o2" to "50–65 %",
    "q.l13#12.o3" to "Nästan 100 %",
    "q.l13#12.e" to "Ju högre och snabbare du går, desto vanligare: omkring 50–65 % av dem över 4 000 m får akut höjdsjuka, och studier mellan 2 500 och 4 300 m ger ungefär 25–43 %. Höjdsjuka är alltså normalt, inte undantag — och därför är ett planerat acklimatiseringsschema en nödvändighet, inte försiktighet.",
    "q.l13#13.p" to "Vilket påstående om ålder och risk för höjdsjuka är korrekt?",
    "q.l13#13.o0" to "Unga får inte höjdsjuka",
    "q.l13#13.o1" to "Ju äldre, desto högre måste risken vara",
    "q.l13#13.o2" to "Ålder höjer inte risken nämnvärt; stigningstakt och sovhöjd är det som avgör",
    "q.l13#13.o3" to "Bara otränade får det",
    "q.l13#13.e" to "Studier visar att äldre vandrare på måttlig höjd (i genomsnitt 65 år) har samma frekvens som yngre. Det som faktiskt avgör risken är stigningstakt, sovhöjd och individuell fysiologi — att skylla på ålder eller form är en farlig felbedömning.",
    "q.l14#0.p" to "Vilka tecken ska larma för HACE?",
    "q.l14#0.o0" to "Ostadig gång (kan inte gå rakt) och förändrat medvetande",
    "q.l14#0.o1" to "Lindrig huvudvärk",
    "q.l14#0.o2" to "Något sämre aptit",
    "q.l14#0.o3" to "Lindrig värk i benen",
    "q.l14#0.e" to "Ataxi och förändrat medvetande är kärnmarkörerna för HACE: hjärnödem påverkar redan rörelse och kognition. Vid dessa tecken måste du gå ner omedelbart och söka medicinsk hjälp — inte längre avvakta och se.",
    "q.l14#1.p" to "Vilket är det mest typiska tidiga tecknet på HAPE?",
    "q.l14#1.o0" to "Andnöd i vila, med tvärt fall i arbetsförmåga",
    "q.l14#1.o1" to "Lite rinnande näsa",
    "q.l14#1.o2" to "Lätt domning i fingrarna",
    "q.l14#1.o3" to "Törst",
    "q.l14#1.e" to "HAPE kännetecknas av andnöd även i vila. Till skillnad från vanlig utmattning lättar det inte med vila utan fortsätter förvärras, och kan utvecklas till skummigt slem och cyanos — en signal att gå ner omedelbart.",
    "q.l14#2.p" to "Vad är den grundläggande behandlingen vid HACE och HAPE?",
    "q.l14#2.o0" to "Ta ett smärtstillande och fortsätt klättra",
    "q.l14#2.o1" to "Gå ner till lägre höjd omedelbart, med syre och andra stödåtgärder",
    "q.l14#2.o2" to "Vila på plats i två dagar",
    "q.l14#2.o3" to "Drick mer vatten och sov mer",
    "q.l14#2.e" to "Nedstigning är den enda åtgärd som tillförlitligt vänder sjukdomen, eftersom den tar bort orsaken — hypoxin. Syre, hyperbarisk påse och läkemedel är stöd som köper tid när nedstigningen inte kan börja genast.",
    "q.l14#3.p" to "Enligt kliniska källor, vilket är det vanliga dexametasonschemat vid behandling av HACE?",
    "q.l14#3.o0" to "8–10 mg initialt, därefter 4 mg var 6:e timme",
    "q.l14#3.o1" to "2 mg en gång dagligen",
    "q.l14#3.o2" to "10 mg var 2:a timme",
    "q.l14#3.o3" to "Bara om patienten är medvetslös",
    "q.l14#3.e" to "Detta är en behandlingsdos och måste ges under medicinsk övervakning. Läkemedlet köper tid för nedstigningen; det ersätter den aldrig. Nedstigning är fortfarande grundbehandlingen vid både HACE och HAPE.",
    "q.l14#4.p" to "Ungefär hur ofta förekommer HAPE och HACE tillsammans?",
    "q.l14#4.o0" to "Nästan aldrig",
    "q.l14#4.o1" to "Cirka 13–20 % av HAPE-fallen utvecklar också HACE",
    "q.l14#4.o2" to "I 100 % av fallen",
    "q.l14#4.o3" to "Bara hos barn",
    "q.l14#4.e" to "Siffran visar att de två kritiska formerna av höjdsjuka ofta uppträder tillsammans. När en lagmedlem visar tecken på lungödem ska du därför också följa medvetande och gång, förbereda dig på det värsta och gå ner omedelbart.",
    "q.l14#5.p" to "Om en lagmedlem inte längre kan gå, vad är prioriterat?",
    "q.l14#5.o0" to "Uppmuntra dem att fortsätta gå",
    "q.l14#5.o1" to "Organisera bärande, ge syre, överväg hyperbarisk kammare och gå ner så snabbt som möjligt",
    "q.l14#5.o2" to "Vila på plats och invänta återhämtning",
    "q.l14#5.o3" to "Gå tillbaka till lägret efter utrustningen först",
    "q.l14#5.e" to "Att förlora förmågan att gå betyder kritiskt tillstånd. Nedstigningen beror då på att laget bär patienten eller på utomstående räddning — så den verkliga säkerhetsstrategin är att aldrig låta någon nå denna punkt, och det är precis värdet av att känna igen AMS tidigt.",
    "q.l14#6.p" to "Vad gör en portabel hyperbarisk kammare (som en Gamow-påse)?",
    "q.l14#6.o0" to "Botar höjdsjuka helt",
    "q.l14#6.o1" to "Simulerar lägre höjd för att stabilisera patienten när omedelbar nedstigning är omöjlig",
    "q.l14#6.o2" to "Ersätter nedstigning",
    "q.l14#6.o3" to "Ger främst värme",
    "q.l14#6.e" to "En hyperbarisk kammare köper tid; den är inte behandlingens slutpunkt. Den kan hålla sjukdomen i schack i dåligt väder, i väntan på helikopter eller när nedstigningen inte kan börja direkt — men nedstigning krävs ändå till slut.",
    "q.l14#7.p" to "Vilken är rätt hållning till läkemedel mot höjdsjuka?",
    "q.l14#7.o0" to "Om symtomen lindras, fortsätt stiga",
    "q.l14#7.o1" to "Det är ett stöd som köper tid, används enligt läkarordination och aldrig ersätter nedstigning",
    "q.l14#7.o2" to "Det kan delas ut fritt till kamrater",
    "q.l14#7.o3" to "Ju tidigare desto bättre, ingen medicinsk bedömning behövs",
    "q.l14#7.e" to "Dessa läkemedel har specifika indikationer, kontraindikationer och biverkningar, och att stiga under deras skydd döljer tecknen på försämring. Standarden är användning efter medicinsk bedömning, med nedstigning som grundbehandling.",
    "q.l14#8.p" to "Vilken dos dexametason är vanlig vid höghöjdshjärnödem?",
    "q.l14#8.o0" to "20 mg var 12:e timme",
    "q.l14#8.o1" to "4 mg var 6:e timme",
    "q.l14#8.o2" to "8 mg en gång dagligen",
    "q.l14#8.o3" to "10 mg var 2:a timme",
    "q.l14#8.e" to "Manualen anger 4 mg var 6:e timme. Det sänker intrakraniellt tryck och lindrar hjärnödem, oftast med tydlig förbättring inom sex timmar — men det köper bara tid för nedstigningen och ersätter den aldrig.",
    "q.l14#9.p" to "Behandlar dexametason höghöjdslungödem?",
    "q.l14#9.o0" to "Ja, det är förstahandsvalet",
    "q.l14#9.o1" to "Nej, det har ingen terapeutisk effekt på lungödem",
    "q.l14#9.o2" to "Ja, men dosen måste dubblas",
    "q.l14#9.o3" to "Det fungerar bara hos barn",
    "q.l14#9.e" to "Detta är lätt att blanda ihop: dexametason riktar sig mot hjärnödem och är verkningslöst vid lungödem, medan nifedipin riktar sig mot lungödem och har begränsad effekt på hjärnödem. De två kritiska tillstånden kräver olika läkemedel — fel medel är ingen behandling alls.",
    "q.l14#10.p" to "Vid höghöjdslungödem, vilket nifedipinschema rekommenderas och vilken viktig biverkning har det?",
    "q.l14#10.o0" to "20–30 mg depot var 12:e timme; blodtrycket kan falla snabbt, så att resa sig hastigt kan ge svimning",
    "q.l14#10.o1" to "4 mg var 6:e timme; det gör folk dåsiga",
    "q.l14#10.o2" to "125 mg en gång dagligen; det höjer blodtrycket",
    "q.l14#10.o3" to "Endast intravenöst; inga biverkningar",
    "q.l14#10.e" to "Nifedipin lindrar den hypoxiska lungvasokonstriktionen och används för att förebygga och behandla lungödem. Biverkningen är mycket praktisk: blodtrycket kan falla snabbt, så att resa sig från sittande eller liggande kan ge svimning — särskilt farligt i brant sluttning eller vid nattlig uppstigning.",
    "q.l14#11.p" to "Hur ska dexametason ges till en höjdsjuk patient som fortsätter kräkas?",
    "q.l14#11.o0" to "Peroralt, i högre dos",
    "q.l14#11.o1" to "Det måste ges som injektion",
    "q.l14#11.o2" to "Under tungan",
    "q.l14#11.o3" to "Det kan inte ges; vänta bara",
    "q.l14#11.e" to "Kontinuerlig kräkning betyder att tabletter inte absorberas och kan helt enkelt kräkas upp. Manualen säger tydligt att injektion krävs — en påminnelse om att administreringsvägen i sig måste tänkas igenom i förväg i varje plan för höjdnödsituation.",
    "q.l15#0.p" to "Över 3 000 m, hur mycket bör sovhöjden öka per dag?",
    "q.l15#0.o0" to "Högst 500 m",
    "q.l15#0.o1" to "Högst 1 500 m",
    "q.l15#0.o2" to "Så snabbt som möjligt",
    "q.l15#0.o3" to "Det finns ingen gräns",
    "q.l15#0.e" to "Att hålla den dagliga ökningen av sovhöjden inom 500 m, med en vilodag ungefär var 1 000 m, är grundrådet som upprepas i internationella riktlinjer. Det ger kroppen tid att kompensera. (Källor anger 300–700 m; kursen använder en av de vanligare nivåerna.)",
    "q.l15#1.p" to "Vad betyder «klättra högt, sov lågt»?",
    "q.l15#1.o0" to "Gå högre under dagen och återvänd till lägre höjd för att sova",
    "q.l15#1.o1" to "Vila på dagen och färdas på natten",
    "q.l15#1.o2" to "Stanna på samma höjd hela tiden",
    "q.l15#1.o3" to "Sova bara på högsta punkten",
    "q.l15#1.e" to "Daglig exponering på höjd stimulerar produktionen av röda blodkroppar och andningsanpassningen, medan återgången till lägre höjd för att sova lindrar symtom och skyddar sömnkvaliteten. Kombinationen är det mest effektiva sättet att acklimatisera sig.",
    "q.l15#2.p" to "Vilket av dessa ökar acklimatiseringsbördan?",
    "q.l15#2.o0" to "Att dricka tillräckligt",
    "q.l15#2.o1" to "Alkohol eller lugnande läkemedel",
    "q.l15#2.o2" to "Att äta mest kolhydrater",
    "q.l15#2.o3" to "Att sova tillräckligt",
    "q.l15#2.e" to "Alkohol och lugnande medel dämpar andningsdriften och förvärrar nattlig periodisk andning och hypoxi, vilket kraftigt ökar risken för sjukdom. På höjd är kvaliteten på din andning under sömnen i sig en del av acklimatiseringen.",
    "q.l15#3.p" to "Vad är poängen med att följa syremättnaden med pulsoximeter?",
    "q.l15#3.o0" to "Den kan helt ersätta symtombedömningen",
    "q.l15#3.o1" to "Den ger en objektiv referens, särskilt för personer med tidigare höjdsjuka",
    "q.l15#3.o2" to "Bara för att föra journal",
    "q.l15#3.o3" to "Den har inget praktiskt värde",
    "q.l15#3.e" to "Mättnaden är en användbar referens, men den individuella variationen är stor och den kan inte vara enda beslutsgrund. Symtom och funktionstillstånd — kan personen gå rakt, fungerar personen — är fortfarande huvudkriteriet.",
    "q.l15#4.p" to "För personer med hög risk för HAPE, vilka förebyggande läkemedel kan en läkare överväga?",
    "q.l15#4.o0" to "Nifedipin eller sildenafil (en PDE-hämmare)",
    "q.l15#4.o1" to "Bredspektrumantibiotika",
    "q.l15#4.o2" to "Vanliga smärtstillande",
    "q.l15#4.o3" to "Vitaminpreparat",
    "q.l15#4.e" to "Båda grupperna sänker trycket i lungartären och används för att förebygga HAPE hos högriskpersoner, efter medicinsk bedömning. De verkar på en annan punkt än acetazolamid och kan inte ersätta det.",
    "q.l15#5.p" to "Varför är för snabb stigning en av de starkaste riskfaktorerna för höjdsjuka?",
    "q.l15#5.o0" to "För att det är tröttande",
    "q.l15#5.o1" to "För att kroppen inte hinner utveckla andningsanpassning och öka antalet röda blodkroppar",
    "q.l15#5.o2" to "För att du bär mer vikt",
    "q.l15#5.o3" to "För att bergsvädret ändras snabbt",
    "q.l15#5.e" to "Acklimatisering är en ansamling av en rad fysiologiska kompensationer, och den tar tid mätt i dagar. När stigningen går fortare än kompensationen syns gapet som symtom — och det är där alla rekommendationer om stigningstakt kommer ifrån.",
    "q.l15#6.p" to "Vad gör tillräckligt drickande för acklimatiseringen?",
    "q.l15#6.o0" to "Bara släcker törst",
    "q.l15#6.o1" to "Upprätthåller cirkulation och ämnesomsättning; uttorkning förvärrar symtomen markant",
    "q.l15#6.o2" to "Förebygger lungödem",
    "q.l15#6.o3" to "Ersätter förebyggande läkemedel",
    "q.l15#6.e" to "Torr luft och snabbare andning på höjd ökar vätskeförlusten betydligt, och uttorkning gör blodet tjockare, vilket förvärrar känslan av hypoxi och huvudvärken. Undvik samtidigt överdrivet drickande — målet är jämnt, tillräckligt intag.",
    "q.l15#7.p" to "Varför undvika överansträngning på höjd?",
    "q.l15#7.o0" to "För att du blir trött snabbt",
    "q.l15#7.o1" to "Överansträngning kan utlösa HAPE, särskilt före acklimatisering",
    "q.l15#7.o2" to "För att det ger uttorkning",
    "q.l15#7.o3" to "För att det saktar ner laget",
    "q.l15#7.e" to "Hård ansträngning höjer trycket i lungartären och är en tydlig utlösare av HAPE hos personer som ännu inte acklimatiserat sig. Att kontrollera tempot handlar inte bara om att spara energi; det sänker risken för sjukdom.",
    "q.l15#8.p" to "När ska acetazolamid startas och avslutas?",
    "q.l15#8.o0" to "Starta vid ankomst till höjd och sluta när du acklimatiserat dig",
    "q.l15#8.o1" to "Starta cirka en dag före uppstigningen och sluta cirka två dagar efter",
    "q.l15#8.o2" to "Ta det kontinuerligt hela resan",
    "q.l15#8.o3" to "Bara efter att symtom uppträtt",
    "q.l15#8.e" to "Att starta en dag tidigt betyder att läkemedlet redan verkar när du stiger; att sluta cirka två dagar efter uppstigningen beror på att kroppen börjat acklimatisera sig själv. Acetazolamid påskyndar acklimatiseringen, det ersätter den inte.",
    "q.l15#9.p" to "Ger utsättning av acetazolamid rebound-symtom?",
    "q.l15#9.o0" to "Ja, dosen måste trappas ned",
    "q.l15#9.o1" to "Nej, acklimatiseringen återgår bara till sin normala takt",
    "q.l15#9.o2" to "Ja, symtomen kommer tillbaka dubbelt",
    "q.l15#9.o3" to "Det beror på höjden",
    "q.l15#9.e" to "Manualen säger rakt ut att utsättning inte ger rebound — acklimatiseringstakten återgår bara till det normala. Det är viktigt: det visar att läkemedlet inte dämpar något, bara påskyndar processen en tid.",
    "q.l15#10.p" to "Hur används aspirin för att lindra höjdhuvudvärk?",
    "q.l15#10.o0" to "500 mg en gång, efter att huvudvärken börjat",
    "q.l15#10.o1" to "Starta en dag före uppstigningen, 320 mg tre gånger dagligen tills acklimatiseringen är klar",
    "q.l15#10.o2" to "100 mg en gång dagligen",
    "q.l15#10.o3" to "Bara vid sänggåendet",
    "q.l15#10.e" to "Detta är förebyggande användning snarare än «ta när det gör ont»: börja tidigt, dosera regelbundet, fortsätt tills acklimatiseringsprocessen är klar. Notera att aspirin innebär gastrointestinala risker och blödningsrisk — det är ett medicinskt beslut som ska bedömas av läkare.",
    "q.l15#11.p" to "Vilken är rätt syn på ginkgoextrakt för att förebygga höjdsjuka?",
    "q.l15#11.o0" to "Det fungerar bättre än acetazolamid och kan ersätta det",
    "q.l15#11.o1" to "Det har viss förebyggande effekt, men kontrollerade studier visar att det är långt svagare än acetazolamid",
    "q.l15#11.o2" to "Det är helt verkningslöst",
    "q.l15#11.o3" to "Det fungerar bara vid hjärnödem",
    "q.l15#11.e" to "Manualen är försiktig: vissa studier visar symtomlindring, men doser och förhållanden varierar för mycket för att ge en tillförlitlig dos, och direkt jämförande studier visar att det är betydligt svagare än acetazolamid. Notera också interaktionen med antikoagulerande läkemedel.",
    "q.l16#0.p" to "Vad betyder det när frysningarna upphör?",
    "q.l16#0.o0" to "Kroppen har anpassat sig till kylan",
    "q.l16#0.o1" to "Hypotermin förvärras — ett varningstecken",
    "q.l16#0.o2" to "Du kan fortsätta röra dig",
    "q.l16#0.o3" to "Du måste dricka vatten omedelbart",
    "q.l16#0.e" to "Frysningar är kroppens sista sätt att producera värme. När de upphör har värmeproduktionen sviktat och kärntemperaturen faller snabbare — den avgörande gränsen mellan lindrig och måttlig eller svår hypotermi, och ett skäl att agera omedelbart.",
    "q.l16#1.p" to "Vilken är rätt metod för uppvärmning av förfrysning i fält?",
    "q.l16#1.o0" to "Gnida området med snö",
    "q.l16#1.o1" to "Sänka ned i vatten på 37–40 °C i cirka 30 minuter, tills huden rodnar och mjuknar",
    "q.l16#1.o2" to "Värma vid en eld",
    "q.l16#1.o3" to "Lägga en varmvattenflaska direkt på",
    "q.l16#1.e" to "Förfrusen vävnad innehåller iskristaller, och gnidning ger sekundär cellskada; stark värme bränner hud som förlorat känseln. Snabb uppvärmning i varmt vatten är den enda standardmetoden — den oskadade handen eller armhålan kan användas som nödåtgärd.",
    "q.l16#2.p" to "När ska förfrysning inte värmas upp i fält?",
    "q.l16#2.o0" to "Värma all förfrysning alltid",
    "q.l16#2.o1" to "När det finns risk för återfrysning, eftersom frysning–upptining–frysning ger värre skada",
    "q.l16#2.o2" to "Aldrig värma på dagen",
    "q.l16#2.o3" to "Bara lindrig förfrysning ska värmas",
    "q.l16#2.e" to "En cykel av uppvärmning och återfrysning förstör långt mer vävnad än att förbli frusen. Om fortsatt kyla är sannolik och värme inte kan garanteras ska du skydda området, undvika friktion och ta dig ner dit varaktig värme är möjlig innan du värmer upp.",
    "q.l16#3.p" to "Varför undvika kraftiga rörelser av extremiteterna vid måttlig eller svårare hypotermi?",
    "q.l16#3.o0" to "För att det kostar energi",
    "q.l16#3.o1" to "För att den kalla hjärtmuskeln lätt hamnar i arytmi",
    "q.l16#3.o2" to "För att patienten blir irriterad",
    "q.l16#3.o3" to "För att det förvärrar förfrysningen",
    "q.l16#3.e" to "Detta är den mest kontraintuitiva punkten i hypotermivård: att låta patienten gå är ofta dödligt. I ett kallt hjärta är myokardiet mycket irritabelt, och plötslig rörelse av extremiteterna eller hårdhänt hantering kan direkt utlösa ventrikelflimmer.",
    "q.l16#4.p" to "Vilken vattentemperatur är rätt för att värma upp förfrysning?",
    "q.l16#4.o0" to "0–5 °C",
    "q.l16#4.o1" to "20–25 °C",
    "q.l16#4.o2" to "37–40 °C",
    "q.l16#4.o3" to "Över 60 °C",
    "q.l16#4.e" to "För kallt och uppvärmningen misslyckas; för varmt och hud utan känsel bränns. 37–40 °C smälter iskristallerna snabbt utan termisk skada. Uppvärmningen är starkt smärtsam och kräver smärtlindring.",
    "q.l16#5.p" to "Varför värma bålen före extremiteterna vid hypotermi?",
    "q.l16#5.o0" to "För att extremiteterna inte spelar roll",
    "q.l16#5.o1" to "Uppvärmning av extremiteterna för kallt perifert blod tillbaka till kärnan och sänker kärntemperaturen ytterligare",
    "q.l16#5.o2" to "För att bålen är lättare att arbeta med",
    "q.l16#5.o3" to "För att extremiteterna kan vara förfrusna redan",
    "q.l16#5.e" to "Detta är en av nyckelprinciperna i hypotermivård. Behandlar du extremiteterna först driver du kallt perifert blod tillbaka in i kärnan, vilket kan sänka kärntemperaturen ytterligare och framkalla arytmi — kärna först, extremiteter sedan.",
    "q.l16#6.p" to "Hur hanteras lindrig hypotermi i fält?",
    "q.l16#6.o0" to "Skicka dem till sjukhus omedelbart",
    "q.l16#6.o1" to "Bort från vind och kyla, byta blöta kläder, tillföra värme och fortsätta följa försämring",
    "q.l16#6.o2" to "Låta dem gå för att producera värme",
    "q.l16#6.o3" to "Gnida kroppen med snö för att stimulera cirkulationen",
    "q.l16#6.e" to "En lindrigt nedkyld person kan fortfarande producera värme, så prioriteringen är att stoppa ytterligare värmeförlust och tillföra energi. Men fortsätt följa: att frysningarna upphör är oftast ett tecken på övergång till måttlig hypotermi, inte på förbättring.",
    "q.l16#7.p" to "Kan du lägga en varmvattenflaska direkt mot förfrusen vävnad?",
    "q.l16#7.o0" to "Ja, ju snabbare uppvärmning desto bättre",
    "q.l16#7.o1" to "Nej — hud utan känsel bränns lätt; använd bara vatten på 37–40 °C",
    "q.l16#7.o2" to "Ja, om den lindas i en handduk",
    "q.l16#7.o3" to "Ja, om temperaturen inte är för hög",
    "q.l16#7.e" to "Förfrusen hud har förlorat både smärt- och temperaturkänsel och kan därför inte signalera att något är för varmt. En direkt värmekälla tillför lätt en brännskada och kan förstöra vävnad som annars kunde återhämta sig.",
    "q.l16#8.p" to "[Flerval] Vilket av dessa är fel i första hjälpen vid hypotermi?",
    "q.l16#8.o0" to "Ge patienten alkohol för att värma",
    "q.l16#8.o1" to "Låta en svårt nedkyld patient gå för att producera värme",
    "q.l16#8.o2" to "Gnida förfrusna extremiteter kraftigt",
    "q.l16#8.o3" to "Värma extremiteterna före bålen",
    "q.l16#8.o4" to "Flytta patienten ur vinden och byta blöta kläder",
    "q.l16#8.e" to "De fyra första är fel, var och en av sitt skäl: alkohol vidgar perifera kärl och påskyndar värmeförlusten; gång kan utlösa arytmi vid svår hypotermi; gnidning ger sekundär skada på förfrusen vävnad; och uppvärmning av extremiteterna driver kallt blod till kärnan och sänker kärntemperaturen ytterligare.",
    "q.l16#9.p" to "Vilken är kärnprioriteringen vid hypotermivård?",
    "q.l16#9.o0" to "Värma extremiteterna först, sedan bålen",
    "q.l16#9.o1" to "Värma bålens kärna först, samtidigt som hårdhänt hantering och kraftiga rörelser av extremiteterna undviks",
    "q.l16#9.o2" to "Ge patienten varmt vatten först",
    "q.l16#9.o3" to "Ta av alla kläder först",
    "q.l16#9.e" to "Kärna först är första principen: när bålen är varm kan hjärta och hjärna fungera igen och blodet kan säkert skickas ut till extremiteterna. Omvänd ordning sänker kärntemperaturen direkt.",
    "q.l16#10.p" to "Vilken är rätt eftervård när förfrysningen värmts upp?",
    "q.l16#10.o0" to "Pricka hål på blåsorna för att lätta trycket",
    "q.l16#10.o1" to "Pricka inte blåsorna; lägg en lös steril förband och undvik belastning",
    "q.l16#10.o2" to "Massera kraftigt för att förbättra cirkulationen",
    "q.l16#10.o3" to "Sätt området intill en värmekälla omedelbart",
    "q.l16#10.e" to "Uppvärmd vävnad är extremt skör: blåsor är ett naturligt förband och att punktera dem bjuder in infektion; massage ger mekanisk skada; värme bränner hud utan känsel. Skydda området, håll det torrt, undvik belastning och sök medicinsk vård.",
    "q.l16#11.p" to "Vilka långsiktiga följder kan förfrysning lämna?",
    "q.l16#11.o0" to "Oftast full återhämtning utan följder",
    "q.l16#11.o1" to "Köldkänslighet, avvikande känsel och avvikande svettning, som kan ta månader eller längre att lägga sig",
    "q.l16#11.o2" to "Bara kosmetiska effekter",
    "q.l16#11.o3" to "Bara förlorad idrottsförmåga",
    "q.l16#11.e" to "Förfrysning skadar djup vävnad och nervändar, så även när huden ser återställd ut kan köldkänslighet, domning, stickningar och avvikande svettning bestå länge. Det är precis därför förebyggande av förfrysning är långt viktigare än behandling.",
    "q.l17#0.p" to "Hur ska du slå med ett isverktyg?",
    "q.l17#0.o0" to "Hugga hårt med överarmen",
    "q.l17#0.o1" to "Slå från handleden så att udden går in i isen vertikalt",
    "q.l17#0.o2" to "Hamra ytan med adzen",
    "q.l17#0.o3" to "Skära in i isen horisontellt",
    "q.l17#0.e" to "Ett slag från handleden driver in udden vertikalt och snabbt: den biter lättare och kostar mindre energi. Att hugga med hela armen landar oftast udden i vinkel och krossar ytan till ett skal som inte håller.",
    "q.l17#1.p" to "Vad betyder trepunktskontakt i isklättring?",
    "q.l17#1.o0" to "Två händer och en fot (eller två fötter och en hand) håller tre stabila kontakter medan den fjärde flyttas",
    "q.l17#1.o1" to "Tre personer klättrar tillsammans",
    "q.l17#1.o2" to "Tre knutar delar lasten",
    "q.l17#1.o3" to "Räcket måste ha tre fästpunkter",
    "q.l17#1.e" to "Trepunktskontakt är rörelseregeln som is och klippa delar: håll alltid tre tillförlitliga kontakter och flytta bara en. Då har du fortfarande stöd om en kontakt sviker.",
    "q.l17#2.p" to "Vad är typiskt för WI4?",
    "q.l17#2.o0" to "Låg vinkel där du kan gå upp",
    "q.l17#2.o1" to "Nästan vertikalt med korta vertikala passager, och säkring som kan vara dålig",
    "q.l17#2.o2" to "Bara överhäng",
    "q.l17#2.o3" to "Du behöver bara en vandringsstav",
    "q.l17#2.e" to "WI4 betyder att underlaget är nära vertikalt med korta vertikala avsnitt, och platserna där du kan sätta en skruv är kanske inte bra. Det kräver bättre teknik och bedömning. WI1–WI2 är inlärningsterräng.",
    "q.l17#3.p" to "Varför spara på slagen i isklättring?",
    "q.l17#3.o0" to "För att spara energi",
    "q.l17#3.o1" to "Tillhuggen is blir ett skal som inte håller",
    "q.l17#3.o2" to "För att verktyget slits",
    "q.l17#3.o3" to "För att det stör kamraterna",
    "q.l17#3.e" to "Varje bomt slag lämnar en krater. Att hamra upprepade gånger förstör den bärande isen över en hel panel och tvingar dig att hänga på armarna i stället — en ond cirkel.",
    "q.l17#4.p" to "Varför är isklättring farligare än sportklättring?",
    "q.l17#4.o0" to "För att det är kallare",
    "q.l17#4.o1" to "Isskruvar kan ryckas ut under last, och isen ändras från dag till dag",
    "q.l17#4.o2" to "För att det inte finns säkring",
    "q.l17#4.o3" to "För att du inte kan använda rep",
    "q.l17#4.e" to "En välplacerad kil eller bult i klippa förblir tillförlitlig; en skruv beror på isen själv, och is smälter, blir spröd och får hålrum — en placering som höll i går kan betyda ingenting i dag.",
    "q.l17#5.p" to "Varför få fötterna stabila innan du slår med verktyget?",
    "q.l17#5.o0" to "För att armar tröttas snabbare än ben",
    "q.l17#5.o1" to "Fötterna bär vikten och ger vilan; armarna hjälper bara till",
    "q.l17#5.o2" to "För att isverktyg är dyra",
    "q.l17#5.o3" to "För att det ser mer professionellt ut",
    "q.l17#5.e" to "Armstyrka töms mycket snabbt på is; fötterna kan bära vikt i timmar. Att slå innan fötterna är satta bränner armarna tidigt och ökar faktiskt risken att falla.",
    "q.l17#6.p" to "Under vilka förhållanden blir isen oftast dålig?",
    "q.l17#6.o0" to "Efter en kall natt",
    "q.l17#6.o1" to "Efter stark sol eller stigande temperatur, när isen mjuknar och blir bikakeformad",
    "q.l17#6.o2" to "Precis efter nysnö",
    "q.l17#6.o3" to "När vinden ökar",
    "q.l17#6.e" to "Is är en funktion av temperaturen. Hård morgonis tar exakta placeringar; eftermiddagens slask känns lätt men skruvarna dras ur lättare. Att bedöma is betyder att väga tid på dygnet, exposition, temperatur och solhistorik.",
    "q.l17#7.p" to "Innan du sätter en isskruv, vad ska du bekräfta?",
    "q.l17#7.o0" to "Om skruven har en synlig färg",
    "q.l17#7.o1" to "Om isen där är solid, utan hålrum eller bikakestruktur",
    "q.l17#7.o2" to "Om den blir bra på bild",
    "q.l17#7.o3" to "Hur långt över marken den sitter",
    "q.l17#7.e" to "En skruvs styrka kommer från isen, inte från tekniken. En skruv i ett hålrum eller bikakeis klarar knappt ett fall — detta är den mest grundläggande skillnaden mellan is- och klippssäkring.",
    "q.l17#8.p" to "Underarmarna pumpar igenom på en islängd. Vad ska du göra?",
    "q.l17#8.o0" to "Klättra snabbare för att komma igenom",
    "q.l17#8.o1" to "Ta dig till en ståplats så snart du kan, lägg vikten på fötterna och skaka ut armarna",
    "q.l17#8.o2" to "Greppa hårdare för att hålla dig stabil",
    "q.l17#8.o3" to "Backa omedelbart",
    "q.l17#8.e" to "Pump är ischemi i underarmen; fortsätter du tappar du greppet helt. Rätt svar är att flytta vikten till fötterna medan du fortfarande har kontroll och låta blodet återvända — det är vad «låt inte fötterna vara lata» verkligen betyder i praktiken.",
    "q.l17#9.p" to "[Matchning] Para ihop varje WI-grad för vattenis med dess typiska karaktär.",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.r0" to "Ihållande is kring 60° med möjliga bulor; bra säkring",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.r1" to "Ihållande 60–75°; oftast bra säkring men fysiskt krävande",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.r2" to "Nästan vertikalt med korta vertikala passager; säkringen kan vara dålig",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r3" to "Ihållande vertikalt; dålig säkring och mycket krävande",
    "q.l17#9.e" to "En WI-grad kombinerar tre variabler: vinkel, säkringskvalitet och fysisk kostnad. Ju högre grad, desto mindre utrymme för reträtt eller självräddning — därför är graden bara en referens och dagens is och lagets skick avgör utfallet.",
    "q.l17#10.p" to "[Flerval] Vilken utrustning ska sitta på selen inom räckhåll vid isklättring?",
    "q.l17#10.o0" to "Flera isskruvar",
    "q.l17#10.o1" to "Karbiner och quickdraws",
    "q.l17#10.o2" to "Prusiklina",
    "q.l17#10.o3" to "Ett säkringsdon",
    "q.l17#10.o4" to "En extra sovsäck",
    "q.l17#10.e" to "Isklättring betyder att säkringen byggs medan du rör dig, så allt som ligger begravt i ryggsäcken kan lika gärna inte finnas. Manualens räddningslista — skruvar, karbiner, sling, trissa, prusikar, greppyxa — följer samma logik: allt du kan behöva stannar inom räckhåll.",
    "q.l17#11.p" to "Varför kan en isskruv ryckas ut?",
    "q.l17#11.o0" to "För att skruven är för kort",
    "q.l17#11.o1" to "För att isen själv kan ha hålrum, bikakestruktur eller smälta och inte hålla",
    "q.l17#11.o2" to "För att för mycket är hängt på den",
    "q.l17#11.o3" to "För att skruven är slö",
    "q.l17#11.e" to "Styrkan kommer från isen, inte från placeringen. En skruv i hålrum eller bikakeis klarar knappt ett fall — den väsentliga skillnaden mot klippssäkring och skälet att kontrollera isen innan du placerar.",
    "q.l17#12.p" to "Varför är en isgrad bara en referens?",
    "q.l17#12.o0" to "För att grader är godtyckliga",
    "q.l17#12.o1" to "För att isen ändras dagligen — sol, temperatur och säsong kan förändra samma rutt märkbart",
    "q.l17#12.o2" to "För att grader skiljer mellan länder",
    "q.l17#12.o3" to "För att grader bara beskriver längd",
    "q.l17#12.e" to "Is är en funktion av temperaturen: hård morgonis kräver exakta placeringar, medan mjuk eftermiddagis ser lätt ut men skruvarna dras ur lättare. Samma rutt kan variera mer än en grad — så det du ser framför dig väger alltid tyngre än siffran i föraren.",
    "q.l17#13.p" to "[Ordning] Sätt rytmen med trepunktskontakt i isklättring i rätt ordning.",
    "q.l17#13.o0" to "Läs isen och välj var verktyget och fötterna ska gå",
    "q.l17#13.o1" to "Sparka in frontpiggarna och etablera båda fötterna",
    "q.l17#13.o2" to "Med fötterna stabila, slå med verktyget och bekräfta att det sitter",
    "q.l17#13.o3" to "Med tre punkter stabila, flytta den fjärde",
    "q.l17#13.e" to "Denna ordning förklarar varför «låt inte fötterna vara lata» är isklättringens kärndisciplin: fötterna bär vikt i timmar, armarna hjälper bara. Att slå innan fötterna är satta tömmer armarna tidigt — på brant is är det dödligt.",
    "q.l18#0.p" to "Vid vilka sluttningsvinklar samlas lavinerna mest?",
    "q.l18#0.o0" to "10°–25°",
    "q.l18#0.o1" to "34°–45°",
    "q.l18#0.o2" to "55°–70°",
    "q.l18#0.o3" to "Vertikal is",
    "q.l18#0.e" to "Statistiken visar att de allra flesta laviner inträffar mellan 34° och 45° (96 % ligger inom 30–50°). Det är precis brant nog att glida samtidigt som snön kan ligga kvar — farofönstret, och den vinkel alpina rutter oftast korsar.",
    "q.l18#1.p" to "Varför inträffar de flesta olyckor vid fara nivå 3, betydande?",
    "q.l18#1.o0" to "För att snötäcket är som mest instabilt",
    "q.l18#1.o1" to "För att förhållandena ser acceptabla ut och lättast underskattas",
    "q.l18#1.o2" to "För att alla stannar hemma",
    "q.l18#1.o3" to "För att prognosen är felaktig",
    "q.l18#1.e" to "Paradoxen med nivå 3 är att laviner verkligen är möjliga medan terrängen ser «okej» ut, så många människor går in i lavinterräng. Vid nivå 4 och 5 håller sig de flesta borta, så andelen olyckor sjunker. Det farligaste tillståndet är aldrig det extrema, utan det måttliga som underskattas.",
    "q.l18#2.p" to "Vad är lavintrion?",
    "q.l18#2.o0" to "Sändare (transceiver), sond och spade",
    "q.l18#2.o1" to "Hjälm, rep och sele",
    "q.l18#2.o2" to "Yxa, stegjärn och isskruvar",
    "q.l18#2.o3" to "Tält, sovsäck och liggunderlag",
    "q.l18#2.e" to "Sändaren lokaliserar, sonden preciserar och spaden gräver. Alla tre behövs, och alla tre måste övas om du ska klara en räddning inom det gyllene fönstret på drygt tio minuter.",
    "q.l18#3.p" to "Varför är sluttningar som inte ser branta ut ofta de farligaste?",
    "q.l18#3.o0" to "För att snön är djupare",
    "q.l18#3.o1" to "För att 34–45° är där lavinerna samlas, och människor underskattar systematiskt vinkeln",
    "q.l18#3.o2" to "För att folk rör sig snabbare där",
    "q.l18#3.o3" to "För att solen är starkare",
    "q.l18#3.e" to "Under cirka 30° är det för flackt för flaklaviner; över cirka 50° samlas snön inte. Farofönstret ligger precis i det intervall som känns gångbart — och det är just därför det underskattas.",
    "q.l18#4.p" to "Hur korsar man lavinterräng på rätt sätt?",
    "q.l18#4.o0" to "Låta hela laget gå igenom snabbt tillsammans",
    "q.l18#4.o1" to "Sprida ut, korsa en i taget, sätta en vakt och planera en flyktväg",
    "q.l18#4.o2" to "Ta den kortaste linjen längs dalbotten",
    "q.l18#4.o3" to "Hålla sig där snön är djupast",
    "q.l18#4.e" to "En i taget begränsar risken till en person, och en vakt kan lokalisera och organisera räddning omedelbart. Att alla korsar samtidigt betyder att en utlösning begraver hela laget — det värsta möjliga utfallet.",
    "q.l18#5.p" to "Du hör ett «whumpf» när snötäcket sätter sig. Vad betyder det?",
    "q.l18#5.o0" to "Du trampade bara i ett hål",
    "q.l18#5.o1" to "Det finns ett lättutlöst svagt lager och snötäcket är instabilt",
    "q.l18#5.o2" to "Snön är djup och det går bra att färdas",
    "q.l18#5.o3" to "Snötäcket har stabiliserats",
    "q.l18#5.e" to "Ett «whumpf» är ljudet av snötäcket som sätter sig när ett svagt lager brister. Det är en mycket direkt stabilitetssignal — att fortsätta ut på den sluttningen betyder att du använder dig själv för att testa om det går som flak.",
    "q.l18#6.p" to "Varför är flaklaviner dödligare än lössnölaviner?",
    "q.l18#6.o0" to "För att de är kallare",
    "q.l18#6.o1" to "Ett helt flak släpper på en gång och begraver dig, vilket nästan inte lämnar någon chans till självräddning",
    "q.l18#6.o2" to "För att de låter mer",
    "q.l18#6.o3" to "För att de inträffar oftare",
    "q.l18#6.e" to "Ett flak brister över hela sluttningen på en gång, så du tappar underlaget medan du är kvar på ytan. När du väl är begravd gör snöns vikt och snabba sättning självräddning nästan omöjlig — därför måste kamraträddningen börja omedelbart.",
    "q.l18#7.p" to "Hur ska en sändare bäras och användas?",
    "q.l18#7.o0" to "Var som helst i ryggsäcken går bra",
    "q.l18#7.o1" to "Kontrollera varandras sändarläge före avfärd och öva sökrutinerna regelbundet",
    "q.l18#7.o2" to "Bärs bara av lagledaren",
    "q.l18#7.o3" to "Slås av för att spara batteri",
    "q.l18#7.e" to "En sändare i ryggsäcken är nästan värdelös — under snön kanske armarna inte kan röra sig alls, så den måste bäras på kroppen, oftast på bröstet. Sökrutinen måste också övas, annars hittar du ingen inom de gyllene tio minuterna.",
    "q.l18#8.p" to "Före du går in i lavinterräng, vad är den viktigaste förberedelsen?",
    "q.l18#8.o0" to "Att ha all utrustning räcker",
    "q.l18#8.o1" to "Läsa dagens lavinprognos och fortsätta justera rutt och plan utifrån observationer i fält",
    "q.l18#8.o2" to "Lita helt på personlig erfarenhet",
    "q.l18#8.o3" to "Följa spåren någon annan lämnat",
    "q.l18#8.e" to "Prognosen ger en regional bedömning, fältobservationer ger bevis på sluttningsnivå; du behöver båda. Att följa gamla spår är särskilt farligt — de kan vara timmar gamla och snötäcket har redan förändrats.",
    "q.l18#9.p" to "Enligt statistiken, vilken orsak står för flest dödsfall i alpina sammanhang?",
    "q.l18#9.o0" to "Lavin först, sedan fall",
    "q.l18#9.o1" to "Fall först, sedan lavin",
    "q.l18#9.o2" to "Sjukdom först, sedan stenfall",
    "q.l18#9.o3" to "Hypotermi först, sedan lavin",
    "q.l18#9.e" to "Manualen är tydlig: fall först, lavin sedan. Ordningen spelar roll — laviner fruktar man mest, men det är det vardagliga halket som dödar flest. Rangordna risker efter data, inte efter intryck.",
    "q.l18#10.p" to "Efter en begravning, ungefär hur långt är det gyllene räddningsfönstret?",
    "q.l18#10.o0" to "Ungefär tio till femton minuter",
    "q.l18#10.o1" to "Två timmar",
    "q.l18#10.o2" to "Sex timmar",
    "q.l18#10.o3" to "24 timmar",
    "q.l18#10.e" to "Tio till femton minuter — en tidsskala som betyder att räddningen måste göras av dina kamrater, eftersom organiserad räddning kommer alldeles för sent. Därför måste trion bäras och övas, inte bara packas.",
    "q.l18#11.p" to "[Flerval] Vilka fältsignaler är värda att följa när du bedömer lavinrisken?",
    "q.l18#11.o0" to "Ett «whumpf» när snötäcket sätter sig",
    "q.l18#11.o1" to "Färska sprickor som uppstår i sluttningen",
    "q.l18#11.o2" to "Nyligen nysnö eller tydlig vindtransport",
    "q.l18#11.o3" to "Hörbar sättning och nedsjunkning under foten på väg upp",
    "q.l18#11.o4" to "Cirrusmoln och utmärkt sikt",
    "q.l18#11.e" to "Dessa är direkta bevis på att stabiliteten sjunker just nu. Deras värde är omedelbarheten: prognosen ger en regional bild, medan dessa signaler beskriver sluttningen under dina fötter i detta ögonblick. Du behöver båda.",
    "q.l18#12.p" to "Bilden visar tre delar av samma berg. Tryck på delen med högst lavinrisk.",
    "q.l18#12.e" to "Laviner samlas mellan 34° och 45°. Den flacka sluttningen till vänster (cirka 16°) är för plan för flaklaviner; den branta till höger (cirka 60°) är för brant för att snön ska bygga tjocka flak. Bara mittsluttningen på cirka 40° ligger i fönstret där snö både samlas och kan glida — och det är precis den vinkel klätterleder oftast korsar, vilket är varför den så lätt underskattas.",
    "q.l19#0.p" to "Vad är syftet med att sätta en vändtid?",
    "q.l19#0.o0" to "Att ovillkorligen vända vid den tiden och undvika att tas som gisslan av målet",
    "q.l19#0.o1" to "Att beräkna din klätterhastighet",
    "q.l19#0.o2" to "Att avgöra hur mycket mat du bär",
    "q.l19#0.o3" to "En formalitet",
    "q.l19#0.e" to "En vändtid tar beslutet ur ögonblickets känsla: en regel satt när du var rationell upprätthåller omdömet åt dig när du är trött och ovillig. Det är det mest effektiva verktyget mot toppfeber.",
    "q.l19#1.p" to "Vad orsakar vanligen toppfeber?",
    "q.l19#1.o0" to "Mycket bra väder",
    "q.l19#1.o1" to "Sjunkna kostnader plus grupptryck som förvränger omdömet",
    "q.l19#1.o2" to "Otillräcklig utrustning",
    "q.l19#1.o3" to "För låg höjd",
    "q.l19#1.e" to "Tid, pengar och ansträngning som redan investerats gör det svårt att erkänna att du bör stanna; tystnad eller ömsesidig uppmuntran i laget dämpar tvivlet ytterligare. Att förstå mekanismen är förutsättningen för att sätta objektiva regler i förväg.",
    "q.l19#2.p" to "När ska ett lag avgöra sitt reträttbeslut?",
    "q.l19#2.o0" to "Före avfärd, genom att komma överens om objektiva utlösare och vem som beslutar",
    "q.l19#2.o1" to "På toppen",
    "q.l19#2.o2" to "När faran visar sig, genom improvisation",
    "q.l19#2.o3" to "På plats av den starkaste",
    "q.l19#2.e" to "Att diskutera reträtt när man är trött, hypoxisk och känslomässig tippar nästan alltid mot att fortsätta. Kom överens om objektiva utlösare i förväg — en tid, ett väderomslag, en viss typ av lagtillstånd — och utse vem som har sista ordet.",
    "q.l19#3.p" to "Varför inträffar så många olyckor på nedstigningen?",
    "q.l19#3.o0" to "För att terrängen nedåt är svårare",
    "q.l19#3.o1" to "För att uppmärksamheten sjunker när målet är nått, medan kroppen redan är nära sin gräns",
    "q.l19#3.o2" to "För att vädret alltid är sämre på väg ned",
    "q.l19#3.o3" to "För att utrustningen sviker",
    "q.l19#3.e" to "«Toppen är bara halva resan» betyder egentligen att resans risk frigörs på väg ned. Replag, säkring och tempo på nedstigningen får inte slappna av bara för att du nått toppen.",
    "q.l19#4.p" to "Vad är värdet av att komma överens om reträttbeslutet i förväg?",
    "q.l19#4.o0" to "Det sparar tid",
    "q.l19#4.o1" to "Det tar beslutet bort från trötthet och känslor och låter ditt omdöme före avfärden verka",
    "q.l19#4.o2" to "Det ger ledaren mer auktoritet",
    "q.l19#4.o3" to "Det undviker gräl",
    "q.l19#4.e" to "Att besluta när man är hypoxisk, trött och ovillig tippar nästan alltid mot att fortsätta. Att i förväg enas om objektiva utlösare och beslutsrätt är att låta den lugna versionen av dig besluta åt den utmattade.",
    "q.l19#5.p" to "Varför måste en reträttplan skrivas in i klätterplanen?",
    "q.l19#5.o0" to "För att planen ska se komplett ut",
    "q.l19#5.o1" to "Reträtt kräver utrustning, en rutt och en tidsbudget; improviserade beslut lämnar ingen tid att förbereda",
    "q.l19#5.o2" to "För att klara en inspektion",
    "q.l19#5.o3" to "För att regelverket kräver det",
    "q.l19#5.e" to "Reträtt är en verklig teknisk operation: den kan kräva förankring, firning och förflyttning i mörker. Om planen aldrig budgeterat tid och utrustning för den blir reträtten en högriskimprovisation.",
    "q.l19#6.p" to "När lagmedlemmar är oense om rutten eller vädret, vad är rätt angreppssätt?",
    "q.l19#6.o0" to "Majoritetsröstning",
    "q.l19#6.o1" to "Anta den mest konservativa uppfattningen tills nytt underlag övertygar alla",
    "q.l19#6.o2" to "Låt den starkaste bestämma",
    "q.l19#6.o3" to "Rösta och sluta diskutera",
    "q.l19#6.e" to "I miljöer med hög risk bör den mest konservativa uppfattningen väga tungt. Majoritetsröstning tystar en minoritets berättigade oro — och den vanligaste repliken i olycksutredningar är «någon kände sig illa till mods men ingen sade något».",
    "q.l19#7.p" to "Vilken syn på «med guide är du säker» är korrekt?",
    "q.l19#7.o0" to "En guide gör dig absolut säker",
    "q.l19#7.o1" to "En guide minskar risken men kan inte ta bort objektiva faror; medlemmarna måste fortfarande bedöma",
    "q.l19#7.o2" to "Guider visar bara vägen; säkerheten är din egen sak",
    "q.l19#7.o3" to "Medlemmar behöver inte bedöma något",
    "q.l19#7.e" to "En guides värde är erfarenhet och besluts kvalitet, men laviner, stenfall och väder försvinner inte för att någon leder. Medlemmar som förstår risken, ser farotecken och säger till är själva en del av lagets säkerhetskapacitet.",
    "q.l19#8.p" to "Vad är målförskjutning i bergsbestigning?",
    "q.l19#8.o0" to "Att sänka ruttens svårighetsgrad",
    "q.l19#8.o1" to "Att gradvis luckra upp de säkerhetsstandarder du satt för att nå toppen",
    "q.l19#8.o2" to "Att byta måltopp mitt i resan",
    "q.l19#8.o3" to "Att minska laget",
    "q.l19#8.e" to "Målförskjutning är toppfeberns klassiska signatur: vändtiden glider hela tiden, det acceptabla väderfönstret vidgas hela tiden, symtom tolereras hela tiden. Enda försvaret är att kvantifiera standarderna i förväg, så att en uppluckring blir explicit och måste förklaras för kamraterna.",
    "q.l19#9.p" to "[Flerval] Vad ska en komplett klätterplan innehålla?",
    "q.l19#9.o0" to "Rutt och tidsschema, inklusive vändtiden",
    "q.l19#9.o1" to "Reträttplan och alternativa rutter",
    "q.l19#9.o2" to "Bedömning av lagets tillstånd och rollfördelning",
    "q.l19#9.o3" to "Kommunikationssätt, kontaktperson och nödprocedur",
    "q.l19#9.o4" to "En medie- och publiceringsplan",
    "q.l19#9.e" to "De fyra första är obligatoriska. De som oftast hoppas över är den andra och den fjärde — för de behövs inte när allt går bra. Men en plan är värd sitt pris just när det går dåligt, och då finns ingen tid att skriva den.",
    "q.l19#10.p" to "Varför budgetera reservdagar i en resplan?",
    "q.l19#10.o0" to "För att absorbera förseningar som ett senare väderfönster eller att någon mår dåligt",
    "q.l19#10.o1" to "För att vila mer",
    "q.l19#10.o2" to "För att spara pengar",
    "q.l19#10.o3" to "För att resplanen ska se bekväm ut",
    "q.l19#10.e" to "Högfjällsresor glider nästan alltid: vädret vägrar samarbeta, någon behöver en extra acklimatiseringsdag, anmarschen är långsammare än väntat. Utan marginal tvingar varje försening dig att skära i acklimatiseringen eller förlänga dagsetapperna — båda höjer risken kraftigt.",
    "q.l19#11.p" to "[Ordning] Sätt stegen för att bygga en klätterplan i rimlig ordning.",
    "q.l19#11.o0" to "Fastställ mål och rutt; samla information och historiskt väder",
    "q.l19#11.o1" to "Bedöm lagets förmåga och tid; planera acklimatiseringens rytm",
    "q.l19#11.o2" to "Sätt vändtiden och mätbara reträttutlösare",
    "q.l19#11.o3" to "Skriv reträttplan och nödprocedur, och informera kontaktpersonen hemma",
    "q.l19#11.e" to "Ordningen säger: sätt målet, kontrollera förmågan, dra den röda linjen och behåll sedan utgången. Många gör tvärtom — mål först, utgång sist — och därför hamnar utgången längst ned i listan och blir aldrig ordentligt utformad.",
    "q.l19#12.p" to "Varför underskattas nedstigningstiden så ofta?",
    "q.l19#12.o0" to "För att det går snabbare nedför",
    "q.l19#12.o1" to "För att du är sliten, underlaget kan vara sämre, och du måste fortfarande säkra och plocka utrustning",
    "q.l19#12.o2" to "För att kartorna är felaktiga",
    "q.l19#12.o3" to "För att guiderna stressar dig",
    "q.l19#12.e" to "Uppstigningen kan ha tagit sex timmar, men nedstigningen tar ofta längre: mindre energi, mjukare eller isigare snö, sämre sikt och kanske firningar och utrustningshämtning. Att uppskatta nedstigningen från uppstigningen är ett av de vanligaste planeringsfelen.",
    "q.l19#13.p" to "Varför skriva ut kommunikation och kontaktavtal i planen?",
    "q.l19#13.o0" to "För protokollet",
    "q.l19#13.o1" to "För att de hemma måste veta var man ska söka och när man ska börja om du försvinner",
    "q.l19#13.o2" to "För att rapportera till företaget",
    "q.l19#13.o3" to "För att uppfylla tillståndskrav",
    "q.l19#13.e" to "Det svåraste i sök- och räddningsarbete är att inte veta var personen är. Resplan, rutt, alternativ och tider för avstämning är det som pressar en sökning från dagar till timmar — och den informationen kan bara lämnas före avfärd.",
    "q.l19#14.p" to "Hur påverkar lagstorleken planen?",
    "q.l19#14.o0" to "Storleken är irrelevant för planeringen",
    "q.l19#14.o1" to "Fler personer betyder långsammare rörelse, tyngre logistik och svårare att synkronisera acklimatiseringen",
    "q.l19#14.o2" to "Fler personer är säkrare, så ingen justering behövs",
    "q.l19#14.o3" to "Fler personer går snabbare",
    "q.l19#14.e" to "Ett stort lag delar personal och resurser, men betalar med hastighet och flexibilitet: alla har sin egen rytm och laget kan bara röra sig i den långsammastes takt. Lagstorleken hör hemma i din tidsuppskattning, inte i ett klagomål efteråt.",
    "q.l19#15.p" to "Fyll i: högfjällsresor budgeterar vanligen cirka ( ) % reservdagar.",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20–30",
    "q.l19#15.a5" to "tjugo",
    "q.l19#15.e" to "Den vanliga rekommendationen är 20–30 % marginal. En tiodagarsresa bör till exempel planeras som tolv eller tretton dagar för proviant, tillstånd och avfärd — det ser överförsiktigt ut tills man jämför med hur ofta förseningar faktiskt inträffar.",
    "q.l20#0.p" to "Vad är den första principen vid räddning?",
    "q.l20#0.o0" to "Flytta den skadade så snabbt som möjligt",
    "q.l20#0.o1" to "Säkra platsen så att du inte skapar en andra skadad",
    "q.l20#0.o2" to "Fotografera platsen först",
    "q.l20#0.o3" to "Ge den skadade vatten först",
    "q.l20#0.e" to "Bland stenfall, laviner, sprickor eller brant terräng gör brådskan till den skadade ofta räddaren till en andra skadad och halverar den tillgängliga arbetskraften. Att bedöma platsen är första steget och det du inte kan hoppa över.",
    "q.l20#1.p" to "Var börjar rätt nödsekvens?",
    "q.l20#1.o0" to "Säkra platsen först, bedöm sedan skadorna",
    "q.l20#1.o1" to "Flytta den skadade till säkerhet först",
    "q.l20#1.o2" to "Leta efter mat och vatten",
    "q.l20#1.o3" to "Bygg ett repsystem",
    "q.l20#1.e" to "Standardsekvensen är säkerhet, bedömning, larm, behandling, transport. Att hoppa över säkerhetsbedömningen och gå rakt till den skadade är det vanligaste räddningsfelet.",
    "q.l20#2.p" to "Varför spelar förebyggande långt större roll än räddning på höjd?",
    "q.l20#2.o0" to "För att räddning är dyr",
    "q.l20#2.o1" to "För att räddning begränsas av väder, syre och personal och ofta inte hinner fram",
    "q.l20#2.o2" to "För att räddningsteamen är ovilliga",
    "q.l20#2.o3" to "För att det inte finns mobiltäckning",
    "q.l20#2.e" to "Höjden försämrar båda sidor: helikoptrar begränsas av turbulens och höjd, markteam behöver timmar för att komma fram, och en skadad försämras snabbare i hypoxi och kyla. Det tidsgapet är den enda räddningsresurs du faktiskt har.",
    "q.l20#3.p" to "Varför tar bergsräddning ofta timmar eller dygn?",
    "q.l20#3.o0" to "För att teamen inte vill gå",
    "q.l20#3.o1" to "Hårda begränsningar från väder, syre, kommunikation och personal; helikoptrar begränsas av turbulens och höjd",
    "q.l20#3.o2" to "För att avstånden är för stora",
    "q.l20#3.o3" to "För att det kostar för mycket",
    "q.l20#3.e" to "På höjd kämpar en helikopter med lyftkraft och turbulens, och ett markteam behöver timmar för att nå dig. Gapet betyder en sak: högt uppe är du ditt eget första räddningsteam.",
    "q.l20#4.p" to "Vad är poängen med att lämna resplan och kontaktperson?",
    "q.l20#4.o0" to "En formalitet",
    "q.l20#4.o1" to "Om du försvinner vet räddningen var den ska söka, vilket kraftigt förkortar sökningen",
    "q.l20#4.o2" to "För att göra reseersättningar enklare",
    "q.l20#4.o3" to "För att följa reglerna",
    "q.l20#4.e" to "Det svåraste i sök- och räddningsarbete är att inte veta var personen är. Resplan, rutt, alternativa planer och kontaktavtal är det som pressar en sökning från dagar till timmar.",
    "q.l20#5.p" to "Vid bedömning av en skadad, vad behandlas först?",
    "q.l20#5.o0" to "Spjäla frakturer",
    "q.l20#5.o1" to "Livshotande problem som luftvägar och andning",
    "q.l20#5.o2" to "Dokumentera skadorna i detalj",
    "q.l20#5.o3" to "Rengöra synliga sår",
    "q.l20#5.e" to "Bedömningen följer «livshot först»: luftvägar, andning och cirkulation före frakturer och sår som inte är omedelbart dödliga. Får du ordningen fel betyder allt annat mycket mindre.",
    "q.l20#6.p" to "Varför är isolering en kritisk del av första hjälpen på höjd?",
    "q.l20#6.o0" to "För att den skadade blir bekvämare",
    "q.l20#6.o1" to "För att en orörlig skadad snabbt förlorar värme, vilket förvärrar skadan",
    "q.l20#6.o2" to "För att regelverket kräver det",
    "q.l20#6.o3" to "För att det blir lättare att bära",
    "q.l20#6.e" to "I kyla och hypoxi tappar en skadad som inte kan röra sig snabbt värmeproduktionen. Hypotermi fördjupar chocken och döljer symtom, så isolering mot marken, vindskydd och byte av blöta kläder är lika viktigt som att stoppa blödning.",
    "q.l20#7.p" to "Vad ska lagets nödplan vara när kommunikationen fallerar?",
    "q.l20#7.o0" to "Vänta på platsen tills kontakten återupptas",
    "q.l20#7.o1" to "I förväg komma överens om en mötesplats, en tidsgräns för förlorad kontakt och uppföljande åtgärder",
    "q.l20#7.o2" to "Dela upp sig och söka omedelbart",
    "q.l20#7.o3" to "Alla går ner på en gång",
    "q.l20#7.e" to "Att tappa kommunikationen i bergen är normalt, inte ett undantag. Att i förväg enas om vad som gäller om ni inte hört av er vid en viss tid förhindrar panik på plats och säger till kontaktpersonen när larmet ska gå.",
    "q.l20#8.p" to "Vilken är rätt hållning till träning i första hjälpen och räddning?",
    "q.l20#8.o0" to "Att titta på en instruktionsvideo och memorera stegen räcker",
    "q.l20#8.o1" to "Du måste öva praktiskt regelbundet; läsning räcker inte in i en verklig situation",
    "q.l20#8.o2" to "Bara ledaren behöver det",
    "q.l20#8.o3" to "Det är bara för professionella räddare",
    "q.l20#8.e" to "Första hjälpen och räddning är starkt procedurella färdigheter, och under press faller du tillbaka till den nivå du faktiskt tränat på. Läsning bygger ramverket; bara upprepad övning håller handlingarna korrekta när du är rädd.",
    "q.l20#9.p" to "[Ordning] Sätt standardsekvensen för bedömning och behandling av skadad i ordning.",
    "q.l20#9.o0" to "Säkra platsen så att du inte skapar en andra skadad",
    "q.l20#9.o1" to "Bedöm medvetande, luftvägar, andning och cirkulation",
    "q.l20#9.o2" to "Behandla omedelbara livshot: blödning, isolering, spjäla",
    "q.l20#9.o3" to "Larma och organisera transport, eller invänta professionell räddning",
    "q.l20#9.e" to "Steg ett och fyra är de som oftast hoppas över — under stress springer folk rakt till den skadade. Men en osäker plats gör räddaren till en andra skadad och halverar din arbetskraft, och utan larm finns ingen backup för något av det som följer.",
    "q.l20#10.p" to "[Flerval] Vilken nyckelinformation ska ett larm innehålla?",
    "q.l20#10.o0" to "Exakt plats (koordinater eller ett igenkännbart landmärke)",
    "q.l20#10.o1" to "Antal skadade, medvetande och andningsstatus",
    "q.l20#10.o2" to "Terräng och väder på platsen",
    "q.l20#10.o3" to "Tillgängligt kommunikationssätt och tider för avstämning",
    "q.l20#10.o4" to "Den skadades klätter-CV",
    "q.l20#10.e" to "Dessa fyra avgör vad som skickas, hur mycket och på vilken väg. En vag plats slösar timmar, okända skador betyder fel utrustning, och okänt väder kan sätta räddningsteamet i fara också. Att larma är en kommunikationsfärdighet värd att öva.",
    "q.l20#11.p" to "Varför är helikopterräddning på höjd ofta omöjlig?",
    "q.l20#11.o0" to "För att det är för dyrt",
    "q.l20#11.o1" to "För att tunn luft minskar lyftkraft och nyttolast, turbulensen är kraftig och väderfönstren korta",
    "q.l20#11.o2" to "För att piloter vägrar flyga dit",
    "q.l20#11.o3" to "För att det inte finns luftleder på höjd",
    "q.l20#11.e" to "En helikopters lyftkraft kommer från luften, och på höjd är luften tunn, vilket direkt begränsar hur mycket den kan lyfta och hur högt den kan arbeta. Lägg till turbulent bergsluft och snabbt skiftande väder, och det flygbara fönstret kan vara bara några tiotals minuter. Därför kan räddning inte vara din plan.",
    "q.l20#12.p" to "[Matchning] Para ihop varje första hjälpen-åtgärd med när den tillämpas.",
    "q.l20#12.l0" to "Isolering",
    "q.l20#12.r0" to "Prioritet för varje skadad på höjd, för att hindra hypotermi att fördjupa chocken",
    "q.l20#12.l1" to "Blödningskontroll",
    "q.l20#12.r1" to "Första åtgärd vid öppet sår eller blödning från extremitet",
    "q.l20#12.l2" to "Spjäla",
    "q.l20#12.r2" to "Misstänkt fraktur eller ledskada, för att undvika ytterligare skada vid förflyttning",
    "q.l20#12.l3" to "Syre",
    "q.l20#12.r3" to "Andningssvårigheter, tydligt låg mättnad eller misstänkt lungödem",
    "q.l20#12.e" to "Alla fyra är basåtgärder på höjd, inte specialistprocedurer. Gemensamt är att de inte kräver komplex utrustning men väl rätt ordning — isolering kommer till exempel ofta sent i allmän första hjälpen men är en prioritet högt uppe.",
    "q.l20#13.p" to "Varför bedöma risken i själva räddningen?",
    "q.l20#13.o0" to "För att räddning är tröttande",
    "q.l20#13.o1" to "För att räddningen kan sätta fler människor i fara och sänka de totala överlevnadschanserna",
    "q.l20#13.o2" to "För att försäkringen kräver det",
    "q.l20#13.o3" to "För att regelverket kräver det",
    "q.l20#13.e" to "Räddningsbeslut är resursfördelning: om du skadar två räddare på väg till den skadade går du från en skadad och två räddare till tre skadade och ingen. Det är inte kyla, det är aritmetiken som maximerar den totala överlevnaden.",
    "q.l20#14.p" to "När ska självräddning upphöra och professionell räddning inväntas?",
    "q.l20#14.o0" to "Fortsätt självrädda så länge du har kraft",
    "q.l20#14.o1" to "När självräddning riskerar ytterligare skador, eller förhållandena överstiger lagets förmåga",
    "q.l20#14.o2" to "Bara när du är helt utmattad",
    "q.l20#14.o3" to "Sluta aldrig självrädda",
    "q.l20#14.e" to "Självräddning handlar om att köpa tid, inte om att chansa. När fortsättning kan skada den skadade eller räddarna värre, eller när storm gör rörelse farligare än att stanna, är det bättre att hålla situationen och invänta förstärkning.",
    "q.l20#15.p" to "Fyll i: i SAMPLE-bedömningen står E för ( ).",
    "q.l20#15.a0" to "händelse",
    "q.l20#15.a1" to "Händelse",
    "q.l20#15.a2" to "det som hände",
    "q.l20#15.a3" to "incident",
    "q.l20#15.e" to "E står för Event, vad som hände. Denna punkt undervärderas ofta: mekanismen (hur fallet gick till, om huvudet träffades, hur länge begravningen varade) pekar direkt på de sannolika skadorna och är en nyckel i bedömningen.",
    "q.l21#0.p" to "I ett treskiktssystem, vad är underställets huvuduppgift?",
    "q.l21#0.o0" to "Stänga ute vind och snö",
    "q.l21#0.o1" to "Flytta svett bort från huden och hålla dig torr",
    "q.l21#0.o2" to "Ge det mesta av värmen",
    "q.l21#0.o3" to "Förvara reservdelar",
    "q.l21#0.e" to "Underställets kärnfunktion är fukttransport. Det ligger mot huden, och om det förblir fuktigt spelar det ingen roll hur många lager du har utanpå — värmen fortsätter att dras bort, och därför kallas understället den andra huden.",
    "q.l21#1.p" to "Varför är fleece mer tillförlitligt än dun i våta förhållanden?",
    "q.l21#1.o0" to "För att fleece är tjockare",
    "q.l21#1.o1" to "För att polyesterfiber är naturligt hydrofob och isolerar även vått",
    "q.l21#1.o2" to "För att fleece är billigare",
    "q.l21#1.o3" to "För att dun inte kan bäras som innerlager",
    "q.l21#1.e" to "Fleece är gjord av plastfiber (polyester) som nästan inte absorberar något, så den fångar fortfarande ett luftlager och isolerar när den är fuktig. Dun faller ihop och tappar resningen när det blir vått — därför måste dun hållas strikt torrt.",
    "q.l21#2.p" to "Vilken fill power rekommenderas för en dunjacka för extrem högfjällskyla?",
    "q.l21#2.o0" to "Under 500",
    "q.l21#2.o1" to "Runt 600",
    "q.l21#2.o2" to "800 fill power eller mer",
    "q.l21#2.o3" to "Fill power spelar ingen roll",
    "q.l21#2.e" to "Ju högre fill power, desto mer luft fångar samma vikt dun och desto effektivare isolering. 800 och mer är den vanliga rekommendationen för högfjällsresor, tillsammans med huva och utan syntetfyllning.",
    "q.l21#3.p" to "Vad är skaljackans kärnfunktion?",
    "q.l21#3.o0" to "Ge det mesta av värmen",
    "q.l21#3.o1" to "Vattentät, vindtät och andande, med huva som ryms över hjälmen",
    "q.l21#3.o2" to "Transportera bort svett",
    "q.l21#3.o3" to "Lägga till vikt för träningseffekt",
    "q.l21#3.e" to "Skalet stänger ute vind, regn och snö samtidigt som det släpper ut fukten du producerar. Vid dålig andning kondenserar svettångan på innerlagren — du skapar din egen fuktiga miljö.",
    "q.l21#4.p" to "Vilken handske i systemet är särskilt för att hantera pekskärmar?",
    "q.l21#4.o0" to "Tunna fleecehandskar",
    "q.l21#4.o1" to "En vindtät och nötningsbeständig handske med bra pekskärmskänslighet",
    "q.l21#4.o2" to "Tjocka isolerade guidehandskar",
    "q.l21#4.o3" to "Toppvantar",
    "q.l21#4.e" to "Att hantera telefon, GPS eller kamera på höjd kräver en handske som både är vindtät och pekskärmskänslig. Att ta av handskarna för att trycka är en av de vanligaste utlösarna av förfrysning — bär hellre ett extra par just för detta.",
    "q.l21#5.p" to "Vilket påstående om värmepåsar för händer och fötter är korrekt?",
    "q.l21#5.o0" to "De kan fästas var som helst på utsidan av strumpan",
    "q.l21#5.o1" to "Använd dem bara i slutna utrymmen som handskar eller inuti kängan; i ventilerad luft kan de nå cirka 74 °C",
    "q.l21#5.o2" to "Ju närmare huden, desto bättre",
    "q.l21#5.o3" to "De kan fästas på utsidan av mössan",
    "q.l21#5.e" to "Värmepåsar bygger på begränsad lufttillförsel för att styra temperaturen. I ventilerad luft reagerar de våldsamt och kan nå ungefär 74 °C, tillräckligt för brännskada. De hör alltså hemma i slutna utrymmen — handskar, inuti kängan — och aldrig direkt mot huden eller på en öppen yta.",
    "q.l21#6.p" to "Varför rekommenderas isolerande jackor och dunjackor med huva?",
    "q.l21#6.o0" to "För att de ser bättre ut",
    "q.l21#6.o1" to "För att de är mer mångsidiga och minskar värmeförlusten från huvudet markant",
    "q.l21#6.o2" to "För att de är lättare att packa",
    "q.l21#6.o3" to "För att varianter med huva är lättare",
    "q.l21#6.e" to "Huvudet är en stor källa till värmeförlust, och huvan är den lättaste isolering som finns direkt på kärnan. En jacka med huva kan tas på direkt i lägret, på rasten eller när temperaturen faller plötsligt; utan huva tvingas du bära en separat mössa, vilket är mer besvär och mer vikt.",
    "q.l21#7.p" to "[Flerval] Vilka regler för användning och förvaring av dunjacka är korrekta?",
    "q.l21#7.o0" to "Håll den strikt torr; blir den fuktig tappar den snabbt isolering",
    "q.l21#7.o1" to "Förvara den torr",
    "q.l21#7.o2" to "I extrem kyla, välj en variant med huva och utan syntetfyllning",
    "q.l21#7.o3" to "Ju högre fill power, desto varmare vid samma vikt",
    "q.l21#7.o4" to "Förvara den långsiktigt i en kompressionspåse för att spara plats",
    "q.l21#7.e" to "Dun isolerar genom att fånga luft och faller ihop när det blir vått. Därför föredras fleece (hydrofob polyester) som arbetande mellanlager i våta förhållanden, medan dunet hålls som kärnisolering för torr miljö.",
    "q.l21#8.p" to "Vilken är en rimlig specifikation för solskydd på höjd?",
    "q.l21#8.o0" to "SPF 15, en vanlig lotion räcker",
    "q.l21#8.o1" to "Hög halt zinkoxid, nivå SPF 50",
    "q.l21#8.o2" to "Under SPF 30 andas bättre",
    "q.l21#8.o3" to "Vilken produkt som helst med solskydd, oavsett siffra",
    "q.l21#8.e" to "UV är intensivt på höjd och snöreflektionen ger en andra dos, så vanligt solskydd slutar snabbt att räcka. Hög halt zinkoxid och SPF 50 är den vanliga rekommendationen, och det måste läggas på igen enligt schema eftersom svett, torkande och friktion bryter ner skyddet.",
    "q.l21#9.p" to "Vad är viktigt när du väljer läppbalsam för utomhusbruk?",
    "q.l21#9.o0" to "Ju billigare desto bättre",
    "q.l21#9.o1" to "Rik på zink, något svettresistent, med SPF 30–50",
    "q.l21#9.o2" to "Återfuktande räcker",
    "q.l21#9.o3" to "Mentol känns svalare",
    "q.l21#9.e" to "Läpphuden är tunn och har nästan inget melaninskydd, så den bränns och spricker lätt på höjd. Zink ger fysiskt skydd, och svettresistens håller den kvar genom svettning, ätande och drickande — den minsta utrustningsdetaljen, den oftast förbisedda och den som mest påverkar hur resan känns.",
    "q.l22#0.p" to "Vilken är den mest grundläggande utrustningen för att bygga ett sprickräddningssystem?",
    "q.l22#0.o0" to "Prusiköglor (accessory cord)",
    "q.l22#0.o1" to "Kikare",
    "q.l22#0.o2" to "En extra sovsäck",
    "q.l22#0.o3" to "Vandringsstavar",
    "q.l22#0.e" to "Prusiköglor används för att knyta friktionsknutar och är kärnan i ett 3:1-hissystem. Utan dem har du bara 1:1-drag med bara händerna — och en person kan nästan aldrig hissa upp en kamrat ur en spricka med rå kraft.",
    "q.l22#1.p" to "I högfjällsområden, vad är oftast det mest tillförlitliga sättet att larma?",
    "q.l22#1.o0" to "Mobiltelefonsignal",
    "q.l22#1.o1" to "Satellittelefon eller GPS-tracker",
    "q.l22#1.o2" to "Ropa",
    "q.l22#1.o3" to "Tända en rökig eld",
    "q.l22#1.e" to "De flesta bergsområden saknar mobiltäckning. En satellittelefon ger direktsamtal och meddelanden, och en GPS-tracker låter omvärlden följa din position — båda ska ordnas före avfärd, inte i berget.",
    "q.l22#2.p" to "Vilken ljusstyrka rekommenderas för en reservpannlampa?",
    "q.l22#2.o0" to "Under 100 lumen",
    "q.l22#2.o1" to "200 lumen räcker",
    "q.l22#2.o2" to "400 lumen eller mer",
    "q.l22#2.o3" to "Ljusstyrkan spelar ingen roll",
    "q.l22#2.e" to "En pannlampa används för att röra sig i tältet på natten och för starter före gryningen (toppstötar börjar oftast tidigt). I vind, snö, dimma och när du måste urskilja rutten påverkar tillräcklig ljusstyrka kvaliteten i dina bedömningar direkt. Vädertåliga modeller är klart bättre i dåliga förhållanden.",
    "q.l22#3.p" to "Vilket är nyckelkravet när du väljer alpin sele?",
    "q.l22#3.o0" to "Så lätt som möjligt, oavsett storlek",
    "q.l22#3.o1" to "Tillräckligt stor i midja och ben för att rymmas över yttersta klädlagret",
    "q.l22#3.o2" to "Måste ha flera utrustningsöglor",
    "q.l22#3.o3" to "En iögonfallande färg",
    "q.l22#3.e" to "På höjd har du oftast skrymmande kläder, och selen måste ändå sitta rätt över dem. En sele som dragits ut till sista läget bara för att stängas över tjocka lager är en vanlig och farlig felkonfiguration.",
    "q.l22#4.p" to "Vad använder en höjdmätarklockas stormlarm för att upptäcka oväder?",
    "q.l22#4.o0" to "Satellitbilder av moln",
    "q.l22#4.o1" to "Ett snabbt fall i lufttrycket under kort tid",
    "q.l22#4.o2" to "Mätning av vindhastighet",
    "q.l22#4.o3" to "Ett plötsligt temperaturfall",
    "q.l22#4.e" to "Ett snabbt tryckfall är förebudet till försämrat väder. En höjdmätarklocka varnar genom att kontinuerligt övervaka tryckförändringen, vilket är mycket praktiskt på höjd — eftersom hur väderfönstret förskjuts ofta är den avgörande variabeln för en resa.",
    "q.l22#5.p" to "[Matchning] Para ihop varje karbinform med dess mest lämpliga användning.",
    "q.l22#5.l0" to "HMS päronformad",
    "q.l22#5.r0" to "Bred öppning; tar italienskt halvslag vid firning, mest mångsidig",
    "q.l22#5.l1" to "D-formad",
    "q.l22#5.r1" to "Ofta i par med en trissa i räddningssystem",
    "q.l22#5.l2" to "X-formad",
    "q.l22#5.r2" to "Symmetrisk, enkel låsning, lätt att klicka i",
    "q.l22#5.l3" to "B-formad",
    "q.l22#5.r3" to "Den grundläggande karbinen för alla slags tillfälliga kopplingar",
    "q.l22#5.e" to "Varje form har sin styrka: HMS öppnar brett nog för halvslag och firning, D är stark och tar trissa bra, X är symmetrisk och lätt att hantera, B är basmodellen för allt. Att välja karbin handlar inte om vilken som är «starkast», utan om mekanismen passar uppgiften.",
    "q.l22#6.p" to "Vad varnar handboken särskilt för vid användning av greppyxa?",
    "q.l22#6.o0" to "Att använda den i våta förhållanden",
    "q.l22#6.o1" to "Att föra greppyxan alltför nära den fasta änden (en knut)",
    "q.l22#6.o2" to "Att manövrera den med en hand",
    "q.l22#6.o3" to "Att använda den på snö",
    "q.l22#6.e" to "För du greppyxan ända intill en knut eller fast punkt kan den inte flyttas längre samtidigt som den är svår att snabbt lossa, och du sitter fast där — varken upp eller loss. Den sortens låsning är mycket farlig när du behöver justera snabbt, så lös den medan du har marginal.",
    "q.l22#7.p" to "Vilket påstående om valet mellan fasta rep och replag är korrekt?",
    "q.l22#7.o0" to "Fasta rep är alltid säkrare än replag",
    "q.l22#7.o1" to "Stora lag använder ofta fasta rep; små lag eller tekniska toppar är effektivare i replag",
    "q.l22#7.o2" to "Replag passar bara på snösluttningar",
    "q.l22#7.o3" to "Fasta rep är bara för nedstigning",
    "q.l22#7.e" to "Fasta rep höjer den totala säkerheten men kräver fler personer och mer utrustning och tar längre tid att rigga. Ett litet, effektivt lag eller en teknisk topp tjänar ofta på replag. Det är ett skolboksexempel på «inget enda rätt svar, bara rätt matchning».",
    "q.l22#8.p" to "[Flerval] Vilka av dessa är kommunikations- och navigationsenheter för hög höjd?",
    "q.l22#8.o0" to "Satellittelefon",
    "q.l22#8.o1" to "Tvåvägsradio",
    "q.l22#8.o2" to "GPS-tracker",
    "q.l22#8.o3" to "Höjdmätarklocka med barometer",
    "q.l22#8.o4" to "Kikare",
    "q.l22#8.e" to "De fyra gör olika saker: satellittelefonen för att larma utåt, radion för samordning inom laget, GPS-trackern så att omvärlden vet var du är, och höjdmätarklockan för tryck- och höjdtrender. Riskerna på höjd är just att inte kunna larma och inte veta var man är — dessa enheter träffar de två direkt.",
    "q.l22#9.p" to "Varför måste hjälmen ta en pannlampsfästning?",
    "q.l22#9.o0" to "För visuell enhetlighet",
    "q.l22#9.o1" to "För att toppstötar oftast börjar före soluppgången, och pannlampan måste sitta stabilt på huvudet",
    "q.l22#9.o2" to "För att minska pannlampans vikt",
    "q.l22#9.o3" to "För att öka hjälmens styrka",
    "q.l22#9.e" to "Toppdagen börjar oftast tidigt, och pannlampan är den enda ljuskällan; med hjälm på måste den fästas på hjälmen för att peka stadigt. En lampa som vinglar eller lossnar under rörelse gör att du inte ser dina fotsteg — en verklig risk i teknisk terräng.",
    "q.m01#0.p" to "Ungefär hur mycket faller lufttemperaturen per 1 000 m stigning?",
    "q.m01#0.o0" to "Cirka 1,5 °C",
    "q.m01#0.o1" to "Cirka 3 °C",
    "q.m01#0.o2" to "Cirka 6,5 °C",
    "q.m01#0.o3" to "Cirka 10 °C",
    "q.m01#0.e" to "Temperaturen faller cirka 6,5 °C per 1 000 m — den vertikala temperaturgradienten. Den förklarar snögränsens höjd och varför en topp på 5 000 m är snötäckt även på sommaren.",
    "q.m01#1.p" to "Vad är den grundläggande orsaken till hypoxi på höjd?",
    "q.m01#1.o0" to "Andelen syre i luften är lägre",
    "q.m01#1.o1" to "Lufttrycket faller, så syrgasets partialtryck i varje andetag sjunker",
    "q.m01#1.o2" to "Ultraviolett ljus bryter ner syret",
    "q.m01#1.o3" to "Luften blir tunnare och syret ersätts av andra gaser",
    "q.m01#1.e" to "Detta är en mycket vanlig missuppfattning. Syret utgör fortfarande cirka 21 % av luften på höjd — andelen ändras inte. Det som ändras är trycket: vid lägre tryck finns färre syremolekyler i samma volym, så partialtrycket faller och kroppen får mindre syre.",
    "q.m01#2.p" to "[Flerval] Vilka av dessa är typiska drag i högfjällsmiljö?",
    "q.m01#2.o0" to "Lågt tryck och lågt partialtryck för syre",
    "q.m01#2.o1" to "Låg temperatur med stor dygnsvariation",
    "q.m01#2.o2" to "Markant starkare ultraviolett strålning",
    "q.m01#2.o3" to "Extremt torr luft",
    "q.m01#2.o4" to "Betydligt lägre andel syre i luften",
    "q.m01#2.e" to "De fyra första stämmer, och de förstärker varandra: kyla plus hypoxi gör att kroppen har svårt både att producera värme och att få syre; torrhet plus stark UV skadar luftvägar, hud och ögon snabbare. Utrustning och resplan måste täcka alla fyra samtidigt.",
    "q.m01#3.p" to "Lufttrycket vid havsnivå är cirka 1 013 hPa. Vad är trycket på 5 000 m?",
    "q.m01#3.o0" to "Cirka 900 hPa",
    "q.m01#3.o1" to "Cirka 700 hPa",
    "q.m01#3.o2" to "Cirka 540 hPa",
    "q.m01#3.o3" to "Cirka 300 hPa",
    "q.m01#3.e" to "På 5 000 m är trycket ungefär hälften av havsnivån. Varje andetag innehåller därför ungefär hälften så många syremolekyler — kroppen kompenserar med högre andningsfrekvens och puls, och det är den fysiska orsaken till att du blir andfådd och går långsammare högt uppe.",
    "q.m01#4.p" to "Fyll i: temperaturen faller cirka ( ) °C per 1 000 m stigning.",
    "q.m01#4.a0" to "6,5",
    "q.m01#4.a1" to "sex komma fem",
    "q.m01#4.e" to "6,5 °C per 1 000 m. Siffran är genuint användbar i planeringen: att gå från ett basläger på 3 000 m till 5 000 m innebär ungefär 13 °C kallare, vilket direkt avgör hur tjock dunjacka och sovsäck måste vara.",
    "q.m01#5.p" to "[Ordning] Sätt orsakskedjan för höjdhypoxi i ordning.",
    "q.m01#5.o0" to "Lufttrycket faller och sänker partialtrycket för det syre du andas in",
    "q.m01#5.o1" to "Syremättnaden i artärblodet faller",
    "q.m01#5.o2" to "Kroppen kompenserar med högre andning och puls",
    "q.m01#5.o3" to "Långvarig hypoxi kan leda till höjdsjuka",
    "q.m01#5.e" to "Denna kedja är höjdmedicinens skelett: miljö, fysiologi, kompensation, dekompensation. När du ser den upphör AMS, HACE och HAPE att vara separata fakta och blir olika stadier i en kedja.",
    "q.m01#6.p" to "Vad är reflektionen från nysnö?",
    "q.m01#6.o0" to "Cirka 20 %",
    "q.m01#6.o1" to "Cirka 40 %",
    "q.m01#6.o2" to "Cirka 60 %",
    "q.m01#6.o3" to "Cirka 80–90 %",
    "q.m01#6.e" to "Nysnö reflekterar ungefär 80–90 % av solstrålningen. UV-exponeringen på ett snöfält blir därför nästan dubbel: direkt ovanifrån plus reflektion från ytan. Därför är snöblindhet och svåra solbrännskador så vanliga i bergen.",
    "q.m01#7.p" to "Varför är solskydd på höjd obligatoriskt och inte valfritt?",
    "q.m01#7.o0" to "För att solen är närmare jorden där",
    "q.m01#7.o1" to "För att UV ökar med höjden och snön reflekterar det tillbaka mot ansiktet",
    "q.m01#7.o2" to "För att ozonlagret är tunnare så synligt ljus är starkare",
    "q.m01#7.o3" to "För att kyla försvagar hudens motstånd",
    "q.m01#7.e" to "UV-intensiteten ökar cirka 10–12 % per 1 000 m, och snön ger ytterligare 80–90 % reflektion. Tillsammans överstiger dosen långt en låglandspunkt på samma latitud. Solskydd, läppbalsam och UV400-glasögon är utrustning, inte tillbehör.",
    "q.m01#8.p" to "Torr luft på höjd har en lätt förbisedd konsekvens. Vilken?",
    "q.m01#8.o0" to "Bättre hud",
    "q.m01#8.o1" to "Omärkbar vätskeförlust via andning och svettning, vilket förvärrar uttorkning och höjdsymtom",
    "q.m01#8.o2" to "Större aptit",
    "q.m01#8.o3" to "Djupare sömn",
    "q.m01#8.e" to "Torr luft plus snabbare andning drar kontinuerligt fukt från luftvägarna, och du känner ofta ingen törst alls. Uttorkning gör blodet tjockare och förvärrar känslan av hypoxi och huvudvärken — så regelbundet drickande är en del av acklimatiseringen, inte en eftertanke.",
    "q.m01#9.p" to "[Flerval] Vilka av dessa skador orsakas direkt av högfjällsmiljön?",
    "q.m01#9.o0" to "Solbränna",
    "q.m01#9.o1" to "Snöblindhet",
    "q.m01#9.o2" to "Uttorkning",
    "q.m01#9.o3" to "Spruckna läppar",
    "q.m01#9.o4" to "Stukad fotled",
    "q.m01#9.e" to "De fyra första är miljöskador, och de har ett gemensamt drag: de är nästan helt förebyggbara. Till skillnad från laviner är de inte svåra att förutse — de beror enbart på utrustning och vanor, så ser man dem i ett lag har oftast något gått fel i förberedelsen.",
    "q.m01#10.p" to "Vilket påstående om luftens sammansättning på höjd är korrekt?",
    "q.m01#10.o0" to "Andelen syre faller när man kommer högre",
    "q.m01#10.o1" to "Andelen är ungefär densamma; lägre tryck sänker partialtrycket",
    "q.m01#10.o2" to "Andelen kväve ökar med höjden",
    "q.m01#10.o3" to "Syre trängs undan av andra gaser på höjd",
    "q.m01#10.e" to "I troposfären är blandningen i praktiken konstant (cirka 21 % syre, 78 % kväve). Det som ändras med höjden är trycket — hur många molekyler som finns i samma andetag. Får du den distinktionen klar blir många utrustnings- och fysiologifrågor lätta.",
    "q.m01#11.p" to "Varför är toppar på 5 000 m snötäckta även på sommaren?",
    "q.m01#11.o0" to "För att höga platser är längre från solen",
    "q.m01#11.o1" to "För att luften på höjd är mycket kallare än låglandet på samma latitud, så nederbörd faller som snö",
    "q.m01#11.o2" to "För att starka toppvindar hindrar smältning",
    "q.m01#11.o3" to "För att packad snö blir is och aldrig smälter igen",
    "q.m01#11.e" to "Regeln 6,5 °C per 1 000 m håller sommartemperaturerna på 5 000 m under noll. Det förklarar också varför samma berg är svårare en säsong än en annan — snögränsen flyttar sig, och rutten med den.",
    "q.m01#12.p" to "Från ett basläger på 3 000 m till ett läger på 5 000 m, med medelgradienten, ungefär hur många grader kallare är det?",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13 °C. Räkningen: 2 000 m stigning vid 6,5 °C per 1 000 m ger 2 × 6,5 = 13 °C. Den uppskattningen är mycket praktisk före en resa — den avgör hur tjock isolering och sovsäck måste vara.",
    "q.m02#0.p" to "Vilken typ av form spelar störst roll för högfjällsklättring?",
    "q.m02#0.o0" to "Explosiv kraft och korta spurter",
    "q.m02#0.o1" to "Aerob uthållighet som håller i timmar",
    "q.m02#0.o2" to "Maximal greppstyrka",
    "q.m02#0.o3" to "Rörlighet",
    "q.m02#0.e" to "Högfjällsklättring är långt arbete med låg intensitet: sex till tio timmar om dagen, aldrig brant men obevekligt. Hypoxin begränsar den anaeroba kapaciteten kraftigt, så det som bär dig är en aerob bas och förmågan att hålla jämnt tempo.",
    "q.m02#1.p" to "Hur ska träningen läggas upp före avfärd?",
    "q.m02#1.o0" to "Tränga in ett stort block veckan före",
    "q.m02#1.o1" to "Trappa ner under de sista två till tre veckorna och åka upp utvilad",
    "q.m02#1.o2" to "Träna maximalt ända till dagen före",
    "q.m02#1.o3" to "Inte träna alls; lita på acklimatisering på plats",
    "q.m02#1.e" to "Träningseffekten skapas under återhämtningen. Att komma fram trött underminerar både prestation och acklimatisering — och acklimatiseringen kostar i sig energi. Nedtrappningen är det som omvandlar träning till form.",
    "q.m02#2.p" to "Vad ska kosten på höjd bygga på?",
    "q.m02#2.o0" to "Fet mat",
    "q.m02#2.o1" to "Kolhydrater",
    "q.m02#2.o2" to "Proteinrik mat",
    "q.m02#2.o3" to "Bara vätska",
    "q.m02#2.e" to "Kolhydrater omsätts effektivare och kräver mindre syre under hypoxi, och kroppen föredrar dem instinktivt högt uppe. Det går emot intuitionen att höjd kräver kalorität fett — begränsningen ligger i syreeffektiviteten.",
    "q.m02#3.p" to "Vad är en praktisk indikator på tillräckligt drickande?",
    "q.m02#3.o0" to "Hur törstig du känner dig",
    "q.m02#3.o1" to "Att urinen är ljus",
    "q.m02#3.o2" to "Att dricka en fast liter om dagen",
    "q.m02#3.o3" to "Förändringar i kroppsvikt",
    "q.m02#3.e" to "Törst är opålitligt på höjd — både kyla och hypoxi dämpar den. Urinens färg och lukt är ett mer direkt dagligt mått: ljus betyder ungefär tillräckligt, mörkare och starkare betyder drick mer.",
    "q.m02#4.p" to "Varför undvika alkohol på höjd?",
    "q.m02#4.o0" to "För att man går upp i vikt",
    "q.m02#4.o1" to "För att det dämpar andningsdriften och förvärrar nattlig hypoxi",
    "q.m02#4.o2" to "För att det påskyndar UV-skador",
    "q.m02#4.o3" to "För att det inte finns någon kylskåp",
    "q.m02#4.e" to "Både alkohol och lugnande medel dämpar andningscentrum. Nätterna på höjd lutar redan mot periodisk andning, och extra andningsdämpning sänker mättnaden markant — en av nyckelmekanismerna bakom att höjdsjuka förvärras under natten.",
    "q.m02#5.p" to "[Flerval] Vilka sätt att få i sig energi under rörelse på höjd är riktiga?",
    "q.m02#5.o0" to "Lite och ofta, innan du är vrålhungrig",
    "q.m02#5.o1" to "Föredra lättsmält mat med måttlig vattenhalt",
    "q.m02#5.o2" to "Bygg på kolhydrater",
    "q.m02#5.o3" to "Ät en stor måltid för att minska antalet ätandetillfällen",
    "q.m02#5.e" to "Lite och ofta underlättar matsmältningen och håller blodsockret jämnt. En stor måltid i hypoxi ger oftast uppblåsthet och illamående — och eftersom aptitlöshet i sig är ett vanligt symtom slår det tillbaka att tvinga i sig mycket.",
    "q.m02#6.p" to "Aptiten sjunker på höjd. Vad är rätt svar?",
    "q.m02#6.o0" to "Sluta äta och vänta på hunger",
    "q.m02#6.o1" to "Äta medvetet, med kolhydratrik och lättsmält mat",
    "q.m02#6.o2" to "Dricka mycket kaffe i stället för att äta",
    "q.m02#6.o3" to "Bara ta elektrolyter",
    "q.m02#6.e" to "Aptitlöshet är en del av höjdsjukan, och att äta för lite försvagar acklimatiseringen — en ond cirkel. Ät medvetet, lite och ofta: det handlar inte om du känner hunger, det är en nödvändig åtgärd.",
    "q.m02#7.p" to "Vilket påstående om form och höjd är korrekt?",
    "q.m02#7.o0" to "Är du i form får du ingen höjdsjuka",
    "q.m02#7.o1" to "Form förbättrar prestationen men kan inte ersätta acklimatisering",
    "q.m02#7.o2" to "Otränade bör inte åka till höjd",
    "q.m02#7.o3" to "Ju bättre form, desto mindre acklimatisering behövs",
    "q.m02#7.e" to "Form och acklimatisering är två skilda linjer. En vältränad person kan känna sig bekvämare på samma höjd, men fysiologin behöver ändå dagar — och logiken «jag är i form, alltså blir jag inte sjuk» ligger bakom många olyckor.",
    "q.m02#8.p" to "[Ordning] Sätt en rimlig förberedelsesekvens före klättringen i tidsordning.",
    "q.m02#8.o0" to "Grundläggande konditionsträning (två till tre månader före)",
    "q.m02#8.o1" to "Nedtrappning och skyddad återhämtning (två till tre veckor före)",
    "q.m02#8.o2" to "Kontroll av utrustning, resplan och försäkring (en vecka före)",
    "q.m02#8.o3" to "Acklimatisering enligt plan (under resan)",
    "q.m02#8.e" to "Ordningen är metoden: träna tidigt, lämna utrymme för återhämtning, förbered i detalj, acklimatisera långsamt. Stegen som oftast rubbas är de två sista — många kontrollerar utrustningen noggrant och jagar sedan schemat i berget och kortar acklimatiseringen.",
    "q.m02#9.p" to "Vilket problem kan överdrivet drickande (stor volym på kort tid) ge på höjd?",
    "q.m02#9.o0" to "Inga alls",
    "q.m02#9.o1" to "Det späder ut blodets elektrolyter och kan i svåra fall ge hyponatremi",
    "q.m02#9.o2" to "Det förebygger effektivt lungödem",
    "q.m02#9.o3" to "Det kan ersätta mat",
    "q.m02#9.e" to "«Drick tillräckligt» är inte «drick desperat». En stor volym på kort tid utan elektrolyter kan späda ut blodets natrium och ge huvudvärk, illamående och förändrat medvetande — symtom som liknar höjdsjuka och lätt misstolkas. Svaret är jämnt, tillräckligt intag.",
    "q.m03#0.p" to "Vad är kärnan i principen om låg påverkan?",
    "q.m03#0.o0" to "Bär lättare utrustning för att minska belastningen på kroppen",
    "q.m03#0.o1" to "Minimera mänsklig aktivitets påverkan på fjällmiljön",
    "q.m03#0.o2" to "Sänk svårighetsgraden för att hålla dig säker",
    "q.m03#0.o3" to "Minska antalet personer i laget",
    "q.m03#0.e" to "Principen om låg påverkan är den miljöetik som främjas inom utomhusklättring. Det handlar inte om hur lätt du färdas utan om hur mycket berget förändras av din närvaro — skräp, tramp, eld och störning av djurlivet räknas alla.",
    "q.m03#1.p" to "När du lämnar lägret, vad är rätt sätt att hantera skräp?",
    "q.m03#1.o0" to "Matrester kan grävas ner på plats",
    "q.m03#1.o1" to "Bär ut allt, inklusive toalettpapper och hygienartiklar",
    "q.m03#1.o2" to "Ta bara plast",
    "q.m03#1.o3" to "Bränn det i en grop",
    "q.m03#1.e" to "Handboken är tydlig: lägg allt du producerar i påsar och bär ut det, kontrollera lägret och aktivitetsområdet, och bär ut hygienartiklar som toalettpapper. Nedgrävning och bränning lämnar båda spår, och i kall höghöjdsmiljö bryts avfall ner extremt långsamt.",
    "q.m03#2.p" to "Vilken princip styr placeringen av en toalett i naturen?",
    "q.m03#2.o0" to "Ju mer dold desto bättre — avskildhet först",
    "q.m03#2.o1" to "Bort från vattenkällor, läger och leder",
    "q.m03#2.o2" to "Där snön är planast",
    "q.m03#2.o3" to "Nära en bäck så att det spolas bort",
    "q.m03#2.e" to "Målet är att undvika att förorena vatten och att nästa grupp inte ska gå rakt in i det. I praktiken betyder det ett bestämt avstånd från vatten och leder, en grund grop och att papper bärs ut — och ovanför snögränsen bärs allt ut, eftersom det knappt bryts ner.",
    "q.m03#3.p" to "Varför ska mat och skräp förvaras tätt?",
    "q.m03#3.o0" to "För att det inte ska bli fuktigt",
    "q.m03#3.o1" to "För att djur inte ska ta det och bli tillvanda",
    "q.m03#3.o2" to "För att spara plats i ryggsäcken",
    "q.m03#3.o3" to "För att det blir lättare att väga",
    "q.m03#3.e" to "Djur som tar mat lärs oftast att göra det av grupper: när de förknippar lägret med mat ökar risken på den leden permanent. Tätt förvar skyddar din mat, djuren och alla som kommer efter dig.",
    "q.m03#4.p" to "Vad menas i första hand med djurlivets känsliga period?",
    "q.m03#4.o0" to "Dagtidens födosökstimmar",
    "q.m03#4.o1" to "Parning och uppfödning av ungar",
    "q.m03#4.o2" to "Flyttsäsong",
    "q.m03#4.o3" to "Vinterdvala",
    "q.m03#4.e" to "Djur är särskilt känsliga för störning under parning och uppfödning av ungar, och en hona som försvarar ungar kan vara aggressiv. Förutom att undvika deras område bör du undvika fasta tider och platser för vatten — det skyddar dem och det skyddar dig.",
    "q.m03#5.p" to "Varför ska du hålla dig på befintliga leder?",
    "q.m03#5.o0" to "För att reglerna kräver det",
    "q.m03#5.o1" to "För att tramp skapar bestående nya stigar och utlöser erosion",
    "q.m03#5.o2" to "För att leder är lättare att gå",
    "q.m03#5.o3" to "För att guider markerar dem",
    "q.m03#5.e" to "Vegetation på hög höjd växer extremt långsamt; ett enda kängavtryck kan finnas kvar i åratal. Parallella «genvägar» skär genom vegetationen och samlar vattnet, vilket till slut gräver fåror — så börjar en led försämras.",
    "q.m03#6.p" to "[Flerval] Vilka av dessa måste bäras ut ur fjällen?",
    "q.m03#6.o0" to "Matförpackningar",
    "q.m03#6.o1" to "Fruktskal och matrester",
    "q.m03#6.o2" to "Använt toalettpapper",
    "q.m03#6.o3" to "Cigarettfimpar",
    "q.m03#6.o4" to "Tejp och snöre kan brännas på plats",
    "q.m03#6.e" to "De fyra första följer med ut. Det vanligaste missförståndet är fruktskal och matrester — de ser nedbrytbara ut, men i kall och torr alpin miljö bryts de ner mycket långsamt och de lockar till sig djur och förändrar deras beteende.",
    "q.m03#7.p" to "Vilken inställning är rätt till att ta naturföremål (stenar, växter, fossil) som souvenirer?",
    "q.m03#7.o0" to "Små saker går bra att ta",
    "q.m03#7.o1" to "Ta inget naturligt — ta fotografier i stället",
    "q.m03#7.o2" to "Okej så länge du inte skadar miljön",
    "q.m03#7.o3" to "Insamling av prover hjälper vetenskapen",
    "q.m03#7.e" to "«Ta bara fotografier, lämna bara fotspår» är den klassiska formuleringen. Naturföremål är en del av den lokala ekologin och landskapet, och när varje grupp tar lite blir den samlade effekten stor.",
    "q.m03#8.p" to "Hur påverkar klättring i första hand fjällmiljön?",
    "q.m03#8.o0" to "Bara genom skräp",
    "q.m03#8.o1" to "Skador på vegetation, minskade områden för djurlivet, skräp och kulturell påverkan från utomstående besökare på lokalsamhällen",
    "q.m03#8.o2" to "Mest buller",
    "q.m03#8.o3" to "Påverkan är försumbar",
    "q.m03#8.e" to "Handboken delar upp påverkan i ekologisk och social: skador på vegetation, undanträngda djur och skräp på ena sidan, kulturellt tryck på lokala levnadssätt på den andra. Att förstå detta är varför etikett är en del av klätterutbildningen.",
    "q.m03#9.p" to "[Ordning] Sätt rutinen för låg påverkan när du lämnar lägret i rätt ordning.",
    "q.m03#9.o0" to "Packa ihop personlig och gemensam utrustning",
    "q.m03#9.o1" to "Sortera och påsa allt skräp",
    "q.m03#9.o2" to "Hantera mänskligt avfall (gräv ner eller bär ut)",
    "q.m03#9.o3" to "Gå runt lägret och aktivitetsområdet och bekräfta att inget lämnats",
    "q.m03#9.e" to "Det sista steget — rundvandringen — hoppas oftast över och är viktigast: folk tar instinktivt «sina egna saker», och det är precis så tältpinnar, repändar och tappade omslag blir kvar. Att se sig tillbaka kostar nästan ingenting.",
    "q.m04#0.p" to "Vad är det mest tillförlitliga tecknet på att vädret slår om?",
    "q.m04#0.o0" to "Om det är sol just nu",
    "q.m04#0.o1" to "Trender i lufttryck, moln och vind",
    "q.m04#0.o2" to "Prognosen från före avfärd",
    "q.m04#0.o3" to "Hur dina kamrater känner sig",
    "q.m04#0.e" to "Läget just nu är en ögonblicksbild; trenden är riktningen. Trycket faller stadigt, molnen blir tätare och lägre, vinden ökar — när alla tre syns samtidigt slår vädret om. Det är det praktiska värdet av att bära barometer, i klockan eller separat.",
    "q.m04#1.p" to "Vad är typiskt för cumulonimbus, och vad betyder det?",
    "q.m04#1.o0" to "Tunt och jämnt — stabilt väder",
    "q.m04#1.o1" to "Vertikal utveckling med städsky — åska och kraftig nederbörd",
    "q.m04#1.o2" to "Utspritt i lager — bara duggregn",
    "q.m04#1.o3" to "Trådiga slöjor — bra väder",
    "q.m04#1.e" to "Den vertikala tillväxten visar stark konvektion, och städskyen betyder att den nått mogen fas. Att möta en på hög höjd betyder att blixt, hagel och kraftig nederbörd alla är möjliga — lämna exponerade ryggar och höjdpartier omedelbart.",
    "q.m04#2.p" to "Vilka kartskalor används vanligen vid klättring?",
    "q.m04#2.o0" to "1:1 000 och 1:5 000",
    "q.m04#2.o1" to "1:50 000 och 1:10 000",
    "q.m04#2.o2" to "1:250 000 och 1:500 000",
    "q.m04#2.o3" to "Vilken skala som helst duger",
    "q.m04#2.e" to "1:50 000 och 1:10 000 är det vanliga paret: den första täcker ett stort område och passar ruttplanering, den andra har detaljerna och passar teknisk terräng. 1:200 000 används ibland, och 1:10 000 mer sällan — bladet täcker så lite mark att du snabbt går utanför det.",
    "q.m04#3.p" to "Tätt liggande höjdkurvor på en topografisk karta betyder vad?",
    "q.m04#3.o0" to "En svag sluttning",
    "q.m04#3.o1" to "En brant sluttning",
    "q.m04#3.o2" to "En dal",
    "q.m04#3.o3" to "En glaciär",
    "q.m04#3.e" to "Ju tätare höjdkurvorna ligger, desto mer höjd vinns över samma horisontella avstånd — med andra ord desto brantare. Det är en användbar läskunskap vid planering: du kan markera branta partier, hyllor och möjliga tältplatser innan du går.",
    "q.m04#4.p" to "Vad anger en sluten höjdkurva på en topografisk karta?",
    "q.m04#4.o0" to "En sjö",
    "q.m04#4.o1" to "En egen topp",
    "q.m04#4.o2" to "En glaciär",
    "q.m04#4.o3" to "En klippa",
    "q.m04#4.e" to "En sluten kurva betyder att massivet faller undan på alla sidor — själva definitionen av en egen topp. Flera koncentriska slutna kurvor betyder att berget stiger stegvis, med den innersta kurvan som toppområde.",
    "q.m04#5.p" to "[Flerval] Vad ska du tänka på när du använder kompass?",
    "q.m04#5.o0" to "Håll den så horisontell som möjligt",
    "q.m04#5.o1" to "Håll dig borta från magnetiska föremål",
    "q.m04#5.o2" to "Ta inte nålens S-ände för norr",
    "q.m04#5.o3" to "Korrigera för den lokala missvisningen",
    "q.m04#5.o4" to "Håll den nära metallspännena på ryggsäcken så att den ligger stadigt",
    "q.m04#5.e" to "Alla fyra står uttryckligen i handboken. Bara felet med S-änden ger ett riktningsfel på 180° — i komplex terräng kan det skicka dig åt motsatt håll utan att du märker det.",
    "q.m04#6.p" to "Vad är missvisning (magnetisk deklination)?",
    "q.m04#6.o0" to "Ett tillverkningsfel i kompassen",
    "q.m04#6.o1" to "Skillnaden mellan magnetisk nord och rättvisande nord, som måste korrigeras",
    "q.m04#6.o2" to "En vinkeländring orsakad av höjden",
    "q.m04#6.o3" to "Förvrängning orsakad av kartprojektionen",
    "q.m04#6.e" to "Nålen pekar mot magnetisk nord medan kartor refererar till rättvisande nord, och de två skiljer sig. Missvisningen varierar mellan regioner, så den måste korrigeras när du arbetar med karta och kompass tillsammans — annars förskjuts hela rutten.",
    "q.m04#7.p" to "Vad representerar de jämna fyrkantiga rutnätslinjerna på en topografisk karta?",
    "q.m04#7.o0" to "Latitud- och longitudlinjer",
    "q.m04#7.o1" to "Ett UTM-rutnät (Universal Transverse Mercator)",
    "q.m04#7.o2" to "Höjdkurvor",
    "q.m04#7.o3" to "Administrativa gränser",
    "q.m04#7.e" to "Rutnätet är inte latitud och longitud utan UTM. Det spelar roll eftersom jorden är en ellipsoid, så lat/long-rutor är inte lika stora på olika breddgrader, medan UTM-rutor är det — vilket gör det enkelt att mäta avstånd och koordinater.",
    "q.m04#8.p" to "Varför ska du inte lita enbart på GPS?",
    "q.m04#8.o0" to "För att GPS inte är tillräckligt noggrann",
    "q.m04#8.o1" to "För att enheten kan ta slut på batteri, bli blöt, gå sönder eller tappa signal",
    "q.m04#8.o2" to "För att GPS bara fungerar i städer",
    "q.m04#8.o3" to "För att GPS kräver en prenumeration",
    "q.m04#8.e" to "GPS är ett utmärkt hjälpmedel, men det förutsätter en fungerande enhet. Batterier tar slut snabbt i höghöjdskyla, och vatten och tapp är vanliga. Karta och kompass behöver ingen ström — därför är de fortfarande obligatoriska i klätterutbildningen.",
    "q.m04#9.p" to "När sikten slår igen (dimma, whiteout), vad ska du göra först?",
    "q.m04#9.o0" to "Öka farten och ta dig igenom",
    "q.m04#9.o1" to "Bekräfta din position och kurs direkt, och vänta på platsen om det behövs",
    "q.m04#9.o2" to "Fortsätt rakt fram enligt den ursprungliga planen",
    "q.m04#9.o3" to "Dela upp dig och leta efter rutten",
    "q.m04#9.e" to "Farorna med whiteout är att tappa alla visuella referenser, och folk går instinktivt i fel riktning. Fastställ positionen, anteckna kursen och vänta vid behov — mycket säkrare än att pressa på, och att dela upp sig är det sämsta alternativet av alla.",
    "q.m05#0.p" to "Vad är den grundläggande skillnaden mellan en trekkingtopp och ett tekniskt berg?",
    "q.m05#0.o0" to "Höjden",
    "q.m05#0.o1" to "Om teknisk utrustning och tekniska rörelser krävs",
    "q.m05#0.o2" to "Vilket land det ligger i",
    "q.m05#0.o3" to "Om tillstånd krävs",
    "q.m05#0.e" to "Gränsen går vid tekniskt krav, inte höjd. Kilimanjaro på 5 895 m kräver ingen teknisk utrustning, medan Haba Snow Mountain på 5 396 m kräver stegjärn och isyxa ovanför snögränsen. Höjden är bara en dimension av svårigheten.",
    "q.m05#1.p" to "Vad heter Kilimanjaros högsta punkt?",
    "q.m05#1.o0" to "Uhuru Peak",
    "q.m05#1.o1" to "Kibo",
    "q.m05#1.o2" to "Mawenzi",
    "q.m05#1.o3" to "Shira",
    "q.m05#1.e" to "Toppen är Uhuru Peak på 5 895 m. Kilimanjaro är en vilande vulkan byggd av tre koner — Kibo, Mawenzi och Shira — och Uhuru är den högsta punkten på Kibo.",
    "q.m05#2.p" to "Vad gör Kilimanjaro unikt?",
    "q.m05#2.o0" to "Det är den minst bestigna 5 000 m-toppen i världen",
    "q.m05#2.o1" to "Det ligger nära ekvatorn men bär glaciärer och passerar klimatzoner från regnskog till alpinsk öken",
    "q.m05#2.o2" to "Det kräver mycket teknisk utrustning",
    "q.m05#2.o3" to "Det kan bara bestigas en månad om året",
    "q.m05#2.e" to "Ekvator plus glaciärer gör Kilimanjaro till en vertikal klimatkorridor: regnskog till is på en och samma resa. Det skapar också ett praktiskt problem — stort höjdspann med snabb höjdökning, så acklimatiseringen blir den stora utmaningen.",
    "q.m05#3.p" to "Aotaina tillhör vilken toppgrupp?",
    "q.m05#3.o0" to "Siguniang",
    "q.m05#3.o1" to "San'ao-snöbergen",
    "q.m05#3.o2" to "Gongga",
    "q.m05#3.o3" to "Meili Snow Mountain",
    "q.m05#3.e" to "Gruppen San'ao i Heishui i Sichuan består av Aotaiji (bergets fader), Aotaimei (modern) och Aotaina (sonen). Aotaina är den lättaste av de tre och väljs ofta som första snötopp.",
    "q.m05#4.p" to "Vilken beskrivning av Aotainas höjd är korrekt?",
    "q.m05#4.o0" to "Alla källor anger 4 800 m",
    "q.m05#4.o1" to "Officiell höjd 5 211 m, men uppmätt cirka 4 800 m — källorna skiljer sig",
    "q.m05#4.o2" to "Officiellt 4 800 m, uppmätt 5 211 m",
    "q.m05#4.o3" to "Höjden har aldrig ifrågasatts",
    "q.m05#4.e" to "Sådana skillnader är vanliga i toppdata: officiella siffror, uppmätta värden och olika mätstandarder varierar. Den praktiska lärdomen är att ange källan när du citerar toppdata, i stället för att behandla en siffra som absolut sanning.",
    "q.m05#5.p" to "Vilka höjder har Siguniangs Da Feng och Er Feng?",
    "q.m05#5.o0" to "5 025 m och 5 276 m",
    "q.m05#5.o1" to "5 276 m och 5 025 m",
    "q.m05#5.o2" to "5 025 m och 5 355 m",
    "q.m05#5.o3" to "4 850 m och 5 276 m",
    "q.m05#5.e" to "Da Feng är 5 025 m och Er Feng 5 276 m. De paras ofta som en inträdesprogression: Da Feng först för höjdvana, sedan Er Feng, vars sista parti kräver enkel teknisk assistans — ett naturligt steg mot teknisk klättring.",
    "q.m05#6.p" to "[Flerval] När du väljer en första snötopp, vilka faktorer är mest värda att jämföra?",
    "q.m05#6.o0" to "Hur etablerad rutten är och dess toppfrekvens",
    "q.m05#6.o1" to "Om guidning och räddningsstöd är tillförlitligt",
    "q.m05#6.o2" to "Om höjdökningen är vettigt taktad",
    "q.m05#6.o3" to "Din nuvarande form och den tid du kan avsätta",
    "q.m05#6.o4" to "Hur populär toppen är i sociala medier",
    "q.m05#6.e" to "De fyra första svarar tillsammans på «passar det här berget mig just nu». Att bara titta på höjdsiffran vilseleder: en 5 000 m-topp med vettig takt och bra stöd kan vara säkrare än en 5 500 m-topp som tvingar fram tre stressade dagar.",
    "q.m05#7.p" to "Vad är den vanligaste orsaken till misslyckande på en introduktionstopp?",
    "q.m05#7.o0" to "Teknisk svårighet",
    "q.m05#7.o1" to "Höjdsjuka och väder, inte teknisk svårighet",
    "q.m05#7.o2" to "Otillräcklig utrustning",
    "q.m05#7.o3" to "För litet lag",
    "q.m05#7.e" to "Det här är den mest underskattade punkten: på introduktionstoppar är misslyckandet nästan alltid «vi tog slut på ork» eller «vädret väntade inte», inte «vi klarade inte nyckelpassagen». Den verkliga läxan på den här nivån är därför acklimatisering, takt och form — inte tekniska rörelser.",
    "q.m05#8.p" to "Varför är toppfrekvensen ett användbart mått när du väljer topp?",
    "q.m05#8.o0" to "För att den speglar hur vacker toppen är",
    "q.m05#8.o1" to "För att den sammanfattar ruttens svårighet, takten och den verkliga nivån på stödet",
    "q.m05#8.o2" to "För att den bestämmer kostnaden",
    "q.m05#8.o3" to "För att den inte har något med säkerhet att göra",
    "q.m05#8.e" to "Toppfrekvensen är produkten av många saker: hur svår rutten är, om höjdökningen är vettig, hur breda väderfönstren är, hur tillförlitlig logistiken är. Den säger mer om vad du faktiskt möter än höjden ensam.",
    "q.m05#9.p" to "Vilken inställning är rätt till en introduktionssnötopp?",
    "q.m05#9.o0" to "Introduktion betyder ingen risk",
    "q.m05#9.o1" to "Introduktion betyder bara lägre tekniskt krav; höjd- och vädrisker är fortfarande verkliga",
    "q.m05#9.o2" to "Introduktionstoppar kräver ingen guide",
    "q.m05#9.o3" to "Introduktionstoppar kräver ingen formförberedelse",
    "q.m05#9.e" to "«Introduktion» beskriver den tekniska tröskeln, inte den totala risken. Höjden i sig, plötsligt väder och utmattning kan döda på vilken höjd som helst. Att behandla introduktion som «lätt» är där dålig förberedelse börjar.",
    "q.m06#0.p" to "Vilka är de tre grundsystemen i teknisk klättring?",
    "q.m06#0.o0" to "Utrustning, form, väder",
    "q.m06#0.o1" to "Självstopp, säkring, rörelse",
    "q.m06#0.o2" to "Uppstigning, nedstigning, vila",
    "q.m06#0.o3" to "Stegjärn, isyxa, rep",
    "q.m06#0.e" to "Självstopp svarar på «vad gör jag efter att ha tappat fotfästet», säkring svarar på «vem fångar mig om jag faller», och rörelse svarar på «hur tar jag mig över farlig mark». Tillsammans sluter de cirkeln — ta bort en och teknisk klättring fungerar inte.",
    "q.m06#1.p" to "Vad är det grundläggande syftet med att lära sig teknisk klättring?",
    "q.m06#1.o0" to "Att klättra svårare rutter",
    "q.m06#1.o1" to "Att göra en okontrollerad glidning till en hanterad risk",
    "q.m06#1.o2" to "Att få ett certifikat",
    "q.m06#1.o3" to "Att röra sig snabbare",
    "q.m06#1.e" to "Tekniken sänker inte berget; den förändrar vad som händer efter ett misstag. Med självstopp är en halkning inte längre en oåterkallelig katastrof; med säkring betyder ett fel inte automatiskt ett fall. Det är det verkliga värdet.",
    "q.m06#2.p" to "Vad är det mest effektiva sättet att bemästra en teknisk rörelse?",
    "q.m06#2.o0" to "Titta på instruktionsvideor om och om igen",
    "q.m06#2.o1" to "Träna upprepat på säker mark tills det sitter i ryggmärgen",
    "q.m06#2.o2" to "Läsa handboken och memorera punkterna",
    "q.m06#2.o3" to "Lära sig det på en gång i en riktig brant sluttning",
    "q.m06#2.e" to "Tekniska moment måste utföras under press, och press sänker dig till den nivå du faktiskt tränat på. Svag sluttning, mjuk snö, fri utåtlöpning och en instruktör som säkrar — när alla fyra finns är det där en färdighet verkligen lärs in.",
    "q.m06#3.p" to "Varför kan du inte lära dig självstopp från video?",
    "q.m06#3.o0" to "För att videokvaliteten är dålig",
    "q.m06#3.o1" to "För att det är en reflex som måste byggas genom upprepad träning i fält",
    "q.m06#3.o2" to "För att tekniken som visas är fel",
    "q.m06#3.o3" to "För att självstopp faktiskt är enkelt",
    "q.m06#3.e" to "Efter en halkning har du en eller två sekunder, utan utrymme att tänka. Muskelminnet köps med repetitioner — därför insisterar varje seriös kurs på att du nöter det tills du kan göra det utan att tänka.",
    "q.m06#4.p" to "Vilka är de tre startobjekten i den tekniska utrustningen?",
    "q.m06#4.o0" to "Hjälm, handskar, skidglasögon",
    "q.m06#4.o1" to "Stegjärn som passar dina kängor, en isyxa och en sele",
    "q.m06#4.o2" to "Tält, sovsäck, liggunderlag",
    "q.m06#4.o3" to "GPS, radio, pannlampa",
    "q.m06#4.e" to "Stegjärnen ger grepp, isyxan ger självstopp och stöd, selen kopplar dig till säkringssystemet. Gemensamt är att de bara skapar säkerhet när de är matchade och används som ett system med en partner — ingen enskild del skyddar någon på egen hand.",
    "q.m06#5.p" to "När du har de tekniska färdigheterna, vilken förmåga blir då viktigast?",
    "q.m06#5.o0" to "Klättringshastighet",
    "q.m06#5.o1" to "Att bedöma när du inte behöver den tekniska utrustningen alls",
    "q.m06#5.o2" to "Att underhålla utrustningen",
    "q.m06#5.o3" to "Ytterligare formvinster",
    "q.m06#5.e" to "Det här är den mest kontraintuitiva punkten i teknisk klättring: färdighet låter dig gå in i svårare terräng, medan verkliga experter använder den för att köpa möjligheten att inte gå dit. Omdöme rankas alltid högre än utförande.",
    "q.m06#6.p" to "[Flerval] Vilka av dessa räknas som teknisk klättring?",
    "q.m06#6.o0" to "Att röra sig på en issluttning och göra självstopp",
    "q.m06#6.o1" to "Att korsa en glaciär i replag",
    "q.m06#6.o2" to "Att bygga en säkringsstation",
    "q.m06#6.o3" to "Att fira",
    "q.m06#6.o4" to "Att vandra på en etablerad led",
    "q.m06#6.e" to "De fyra första är tekniska: var och en kräver utrustning, system och särskild träning. Att bara gå på snö eller följa en etablerad led är det inte — skillnaden är om systemen krävs.",
    "q.m06#7.p" to "Varför kan teknisk förmåga aldrig ersätta omdöme?",
    "q.m06#7.o0" to "För att teknisk förmåga inte går att träna",
    "q.m06#7.o1" to "För att dåligt omdöme försätter dig i terräng du aldrig borde ha gått in i, där tekniken inte kan rädda dig",
    "q.m06#7.o2" to "För att omdöme är lättare att lära",
    "q.m06#7.o3" to "För att teknik bara gäller klippa",
    "q.m06#7.e" to "Teknik är det du använder när du redan är i fara; omdömet avgör om du går in i faran alls. Olycksutredningar hittar sällan «rörelsen var fel» — mycket oftare är slutsatsen «de borde inte ha varit där».",
    "q.m06#8.p" to "[Ordning] Sätt inlärningsordningen för teknisk klättring i en vettig ordning.",
    "q.m06#8.o0" to "Förstå utrustningen: hur stegjärn, isyxa och sele fungerar",
    "q.m06#8.o1" to "Träna grundmomenten upprepat på säker mark (till exempel självstopp)",
    "q.m06#8.o2" to "Lär dig repsystemen: knopar, replag, säkringar",
    "q.m06#8.o3" to "Tillämpa allt på riktiga men kontrollerade rutter",
    "q.m06#8.e" to "Logiken är: skydda dig själv först, koppla sedan ihop dig med andra, gå sedan in i riktig terräng. Hoppar du över ett steg blir det en lucka i förmågan — att gå ut i replag på en glaciär med oputsad självstopp multiplicerar till exempel risken för hela laget.",
    "q.m06#9.p" to "Vad har det här avsnittet åstadkommit?",
    "q.m06#9.o0" to "Slutfört all höghöjdsträning",
    "q.m06#9.o1" to "Byggt grunden i miljö, vetenskap och utrustning, redo att börja med tekniska rörelser",
    "q.m06#9.o2" to "Slutfört förberedelserna för 8 000 m",
    "q.m06#9.o3" to "Tagit ett räddningscertifikat",
    "q.m06#9.e" to "Introduktionsavsnittet för 5 000 m handlar om att lägga basen: miljökunskap, utrustning, klädsel, form, låg påverkan, väder och navigering, och till slut teknisk klättring. Nästa avsnitt börjar på riktigt med stegjärn, isyxa, självstopp och reparbete.",
    "q.m07#0.p" to "Vad är grundtanken bakom ankarkonstruktion?",
    "q.m07#0.o0" to "Använd så lite utrustning som möjligt",
    "q.m07#0.o1" to "Att ingen enskild fästpunkt som ger upp ska få systemet att kollapsa",
    "q.m07#0.o2" to "Bygg ankaret så högt som möjligt",
    "q.m07#0.o3" to "Använd bara naturliga fästpunkter",
    "q.m07#0.e" to "Klipp- och snöankare kan aldrig vara absolut säkra, så systemet konstrueras för att tåla fel i stället för att vara absolut starkt. Allt annat — redundans, utjämning, ingen förlängning — är bara den tanken utskriven.",
    "q.m07#1.p" to "Med två fästpunkter i 90° vinkel, ungefär hur stor andel av lasten bär var och en?",
    "q.m07#1.o0" to "Cirka 50 %",
    "q.m07#1.o1" to "Cirka 58 %",
    "q.m07#1.o2" to "Cirka 71 %",
    "q.m07#1.o3" to "Cirka 100 %",
    "q.m07#1.e" to "Det är nyckeltalen från handbokens tabell: vid 0° bär varje punkt cirka 50 %, vid 60° cirka 58 %, vid 90° cirka 71 %. Ju bredare vinkel, desto mer kraft känner varje punkt från samma person — vilket direkt styr hur du väljer och placerar punkterna.",
    "q.m07#2.p" to "Hur bör vinkeln mellan fästpunkterna hanteras ur lastsynpunkt?",
    "q.m07#2.o0" to "Så liten som möjligt, så att lastriktningarna är nästan parallella",
    "q.m07#2.o1" to "Så stor som möjligt, för att sprida lasten i olika riktningar",
    "q.m07#2.o2" to "Den måste vara 90°",
    "q.m07#2.o3" to "Vinkeln påverkar inte lasten",
    "q.m07#2.e" to "Ju mindre vinkel, desto närmare 50/50-fördelning; ökar du den stiger lasten på varje punkt. Tumregeln «håll slingans vinkel inom 60°» kommer direkt från de siffrorna.",
    "q.m07#3.p" to "[Flerval] Vilka dimensioner bör du bedöma när du värderar ett ankare?",
    "q.m07#3.o0" to "Solid: varje punkt är tillräckligt stark",
    "q.m07#3.o1" to "Redundant: flera oberoende punkter",
    "q.m07#3.o2" to "Utjämnad: lasten fördelas vettigt",
    "q.m07#3.o3" to "Ingen förlängning: ett haveri skapar ingen förlängning med ryckbelastning",
    "q.m07#3.o4" to "Symmetri: ett prydligt och visuellt balanserat arrangemang",
    "q.m07#3.e" to "Dessa fyra är grundramverket. Ingen förlängning är den som oftast glöms: lämnar du slack mellan punkterna får ett haveri de återstående att rycka till. Ryckbelastningar är mycket större än statiska laster, vilket många inte inser.",
    "q.m07#4.p" to "[Matchning] Matcha varje säkringstyp med medium och metod.",
    "q.m07#4.l0" to "Naturlig säkring",
    "q.m07#4.l1" to "Snösäkring",
    "q.m07#4.l2" to "Issäkring",
    "q.m07#4.r0" to "Klipppelare, stora träd, block — bekräfta att de är intakta och stabila",
    "q.m07#4.r1" to "Snöankare, deadman, T-ränna — tillförlitligheten hänger starkt på snökvalitet och nedgrävning",
    "q.m07#4.r2" to "Isskruv — bekräfta att isen är solid, utan hålrum eller vaxkakestruktur",
    "q.m07#4.e" to "Tre medium, tre helt olika kriterier. En av de vanligaste olycksorsakerna är att bedöma snö eller is med klippinstinkt — «det ser solitt ut» betyder nästan ingenting i ett snötäcke.",
    "q.m07#5.p" to "Vilket av dessa är falsk redundans?",
    "q.m07#5.o0" to "Att använda två delar med olika styrka",
    "q.m07#5.o1" to "Två fästpunkter som i praktiken hänger på samma spricka eller samma block",
    "q.m07#5.o2" to "Att förbinda punkterna med slingor",
    "q.m07#5.o3" to "Att placera tre fästpunkter",
    "q.m07#5.e" to "Redundans kräver oberoende haveri. Om två punkter delar en spricka tar sprickans öppnande båda på en gång — det ser ut som två punkter men fungerar som en. Falsk redundans är vanlig och livsfarlig.",
    "q.m07#6.p" to "Varför förspänna systemet för att uppnå ingen förlängning?",
    "q.m07#6.o0" to "För att det ska se prydligt ut",
    "q.m07#6.o1" to "För att hindra att ett haveri rycker till de återstående punkterna",
    "q.m07#6.o2" to "För att spara slinglängd",
    "q.m07#6.o3" to "För att det ska gå snabbare att riva",
    "q.m07#6.e" to "En ryckbelastning är mycket större än en statisk — samma person som plötsligt belastar en punkt ger mycket mer kraft än att hänga stilla. Ett slakt ankare ser «mer flexibelt» ut men förstärker i själva verket ett haveri till ett ryck genom hela systemet.",
    "q.m07#7.p" to "[Ordning] Sätt stegen för att bygga ett ankare i vettig ordning.",
    "q.m07#7.o0" to "Se dig omkring och välj användbara, inbördes oberoende fästpunkter",
    "q.m07#7.o1" to "Placera varje punkt och bekräfta att den är stark på egen hand",
    "q.m07#7.o2" to "Förbind punkterna med slinga eller rep, kontrollera vinkeln och förspänn",
    "q.m07#7.o3" to "Kontrollera hela systemet för falsk redundans och förlängning",
    "q.m07#7.e" to "Ordningen är: välj placeringar, bygg de enskilda punkterna, koppla ihop systemet, granska det. Granskningen är ingen formalitet — under bygget koncentrerar du dig på varje placering och missar lätt helheten, till exempel att två punkter delar en formation.",
    "q.m07#8.p" to "Vad är viktigast att kontrollera vid naturlig säkring?",
    "q.m07#8.o0" to "Om den är stor nog",
    "q.m07#8.o1" to "Om den är intakt — inte lös, vittrad eller lossnad från huvudmassan",
    "q.m07#8.o2" to "Om den ser bra ut",
    "q.m07#8.o3" to "Om den är lätt att slinga",
    "q.m07#8.e" to "Farorna med naturlig säkring är oftast att den ser stor ut men redan är lös. Det avgörande är om den verkligen hör till huvudmassan, och om det finns sprickor eller tecken på vittring. Stor, grov och självklar betyder inte solid.",
    "q.m07#9.p" to "Varför bygga ett ankare så snabbt som rimligt?",
    "q.m07#9.o0" to "För att spara energi",
    "q.m07#9.o1" to "För att tiden du bygger är tid du är exponerad för risk",
    "q.m07#9.o2" to "För att kamraterna skyndar på dig",
    "q.m07#9.o3" to "För att utrustning tappas bort",
    "q.m07#9.e" to "Medan du bygger ett ankare är du ofta osäkrad eller dåligt säkrad, så exponeringen bör vara kort. Därför värderar bedömningen inte bara solid, redundant och utjämnad, utan också effektivitet och timing.",
    "q.m07#10.p" to "Vad beror ett snöankares tillförlitlighet i första hand på?",
    "q.m07#10.o0" to "Utrustningens märke",
    "q.m07#10.o1" to "Snökvaliteten och hur väl det är nedgrävt",
    "q.m07#10.o2" to "Höjden",
    "q.m07#10.o3" to "Repets färg",
    "q.m07#10.e" to "Samma snöankare eller deadman håller vitt skilda laster i djup snö, blöt snö eller vid kanten av en snöbrygga. Snösäkringar kräver att du läser snötäcket på plats, vilket också gör snösäkring till en av de mest krävande färdigheterna.",
    "q.m07#11.p" to "Om ett ankare bara har en enda fästpunkt, vad är det största problemet?",
    "q.m07#11.o0" to "Lasten blir för hög",
    "q.m07#11.o1" to "Det finns ingen marginal alls — ger den punkten upp kollapsar systemet",
    "q.m07#11.o2" to "Det är besvärligt att hantera",
    "q.m07#11.o3" to "Det ser fult ut",
    "q.m07#11.e" to "Ett enpunktsankare lämnar ditt liv till en osäker faktor. Ibland är det verkligen enda möjligheten — en bra isskruv till exempel — och då gäller det att göra den punkten så bra den kan bli och att minimera hur länge systemet hänger på den.",
    "q.m08#0.p" to "Vilken höjd har Gangshikas huvudtopp?",
    "q.m08#0.o0" to "5 005 m",
    "q.m08#0.o1" to "5 150 m",
    "q.m08#0.o2" to "5 254,5 m",
    "q.m08#0.o3" to "5 396 m",
    "q.m08#0.e" to "Huvudtoppen är 5 254,5 m. Notera hierarkin: tredjetoppen 5 005 m < skuldertoppen 5 150 m < huvudtoppen 5 254,5 m — tre höjder, tre svårighetsnivåer, vilket är varför Gangshika ofta används som etappmål.",
    "q.m08#1.p" to "Vilken höjd och karaktär har Gangshikas tredjetopp?",
    "q.m08#1.o0" to "5 005 m, tekniskt insteg, cirka 95 % toppfrekvens för nybörjare",
    "q.m08#1.o1" to "5 254 m, mycket teknisk",
    "q.m08#1.o2" to "5 150 m, ren vandring",
    "q.m08#1.o3" to "5 396 m, glaciärrutt",
    "q.m08#1.e" to "Tredjetoppen är 5 005 m och tekniskt insteg. En nybörjartoppfrekvens på cirka 95 % säger att rutten är hanterbar och logistiken mogen — väl lämpad för att ta på teknisk utrustning första gången.",
    "q.m08#2.p" to "Vilken geografisk betydelse har Gangshika?",
    "q.m08#2.o0" to "Qilianbergens högsta topp",
    "q.m08#2.o1" to "Högsta toppen i östra Qilian",
    "q.m08#2.o2" to "Tibetanska platåns högsta topp",
    "q.m08#2.o3" to "Hengduanbergens högsta topp",
    "q.m08#2.e" to "Gangshika är högsta toppen i östra Qilian, i Menyuan härad i Haibei prefektur, Qinghai. Det är också en av de höga snötoppar som ligger närmast en stad i Kina — tillgängligheten styr direkt hur populär en topp blir som träningsmål.",
    "q.m08#3.p" to "Vilken är ansatssträckan och den typiska tiden för Gangshikas tredjetopp?",
    "q.m08#3.o0" to "Cirka 3 km / 2 timmar",
    "q.m08#3.o1" to "Cirka 10 km / 6 timmar",
    "q.m08#3.o2" to "Cirka 25 km / två dagar",
    "q.m08#3.o3" to "Cirka 1 km / 30 minuter",
    "q.m08#3.e" to "Cirka 10 km och sex timmar. Den belastningen är precis rätt för en första teknisk klättring: du vinner inte genom att uthärda en lång marsch, utan genom att koncentrera dig på teknik och omdöme.",
    "q.m08#4.p" to "Vilken höjd har Haba Snow Mountain?",
    "q.m08#4.o0" to "5 005 m",
    "q.m08#4.o1" to "5 254 m",
    "q.m08#4.o2" to "5 396 m",
    "q.m08#4.o3" to "5 642 m",
    "q.m08#4.e" to "Haba är 5 396 m, i Shangri-La i Yunnan. Värdet är att det ovanför snögränsen finns riktig is som kräver stegjärn och isyxa, men utan en 6 000 m-topps strikta acklimatiseringstryck.",
    "q.m08#5.p" to "Var kräver Haba Snow Mountain teknisk färdighet?",
    "q.m08#5.o0" to "Det kräver klättringsförmåga på klippa",
    "q.m08#5.o1" to "Ovanför snögränsen finns en issluttning som kräver stegjärn och isyxa",
    "q.m08#5.o2" to "Det kräver dykförmåga",
    "q.m08#5.o3" to "Det kräver ingen teknisk utrustning alls",
    "q.m08#5.e" to "Habas nyckelord är «is ovanför snögränsen». Du måste kunna röra dig stadigt på is med stegjärn och använda isyxan för stöd och självstopp — precis det som de tidigare lektionerna i den här 5 000 m-progressionen tar upp.",
    "q.m08#6.p" to "Vilken höjd och status har Elbrus?",
    "q.m08#6.o0" to "5 642 m, Europas högsta topp",
    "q.m08#6.o1" to "5 895 m, Afrikas högsta",
    "q.m08#6.o2" to "5 254 m, Qiliangedens högsta",
    "q.m08#6.o3" to "6 178 m, en hög topp i Kunlun",
    "q.m08#6.e" to "Elbrus är 5 642 m, Europas högsta topp, i Kaukasus i Ryssland. Dess plats i progressionen är ovanlig: 5 000 m-klass i höjd, men kräver glaciärvandring och replag — en klassisk bro från trekkingtoppar till tekniska toppar.",
    "q.m08#7.p" to "Vilka är grundkraven för att bestiga Elbrus?",
    "q.m08#7.o0" to "Bara god form",
    "q.m08#7.o1" to "Stegjärn och isyxa; glaciärvandring och replag är grundkrav",
    "q.m08#7.o2" to "Extra syrgas",
    "q.m08#7.o3" to "Klättringsförmåga på klippa",
    "q.m08#7.e" to "Elbrus rutt korsar glaciärer, så replag, sprickmedvetenhet och stegjärnshantering är alla basnivå. Den jämförs ofta med Kilimanjaro: båda 5 000 m-klass, den ena en ren vandring och den andra kräver verkligt tekniskt arbete.",
    "q.m08#8.p" to "[Flerval] När du går från trekkingtoppar till tekniska toppar, vilka förmågor bör du bygga först?",
    "q.m08#8.o0" to "Korrekt användning av teknisk utrustning (stegjärn, isyxa, sele)",
    "q.m08#8.o1" to "Grundläggande tekniska moment som att stoppa ett fall",
    "q.m08#8.o2" to "Glaciärvandring i replag och grundläggande säkringssystem",
    "q.m08#8.o3" to "Omdöme om när du inte ska fortsätta",
    "q.m08#8.o4" to "Att köpa dyrare utrustning",
    "q.m08#8.e" to "De tre första är förmågor; den fjärde är en begränsning. Många bygger bara de tre första och blir mer självsäkra i takt med att de blir skickligare — vilket höjer risken. Teknik och omdöme måste utvecklas tillsammans, därför parar det här avsnittet tekniklektioner med topplektioner.",
    "q.m08#9.p" to "[Ordning] Sätt dessa mål i stigande svårighetsordning.",
    "q.m08#9.o0" to "Aotaina (vandring, ingen teknisk svårighet)",
    "q.m08#9.o1" to "Gangshika tredjetopp (tekniskt insteg)",
    "q.m08#9.o2" to "Haba / Elbrus (blandat, stegjärn och replag)",
    "q.m08#9.o3" to "Yuzhu sydsluttning (6 000 m blandat)",
    "q.m08#9.e" to "Nyckeln är att lägga till en ny variabel i taget: ingen teknik, sedan teknisk utrustning, sedan använda den på riktig is, sedan lägga till höjd. Det vanliga misstaget är inte att hoppa över ett steg utan att maxa svårighet och höjd samtidigt, så att du inte vet vilket du var oförberedd på.",
    "q.m08#10.p" to "Varför är tredjetopp till huvudtopp en vettig progression?",
    "q.m08#10.o0" to "För att tredjetoppen ligger närmast huvudtoppen",
    "q.m08#10.o1" to "För att olika rutter på samma berg skiljer teknisk svårighet från miljömässig svårighet",
    "q.m08#10.o2" to "För att huvudtoppen är billigare",
    "q.m08#10.o3" to "För att det är lättare att gå vilse på tredjetoppen",
    "q.m08#10.e" to "Att avancera på samma berg håller miljövariablerna — väder, ansats, logistik, guider — ungefär konstanta, så du tydligt känner var den extra svårigheten kommer ifrån. Byter du berg varje gång kan du aldrig avgöra om teknik eller acklimatisering var begränsningen.",
    "q.m08#11.p" to "Vilken inställning är rätt när du väljer ett 5 000 m-progressionsmål?",
    "q.m08#11.o0" to "Välj det högsta och hoppa över stegen",
    "q.m08#11.o1" to "Lägg till en ny svårighet i taget och prioritera tillförlitligt stöd",
    "q.m08#11.o2" to "Välj det billigaste",
    "q.m08#11.o3" to "Titta bara på toppfrekvens, inte tekniska krav",
    "q.m08#11.e" to "Förmåga byggs kumulativt, och varje överhoppat steg multiplicerar risken. Tillförlitligt stöd — guider, räddning, en reträttplan — är den gemensamma säkerhetsbasen på varje instegsnivå: det kan inte hindra dig från att göra ett misstag, men det hindrar ett misstag från att bli dödligt.",
    "q.m09#0.p" to "Vilka är de två grundläggande målen med läkemedel på höjd?",
    "q.m09#0.o0" to "Bota höjdsjuka och ersätta nedstigning",
    "q.m09#0.o1" to "Påskynda acklimatiseringen och köpa tid för nedstigning",
    "q.m09#0.o2" to "Förbättra form och uthållighet",
    "q.m09#0.o3" to "Förebygga förkylning och förbättra sömnen",
    "q.m09#0.e" to "Att hålla isär dessa två är avgörande: acetazolamid hör till det första (snabbare acklimatisering), dexametason och nifedipin till det andra (köpa tid). Att behandla ett tidsköpande läkemedel som bevis på återhämtning är den farligaste felbedömningen i höjdvård.",
    "q.m09#1.p" to "Påverkar dexametason acklimatiseringen?",
    "q.m09#1.o0" to "Ja, det påskyndar den",
    "q.m09#1.o1" to "Nej, det har ingen effekt på acklimatiseringen alls",
    "q.m09#1.o2" to "Ja, det saktar ner den",
    "q.m09#1.o3" to "Bara vid långvarig användning",
    "q.m09#1.e" to "Handboken är tydlig: dexametason lindrar symtom på hjärnödem, har ingen effekt på acklimatiseringen och behandlar inte lungödem. Det köper enbart tid — och den tiden måste användas till nedstigning.",
    "q.m09#2.p" to "Vilken biverkning av nifedipin kräver mest försiktighet?",
    "q.m09#2.o0" to "Dåsighet",
    "q.m09#2.o1" to "Snabbt blodtrycksfall, så att du kan svimma om du reser dig hastigt",
    "q.m09#2.o2" to "Tinnitus",
    "q.m09#2.o3" to "Aptitlöshet",
    "q.m09#2.e" to "Det är farligt i verkliga situationer: svimning av ortostatisk hypotension i en brant sluttning eller när du kliver ut ur tältet på natten kan få mer omedelbara konsekvenser än höjdsjukan i sig. Handboken noterar också att nifedipin kan hjälpa vandrare men inte är det bästa valet för klättrare.",
    "q.m09#3.p" to "Vilken inställning är rätt till läkemedel på höjd?",
    "q.m09#3.o0" to "Memorera dosen och använd dem själv",
    "q.m09#3.o1" to "Det är ett medicinskt beslut — bedöm med läkare och följ deras anvisningar",
    "q.m09#3.o2" to "Lagmedlemmar kan dela fritt",
    "q.m09#3.o3" to "Biverkningar påverkar inte användningen",
    "q.m09#3.e" to "Varje läkemedel har specifika indikationer, kontraindikationer och biverkningar (nifedipin sänker blodtrycket, aspirin innebär blödningsrisk, dexametason är en steroid). Det här är inte «höjdallmänbildning» utan medicinska ingrepp — därav den upprepade betoningen på medicinsk rådgivning.",
    "q.m09#4.p" to "Symtomen lindras efter dexametason. Vad ska du göra?",
    "q.m09#4.o0" to "Fortsätta uppåt enligt planen",
    "q.m09#4.o1" to "Fortfarande inte vinna höjd; gå ner så snart som möjligt",
    "q.m09#4.o2" to "Öka dosen och fortsätta",
    "q.m09#4.o3" to "Sluta med läkemedlet omedelbart och observera",
    "q.m09#4.e" to "Läkemedlet tar bort symtomen, men orsaken till hjärnödemet — hypoxin — finns kvar. Handbokens slutsats är klar: även med symtomlindring ska du inte fortsätta vinna höjd. Nedstigning är den enda åtgärd som tar bort orsaken.",
    "q.m09#5.p" to "Hur används aspirin för att lindra höjdhuvudvärk?",
    "q.m09#5.o0" to "Ta det när värken börjar",
    "q.m09#5.o1" to "Förebyggande: börja tidigt och dosera regelbundet",
    "q.m09#5.o2" to "Bara vid sänggåendet",
    "q.m09#5.o3" to "Bara efter nedstigning",
    "q.m09#5.e" to "Handboken anger 320 mg tre gånger dagligen från dagen före uppstigningen tills acklimatiseringen är klar — en regelbunden förebyggande regim, inte «ta när det gör ont». De två förhållningssätten bygger på helt olika logik.",
    "q.m09#6.p" to "Vad är den grundläggande skillnaden mellan acetazolamid och dexametason?",
    "q.m09#6.o0" to "Det ena är billigt och det andra dyrt",
    "q.m09#6.o1" to "Det ena påskyndar acklimatiseringen, det andra lindrar bara symtom",
    "q.m09#6.o2" to "Det ena tas oralt och det andra injiceras",
    "q.m09#6.o3" to "De verkar identiskt",
    "q.m09#6.e" to "Den skillnaden avgör allt som följer: med acetazolamid kan förbättring läsas som att kroppen verkligen acklimatiseras; med dexametason är förbättringen bara en maskering — och om du får fortsätta uppåt har motsatta svar i de två fallen.",
    "q.m09#7.p" to "[Flerval] Vilka påståenden om läkemedel på höjd är korrekta?",
    "q.m09#7.o0" to "Läkemedel kan inte ersätta nedstigning",
    "q.m09#7.o1" to "Dos och timing kräver medicinsk vägledning",
    "q.m09#7.o2" to "Olika läkemedel riktar sig mot olika tillstånd och får inte blandas ihop",
    "q.m09#7.o3" to "När läkemedel maskerar symtomen blir bedömningen svårare",
    "q.m09#7.o4" to "När symtomen lindras kan du säkert fortsätta uppåt",
    "q.m09#7.e" to "De fyra första är centrala. Det mest förbisedda är att maskeringen gör bedömningen svårare: när symtomen är borta förlorar du ditt mest direkta mått och måste lita på mer objektiva tecken — gång, medvetande, andning. Titta därför ännu noggrannare på dessa tre efter att läkemedlet getts.",
    "q.m09#8.p" to "Varför är «inga läkemedel, gå ner nu» ofta det mest tillförlitliga valet?",
    "q.m09#8.o0" to "För att läkemedel inte fungerar",
    "q.m09#8.o1" to "För att nedstigning tar bort orsaken, medan läkemedel bara verkar indirekt",
    "q.m09#8.o2" to "För att läkemedel är dyra",
    "q.m09#8.o3" to "För att läkemedel är besvärliga att bära",
    "q.m09#8.e" to "Orsaken till höjdsjuka är hypoxi, och hypoxin kommer direkt från höjden. Nedstigning tar bort orsaken; läkemedel förändrar bara hur kroppen svarar på den. När förhållandena tillåter är nedstigning den högst prioriterade åtgärden.",
    "q.m09#9.p" to "[Ordning] En lagmedlem visar tecken på allvarlig höjdsjuka. Vilken är rätt ordning?",
    "q.m09#9.o0" to "Sluta vinna höjd omedelbart; bedöm medvetande, gång och andning",
    "q.m09#9.o1" to "Ordna nedstigning (minst 1 000 m), med syrgas om det finns",
    "q.m09#9.o2" to "Ge lämpligt läkemedel (till exempel dexametason) under medicinsk övervakning",
    "q.m09#9.o3" to "Om nedstigning är omöjlig, använd tryckkammare och larma räddning",
    "q.m09#9.e" to "Ordningen är prioriteringen: bedöm, gå ner, stötta med läkemedel, och först därefter ta till tidsköpande åtgärder. Det vanligaste felet i verkligheten är att vända på det — jaga läkemedlet först och glömma att nedstigningen är den definitiva behandlingen.",
    "q.m09#10.p" to "Varför är det så viktigt att diskutera en läkemedelsplan med läkare i förväg inför en höghöjdsresa?",
    "q.m09#10.o0" to "För att du inte kan köpa läkemedel på berget",
    "q.m09#10.o1" to "För att professionell rådgivning inte finns där uppe, och kräkningar kan ändra administrationsvägen",
    "q.m09#10.o2" to "För att läkemedel går ut i datum",
    "q.m09#10.o3" to "För att guider kräver det",
    "q.m09#10.e" to "På höjd finns ingen läkare och ingen diagnostik; värre är att patienten kan kräkas och inte kunna ta något oralt. Planen — dos, timing, administrationsväg och kontraindikationer — måste vara överenskommen före avfärd.",
    "q.m09#11.p" to "[Matchning] Matcha varje läkemedel med dess huvudsakliga verkan.",
    "q.m09#11.l0" to "Acetazolamid",
    "q.m09#11.l1" to "Dexametason",
    "q.m09#11.l2" to "Nifedipin",
    "q.m09#11.r0" to "Påskyndar acklimatiseringen; används förebyggande",
    "q.m09#11.r1" to "Sänker intrakranialtrycket och lindrar hjärnödem",
    "q.m09#11.r2" to "Lindrar pulmonell vasokonstriktion; används vid lungödem",
    "q.m09#11.e" to "Tre kort, tre uppgifter: acetazolamid för acklimatisering, dexametason för hjärnan, nifedipin för lungorna. Ta först reda på vilket problem patienten har och välj sedan kort — i stället för att behandla varje läkemedel som en generisk «höjdtablett».",
    "q.m10#0.p" to "Vad är ett väderfönster?",
    "q.m10#0.o0" to "Dagen med lägst nederbördssannolikhet i prognosen",
    "q.m10#0.o1" to "Perioden under vilken du säkert kan genomföra målet",
    "q.m10#0.o2" to "Timmarna med mest dagsljus",
    "q.m10#0.o3" to "Tiden med minst vind",
    "q.m10#0.e" to "Ett väderfönster är ett sammansatt begrepp: det uppfyller både «vädret tillåter det» och «laget klarar det». Därför har ett starkt lags fönster och ett svagt lags fönster helt olika bredd i samma väder — fönster är relativa, inte absoluta.",
    "q.m10#1.p" to "Varför är väderprognoser i berg relativt oprecisa?",
    "q.m10#1.o0" to "För att det finns för få väderstationer",
    "q.m10#1.o1" to "För att komplex terräng skapar enorm lokal variation — olika höjd och riktning kan ha helt olika väder",
    "q.m10#1.o2" to "För att prognosmakarna är slarviga",
    "q.m10#1.o3" to "För att det inte finns data på höjd",
    "q.m10#1.e" to "Orografisk lyftning, blockering och strömning runt ryggar splittrar vädret i små skalor — några kilometer bort kan vara en annan värld. En regional prognos är bara bakgrund; det är fältobservationen du fattar beslut på.",
    "q.m10#2.p" to "Molnen tätnar och basen sjunker — vad tyder det oftast på?",
    "q.m10#2.o0" to "Bättre väder",
    "q.m10#2.o1" to "Försämrat väder, med sikt som sannolikt faller snabbt",
    "q.m10#2.o2" to "Omedelbar uppklarning",
    "q.m10#2.o3" to "Inget särskilt",
    "q.m10#2.e" to "En sjunkande molnbas betyder stigande luftfuktighet och lägre kondensationsnivå — ofta förebudet till ett nederbördsområde. I bergen betyder det också att sikten snart krymper, vilket är en risk i sig.",
    "q.m10#3.p" to "Varför är trycktrenden viktigare än tryckvärdet?",
    "q.m10#3.o0" to "För att värdet alltid är fel",
    "q.m10#3.o1" to "För att vädret drivs av tryckförändringen, och basvärden skiljer sig mellan höjder ändå",
    "q.m10#3.o2" to "För att trender är lättare att minnas",
    "q.m10#3.o3" to "För att värden fluktuerar för mycket",
    "q.m10#3.e" to "Samma tryckvärde betyder helt olika saker på olika höjder och platser, så en enskild siffra saknar referensram. Ett ihållande fall pekar däremot på samma sak överallt: vädret slår om.",
    "q.m10#4.p" to "Vilket praktiskt värde har Beaufortskalan?",
    "q.m10#4.o0" to "Den får vinden att se proffsigare ut",
    "q.m10#4.o1" to "Den omvandlar vindhastighet till en observerbar och kommunicerbar skala för att bedöma framkomlighet och prata med varandra",
    "q.m10#4.o2" to "Den mäter nederbörd",
    "q.m10#4.o3" to "Den uppskattar temperaturen",
    "q.m10#4.e" to "Vind är information som måste sägas: ett lag behöver ett gemensamt språk för «kan vi fortsätta». Beaufort gör en abstrakt hastighet till observerbara tecken — löv, yrsnö, hur det känns — så att bedömningen sprider sig snabbt i gruppen.",
    "q.m10#5.p" to "[Flerval] Vilka av dessa är tecken i fält på att vädret försämras?",
    "q.m10#5.o0" to "Trycket faller stadigt",
    "q.m10#5.o1" to "Molnen tätnar snabbt och basen sjunker",
    "q.m10#5.o2" to "Vinden ökar märkbart och vrider ofta",
    "q.m10#5.o3" to "Cumulonimbus bygger upp i fjärran",
    "q.m10#5.o4" to "Trycket stiger stadigt och vinden avtar",
    "q.m10#5.e" to "De fyra första är handbokens huvudsakliga försämringssignaler. De beskriver alla en trend snarare än ett ögonblick — därför är regelbunden, tidsatt observation viktig. Bara med något att jämföra mot betyder en trend något.",
    "q.m10#6.p" to "Under ett åskväder, vilket beteende är farligast?",
    "q.m10#6.o0" to "Att stanna och gå ner",
    "q.m10#6.o1" to "Att stanna på en rygg, en topp eller öppet vatten — överallt exponerat",
    "q.m10#6.o2" to "Att packa undan metallutrustning",
    "q.m10#6.o3" to "Att huka lågt och vänta",
    "q.m10#6.e" to "Det sämsta i ett åskväder är att vara det högsta objektet omkring sig. Ryggar och toppar är precis de mest exponerade platserna, så lämna dem så fort blixten hotar. Håll metallutrustning samlad och borta från kroppen.",
    "q.m10#7.p" to "Varför startar toppstötar oftast före gryningen?",
    "q.m10#7.o0" to "För att undvika trängseln",
    "q.m10#7.o1" to "För att tidig morgon oftast är dagens mest stabila del, medan eftermiddagens konvektion ökar och oddsen försämras",
    "q.m10#7.o2" to "För att du har mest energi klockan tre på natten",
    "q.m10#7.o3" to "För att det är för varmt på dagen",
    "q.m10#7.e" to "Det följer dygnscykeln: uppvärmningen på dagen driver konvektionen, så moln- och nederbördschansen ökar på eftermiddagen. Att lägga den svåraste och mest kritiska delen före gryningen är att köpa ett mer förlåtande fönster.",
    "q.m10#8.p" to "Hur hänger vändtiden ihop med väderfönstret?",
    "q.m10#8.o0" to "De har inget med varandra att göra",
    "q.m10#8.o1" to "Vändpunkten bör härledas ur väderfönstret; ett krympande fönster flyttar den tidigare",
    "q.m10#8.o2" to "Vändtiden är alltid fast",
    "q.m10#8.o3" to "Vid bra väder behövs ingen vändtid",
    "q.m10#8.e" to "Vändtiden är ingen fast siffra; den räknas fram ur dagens fönster. Hur lång tid till toppen, hur lång tid ner, när fönstret börjar stängas — baklängesräkningen ger den senaste tidpunkt då du måste vända.",
    "q.m10#9.p" to "[Ordning] Sätt stegen i en rutinmässig väderbedömning i vettig ordning.",
    "q.m10#9.o0" to "Före avfärd: kontrollera den regionala prognosen och trycktrenden",
    "q.m10#9.o1" to "Under rörelse: observera moln, vind och sikt med jämna intervall",
    "q.m10#9.o2" to "Jämför fältobservationerna med prognosen för att bedöma trendens riktning",
    "q.m10#9.o3" to "Justera planen eller vänd tidigt utifrån den trenden",
    "q.m10#9.e" to "Steg tre är knuten — många stannar vid steg två och känner att vädret ändras utan att göra det till ett beslut. Observation som aldrig blir handling är ingen observation.",
    "q.m10#10.p" to "När väderfönstret krymper, vad ska du ge upp först?",
    "q.m10#10.o0" to "Säkerhetsutrustningen",
    "q.m10#10.o1" to "Själva toppmålet",
    "q.m10#10.o2" to "Lagmedlemmar",
    "q.m10#10.o3" to "Kommunikationsutrustningen",
    "q.m10#10.e" to "Det här är en prioriteringsfråga: när fönstret inte rymmer både toppen och en säker nedstigning är det nedstigningen du behåller och toppen du släpper. Bestäm det före avfärd, inte på berget.",
    "q.m10#11.p" to "Vilken syn på whiteout är korrekt?",
    "q.m10#11.o0" to "Bara dålig sikt, ingen fara",
    "q.m10#11.o1" to "Du tappar alla visuella referenser och går instinktivt fel — fastställ positionen först",
    "q.m10#11.o2" to "Det för med sig nederbörd",
    "q.m10#11.o3" to "Det händer bara på natten",
    "q.m10#11.e" to "Farorna med whiteout är inte att du inte kan se — det är att du tror att du kan. Utan referenser driver riktningskänslan systematiskt iväg, så första uppgiften är att fastställa position och anteckna kursen, inte att fortsätta gå.",
    "q.m11#0.p" to "Vilken höjd och plats har Yuzhu Feng?",
    "q.m11#0.o0" to "6 178 m, Golmud i Qinghai, östra Kunlun",
    "q.m11#0.o1" to "6 206 m, Damxung i Tibet, Nyainqêntanglha",
    "q.m11#0.o2" to "6 119 m, Khumbu i Nepal",
    "q.m11#0.o3" to "6 189 m, Khumbu i Nepal",
    "q.m11#0.e" to "Yuzhu är 6 178 m, i östra Kunlun inom Golmud i Qinghai. Sydsluttningsrutten är relativt mild och ansatsen god, vilket är varför den är mångas första 6 000 m-topp.",
    "q.m11#1.p" to "Vilken höjd och bergskedja har Qizi Feng?",
    "q.m11#1.o0" to "6 178 m, Kunlun",
    "q.m11#1.o1" to "6 206 m, Nyainqêntanglha",
    "q.m11#1.o2" to "6 119 m, Himalaya",
    "q.m11#1.o3" to "6 189 m, Karakoram",
    "q.m11#1.e" to "Qizi är 6 206 m, i Nyainqêntanglha vid Damxung i Tibet. Kännetecknet är stabila snösluttningar och lätt ansats — stabila sluttningar gör lavin- och sprickrisken jämförelsevis hanterbar, vilket passar den för progressionsträning.",
    "q.m11#2.p" to "Vilken höjd och plats har Lobuche East?",
    "q.m11#2.o0" to "6 119 m, Khumbu i Nepal",
    "q.m11#2.o1" to "6 189 m, Khumbu i Nepal",
    "q.m11#2.o2" to "6 206 m, Damxung i Tibet",
    "q.m11#2.o3" to "6 178 m, Golmud i Qinghai",
    "q.m11#2.e" to "Lobuche East är 6 119 m i Khumbu i Nepal, alldeles vid Everesttrekkeden. Läget ger etablerad acklimatisering och logistik, och de brantare snösluttningarna gör den till ett bra steg mot högre höjd.",
    "q.m11#3.p" to "Vad är det mest typiska tekniska draget hos Island Peak (Imja Tse)?",
    "q.m11#3.o0" to "Ingen teknisk utrustning krävs alls",
    "q.m11#3.o1" to "Replag och passering över sprickor",
    "q.m11#3.o2" to "Extra syrgas krävs",
    "q.m11#3.o3" to "Klättringsförmåga på klippa krävs",
    "q.m11#3.e" to "Island Peak på 6 189 m är en klassisk teknisk 6 000 m-topp: du går i replag och hanterar sprickor. Det är också därför den används som förberedelse för 7 000 m — den sätter glaciärfärd plus replag i verklig användning.",
    "q.m11#4.p" to "Jämfört med 5 000 m, vilken risk ökar mest på 6 000 m?",
    "q.m11#4.o0" to "Stenfall",
    "q.m11#4.o1" to "Acklimatiseringstryck och risken för höjdsjuka",
    "q.m11#4.o2" to "Insekter",
    "q.m11#4.o3" to "Utrustningens vikt",
    "q.m11#4.e" to "Över 6 000 m stiger både förekomsten och svårighetsgraden av höjdsjuka markant — därför behandlar det här avsnittet höjdsjuka som ett kapitel i kärnan. Tekniskt kan steget vara gradvis, men det fysiologiska steget är verkligt.",
    "q.m11#5.p" to "[Flerval] Vad bör du redan behärska före en 6 000 m-topp?",
    "q.m11#5.o0" to "Grundläggande användning av stegjärn och isyxa",
    "q.m11#5.o1" to "Grundläggande knopar och rörelse i replag",
    "q.m11#5.o2" to "Att känna igen och hantera höjdsjuka",
    "q.m11#5.o3" to "Grundläggande förståelse för sprickrisk",
    "q.m11#5.o4" to "Att leda WI5-is på egen hand",
    "q.m11#5.e" to "De fyra första motsvarar instegs- och progressionsavsnitten för 5 000 m. 6 000 m-avsnittet lär inte ut dem igen; det sätter dem i en hårdare miljö. Att gå direkt på 6 000 m med svag grund multiplicerar risken.",
    "q.m11#6.p" to "Varför är Yuzhus sydsluttning ofta det första 6 000 m-målet?",
    "q.m11#6.o0" to "För att den är billigast",
    "q.m11#6.o1" to "För att rutten är relativt mild och ansats och logistik etablerade, så du kan fokusera på acklimatiseringen",
    "q.m11#6.o2" to "För att den inte har någon fara",
    "q.m11#6.o3" to "För att den inte kräver guide",
    "q.m11#6.e" to "Värdet av ett första mål är att bara lägga till en ny variabel. Sydsluttningen håller den tekniska svårigheten inom ett hanterbart intervall så att du kan koncentrera dig på den verkliga utmaningen — acklimatiseringen. Väljer du en tekniskt krävande 6 000 m-topp vet du inte vad som gick fel.",
    "q.m11#7.p" to "[Ordning] Ordna dessa mål från lägst till högst höjd.",
    "q.m11#7.o0" to "Lobuche East (6 119 m)",
    "q.m11#7.o1" to "Yuzhu Feng (6 178 m)",
    "q.m11#7.o2" to "Island Peak (6 189 m)",
    "q.m11#7.o3" to "Qizi Feng (6 206 m)",
    "q.m11#7.e" to "Höjdspannet är litet — 6 119 till 6 206 m, mindre än 90 m. Det visar poängen tydligt: i 6 000 m-bandet bör du välja efter rutt, stöd och dina egna svaga punkter, inte efter höjdsiffran.",
    "q.m11#8.p" to "Varför måste du räkna med sprickor på 6 000 m?",
    "q.m11#8.o0" to "För att sprickor låter",
    "q.m11#8.o1" to "För att snöbryggor kan vara helt övertäckta av nysnö och se ut som vanlig mark",
    "q.m11#8.o2" to "För att sprickor bara syns på natten",
    "q.m11#8.o3" to "För att sprickor är lätta att identifiera",
    "q.m11#8.e" to "Det är just det som gör sprickor så livsfarliga: till skillnad från stenfall ger de ingen tydlig varning. Rätt inställning på 6 000 m är «de finns överallt» och att hantera risken med replag och utrustning i stället för att bedöma om det ser säkert ut.",
    "q.m11#9.p" to "När du väljer en 6 000 m-topp, vad väger tyngre än höjden?",
    "q.m11#9.o0" to "Hur känd toppen är",
    "q.m11#9.o1" to "Ruttens typ (vandring / blandad / teknisk), stödförhållandena och uppstigningstakten",
    "q.m11#9.o2" to "Kostnaden",
    "q.m11#9.o3" to "Populariteten i sociala medier",
    "q.m11#9.e" to "Toppar på liknande höjd kan skilja sig enormt i tekniskt krav och acklimatiseringstryck. Först genom att kombinera rutt, stöd och uppstigningstakt får du svar på «passar det här berget mig just nu».",
    "q.m11#10.p" to "Vilken syn på 6 000 m-tröskeln är korrekt?",
    "q.m11#10.o0" to "Den är mycket låg; det räcker med form",
    "q.m11#10.o1" to "Den är inte hög, men du kan inte börja från noll, och glaciärfärdighet är obligatorisk",
    "q.m11#10.o2" to "Du måste ha klätterbakgrund på klippa",
    "q.m11#10.o3" to "Du måste kunna använda extra syrgas",
    "q.m11#10.e" to "Den typiska 6 000 m-profilen: måttlig teknisk svårighet, men du måste redan kunna gå i replag, bedöma sprickrisk och röra dig självständigt på en glaciär. Det är där «jag kan skydda mig med ett system» börjar — inte där du ser andra göra det.",
    "q.m11#11.p" to "Varför är toppens bästa säsong så avgörande för planen?",
    "q.m11#11.o0" to "För att tillstånd är billigare utanför säsong",
    "q.m11#11.o1" to "För att det klättringsbara fönstret starkt beror på säsongens vädermönster; fel säsong kan ge nästan inget fönster",
    "q.m11#11.o2" to "För att säsongen ändrar snöns färg",
    "q.m11#11.o3" to "För att guider bara arbetar under högsäsong",
    "q.m11#11.e" to "Skälen skiljer sig mellan toppar: vissa säsonger undviker monsunnederbörd, andra extrem vinterkyla och vind. Att förstå varför en säsong fungerar är mycket viktigare än att memorera vilken månad — särskilt när klimatförändringarna förskjuter mönstren.",
    "q.m12#0.p" to "Varför ger ett 3:1 Z-system (Z-drag) tre gånger så stor dragkraft?",
    "q.m12#0.o0" to "För att det använder ett tjockare rep",
    "q.m12#0.o1" to "För att kombinationen prusik och trissa tredubblar din draglängd",
    "q.m12#0.o2" to "För att gravitationen hjälper till",
    "q.m12#0.o3" to "För att trissor automatiskt sparar kraft",
    "q.m12#0.e" to "Mekanisk fördel är i grunden att byta avstånd mot kraft: du drar tre meter rep och lasten stiger en meter. Priset är hastighet — och vid sprickräddning är det priset helt acceptabelt.",
    "q.m12#1.p" to "Vad är trissans huvuduppgift i ett räddningssystem?",
    "q.m12#1.o0" to "Att ge extra styrka",
    "q.m12#1.o1" to "Att minska repets friktionsförluster och förbättra systemets verkningsgrad",
    "q.m12#1.o2" to "Att fixera repet",
    "q.m12#1.o3" to "Att skydda repet från slitage",
    "q.m12#1.e" to "Friktion är den mekaniska fördelens dolda fiende: varje omledning kostar kraft. En trissa förvandlar glidfriktion till rullfriktion, så att det teoretiska 3:1 kommer närmare ett verkligt 3:1.",
    "q.m12#2.p" to "Kan ett räddningssystem byggas utan trissor?",
    "q.m12#2.o0" to "Inte alls",
    "q.m12#2.o1" to "Ja, med karbiner — men friktionen ökar märkbart och verkningsgraden sjunker",
    "q.m12#2.o2" to "Ja, med enbart rep, med samma verkningsgrad",
    "q.m12#2.o3" to "Nej, du måste vänta på utrustning",
    "q.m12#2.e" to "Karbiner kan ersätta trissor, vilket är varför många lag behandlar extra skruvkarbiner som obligatoriska. Skillnaden är att den faktiska fördelen hamnar klart under det teoretiska värdet — att veta det gör att du kan förbereda dig mentalt och fysiskt när utrustningen är ofullständig.",
    "q.m12#3.p" to "[Flerval] Vad anger handboken som standardutrustning för räddning i replag?",
    "q.m12#3.o0" to "2–3 snöankare eller isskruvar",
    "q.m12#3.o1" to "2–5 karbiner och 2–5 slingor",
    "q.m12#3.o2" to "1 säkringstrissa",
    "q.m12#3.o3" to "2–3 prusikar och 1 klättrare (ascender)",
    "q.m12#3.o4" to "1 portabelt kök och en gasbehållare",
    "q.m12#3.e" to "Den viktiga raden i listan är att varje medlem i replaget ska bära tillräcklig räddningsutrustning — det vill säga personlig utrustning, inte delad grupputrustning. När någon faller är det som sitter på din sele den enda utrustning som finns.",
    "q.m12#4.p" to "Hur bromsar en ascender?",
    "q.m12#4.o0" to "Med en fjäder som klämmer repet",
    "q.m12#4.o1" to "Genom omvänd friktion mellan ståltänderna och repet",
    "q.m12#4.o2" to "Genom magnetisk attraktion",
    "q.m12#4.o3" to "Genom repets egen vikt",
    "q.m12#4.e" to "Att förstå mekanismen spelar roll i användningen: eftersom ståltänderna biter i fibrerna skadar för stor kraft repet och kan skära av fibrer vid den belastade punkten. Därför betonar handboken att den så långt möjligt ska användas med en assisterad bromsmetod.",
    "q.m12#5.p" to "Vad händer om du rycker för hårt i en ascender?",
    "q.m12#5.o0" to "Ingenting alls",
    "q.m12#5.o1" to "Ståltänderna skadar repet",
    "q.m12#5.o2" to "Ascendern fastnar",
    "q.m12#5.o3" to "Ascendern faller av",
    "q.m12#5.e" to "Tänderna bromsar genom omvänd friktion, så hård kraft ärr i manteln och kan sammantaget skapa en brottpunkt. Du kommer att se många som vant rycker i ascendern — de byter en vana mot en risk.",
    "q.m12#6.p" to "[Ordning] Sätt stegen för att bygga ett 3:1 Z-system i vettig ordning.",
    "q.m12#6.o0" to "Bekräfta att ankaret håller och flytta den fallnes vikt till det",
    "q.m12#6.o1" to "Sätt huvudprusiken på det belastade repet och lägg till en backupprusik",
    "q.m12#6.o2" to "Koppla en trissa eller karbin till prusiken så att Z-banan bildas",
    "q.m12#6.o3" to "Kontrollera hela systemet och dra sedan, med omspänning efter varje drag",
    "q.m12#6.e" to "Första steget är grunden: utan viktöverföring är dina händer upptagna med att hålla kvar bromsen. Och sista steget — omspänning efter varje drag — hoppas lätt över, och då drar folk länge för att sedan glida tillbaka.",
    "q.m12#7.p" to "[Matchning] Matcha varje räddningsdel med dess roll i systemet.",
    "q.m12#7.l0" to "Prusik",
    "q.m12#7.l1" to "Trissa",
    "q.m12#7.l2" to "Säkringstrissa",
    "q.m12#7.l3" to "Ascender",
    "q.m12#7.r0" to "Engreppsfunktion, så systemet kan matas fram och inte glider tillbaka",
    "q.m12#7.r1" to "Minskar friktionsförluster och förbättrar verkningsgraden",
    "q.m12#7.r2" to "Låser i en riktning; används för att kontrollera utsläpp och åtdragning",
    "q.m12#7.r3" to "Flyttas uppåt på repet; används också för att fixera systemet",
    "q.m12#7.e" to "Fyra olika uppgifter: prusiken ger engreppsfunktion, trissan minskar friktionen, säkringstrissan ger kontroll och ascendern ger rörlighet. Tappar du en blir systemet antingen ineffektivt eller okontrollerbart.",
    "q.m12#8.p" to "Varför lägga en backupprusik vid sidan av huvudprusiken?",
    "q.m12#8.o0" to "För syns skull",
    "q.m12#8.o1" to "För att en prusik kan svikta av is, smuts eller felmatchade diametrar, och ett svikt förlorar fördelen direkt",
    "q.m12#8.o2" to "För att reglerna kräver det",
    "q.m12#8.o3" to "För att hindra att repet tvinnas",
    "q.m12#8.e" to "En prusik verkar genom friktion, och friktionen beror på många saker. Om huvudprusiken glider faller den fallne igen utan varning — backupens uppgift är att fånga det ögonblicket.",
    "q.m12#9.p" to "Hur väljer du mellan ett 2:1- och ett 3:1-system?",
    "q.m12#9.o0" to "2:1 är alltid bättre",
    "q.m12#9.o1" to "Efter bemanning, replängd och terräng: mer fördel kräver mer rep och går långsammare",
    "q.m12#9.o2" to "3:1 är alltid bättre",
    "q.m12#9.o3" to "De är identiska",
    "q.m12#9.e" to "Mekanisk fördel är inte ovillkorligt bra: 3:1 kräver mer rep, och vid sprickräddning är repet ofta begränsat. Det verkliga valet är det system du kan genomföra med det rep och de personer du har — inte det teoretiskt optimala.",
    "q.m12#10.p" to "Varför kan ett system med mekanisk fördel aldrig ersätta omdöme?",
    "q.m12#10.o0" to "För att system går sönder",
    "q.m12#10.o1" to "För att ett system bara mångfaldigar kraft; det kan inte avgöra om du ska dra eller åt vilket håll",
    "q.m12#10.o2" to "För att system är tunga",
    "q.m12#10.o3" to "För att de kräver många personer",
    "q.m12#10.e" to "Det svåra i en räddning är aldrig fysiken; det är omdömet — åt vilket håll, över vilken kant, och om den skadade klarar det. Systemet är ett verktyg; riktningen kommer från människor. Har du fel riktning gör mer kraft det bara värre.",
    "q.m12#11.p" to "Vilket av dessa får inte en prusik att svikta?",
    "q.m12#11.o0" to "Felmatchede repdiametrar",
    "q.m12#11.o1" to "Is eller smuts",
    "q.m12#11.o2" to "För få varv",
    "q.m12#11.o3" to "Ett ljusare färgat huvudrep",
    "q.m12#11.e" to "Diameter, renhet och antalet varv påverkar alla friktionen direkt; färgen har inget med mekaniken att göra. Det visar också att prusikens tillförlitlighet inte kan bedömas på syn — bara genom att kontrollera kombinationen i förväg och testa den i fält.",
    "q.m12#12.p" to "Varför används ofta en säkringstrissa i stället för en vanlig trissa?",
    "q.m12#12.o0" to "För att den är lättare",
    "q.m12#12.o1" to "För att den låser i en riktning, så att du kan kontrollera utsläppet utan att systemet glider tillbaka",
    "q.m12#12.o2" to "För att den är billigare",
    "q.m12#12.o3" to "För att färgen syns bättre",
    "q.m12#12.e" to "Vid räddning drar och justerar man ofta samtidigt, och en vanlig trissa löper fritt åt båda håll — släpper du tappar du framsteg. En engreppskomponent gör positionen till en egenskap hos systemet. Ett tydligt exempel på att hårdvaruval påverkar den operativa säkerheten.",
    "q.m12#13.p" to "Fyll i: Z-systemets mekaniska fördel är ( ):1.",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "tre",
    "q.m12#13.e" to "3:1. Det talets praktiska värde är lastberäkningen: en vuxen med utrustning kan väga 80–100 kg, så vid 3:1 måste du ändå dra med cirka 30 kg kraft — mycket tyngre än det låter, vilket är varför räddningar kräver flera personer.",
    "q.m12#14.p" to "[Flerval] Vad ska kontrollen efter bygget omfatta?",
    "q.m12#14.o0" to "Prusikens varv och lastriktning är korrekta",
    "q.m12#14.o1" to "Trissor och karbiner är låsta",
    "q.m12#14.o2" to "Infästningarna sitter på rätt del av selen",
    "q.m12#14.o3" to "Backup finns och repet är inte fastklämt",
    "q.m12#14.o4" to "Repet och kamraternas kläder har samma färg",
    "q.m12#14.e" to "De fyra kontrollerna motsvarar fyra klassiska fel: prusik bakvänd, grind olåst, klippt i fel ögla, ingen backup. Fel i räddningssystem beror sällan på kunskapsbrist — det är ett överhoppat steg i mörker och stress. Använd en checklista, inte minnet.",
    "q.m12#15.p" to "Varför måste ett räddningssystem övas före avfärd?",
    "q.m12#15.o0" to "För att klara en examination",
    "q.m12#15.o1" to "För att den verkliga räddningen sker på höjd, i kyla och mörker, utförd på instinkt",
    "q.m12#15.o2" to "För att bli van vid utrustningen",
    "q.m12#15.o3" to "För att regelverket anger övningstimmar",
    "q.m12#15.e" to "Förhållandena vid en verklig räddning är nästan alltid de sämsta möjliga: blåst, kalla händer, dåligt ljus, en partner som blir sämre. De enda handlingar som blir gjorda under sådana förhållanden är de du upprepat många gånger tidigare — att lära sig på plats är inget alternativ.",
    "q.m13#0.p" to "Varför är självräddning ett hårt krav på 7 000 m?",
    "q.m13#0.o0" to "För att kamraterna inte vill rädda dig",
    "q.m13#0.o1" to "För att kamrater på höjd kanske inte når dig i tid — du måste kunna hantera din egen situation",
    "q.m13#0.o2" to "För att räddningsutrustningen är otillräcklig",
    "q.m13#0.o3" to "För att reglerna kräver det",
    "q.m13#0.e" to "Ju högre upp, desto dyrare och långsammare blir räddningen. En partner kan kämpa med egen höjdsjuka, och vädret kan förbjuda all förflyttning. Att helt lämna sig själv till utomstående räddning är att acceptera en förutsättning som ingen kan garantera.",
    "q.m13#1.p" to "Vad är grundprincipen för prusikuppstigning?",
    "q.m13#1.o0" to "Att dra sig upp med armstyrka",
    "q.m13#1.o1" to "Att växla mellan två prusikar: en bär vikten medan den andra glider uppåt på repet",
    "q.m13#1.o2" to "Att göra det själv med en ascender",
    "q.m13#1.o3" to "Att greppa repet mellan benen",
    "q.m13#1.e" to "En enda prusik håller bara en position — den kan inte flyttas — så två måste växla: medan den nedre bär vikten glider den övre upp, och tvärtom. Den växlande rörelsen måste nötas i säker miljö; den avgör, i det ögonblick du behöver den som mest, om du kommer upp alls.",
    "q.m13#2.p" to "Varför måste minst en prusik alltid vara belastad under prusikuppstigning?",
    "q.m13#2.o0" to "För att spara kraft",
    "q.m13#2.o1" to "För att om du släpper båda samtidigt glider du tillbaka till start eller faller",
    "q.m13#2.o2" to "För att hålla repet snyggt",
    "q.m13#2.o3" to "För att klättra snabbare",
    "q.m13#2.e" to "Det är trepunktsregeln tillämpad på rep: håll alltid en tillförlitlig stödpunkt. I en spricka gör en enda slint inte bara att du tappar kraft utan kan också låta repet skära djupare in i snökanten, vilket ökar svårigheten i hela räddningen.",
    "q.m13#3.p" to "[Ordning] Sätt de fyra stegen i en replagsräddning i rätt ordning.",
    "q.m13#3.o0" to "Gör självstopp omedelbart och stabilisera dig",
    "q.m13#3.o1" to "Bygg ett oberoende ankare",
    "q.m13#3.o2" to "Flytta lasten till ankaret",
    "q.m13#3.o3" to "Dra med ett 3:1-system",
    "q.m13#3.e" to "Du lärde dig de fyra stegen i 6 000 m-avsnittet; här handlar det om att utföra dem under press. Den största skillnaden mellan övning och verklighet: i verkligheten måste du göra de tre första stegen på tiotals sekunder, medan du i övningen kanske tog fem minuter.",
    "q.m13#4.p" to "Hur långt ifrån varandra bör lagmedlemmar hålla sig i ett åskväder?",
    "q.m13#4.o0" to "Tätt tillsammans",
    "q.m13#4.o1" to "Cirka 50 m",
    "q.m13#4.o2" to "Cirka 500 m",
    "q.m13#4.o3" to "Ingen gräns",
    "q.m13#4.e" to "Handboken föreslår ungefär 50 m — poängen är att undvika att ett nedslag skadar flera samtidigt, så att någon fortfarande kan ge första hjälpen. Bakom siffran ligger en enkel tanke: satsa aldrig allt på ett ställe.",
    "q.m13#5.p" to "Vad är det enda effektiva sättet att minska faran under ett åskväder?",
    "q.m13#5.o0" to "Kasta bort metallutrustning som isyxor",
    "q.m13#5.o1" to "Lämna höjdpunkter och exponerad terräng så snabbt som möjligt och håll dig så lågt du kan",
    "q.m13#5.o2" to "Huka och håll om knäna",
    "q.m13#5.o3" to "Öppna alla blixtlås",
    "q.m13#5.e" to "Handboken avvisar uttryckligen flera vanliga metoder: det finns inga belägg för att små metallföremål som isyxor eller tältstänger drar till sig blixtar, så slösa inte tid på att kasta dem. Det som faktiskt fungerar är att byta position — från det högsta objektet omkring till en oansenlig del av landskapet.",
    "q.m13#6.p" to "Om du hör åska är blixten högst ungefär:",
    "q.m13#6.o0" to "3 km bort",
    "q.m13#6.o1" to "10–16 km bort",
    "q.m13#6.o2" to "30 km bort",
    "q.m13#6.o3" to "50 km bort",
    "q.m13#6.e" to "Att höra åska betyder att blixten är inom 10–16 km, redan inne i det avstånd där du måste agera. Att se blixten betyder att avståndet är högst cirka 24 km — två siffror, två olika responsnivåer.",
    "q.m13#7.p" to "Hur uppskattar du blixtens avstånd från fördröjningen mellan blixt och dunder?",
    "q.m13#7.o0" to "Sekunder × 0,34 = avstånd i km",
    "q.m13#7.o1" to "Sekunder ÷ 0,34 = avstånd i km",
    "q.m13#7.o2" to "Sekunder × 3,4 = avstånd i km",
    "q.m13#7.o3" to "Det går inte att uppskatta",
    "q.m13#7.e" to "Ljud färdas i luft med cirka 0,34 km per sekund, så varje sekund du räknar efter blixten är ungefär 0,34 km. Det praktiska värdet: helt utan utrustning kan du avgöra om ovädret närmar sig eller flyttar bort.",
    "q.m13#8.p" to "Drar små metallföremål (isyxa, tältstänger) till sig blixtar?",
    "q.m13#8.o0" to "Ja — kasta dem omedelbart",
    "q.m13#8.o1" to "Det finns inga belägg för det, så slösa inte tid på att kasta bort dem",
    "q.m13#8.o2" to "Ja, men bara på hög höjd",
    "q.m13#8.o3" to "Bara när de är blöta",
    "q.m13#8.e" to "Det här är en klassisk höghöjdsmyt. Handboken är tydlig: det finns inga belägg, så använd inte dyrbar tid på att göra dig av med utrustning. Det du måste göra är att lämna den exponerade positionen så snabbt som möjligt — det är den avgörande variabeln.",
    "q.m13#9.p" to "Var skyddar du dig bäst under ett åskväder?",
    "q.m13#9.o0" to "På en topp",
    "q.m13#9.o1" to "Mitt i skog, borta från topp och rygg — men aldrig lutad mot ett träd",
    "q.m13#9.o2" to "Mitt i en grässluttning",
    "q.m13#9.o3" to "Inne i ett tält",
    "q.m13#9.e" to "Mitt i skogen fungerar eftersom det finns högre objekt omkring dig, utan att du står direkt mot en ledare. Motexemplet är att tälta på en öppen rygg — handboken kallar det synnerligen dåraktigt, eftersom du då medvetet har slagit läger på den högsta punkten omkring.",
    "q.m13#10.p" to "Varför ska du inte tälta på en rygg medan cumulusmolnen bygger upp?",
    "q.m13#10.o0" to "För att det blåser kraftigt",
    "q.m13#10.o1" to "För att cumulus som växer till cumulonimbus betyder blixt, och en rygg är den mest exponerade platsen av alla",
    "q.m13#10.o2" to "För att sikten är dålig",
    "q.m13#10.o3" to "För att marken är ojämn",
    "q.m13#10.e" to "Övergången från cumulus till cumulonimbus tar ofta bara en eller två timmar. Att tälta på en rygg placerar dig längst fram i ovädrets bana — med all utrustning och alla tält, i ett läge där snabb evakuering nästan är omöjlig.",
    "q.m13#11.p" to "Någon har just träffats av blixten. Vad är första prioritet?",
    "q.m13#11.o0" to "Kontrollera yttre skador först",
    "q.m13#11.o1" to "Kontrollera andning och puls omedelbart, starta HLR om det behövs och skaffa medicinsk hjälp så snart som möjligt",
    "q.m13#11.o2" to "Byt till torra kläder först",
    "q.m13#11.o3" to "Flytta personen till lägre mark först",
    "q.m13#11.e" to "Ett nedslag kan orsaka hjärtstopp och inre skador utan att lämna synliga tecken. Att kontrollera andning och puls kommer därför före allt annat — och även en vaken patient måste evakueras, eftersom strömmens effekt på hjärtat kan visa sig senare.",
    "q.m13#12.p" to "[Flerval] Vad brukar förmågan till självräddning omfatta?",
    "q.m13#12.o0" to "Prusikuppstigning",
    "q.m13#12.o1" to "Självstopp och självskydd",
    "q.m13#12.o2" to "Att bygga ett ankare utan hjälp av en partner",
    "q.m13#12.o3" to "Att bedöma när du ska vänta på plats och när du ska ta dig loss själv",
    "q.m13#12.o4" to "Att freesola utan säkring",
    "q.m13#12.e" to "De tre första är färdigheter, den fjärde är omdöme. Lägg särskilt märke till «bedöma när du ska vänta på plats och när du ska ta dig loss själv»: inte varje situation kräver egen utryckning — är du skadad eller vädret försämras kan det vara säkrare att stanna och invänta räddning än att röra sig förhastat.",
    "q.m13#13.p" to "Varför kan «vänta på att min partner räddar mig» inte vara din huvudsakliga säkerhetsstrategi?",
    "q.m13#13.o0" to "För att partnern kanske inte vill",
    "q.m13#13.o1" to "För att partnern kan vara i fara själv, skadad eller oförmögen att röra sig",
    "q.m13#13.o2" to "För att det inte finns tillräckligt med räddningsutrustning",
    "q.m13#13.o3" to "För att reglerna inte tillåter det",
    "q.m13#13.e" to "Poängen med replag är ömsesidigt skydd, men du kan inte förutsätta att partnern har reservkapacitet. På höjd överskrider det ofta vad som är möjligt när en lagmedlem ska hantera två personers problem — därför är självräddning ett krav och partnerräddning en bonus.",
    "q.m14#0.p" to "Vilken fråga försöker riskbedömningen egentligen besvara?",
    "q.m14#0.o0" to "Finns det fara?",
    "q.m14#0.o1" to "Är den här risken acceptabel, och på vilka grunder?",
    "q.m14#0.o2" to "Hur stor är faran?",
    "q.m14#0.o3" to "Kommer mina kamrater att bli rädda?",
    "q.m14#0.e" to "«Finns det fara?» är nästan alltid «ja» — ingen fjällaktivitet är riskfri. Den verkliga frågan är om risken är värd att ta i förhållande till vinsten, och vad vi grundar det på. Just därför måste bedömningen kunna sägas högt och diskuteras.",
    "q.m14#1.p" to "Vad är «olyckskedjan»?",
    "q.m14#1.o0" to "Antalet skadade i en olycka",
    "q.m14#1.o1" to "En process där flera små fel staplas i följd tills en olycka inträffar",
    "q.m14#1.o2" to "Tidslinjen för en räddning",
    "q.m14#1.o3" to "En kedja av utrustningsfel",
    "q.m14#1.e" to "Det mest värdefulla med begreppet är att det förvandlar en olycka från otur till en påverkbar process. Gör du ett annat val i vilken enskild länk som helst förändras utfallet.",
    "q.m14#2.p" to "Vad är det mest effektiva sättet att bryta olyckskedjan?",
    "q.m14#2.o0" to "Att göra ett mer konservativt val i vilken länk som helst",
    "q.m14#2.o1" to "Att bara fokusera på den sista länken",
    "q.m14#2.o2" to "Att bära mer utrustning",
    "q.m14#2.o3" to "Att förbättra lagets form",
    "q.m14#2.e" to "Vilken länk som helst duger — starta tidigare, vänd i tid, snåla inte med säkringen för att spara tid. Det är också därför marginal slår bot: marginalen verkar tidigt i kedjan, medan boten oftast kommer vid sista länken.",
    "q.m14#3.p" to "[Flerval] Vilka av följande är vanliga beslutsfällor?",
    "q.m14#3.o0" to "Sunk cost (förlorad kostnad)",
    "q.m14#3.o1" to "Grupptryck",
    "q.m14#3.o2" to "Målfokusering",
    "q.m14#3.o3" to "Risktillvänjning",
    "q.m14#3.o4" to "Tro på utrustningsmärken",
    "q.m14#3.e" to "De fyra verkar tillsammans: vi har redan investerat mycket (sunk cost), alla andra går fortfarande uppåt (grupptryck), vi är nästan framme (målfokusering), och förra gången gick det bra (risktillvänjning). När alla fyra dyker upp samtidigt lutar bedömningen nästan oundvikligen mot att ta risken.",
    "q.m14#4.p" to "Hur påverkar sunk cost beslut i bergen?",
    "q.m14#4.o0" to "Det gör människor mer försiktiga",
    "q.m14#4.o1" to "När du redan lagt ner så mycket tid och pengar är det svårt att erkänna att du borde sluta",
    "q.m14#4.o2" to "Det förbättrar formen",
    "q.m14#4.o3" to "Det har ingen effekt",
    "q.m14#4.e" to "Det som definierar sunk cost är att den inte kan återvinnas — ändå blir den psykologiskt ett skäl att fortsätta investera. På berget, tillsammans med målfokusering, förvandlar den en rationell reträtt till «att ge upp», och människor har ett naturligt motstånd mot att ge upp.",
    "q.m14#5.p" to "Vad är «risktillvänjning»?",
    "q.m14#5.o0" to "Att hålla faran inom ett acceptabelt intervall",
    "q.m14#5.o1" to "Att efter att ha klarat ett visst förhållande säkert flera gånger omedvetet omklassificera det som «säkert»",
    "q.m14#5.o2" to "Att lära sig metoder för riskbedömning",
    "q.m14#5.o3" to "Att använda en standardiserad riskgradering",
    "q.m14#5.e" to "Risktillvänjning sker långsamt, vilket är varför den drabbade knappt märker den. Samma klättrare kan vara extremt försiktig första gången på en brant sluttning och inte längre säkra på den tionde — sluttningen har inte förändrats, bedömningen har.",
    "q.m14#6.p" to "Varför är majoritetsbeslut problematiskt i miljöer med hög risk?",
    "q.m14#6.o0" to "För att det är ineffektivt",
    "q.m14#6.o1" to "För att majoritetsbeslut låter en minoritets berättigade oro tystas",
    "q.m14#6.o2" to "För att röstning inte alltid är rättvis",
    "q.m14#6.o3" to "För att lagens storlek skiljer sig",
    "q.m14#6.e" to "Farosignaler upptäcks ofta av bara en eller två personer — någon såg en spricka i snölagret — och den observationen är information som en minoritet har men som är dödlig om den är sann. Att avgöra dess öde genom omröstning ignorerar systematiskt signaler med låg sannolikhet och stor konsekvens.",
    "q.m14#7.p" to "Varför gäller «den mest konservativa åsikten vinner»?",
    "q.m14#7.o0" to "För att konservativa människor är mer erfarna",
    "q.m14#7.o1" to "För att kostnaden för att ha fel i det konservativa alternativet är mycket lägre än i det riskfyllda",
    "q.m14#7.o2" to "För att reglerna kräver det",
    "q.m14#7.o3" to "För att alla ska bli nöjda",
    "q.m14#7.e" to "Det här är ett skolexempel på asymmetrisk kostnad: att vara konservativ kan betyda en bortkastad resa, att vara riskfylld kan betyda döden. När kostnaderna är asymmetriska bör beslutet luta mot den sida vars kostnad är kontrollerbar — och den lutningen måste vara överenskommen före avfärd, annars är den mycket svår att genomföra på plats.",
    "q.m14#8.p" to "[Matchning] Matcha varje beslutsfälla med dess typiska uttryck.",
    "q.m14#8.l0" to "Sunk cost",
    "q.m14#8.l1" to "Grupptryck",
    "q.m14#8.l2" to "Målfokusering",
    "q.m14#8.l3" to "Risktillvänjning",
    "q.m14#8.r0" to "Vi har kommit så här långt — att vända nu vore slöseri",
    "q.m14#8.r1" to "Alla vill fortsätta; det skulle kännas pinsamt att säga att vi borde sluta",
    "q.m14#8.r2" to "Det är bara den sista biten",
    "q.m14#8.r3" to "Förra gången gick det bra",
    "q.m14#8.e" to "Intressant nog dyker dessa fyra meningar ständigt upp i olycksutredningar — och de som säger dem är ofta erfarna klättrare. Det är precis poängen: det här är inte nybörjarproblem, det är problem i hur den mänskliga kognitionen är byggd.",
    "q.m14#9.p" to "Varför betyder «mer erfaren» inte «bedömer mer träffsäkert»?",
    "q.m14#9.o0" to "För att erfarenhet gör dig långsammare",
    "q.m14#9.o1" to "För att erfarenhet gradvis höjer din tolerans för risk",
    "q.m14#9.o2" to "För att erfarenhet inte spelar roll",
    "q.m14#9.o3" to "För att veteraner är envisare",
    "q.m14#9.e" to "Erfarenhet ger förtrogenhet, och förtrogenhet trubbar av vaksamheten. Erfarna lag behöver därför mer externa ramar, inte mindre — fasta vändtider, kvantifierade vädergränser — och använder regler för att motverka en intuition som redan blivit slö.",
    "q.m14#10.p" to "[Ordning] Hur ser en sund process för ett reträttbeslut ut?",
    "q.m14#10.o0" to "Kontrollera de objektiva signaler som bestämdes före avfärd (tid, väder, lagets tillstånd)",
    "q.m14#10.o1" to "Verifiera om de faktiska förhållandena har utlöst någon av dem",
    "q.m14#10.o2" to "Låt den i förväg utsedde beslutsfattaren kalla till reträtt",
    "q.m14#10.o3" to "Genomför reträtten och meddela dem därhemma",
    "q.m14#10.e" to "Värdet med processen är att kontrollera standarden först och situationen sedan — inte tvärtom. Vänder du på ordningen naggas standarden i kanten av stämningen på plats tills den blir «vi ser lite till».",
    "q.m14#11.p" to "Varför utse i förväg vem som har mandat att kalla till reträtt?",
    "q.m14#11.o0" to "För att det ska bli lättare att fördela skuld",
    "q.m14#11.o1" to "För att det är mycket svårt för någon att spontant agera mot gruppens stämning",
    "q.m14#11.o2" to "För att stärka ledarens auktoritet",
    "q.m14#11.o3" to "För att dokumentera processen",
    "q.m14#11.e" to "Reträtt innebär att förneka hela lagets förväntan, vilket är mycket svårt att ta initiativ till i en gruppatmosfär. Gör «att kalla till reträtt» till en i förväg tilldelad plikt i stället för en personlig mods handling — först då blir den faktiskt av.",
    "q.m14#12.p" to "När bör du överväga att avsluta turen?",
    "q.m14#12.o0" to "Aldrig, så länge toppen fortfarande är möjlig",
    "q.m14#12.o1" to "När någon i förväg överenskommen objektiv signal har utlösts",
    "q.m14#12.o2" to "Bara när en lagmedlem är skadad",
    "q.m14#12.o3" to "Närhelst den svagaste bestämmer",
    "q.m14#12.e" to "Utlöst betyder stopp: det är hela poängen med kvantifierade kriterier. Det förvandlar beslutet från «bör vi» till «har det utlösts». Det första kräver argument och övertalning; det andra kräver bara verifiering av fakta — vilket är varför det faktiskt går att genomföra på plats.",
    "q.m14#13.p" to "Vad är det mest effektiva motmedlet mot målfokusering?",
    "q.m14#13.o0" to "Personlig viljestyrka",
    "q.m14#13.o1" to "Att kvantifiera kriterierna före avfärd, så att «lätta på dem» blir en uttalad handling som måste motiveras för kamraterna",
    "q.m14#13.o2" to "Att inte sätta något mål alls",
    "q.m14#13.o3" to "Att bära mer utrustning",
    "q.m14#13.e" to "Psykologisk bias kan inte undvikas genom att påminna sig om att inte falla för den. Den fungerande metoden är att göra «vänd när tiden är inne» till standard, så att den som vill fortsätta aktivt måste ange skäl — bevisbördan vänds i ett drag.",
    "q.m14#14.p" to "Varför är «ingen invände» inte samma sak som «alla var överens»?",
    "q.m14#14.o0" to "För att de kanske inte hörde",
    "q.m14#14.o1" to "För att tystnad bara kan betyda ovilja att förstöra stämningen, med verklig tvekan outsagd",
    "q.m14#14.o2" to "För att någon sov",
    "q.m14#14.o3" to "För att invändningar ignorerades",
    "q.m14#14.e" to "Därför skapar bra lag medvetet oenighet — ledaren frågar rakt ut «vem tycker att vi inte ska fortsätta», eller går runt och låter var och en ta ställning. Tystnad på berget betyder inte enighet; den betyder bara att inget sades.",
    "q.m14#15.p" to "Fyll i luckan: när beslut fattas under osäkerhet bör den mest ( ) åsikten antas först.",
    "q.m14#15.a0" to "konservativa",
    "q.m14#15.e" to "«Konservativ först» är en regel du kan genomföra direkt på plats: du behöver inte bedöma vems argument som är starkast, bara vilket alternativ som är mer konservativt. Priset är möjligen en bortkastad resa — ett pris värt att betala.",
    "q.m14#16.p" to "Scenario: vädret försämras på en toppdag på 7 000 m",
    "q.m14#16.c" to "Det är toppdag på 7 000 m och du startade klockan 03. Klockan 08 når du en punkt ungefär två timmar från toppen. Vinden har tydligt ökat, molnen rusar in från väster och temperaturen faller. En lagmedlem har börjat hosta ihållande och saktar märkbart in.",
    "q.m14#16.e" to "Kärnan i det här scenariot är inte något enskilt svar utan ordningen: verifiera fakta, identifiera farosignalerna, stå emot det psykologiska draget och genomför sedan reträtten ordentligt. De två stegen som oftast fallerar är det första (hoppas över) och det tredje (kapas av känslor).",
    "q.m14#16.s0.p" to "Steg 1: vilken är den första bedömningen du gör just nu?",
    "q.m14#16.s0.o0" to "Bekräfta lagets tillstånd och vädertrenden, och stäm av dem mot de vändsignaler som bestämdes före avfärd",
    "q.m14#16.s0.o1" to "Öka farten och nå toppen innan vädret försämras",
    "q.m14#16.s0.o2" to "Vänta på platsen tills vädret blir bättre",
    "q.m14#16.s0.o3" to "Skicka den långsamma medlemmen ner ensam",
    "q.m14#16.s0.e" to "Varje beslut bör börja med att verifiera fakta: hur mår laget, blir vädret bättre eller sämre, har en förinställd signal utlösts. Hoppar du över det låter du känslan fatta beslutet åt dig.",
    "q.m14#16.s1.p" to "Steg 2: en lagmedlem hostar ihållande. Vad är den mest rimliga åtgärden?",
    "q.m14#16.s1.o0" to "Det är bara kall luft som irriterar luftvägarna — fortsätt gå",
    "q.m14#16.s1.o1" to "På höjd kräver detta hög misstanke om lungödem: sluta vinna höjd och gå ner så snart som möjligt",
    "q.m14#16.s1.o2" to "Ge hostmedicin och fortsätt",
    "q.m14#16.s1.o3" to "Låt personen vila 10 minuter och fortsätt sedan",
    "q.m14#16.s1.e" to "På 7 000 m är en ihållande hosta i vila eller vid lätt ansträngning en signal som kräver hög misstanke. På den här höjden kan kostnaden för att «avvakta lite till» vida överstiga kostnaden för att gå ner direkt.",
    "q.m14#16.s2.p" to "Steg 3: du är två timmar från toppen och beslutar att vända. Vad är det största psykologiska motståndet?",
    "q.m14#16.s2.o0" to "Otillräcklig form",
    "q.m14#16.s2.o1" to "Sunk cost och målfokusering — «vi har tagit oss ända hit»",
    "q.m14#16.s2.o2" to "Utrustningsproblem",
    "q.m14#16.s2.o3" to "Okunnighet om rutten",
    "q.m14#16.s2.e" to "Det är just därför vändtider finns: de flyttar beslutet till ett ögonblick då du fortfarande är rationell. När «det är bara lite till» dyker upp behöver du inte nytt omdöme utan en avstämning mot regeln som bestämdes i förväg.",
    "q.m14#16.s3.p" to "Steg 4: hur bör laget organiseras under nedstigningen?",
    "q.m14#16.s3.o0" to "De starkaste går i förväg för att förbereda lägret",
    "q.m14#16.s3.o1" to "Håll ihop laget, låt den starkaste gå först och sätta takten, och meddela dem därhemma om lagets tillstånd",
    "q.m14#16.s3.o2" to "Dela upp er för att gå ner snabbare",
    "q.m14#16.s3.o3" to "Låt den svagaste gå långsamt ensam",
    "q.m14#16.s3.e" to "På höjd förlorar ett lag som sprider ut sig det ömsesidiga skyddet — och nedstigningen är just den fas med flest olyckor. Att röra sig som en enhet, låta någon kontrollera takten och hålla omvärlden informerad: alla tre är oumbärliga.",
    "q.m15#0.p" to "Vad är det centrala värdet av att läsa moln?",
    "q.m15#0.o0" to "Det får klättringen att verka mer professionell",
    "q.m15#0.o1" to "Det ger dig ledtid på väderförändringen",
    "q.m15#0.o2" to "Det ersätter väderprognosen",
    "q.m15#0.o3" to "Det mäter höjden",
    "q.m15#0.e" to "En prognos kan ge dig en dag i förväg, men vädret i bergen ändras snabbt i små skalor. Molnen är prognosen rakt ovanför ditt huvud — ledtiden kan vara bara en eller två timmar, och den timmen eller två är precis det fönster där du avgör om du ska vända.",
    "q.m15#1.p" to "Vad indikerar cumulusmolnens vertikala utveckling?",
    "q.m15#1.o0" to "Stabilt väder",
    "q.m15#1.o1" to "Stark konvektion, som kan utvecklas till cumulonimbus",
    "q.m15#1.o2" to "Nedkylning är nära förestående",
    "q.m15#1.o3" to "Markvinden avtar",
    "q.m15#1.e" to "Cumulus i sig är inte farlig, men det är en signal som växer. Det viktiga är inte att notera att det är cumulus utan att se den växa, torna upp sig och mörkna — den processen är atmosfären som samlar energi.",
    "q.m15#2.p" to "Vad betyder en städsky på en cumulonimbus?",
    "q.m15#2.o0" to "Den håller fortfarande på att bildas",
    "q.m15#2.o1" to "Den har nått mogen fas; blixt, hagel och kraftig nederbörd är alla möjliga",
    "q.m15#2.o2" to "Den är på väg att lösas upp",
    "q.m15#2.o3" to "Det betyder bara stark vind på hög höjd",
    "q.m15#2.e" to "Städskyen är molnets topp som klippts av av vinden på hög höjd, vilket betyder att uppdraget nått tropopausen och inte kan stiga mer — kännetecknet för ett åskmoln i mogen fas. När du ser en städsky är din reaktionstid redan kort.",
    "q.m15#3.p" to "Vid vilken tid på dygnet bildas cumulusmoln oftast?",
    "q.m15#3.o0" to "Tidig morgon",
    "q.m15#3.o1" to "Förmiddag",
    "q.m15#3.o2" to "Eftermiddag",
    "q.m15#3.o3" to "Sen natt",
    "q.m15#3.e" to "Orsaken är solinstrålningen: marken värms under dagen och ger uppåtgående luft och konvektion. Det är den fysikaliska mekanismen bakom «starta tidigt, gå ner i tid» — inte bara ett ordspråk.",
    "q.m15#4.p" to "Vad indikerar linsmoln (svamp- eller skivformade) oftast?",
    "q.m15#4.o0" to "Lugnt väder",
    "q.m15#4.o1" to "Stark vind",
    "q.m15#4.o2" to "Regn är nära",
    "q.m15#4.o3" to "Stigande temperatur",
    "q.m15#4.e" to "Linsmoln är stående vågmoln som bildas när luft passerar en rygg — deras blotta existens visar hög vindhastighet på höjd. På ett berg betyder det att exponerade ryggar kan få mycket kraftiga byar, och byar är den direkta orsaken till att man tappar balansen.",
    "q.m15#5.p" to "Cirus (tunna höga moln) som ökar markant betyder oftast:",
    "q.m15#5.o0" to "Ett väderväxel närmar sig",
    "q.m15#5.o1" to "Köldperioden är över",
    "q.m15#5.o2" to "Vinden är på väg att avta",
    "q.m15#5.o3" to "UV-strålningen försvagas",
    "q.m15#5.e" to "Cirus är ofta framkanten av ett väderväxel — vädret har inte ändrats än när det dyker upp, men förändringen är på väg. Det är värdefull ledtid, särskilt för en turplan som kräver tidig reträtt.",
    "q.m15#6.p" to "Stratus som sjunker och en molnbas som tydligt faller — vad är den mest direkta effekten?",
    "q.m15#6.o0" to "Temperaturen stiger",
    "q.m15#6.o1" to "Sikten försämras snabbt och terrängbedömningen blir svår",
    "q.m15#6.o2" to "Vinden avtar",
    "q.m15#6.o3" to "Nederbörden upphör",
    "q.m15#6.e" to "Sjunkande stratus ger inte regn utan förlorad sikt — och att förlora sikten är en risk i sig: du kan redan vara ur rutten, närma dig en snöskavel eller missa avtagsvägen för reträtten.",
    "q.m15#7.p" to "[Flerval] Vilka molnförändringar signalerar försämrat väder?",
    "q.m15#7.o0" to "Molntäcket ökar snabbt och lagret tjocknar",
    "q.m15#7.o1" to "Molnbasen fortsätter att sjunka",
    "q.m15#7.o2" to "Molnen mörknar med tydlig vertikal utveckling",
    "q.m15#7.o3" to "En städsky bildas",
    "q.m15#7.o4" to "Molntäcket börjar minska och himlen klarnar",
    "q.m15#7.e" to "Dessa fyra är stadier i en process: täckningen ökar, basen sjunker, kroppen mörknar och tornar upp sig, en städsky syns. Att känna igen dem i ordning gör «vädret slog om» från ett ögonblick till en process du kan varnas för i förväg.",
    "q.m15#8.p" to "Varför utvecklas moln kraftigare i berg än på slätter?",
    "q.m15#8.o0" to "För att det är högre och kallare",
    "q.m15#8.o1" to "För att terrängen tvingar luften uppåt och förstärker konvektionen",
    "q.m15#8.o2" to "För att UV-strålningen är starkare",
    "q.m15#8.o3" to "För att luften är tunn",
    "q.m15#8.e" to "Vind som träffar ett berg tvingas uppåt som om den trycktes uppför en ramp — lyftningen ger direkt avkylning och kondensation, så moln bildas snabbare och mer lokalt än över en slätt. Det är därför vädret i bergen kan ändras helt på mycket kort tid.",
    "q.m15#9.p" to "Hur avgör du om ett moln utvecklas i stället för att lösas upp?",
    "q.m15#9.o0" to "På färgen",
    "q.m15#9.o1" to "Genom att kontinuerligt se om volym, höjd och kantlinjer växer och blir skarpare",
    "q.m15#9.o2" to "På temperaturen",
    "q.m15#9.o3" to "På snödjupet",
    "q.m15#9.e" to "Det avgörande är kontinuerlig observation — en titt ger ett tillstånd, två tittar ger en trend. Ett moln som utvecklas växer i volym, toppen stiger och kanterna blir skarpare; ett som löses upp gör det motsatta. Att titta upp med jämna intervall kostar nästan ingenting och är värt mycket.",
    "q.m15#10.p" to "[Matchning] Matcha varje molntyp med dess väderbetydelse.",
    "q.m15#10.l0" to "Cumulonimbus (städsky)",
    "q.m15#10.l1" to "Linsmoln",
    "q.m15#10.l2" to "Cirus",
    "q.m15#10.l3" to "Låg stratus",
    "q.m15#10.r0" to "Åska, hagel och kraftig nederbörd",
    "q.m15#10.r1" to "Stark vind på höjd, våldsamma byar på ryggar",
    "q.m15#10.r2" to "Ett väderväxel närmar sig",
    "q.m15#10.r3" to "Sikten faller, terrängbedömningen blir svår",
    "q.m15#10.e" to "Dessa fyra täcker de fyra typer av väderinformation du oftast möter på ett berg. En varning: molnläsning kräver bildövning, och den här appen har för närvarande bara textfrågor — bildbaserad molnidentifiering läggs till när bildflödet är på plats.",
    "q.m15#11.p" to "Varför måste molnläsning kombineras med trycktrenden?",
    "q.m15#11.o0" to "För att datat ska bli komplett",
    "q.m15#11.o1" to "För att molnen visar nuvarande tillstånd medan trycktrenden visar förändringens riktning",
    "q.m15#11.o2" to "För att en barometer är mer exakt",
    "q.m15#11.o3" to "För att kunna beräkna höjden",
    "q.m15#11.e" to "De är olika dimensioner: molnen säger vad som finns nu, trycket säger vart det är på väg. Enbart moln gör det lätt att misstolka «blir sämre» som «bara mulet ett tag» — lägg till trenden och bilden är komplett.",
    "q.m15#12.p" to "Vad orsakar i första hand whiteout?",
    "q.m15#12.o0" to "Extremt snöfall",
    "q.m15#12.o1" to "Att moln, dimma och snöyta har liknande färg, så gränsen mellan mark och himmel försvinner",
    "q.m15#12.o2" to "Extremt låg temperatur",
    "q.m15#12.o3" to "Extrem UV",
    "q.m15#12.e" to "Whiteout är inte kraftigt snöfall, det är frånvaro av kontrast. När snö och moln ligger nära varandra i ljusstyrka försvinner horisonten och din uppfattning om avstånd och lutning fallerar helt — vilket förklarar varför det är långt farligare än vanligt snöfall.",
    "q.m15#13.p" to "Varför är en prognos som «spridda skurar» av begränsat värde i bergen?",
    "q.m15#13.o0" to "För att prognoser är felaktiga",
    "q.m15#13.o1" to "För att vädersvängningarnas skala i bergen är mycket mindre än prognosrutnätet, så förhållandena på plats kan vara helt annorlunda",
    "q.m15#13.o2" to "För att klättrare inte läser prognoser",
    "q.m15#13.o3" to "För att nederbörd inte spelar roll",
    "q.m15#13.e" to "Prognosrutnätet kan vara tiotals kilometer stort, medan de två sidorna av en och samma rygg kan ha helt olika väder. En prognos ger dig bakgrundsrisken; bedömningen på plats avgör om du kan röra dig i dag. Ingen av dem ersätter den andra.",
    "q.m15#14.p" to "Prognosen säger «sol» men du ser cumulus växa snabbt vertikalt. Vilken litar du på?",
    "q.m15#14.o0" to "Prognosen — fortsätt enligt plan",
    "q.m15#14.o1" to "Din egen observation — besluta utifrån att det kan försämras",
    "q.m15#14.o2" to "Medelvärdet av de två",
    "q.m15#14.o3" to "Fortsätt titta en timme till",
    "q.m15#14.e" to "En prognos är grov både i ledtid och skala, medan observationen är här och nu. När de krockar vinner bevisen på plats — det är grundhållningen i hela väderbedömningssystemet: prognosen sätter bakgrunden, marken sätter handlingen.",
    "q.m15#15.p" to "Fyll i luckan: efter att ha sett blixten motsvarar varje räknad sekund ungefär ( ) kilometer.",
    "q.m15#15.a0" to "0,34",
    "q.m15#15.a1" to ",34",
    "q.m15#15.a2" to "noll komma tre fyra",
    "q.m15#15.e" to "0,34 km per sekund är ljudets hastighet i luft. Omvandlingen gör sekundräkning till ett användbart verktyg — helt utan utrustning kan du avgöra om ovädret närmar sig eller flyttar bort.",
    "q.m15#16.p" to "[Flerval] I vilka situationer bör du allvarligt överväga att gå ner omedelbart?",
    "q.m15#16.o0" to "Cumulus har utvecklats till cumulonimbus med städsky",
    "q.m15#16.o1" to "Ett «vumpf»-ljud från snötäcket",
    "q.m15#16.o2" to "Sikten faller snabbt och du kan inte längre fastställa positionen",
    "q.m15#16.o3" to "En lagmedlem visar successivt förvärrade höjdsymtom",
    "q.m15#16.o4" to "En lagmedlem säger att hen är lite trött och vill vila tio minuter",
    "q.m15#16.e" to "Dessa fyra kommer från fyra dimensioner — väder, snötäcke, navigering och fysiologi — och gemensamt är att de är progressiva, vilket betyder att kostnaden nu är mycket lägre än om tio minuter. Ju tidigare du beslutar att gå ner, desto billigare är det.",
    "q.m15#17.p" to "Klicka på kurvan i diagrammet som visar frysnivån.",
    "q.m15#17.e" to "Frysnivåkurvan är en av de mest användbara uppgifterna i prognosen: den markerar höjden där nederbörd övergår från regn till snö. En stigande kurva betyder att varmare, fuktigare luft anländer och nederbörden skiftar från snö till regn; en fallande kurva betyder att kall luft är på plats och högre mark får snö. För att avgöra om du möter snöfall på din höjd slår den att läsa temperatursiffror.",
    "q.m15#18.p" to "Detta är prognosen för samma berg under en säsong som slutade tidigt. Hur stor är den totala snömängden i centimeter under de tre perioderna fredag 25 (fm / em / natt)? Ange summan.",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 cm. Nästan 2,8 m snö på ett dygn betyder att rutten är helt begravd, lavinfaran stiger kraftigt och läger riskerar att krossas. I den storleken är frågan inte längre om du kan nå toppen utan om du kan evakuera säkert — det är det typiska sättet en cyklon avslutar en klättringssäsong i förtid.",
    "q.m15#19.p" to "Scenario: läsa en höghöjdsprognos",
    "q.m15#19.c" to "En guide lägger två Manaslu-prognoser framför dig — en från ett normalt klättringsfönster, en från protokollet för en säsong som slutade tidigt. Att förstå dem spelar större roll än att memorera någon siffra.",
    "q.m15#19.e" to "Väderbedömning landar aldrig egentligen i «hur blir vädret i morgon» utan i «kan vi röra oss i det här fönstret». Samma gränssnitt, det ena säger fortsätt och det andra säger stopp — skillnaden ligger inte i att läsa diagrammet utan i att veta under vilka förhållanden du måste stoppa.",
    "q.m15#19.s0.p" to "Steg 1: i prognosen för det normala fönstret, vad representerar de rosa blocken i raden för topphöjd (8 163 m)?",
    "q.m15#19.s0.o0" to "Förväntat snöfall för perioden",
    "q.m15#19.s0.o1" to "Regn för perioden",
    "q.m15#19.s0.o2" to "Upplevd temperatur för perioden",
    "q.m15#19.s0.o3" to "Vindhastighet för perioden",
    "q.m15#19.s0.e" to "Rosa är snö och blått är regn — prognosen markerar nederbördstyp separat på varje höjd just eftersom kärnfrågan är om det snöar eller regnar på din höjd. Blocken i översta raden är små och glesa, så toppen får enstaka lätt snöfall av ringa omfattning.",
    "q.m15#19.s1.p" to "Steg 2: jämfört med prognosen för säsongsslutet, vad är den mest slående förändringen?",
    "q.m15#19.s1.o0" to "Bara temperaturen sjunker",
    "q.m15#19.s1.o1" to "Snöfall och vindhastighet ökar båda kraftigt, och nederbörden täcker alla höjdband",
    "q.m15#19.s1.o2" to "Regn ersätter snö",
    "q.m15#19.s1.o3" to "Frysnivån stiger mycket",
    "q.m15#19.s1.e" to "Snöfallet går från spridda 1–4 cm till 280 cm på ett dygn, vinden från 25–30 km/h till 55–60 km/h, och nederbördsbandet går genom alla nivåer från 8 163 m ner till 1 500 m. Alla tre samtidigt är signaturen för ett väderväxel som passerar rakt över dig.",
    "q.m15#19.s2.p" to "Steg 3: om ditt lag befann sig inom ett sådant prognosfönster, vad är rätt beslut?",
    "q.m15#19.s2.o0" to "Öka farten med toppstöten innan vädret försämras helt",
    "q.m15#19.s2.o1" to "Stoppa toppförsöket omedelbart, gå ner enligt planen och förbered evakuering",
    "q.m15#19.s2.o2" to "Vänta i höglägret på att vädret blir bättre",
    "q.m15#19.s2.o3" to "Dela i två grupper, en som går mot toppen och en som stannar",
    "q.m15#19.s2.e" to "När en prognos visar ett växel som passerar rakt över i stället för en kort fluktuation betyder «vänta tills det går över» oftast flera dagar exponerad på höjd, vilket varken förnödenheter eller tält klarar. Det är därför så många säsonger slutar med «vi måste ut» i stället för «vi blev klara» — och informationen som behövs för det beslutet är precis vad de två diagrammen ger.",
    "q.m15#20.p" to "Scenario: läsa en timprognos",
    "q.m15#20.c" to "Det här är en timprognos för en dag på Gongga Shan (7 556 m). Informationsdensiteten är långt högre än i en 16-dagarsöversikt, men det är också lättare att läsa fel rad — nyckeln är att veta vad varje rad faktiskt säger.",
    "q.m15#20.e" to "En timprognos svarar på det en översikt inte kan: vilken specifik period som är genomförbar. Frysnivån sätter nederbördstypen, den upplevda temperaturen sätter om en människa klarar det, och vindhastighet och solsken sätter hur brett fönstret är. Först lästa tillsammans ger de ett beslut du kan genomföra.",
    "q.m15#20.s0.p" to "Steg 1: raden Freeze visar frysnivån mellan 4 895 och 5 304 m, medan Gonggas topp är 7 556 m. Vad betyder den kombinationen?",
    "q.m15#20.s0.o0" to "All nederbörd på berget faller som snö",
    "q.m15#20.s0.o1" to "Det blir regn på toppen",
    "q.m15#20.s0.o2" to "Det snöar även under frysnivån",
    "q.m15#20.s0.o3" to "Nederbördstypen kan inte bedömas utifrån detta",
    "q.m15#20.s0.e" to "Frysnivån är regn-/snögränsen. Den ligger stadigt på 4 900–5 300 m medan alla klättringsrutter ligger ovanför. Med andra ord ligger hela rutten över frysnivån, så all nederbörd kommer som snö. En siffra svarar på «vilken form av nederbörd möter jag» — därför är frysnivån mer användbar än en temperatursiffra.",
    "q.m15#20.s1.p" to "Steg 2: raden Feels °C visar −18 till −21, medan Max / Min °C bara är −10 till −11. Vad förklarar i huvudsak gapet?",
    "q.m15#20.s1.o0" to "Prognosfel",
    "q.m15#20.s1.o1" to "Vindavkylning — ju starkare vind, desto lägre upplevd temperatur",
    "q.m15#20.s1.o2" to "Temperaturskillnad orsakad av höjden",
    "q.m15#20.s1.o3" to "Effekten av fuktighetsförändring",
    "q.m15#20.s1.e" to "Vindhastigheten i samma period är 20–30 km/h. Vind mot bar hud påskyndar värmeförlusten, så den upplevda temperaturen ligger nästan 10 °C under den uppmätta lufttemperaturen. På höjd avgörs om du kan vara ute av den upplevda temperaturen, inte av lufttemperaturen. Samma −10 °C är en helt annan sak med och utan vind.",
    "q.m15#20.s2.p" to "Steg 3: givet den här prognosen (vind 20–30 km/h, spridda snöfall 2/1/1 cm, upplevd temperatur kring −20 °C, dagsljus 6:56–19:15), vad är din bedömning av fönstret?",
    "q.m15#20.s2.o0" to "Förhållandena är svåra — avbryt all förflyttning",
    "q.m15#20.s2.o1" to "Det är ett jämförelsevis genomförbart fönster; den största utmaningen är kyla och vindavkylning snarare än nederbörd",
    "q.m15#20.s2.o2" to "För mycket nederbörd — det finns lavinfara",
    "q.m15#20.s2.o3" to "För lite data för att bedöma",
    "q.m15#20.s2.e" to "Vind på 20–30 km/h ligger fortfarande inom det genomförbara intervallet, och snöfallet är bara några centimeter. Det verkliga trycket kommer från en upplevd temperatur kring −20 °C, så det är frostskador och nedkylning du värjer dig mot. Logiken för ett sådant fönster: nederbörd och vind är okej, temperaturen och varaktigheten är problemet. Förkorta därför exponeringen, förstärk isoleringen på extremiteterna och flytta fram vändtiden.",
    "q.m15#21.p" to "I samma Gongga-prognos är den uppmätta lufttemperaturen cirka −11 °C medan den upplevda lägsta är −21 °C. Hur stor är skillnaden i grader Celsius?",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10 °C: −11 − (−21) = 10. Gapet är i sig beslutsinformation — klä dig efter den upplevda temperaturen, inte efter lufttemperaturen. Det förklarar också hur folk får frostskador vid −10 °C: de klädde sig efter siffran i diagrammet.",
    "q.m15#22.p" to "Den här prognosen visar vindhastigheten som gröna cirklar. Vad betyder det troligen?",
    "q.m15#22.o0" to "Vindhastigheten i perioden ligger inom intervallet som passar för klättring",
    "q.m15#22.o1" to "Vindhastigheten i perioden har nått en farlig nivå",
    "q.m15#22.o2" to "Det är regn i perioden",
    "q.m15#22.o3" to "Vinddata saknas för perioden",
    "q.m15#22.e" to "Professionella bergvädertjänster färgkodar oftast vindhastigheten efter dess effekt på förflyttning. 20–30 km/h i grönt betyder att det ligger i bandet «kan röra sig»; över det skiftar färgen mot gult eller rött.\nMen färgen är leverantörens förslag, inte ditt kriterium. Olika rutter och olika lag tål samma vind olika. Att läsa siffran spelar större roll än att läsa färgen.",
    "q.m15#23.p" to "Det här professionella gränssnittet visar temperaturer för 8 000 / 6 000 / 4 000 / 2 000 m i fyra parallella rader. Vad är det främsta värdet med den designen?",
    "q.m15#23.o0" to "Du kan läsa prognosen för din egen höjd direkt, utan att extrapolera från låglandsdata",
    "q.m15#23.o1" to "Det får sidan att se rikare ut",
    "q.m15#23.o2" to "Det visar att de fyra raderna är orelaterade",
    "q.m15#23.o3" to "Bara för att göra det lättare att skriva ut på papper",
    "q.m15#23.e" to "En vanlig prognos ger data för en plats, oftast närmaste stad eller flygplats. Du måste extrapolera uppåt berget med en temperaturgradient — ett steg som är lätt att göra fel och som kastar bort terrängdetaljer.\nEn professionell bergstjänst gör motsatsen: den skär berget efter höjd först och prognosticerar varje skikt. Du behöver bara hitta raden för den höjd du kommer att vara på i morgon och läsa den. Det är också ett enkelt test på om en vädertjänst är tillräcklig: skär den efter höjd?",
    "q.m15#24.p" to "I diagrammet visar raden «Cloud base (m)» ett streck (—) för de flesta perioder. Vad är rätt tolkning?",
    "q.m15#24.o0" to "Molnbasen är noll i perioden, det vill säga molnen ligger på marken",
    "q.m15#24.o1" to "Det finns ingen molnbasdata för perioden; det får inte tolkas som «molnbas = 0»",
    "q.m15#24.o2" to "Det betyder att det inte finns några moln alls i perioden",
    "q.m15#24.o3" to "Det betyder att molnbasen ligger över toppen",
    "q.m15#24.e" to "I en värdertabell är «tomt» och «noll» två helt olika saker. Tomt betyder att det inte finns data för posten i perioden — den kanske inte täcks, eller så kan ingen meningsfull uppskattning ges. Det betyder inte att värdet är noll.\nAtt behandla tomt som noll leder till slutsatser som «moln på marken, fruktansvärd sikt» som inte har med fakta att göra. Med vilken värdertabell som helst: skilj de två först. Det är det lättaste misstaget att göra när man läser en prognos, och det som oftast inte påpekas.",
    "q.m15#25.p" to "I vindraden i det här gränssnittet står siffrorna med pilsymboler. Vad visar pilarna troligen?",
    "q.m15#25.o0" to "Trenden i vindhastighet",
    "q.m15#25.o1" to "Vindriktning",
    "q.m15#25.o2" to "Sannolikhet för nederbörd",
    "q.m15#25.o3" to "Temperatur som stiger eller faller",
    "q.m15#25.e" to "Hastighet och riktning måste läsas tillsammans på höjd. Samma 30 km/h känns helt olika på lovart- och läsidan, och påverkar också snötäcket olika: vinden transporterar snö till läsidor och bygger upp flak. Det är en av de viktigaste uppgifterna vid bedömning av lavinfara.\nAtt bara läsa siffran och inte riktningen kastar bort halva informationen. Professionella gränssnitt sätter pilen bredvid siffran just för att de två inte kan läsas åtskilda.",
    "q.m15#26.p" to "I det här 16-dagarsdiagrammet klumpar röda markeringar (Snow) ihop sig kring 6 000 m-bandet medan blå markeringar (Rain) syns under 5 000 m. Vad indikerar det?",
    "q.m15#26.o0" to "Regn-/snögränsen ligger ungefär mellan 5 500 och 6 000 m",
    "q.m15#26.o1" to "Det faller bara snö på berget, aldrig regn",
    "q.m15#26.o2" to "Regnet fortsätter ända upp till toppen",
    "q.m15#26.o3" to "Det kan inte bedömas från det här diagrammet",
    "q.m15#26.e" to "Det här diagrammet säger inte vad som faller var vid en given timme; det svarar direkt på vilket höjdband nederbörden landar i. För en klättrare är det precis den information som spelar roll.\nRött i 6 000 m-bandet och blått bara under 5 000 m placerar regn-/snögränsen ungefär mellan 5 500 och 6 000 m. Tillsammans med den lila frysnivåkurvan i teckenförklaringen (som faller från cirka 6 000 m till cirka 4 800 m) ser du också att gränsen fortsätter att sjunka genom prognosperioden: band som nu får regn övergår gradvis till snö.\nSamma mängd nederbörd har helt olika effekt på en tur beroende på om den faller som regn eller snö.",
    "q.m15#27.p" to "I timprognosen på samma diagram dyker en blixtikon upp klockan 17. Vad signalerar det på höjd?",
    "q.m15#27.o0" to "Det är bara en ikon — ingen särskild hantering behövs",
    "q.m15#27.o1" to "Risk för åska: lägg förflyttningen till förmiddagen och lämna ryggar och exponerad terräng på eftermiddagen",
    "q.m15#27.o2" to "Kraftigt regn är på väg — ta bara med regnjackan",
    "q.m15#27.o3" to "Vindhastigheten ökar till en farlig nivå",
    "q.m15#27.e" to "Eftermiddagsåska är vanligt på höjd och verkligen farligt. Terrängens lyftning gör att cumulus växer snabbt på eftermiddagen. Så «starta tidigt» handlar inte bara om hårdare snö — det handlar också om att lämna exponerad terräng innan ovädren bildas.\nNyckelpunkter i ett åskväder: håll dig borta från toppar, ryggar, enskilda träd och vatten; ligg inte platt på marken; sprid laget cirka 50 m så att ett nedslag inte skadar flera. Blixtens avstånd kan uppskattas i kilometer som sekunder mellan blixt och dunder × 0,34.",
    "q.m15#28.p" to "När det gäller om en terrängdatakälla har en toppmarkering, vad är rätt avvägning?",
    "q.m15#28.o0" to "En markering betyder alltid högre noggrannhet; lita bara på kartor som har en",
    "q.m15#28.o1" to "Markeringar är praktiska för snabb positionering och kommunikation, men exakt terrängbedömning kräver fortfarande höjdkurvor",
    "q.m15#28.o2" to "En karta utan markeringar är värdelös",
    "q.m15#28.o3" to "Markeringar stör bara läsningen; ignorera dem",
    "q.m15#28.e" to "På den här Google-kartan över Muztagh Ata är toppen markerad direkt med en röd nål. Det är mycket användbart för orientering och kommunikation: du vet direkt var målet ligger och kan säga exakt vilken punkt du menar till en partner.\nMen en markering svarar inte på hur brant den här sluttningen är eller var ett läger kan ligga. Exakt terrängbedömning hänger fortfarande på höjdkurvor, och markeringen spelar ingen roll där.\nDet praktiska tillvägagångssättet: använd markeringen för att lokalisera snabbt, använd sedan högkvalitativa höjdkurvor (till exempel SRTM-versionen) för att läsa lutningsvinkel och terrängdetaljer. Var och en gör sitt.",
    "q.m16#0.p" to "Vilka tre skalor måste avancerad lavinbedömning kombinera?",
    "q.m16#0.o0" to "Temperatur, vindhastighet, nederbörd",
    "q.m16#0.o1" to "Regional prognos, terräng, snötäcke",
    "q.m16#0.o2" to "Höjd, lutningsvinkel, solinstrålning",
    "q.m16#0.o3" to "Lagets storlek, utrustning, tid",
    "q.m16#0.e" to "De tre svarar på tre olika frågor: prognosen säger hur riskabelt det är i dag totalt, terrängen säger om den här sluttningen kan hålla snö och glida, snötäcket säger om det är stabilt just nu. Med bara prognosen bedömer du sluttningen under fötterna efter ett regionalt medelvärde.",
    "q.m16#1.p" to "Vid vilken lavinfaranivå inträffar de flesta olyckorna?",
    "q.m16#1.o0" to "1 (låg)",
    "q.m16#1.o1" to "3 (betydande)",
    "q.m16#1.o2" to "5 (mycket stor)",
    "q.m16#1.o3" to "Ingen skillnad",
    "q.m16#1.e" to "Vid nivå 5 håller folk sig borta, så olyckorna är faktiskt färre; vid nivå 3 «ser terrängen gångbar ut», så många människor går in i lavinterräng. Det farligaste tillståndet är aldrig det extrema, utan det måttliga som underskattas.",
    "q.m16#2.p" to "Inom vilket lutningsintervall inträffar de flesta laviner?",
    "q.m16#2.o0" to "10°–25°",
    "q.m16#2.o1" to "34°–45°",
    "q.m16#2.o2" to "55°–70°",
    "q.m16#2.o3" to "Det finns inget mönster",
    "q.m16#2.e" to "Cirka 96 % av lavinerna inträffar mellan 30° och 50°, med tyngdpunkt mellan 34° och 45°. Det är precis det intervall klättringsrutter oftast passerar — brant nog att glida, flackt nog att hålla snö.",
    "q.m16#3.p" to "[Flerval] Vilka förfaranden är korrekta vid passage av lavinterräng?",
    "q.m16#3.o0" to "Håll avstånd och passera en person i taget",
    "q.m16#3.o1" to "Sätt ut en spejare på en säker plats",
    "q.m16#3.o2" to "Planera flyktvägen i förväg",
    "q.m16#3.o3" to "Skicka hela laget över snabbt tillsammans för att förkorta exponeringen",
    "q.m16#3.e" to "De två första begränsar risken till en person; den tredje garanterar en väg ut om något händer. «Alla över samtidigt» gör det motsatta — det förvandlar risken från att möjligen begrava en person till att möjligen begrava hela laget, vilket är precis varför det är det sämsta valet.",
    "q.m16#4.p" to "Var ska spejaren stå?",
    "q.m16#4.o0" to "På sluttningen som passeras",
    "q.m16#4.o1" to "Någonstans där hen ser den som passerar tydligt och själv står säkert",
    "q.m16#4.o2" to "Högst upp på sluttningen",
    "q.m16#4.o3" to "I dalbotten",
    "q.m16#4.e" to "En spejare har två uppgifter: hålla personen i sikte (för att veta var hen är begravd) och agera omedelbart om något händer. Att stå på sluttningen eller i dalbotten gör hen till det andra offret — spejarens egen säkerhet är en förutsättning för att kunna göra jobbet.",
    "q.m16#5.p" to "Vad är syftet med att gräva en snögrop?",
    "q.m16#5.o0" to "Att vila",
    "q.m16#5.o1" to "Att direkt se lagerskiktning, det svaga lagrets läge och hårdhetsskillnader",
    "q.m16#5.o2" to "Att mäta temperaturen",
    "q.m16#5.o3" to "Att ta fotografier",
    "q.m16#5.e" to "En lavin kräver ett svagt lager plus ett flak ovanpå, och den strukturen blir bara synlig när du skär in i den. En grop förvandlar en osynlig inre struktur till synliga bevis — det avgörande steget från att sluta sig till risken till att observera den.",
    "q.m16#6.p" to "Varför är «följ spåren efter dem framför» farligt?",
    "q.m16#6.o0" to "För att spåren är otydliga",
    "q.m16#6.o1" to "För att spåren kan vara timmar gamla, och snötäcket har sedan länge förändrats",
    "q.m16#6.o2" to "För att du kan ta fel väg",
    "q.m16#6.o3" to "För att spår försvårar gången",
    "q.m16#6.e" to "Snötäckets tillstånd förändras ständigt med temperatur, vind och snöfall — några timmar räcker för att gå från «knappt stabilt» till «klart att utlösa». Spår bevisar bara att någon kom över då; de säger inget om det är säkert nu.",
    "q.m16#7.p" to "Hur påverkar vindpålagring lavinfaran?",
    "q.m16#7.o0" to "Vinden plattar till snön och sänker risken",
    "q.m16#7.o1" to "Vinden transporterar snö till läsidor och bygger extra flak och svaga lager som kraftigt höjer risken",
    "q.m16#7.o2" to "Vinden har inget med laviner att göra",
    "q.m16#7.o3" to "Vinden påverkar bara sikten",
    "q.m16#7.e" to "Vinden är den mest underskattade lavinskaparen: på kort tid kan den flytta mycket snö till läsidor, bygga tjocka flak och skapa svaga lager inuti dem. Även utan snöfall kan ny lavinfara uppstå efter en kraftig vind.",
    "q.m16#8.p" to "Vad är huvudfaran med en snöskavel?",
    "q.m16#8.o0" to "Den skymmer sikten",
    "q.m16#8.o1" to "Den kan rasa av sig själv när som helst, och raset kan utlösa en lavin i sluttningen nedanför",
    "q.m16#8.o2" to "Dess färg skiljer sig från snöytan",
    "q.m16#8.o3" to "Den blockerar rutten",
    "q.m16#8.e" to "En snöskavel är farlig på två sätt: står du på den kan du följa med ner, och passerar du under kan den komma ner över dig med stora mängder snö. Det vanliga är att gå omväg på sidan bort från skavelkanten och aldrig vila på en skavel.",
    "q.m16#9.p" to "[Ordning] Hur ser det kompletta förfarandet vid passage av lavinterräng ut?",
    "q.m16#9.o0" to "Kontrollera dagens lavinprognos före start och markera sluttningarna som ska undvikas",
    "q.m16#9.o1" to "Observera fältsignaler på ansatsen (sprickor, sättningsljud, vindpålagrade ytor)",
    "q.m16#9.o2" to "Tilldela spejare, passageordning och flyktväg",
    "q.m16#9.o3" to "Passera en i taget med avstånd och samla igen på en säker punkt",
    "q.m16#9.e" to "De tre första stegen sker alla innan du går in — det är där lavinsäkerhetsarbetet faktiskt ligger. När du väl står på sluttningen finns mycket få val kvar, och de flesta olyckor går tillbaka till att de två första stegen hoppades över.",
    "q.m16#10.p" to "Varför måste en lavinräddning utföras omedelbart av kamraterna?",
    "q.m16#10.o0" to "För att professionell räddning är dyr",
    "q.m16#10.o1" to "För att en begravd persons överlevnadsfönster bara är omkring femton minuter",
    "q.m16#10.o2" to "För att professionella team inte kommer upp",
    "q.m16#10.o3" to "För att kamraterna kan terrängen bättre",
    "q.m16#10.e" to "Ett överlevnadsfönster på femton minuter betyder att de enda som kan rädda dig är de som står bredvid dig. Det är också därför lavintrion måste bäras och måste övas — utrustning du inte kan använda är detsamma som ingen utrustning.",
    "q.m16#11.p" to "[Matchning] Matcha varje lavinfaranivå med dess betydelse.",
    "q.m16#11.l0" to "Nivå 1 — Låg",
    "q.m16#11.l1" to "Nivå 3 — Betydande",
    "q.m16#11.l2" to "Nivå 4 — Stor",
    "q.m16#11.l3" to "Nivå 5 — Mycket stor",
    "q.m16#11.r0" to "Låg: både naturlig och mänsklig utlösning osannolik",
    "q.m16#11.r1" to "Betydande: mänsklig utlösning möjlig, och lättast att underskatta",
    "q.m16#11.r2" to "Stor: naturlig utlösning sannolik; undvik lavinterräng",
    "q.m16#11.r3" to "Mycket stor: omfattande naturliga laviner mycket sannolika",
    "q.m16#11.e" to "Bakom varje siffra ligger en kombination av utlösningssannolikhet och konsekvensens storlek. Nybörjarens klassiska misstag är att behandla nivå 3 som «okej» — ändå är det just den nivån där olyckorna samlas.",
    "q.m16#12.p" to "Vilken funktion och vilka gränser har en lavinryggsäck?",
    "q.m16#12.o0" to "Den förhindrar begravning helt; det finns inga gränser",
    "q.m16#12.o1" to "Den förbättrar chansen att stanna närmare ytan; men den kan inte ersätta sändare, sond och spade och inte heller förhindra trauma",
    "q.m16#12.o2" to "Den är bara för skidorter",
    "q.m16#12.o3" to "Den larmar räddning automatiskt",
    "q.m16#12.e" to "Principen är större volym, större chans att stanna nära ytan — den höjer överlevnadschansen men garanterar den inte. Och en betydande del av lavindödsfallen beror på trauma snarare än kvävning, vilket är varför en ryggsäck aldrig kan vara din enda tillit.",
    "q.m16#13.p" to "Varför är sluttningar som «inte ser så branta ut» ofta de farligaste?",
    "q.m16#13.o0" to "För att snön är djupare",
    "q.m16#13.o1" to "För att 34°–45° är där lavinerna samlas, och ögat underskattar lutningsvinkeln",
    "q.m16#13.o2" to "För att få människor går där",
    "q.m16#13.o3" to "För att vinkeln ändras snabbt",
    "q.m16#13.e" to "Utan referens uppskattar människor lutningsvinkeln med stort fel och läser ofta 35° som 25°. Och 30°–35° är precis det band som «ser gångbart ut men kan glida». En lutningsmätare och en höjdkurvekarta är boten mot den biasen.",
    "q.m16#14.p" to "[Flerval] Vad måste ett lag gå igenom före inträde i lavinterräng?",
    "q.m16#14.o0" to "Bekräfta att alla kan använda sändare, sond och spade",
    "q.m16#14.o1" to "Komma överens om passageordning och spejare",
    "q.m16#14.o2" to "Komma överens om en mötesplats och en flyktväg",
    "q.m16#14.o3" to "Kontrollera att sändarna sänder",
    "q.m16#14.o4" to "Stampa hårt upprepade gånger för att testa snötäckets stabilitet",
    "q.m16#14.e" to "Alla fyra är sista kontroller före inträde och tar bara minuter. De spelar roll eftersom det enda som återstår när du väl står på sluttningen är att hoppas att det inte händer.",
    "q.m16#15.p" to "Snötäcket ger ett «vumpf»-ljud. Vad är rätt reaktion?",
    "q.m16#15.o0" to "Fortsätt — det är bara snön som sätter sig",
    "q.m16#15.o1" to "Stanna omedelbart och bedöm igen; ett svagt lager har börjat ge efter",
    "q.m16#15.o2" to "Gå över snabbare",
    "q.m16#15.o3" to "Vila på plats i tio minuter",
    "q.m16#15.e" to "Ett vumpf är direkta bevis på att ett svagt lager kollapsar — det betyder att en mycket lätt last just utlöste lokal kollaps. Att fortsätta är i praktiken att fråga om lite mer får hela saken att rasa.",
    "q.m16#16.p" to "Fyll i luckan: cirka 96 % av lavinerna inträffar i sluttningar på 30°–50°, med tyngdpunkt mellan 34° och ( )°.",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "fyrtiofem",
    "q.m16#16.e" to "34°–45°. Intervallet är värt att minnas eftersom det både är lavinernas hotspot och den lutning klättringsrutter oftast korsar — det är överlappningen av de två fakta som gör laviner till en av de dominerande objektiva farorna i alpinklättring.",
    "q.m16#17.p" to "Scenario: passera en bit lavinterräng",
    "q.m16#17.c" to "Rutten måste korsa en snösluttning på cirka 35°, ungefär 200 m lång. Dagens lavinprognos är betydande (nivå 3), med 30 cm nysnö den senaste tiden, vind från nordväst och sluttningen vänd mot sydost.",
    "q.m16#17.e" to "Det här scenariot prövar hela lavinarbetsflödet: läs terräng och snötäcke, gör alla förberedelser före inträde och använd sedan formationen för att kontrollera konsekvenserna. Inget enskilt steg är svårt; det svåra är att utföra alla framför en sluttning som ser gångbar ut.",
    "q.m16#17.s0.p" to "Steg 1: vad förtjänar mest försiktighet på den här sluttningen?",
    "q.m16#17.s0.o0" to "Stenfall",
    "q.m16#17.s0.o1" to "Vindpålagrade flak och lutningsvinkeln i sig",
    "q.m16#17.s0.o2" to "Hög temperatur",
    "q.m16#17.s0.o3" to "Markvegetation",
    "q.m16#17.s0.e" to "35° ligger rakt i 34°–45°-hotspotet; nordvästvinden transporterar snö till läsidan (här sydostsidan) och bygger extra flak. Två faktorer som staplas är den klassiska kombinationen «ser gångbart ut, kan glida».",
    "q.m16#17.s1.p" to "Steg 2: när du närmar dig sluttningen, vad ska göras först?",
    "q.m16#17.s1.o0" to "Börja passera direkt",
    "q.m16#17.s1.o1" to "Observera fältsignalerna först, fastställ sedan spejare, passageordning och flyktväg",
    "q.m16#17.s1.o2" to "Stampa hårt på sluttningen för att testa den",
    "q.m16#17.s1.o3" to "Skicka hela laget över snabbt",
    "q.m16#17.s1.e" to "Alla förberedelser hör till tiden före inträdet. Att stampa hårt verifierar inte stabiliteten — det kan direkt utlösa ett snötäcke som redan är nära sin kritiska punkt.",
    "q.m16#17.s2.p" to "Steg 3: hur ska laget ordnas under passagen?",
    "q.m16#17.s2.o0" to "En i taget, med de andra väntande på en säker punkt",
    "q.m16#17.s2.o1" to "Alla hållande varandra i hand",
    "q.m16#17.s2.o2" to "Två och två så att ni ser varandra",
    "q.m16#17.s2.o3" to "På rad, tätt tillsammans",
    "q.m16#17.s2.e" to "En i taget begränsar risken till en person och låter spejaren koncentrera sig på att se en person. Att exponera hela laget samtidigt förstorar konsekvensen från att möjligen begrava en till att möjligen begrava alla.",
    "q.m16#18.p" to "Klicka på det ungefärliga området för Manaslus topp på kartan.",
    "q.m16#18.e" to "En topp är omisskännlig på en höjdkurvekarta: slutna kurvor drar ihop sig ring efter ring medan etiketterna stiger (7600 → 7750 → 7900 → 7950 …). Hitta punkten som omsluts av ringar av små slutna kurvor, och du har den högsta marken.\nOmvänt: där kurvorna breder ut sig och etiketterna fortsätter att falla är det nedför — vilket för övrigt säger vilken sida klättringsrutten följer.",
    "q.m16#19.p" to "På samma karta är höjdkurvorna på nordost- till ostsidan extremt täta. Vad indikerar det?",
    "q.m16#19.o0" to "Den sidan är mycket brant och ett hotspot för seracfall och stenfall",
    "q.m16#19.o1" to "Den sidan är flack och bra för läger",
    "q.m16#19.o2" to "Den sidan är lägre och därför mindre riskabel",
    "q.m16#19.o3" to "Täta kurvor betyder att terrängen där är plan",
    "q.m16#19.e" to "Ju tätare höjdkurvorna är, desto större höjdskillnad över samma horisontella avstånd — det vill säga desto brantare sluttning. På den här kartan faller nordostsidan från 7 950 m till 5 750 m med dussintals kurvor pressade in på kort horisontellt avstånd: en klassisk brant vägg.\nVid ruttplanering slår den här läskunskapen direkt på två saker: om du passerar zoner med seracfall och stenfall, och om det finns användbar reträttterräng om något går fel. De flackare, glest kurvade områdena är där ett läger mer sannolikt kan ligga.",
    "q.m16#20.p" to "Scenario: jämföra två terrängdatakällor",
    "q.m16#20.c" to "En guide ger dig två terrängkartor över samma berg: en från Google Maps, en genererad från NASA SRTM-höjdata. Ingen av dem är fel, men de är inte lika bra på att svara på dina frågor.",
    "q.m16#20.e" to "Den centrala skillnaden mellan terrängdataset är inte noggrannheten utan kurvintervallet, eftersom intervallet sätter hur fina lutningsändringar du kan se. Intuition har ett värde — den bygger en helhetsbild snabbt — men att avgöra om en viss sträcka är brant eller framkomlig går fortfarande tillbaka till kurvtätheten, som kan kvantifieras och jämföras.",
    "q.m16#20.s0.p" to "Steg 1: på den här Google-kartan anger kurvetiketterna 6200, 6400, 6600, 6800… Vilket är kurvintervallet?",
    "q.m16#20.s0.o0" to "50 m",
    "q.m16#20.s0.o1" to "100 m",
    "q.m16#20.s0.o2" to "200 m",
    "q.m16#20.s0.o3" to "500 m",
    "q.m16#20.s0.e" to "Närliggande etiketter skiljer 200 m, så det här kurvsystemet stiger 200 m mellan linjerna. Ett intervall på 200 m räcker för helhetsformen, men terrängdetaljer mellan linjerna — ett klippsteg på 40 m till exempel — försvinner helt från kartan.",
    "q.m16#20.s1.p" to "Steg 2: SRTM-kartan använder 50 m intervall. Jämfört med Google-kartans 200 m, vad är dess mest väsentliga fördel?",
    "q.m16#20.s1.o0" to "Den ser snyggare ut",
    "q.m16#20.s1.o1" to "Linjerna ligger tätare över samma horisontella avstånd och löser upp lutningsändringen fyra gånger finare",
    "q.m16#20.s1.o2" to "Färgerna är starkare",
    "q.m16#20.s1.o3" to "Etiketterna har större stil",
    "q.m16#20.s1.e" to "Ju mindre intervall, desto mer terrängdetalj kan du lösa upp. Bedömningen av om en sluttning är framkomlig hänger just på kurvtätheten: vid 200 m mellanrum slätas ett brant steg på 150 m ut till en mjuk sluttning, medan det vid 50 m ritas som det är.\nDet är därför terrängbedömning på tekniska rutter lutar sig mot högupplösta källor som SRTM.",
    "q.m16#20.s2.p" to "Steg 3: Google-versionen har tydligt ljus och skugga och ser tredimensionell ut. Hur ska du behandla skuggningen när du bedömer branthet?",
    "q.m16#20.s2.o0" to "Ju mörkare skugga, desto brantare sluttning — använd det direkt som bevis",
    "q.m16#20.s2.o1" to "Skuggning återspeglar bara belysning och riktning; den kan inte användas direkt som lutningsmått",
    "q.m16#20.s2.o2" to "Skuggning markerar områden med snötäcke",
    "q.m16#20.s2.o3" to "Skuggning markerar terräng över 7 000 m",
    "q.m16#20.s2.e" to "Reliefskuggning simulerar hur en sluttning belyses av sol från en viss riktning. Mörkt betyder att sluttningen är vänd bort från ljuset, inte att den är brant. En flack nordsluttning kan vara mörkare än en brant sydsluttning.\nAtt använda skuggning som mått på branthet är en vanlig och verkligen farlig felläsning. Skuggning är bra för helhetsintrycket; för att kvantifiera lutningen ska du läsa kurvtätheten, och helst korsvisa mot högupplöst data med höjdetiketter.",
    "q.m16#21.p" to "När det gäller påståendet «Google Maps är intuitivt men oprecist, SRTM är precist men inte intuitivt», vad är rätt förståelse?",
    "q.m16#21.o0" to "SRTM är mer exakt, så Google Maps har inget värde",
    "q.m16#21.o1" to "De bör användas tillsammans: bygg helhetsintrycket från den intuitiva kartan och gör sedan kvantifierade bedömningar med högupplösta höjdkurvor",
    "q.m16#21.o2" to "Google Maps är mer intuitivt, så lita på det först när du bedömer sluttningar",
    "q.m16#21.o3" to "De skiljer sig bara i färg; informationen är densamma",
    "q.m16#21.e" to "De två källorna löser olika problem. Googles reliefskuggning och platsetiketter bygger snabbt rumslig känsla: var berget ligger, dess grova form, åt vilket håll rutten går. SRTM:s 50 m-kurvor stöder kvantifierad bedömning: hur många grader sluttningen har, om det finns någonstans att sätta ett läger.\nSålla med den intuitiva kartan, bekräfta med den högupplösta — det är den praktiska arbetsdelningen. Att bara använda en av dem är antingen långsamt eller fel.",
    "q.m16#22.p" to "Klicka på det ungefärliga området för Everests topp på kartan.",
    "q.m16#22.e" to "För att hitta en topp, leta efter den högsta etiketterade slutna kurvan. Här stiger etiketterna nära det här området till 8600 och 8700 m med ringar som drar ihop sig inåt; den innersta är toppen (8 848 m).\nVar noga med att skilja högt från brant: toppterräng är ofta inte bergets brantaste del — den brantaste marken är där kurvorna ligger tätast. Den skillnaden spelar roll för ruttrisken: att nå toppen prövar acklimatisering och form, medan den tekniska risken främst ligger i några sluttningar på väg upp och ner.",
    "q.m16#23.p" to "Mellan Everests och Lhotses täta slutna kurvor på samma karta finns en zon där kurvorna glesnar markant och marken sjunker något. Vad är det, i terrängtermer?",
    "q.m16#23.o0" to "Källan till en glaciär",
    "q.m16#23.o1" to "Sadel mellan de två topparna",
    "q.m16#23.o2" to "Ryggens högsta punkt",
    "q.m16#23.o3" to "En brant klippa",
    "q.m16#23.e" to "Mellan två täta slutna höjdpunkter, där kurvorna glesnar och marken sjunker, har du en sadel (skard). Den mellan Everest och Lhotse är South Col på cirka 7 900 m, där sydsidans fjärde läger ligger — sista anhalten före toppstöten.\nAtt känna igen sadlar på en höjdkurvekarta är mycket praktiskt. De betyder oftast stark vind och exponering men relativt flack mark: bra för ett läger, dåligt för att dröja sig kvar, vilket är varför toppläger oftast ligger i en sadel och överges samma natt.",
    "q.m16#24.p" to "Klicka på det ungefärliga området för Muztagh Atas topp på kartan.",
    "q.m16#24.e" to "Muztagh Atas toppform är representativ: en kupol, bred och flack på toppen, där den högsta slutna kurvan är vitt utspridd i stället för tätt nästlad som på en vass topp. För att hitta en sådan topp, leta efter den högsta höjdetiketten (7 500 m här) och den slutna ring den sitter i.\nFormen påverkar klättringsupplevelsen direkt. En kupol betyder att toppartiet inte är brant men tar lång tid; med liten relief och inga tydliga landmärken är det lätt att tappa riktningskänslan på snöfältet under nedstigningen. Det är en risk som ofta nämns i samband med Muztagh Ata.",
    "q.m17#0.p" to "Vad är kärnmålet med lägerhantering på höjd?",
    "q.m17#0.o0" to "Att göra lägret bekvämt",
    "q.m17#0.o1" to "Att upprätthålla handlingsförmågan till lägsta möjliga kostnad",
    "q.m17#0.o2" to "Att spara bränsle",
    "q.m17#0.o3" to "Att ta bra fotografier",
    "q.m17#0.e" to "På höjd är varje energienhet en begränsad resurs, och lägret är den enda platsen som ger den tillbaka. Därför bör varje lägerbeslut svara på samma fråga: lämnar det här laget i bättre skick i morgon?",
    "q.m17#1.p" to "Vad är första hänsynen vid val av lägerplats?",
    "q.m17#1.o0" to "Utsikten",
    "q.m17#1.o1" to "Att undvika lavinbanor, zoner med seracfall, mark under snöskavlar och sprickor",
    "q.m17#1.o2" to "Att vara nära vatten",
    "q.m17#1.o3" to "Att vara nära ruttens start",
    "q.m17#1.e" to "Den första regeln för lokalisering är att inte bli träffad av en objektiv fara — för lägret är där du stannar i timmar eller en hel dag och knappt kan flytta dig snabbt. Utsikt och bekvämlighet är sekundära variabler.",
    "q.m17#2.p" to "Varför får du inte slå läger under en snöskavel?",
    "q.m17#2.o0" to "För att marken är ojämn",
    "q.m17#2.o1" to "För att en snöskavel kan brytas loss när som helst och skicka en massa snö och is rakt ner på lägret",
    "q.m17#2.o2" to "För att det blåser",
    "q.m17#2.o3" to "För att du inte ser utsikten",
    "q.m17#2.e" to "Ett skavelbrott ger ingen förutsägbar varning: det kan komma i eftermiddagsvärmen eller under den kallaste timmen före gryningen. Att lägga lägret under en skavel är att acceptera ett ständigt hot som du varken kan övervaka eller reagera på i förväg.",
    "q.m17#3.p" to "[Flerval] Vilka områden bör en lägerplats undvika?",
    "q.m17#3.o0" to "Under en lavinbana",
    "q.m17#3.o1" to "Rakt under eller ovanför en snöskavel",
    "q.m17#3.o2" to "Tydliga sprickfält",
    "q.m17#3.o3" to "Inom räckhåll för seracfall",
    "q.m17#3.o4" to "En öppen utsiktsplats med god panorama",
    "q.m17#3.e" to "Alla fyra är fall där en objektiv fara landar exakt på lägret. Gemensamt är att de är svåra att övervaka och att konsekvensen om de inträffar är på lagnivå — därför bör lokaliseringskraven för ett läger vara mer konservativa än för en rutt.",
    "q.m17#4.p" to "Hur ska bränsle och mat fördelas?",
    "q.m17#4.o0" to "Allt hos en person",
    "q.m17#4.o1" to "Packat per dag, med en nödreserv avsatt",
    "q.m17#4.o2" to "Allt vid tältöppningen",
    "q.m17#4.o3" to "Jämnt fördelat per person utan marginal",
    "q.m17#4.e" to "Packning per dag gör förbrukningen spårbar, och reserven garanterar att det alltid finns energi nog att gå ner säkert. På ett berg är bränsle inte bara för matlagning — det är också hur du smälter snö till vatten, torkar kläder och håller kroppstemperaturen uppe.",
    "q.m17#5.p" to "Varför hålla en nödreserv?",
    "q.m17#5.o0" to "För att maten blir dålig",
    "q.m17#5.o1" to "För att garantera bränsle och mat för en säker nedstigning under alla förhållanden",
    "q.m17#5.o2" to "För att affären kräver det",
    "q.m17#5.o3" to "För att lätta packningen på vägen tillbaka",
    "q.m17#5.e" to "Reserven riktar sig mot värsta fallet: vädret slår om, du tvingas stanna en extra dag, någon skadas och behöver gå ner långsamt. Om alla resurser är fördelade på ett bästa-fall-schema lämnar varje försening dig utan både förnödenheter och förmåga att röra dig.",
    "q.m17#6.p" to "Hur ska elektronik (telefon, kamera, pannlampsbatterier) hanteras över natten?",
    "q.m17#6.o0" to "Lämnas utanför tältet",
    "q.m17#6.o1" to "Förvaras mot kroppen eller i sovsäcken för värme",
    "q.m17#6.o2" to "Förvaras i ryggsäckens yttersta ficka",
    "q.m17#6.o3" to "Ingen hantering behövs",
    "q.m17#6.e" to "Litiumbatterier tappar mycket kapacitet i kyla och kan stänga av sig helt. Att hålla dem varma handlar inte om att skydda apparaten — det handlar om att pannlampan ska lysa och GPS:en starta i morgon. Det är säkerhetsutrustning, inte personliga saker.",
    "q.m17#7.p" to "Vad ska göras med blöta kläder?",
    "q.m17#7.o0" to "Hängas ute för att frysa torrt",
    "q.m17#7.o1" to "Hållas nära kroppen eller i sovsäcken så att de torkar av kroppsvärmen",
    "q.m17#7.o2" to "Läggas i en hög i tälthörnet",
    "q.m17#7.o3" to "Stoppas direkt i ryggsäcken",
    "q.m17#7.e" to "Nattemperaturen på höjd är extremt låg, så blöta kläder som hängs ute fryser till is. Att torka mot kroppen är inte grundligt, men åtminstone inte is när du tar på dem i morgon — ett klassiskt exempel på att behandla kroppsvärme som en resurs.",
    "q.m17#8.p" to "Varför ska lägret alltid hållas i ett skick där du omedelbart kan packa och lämna det?",
    "q.m17#8.o0" to "För att avfärden ska bli bekväm",
    "q.m17#8.o1" to "För att väder eller en lagmedlems tillstånd när som helst kan kräva en nödevakuering",
    "q.m17#8.o2" to "För att spara packningstid",
    "q.m17#8.o3" to "För att hålla ordning",
    "q.m17#8.e" to "Väderfönstret vid höglägret kan stängas plötsligt, och en lagmedlem kan plötsligt utveckla höjdsymtom. Då avgör hur lång tid det tar att komma iväg hur mycket risk du bär — och utrustning utspridd över hela tältet kan kosta en extra halvtimme.",
    "q.m17#9.p" to "Vilket är INTE en huvudorsak till dålig sömn på höjd?",
    "q.m17#9.o0" to "Periodisk andning som ger upprepade korta uppvaknanden",
    "q.m17#9.o1" to "Hypoxi och förhöjd puls",
    "q.m17#9.o2" to "Kyla och obehag",
    "q.m17#9.o3" to "Att tältet har för ljus färg",
    "q.m17#9.e" to "De tre första är verkliga fysiologiska orsaker, och periodisk andning är den mest typiska: på höjd blir nattandningen ofrivilligt intermittent och drar dig upprepade gånger tillbaka till lätt sömn. Sömnkvaliteten påverkar i sin tur acklimatiseringen direkt — så att sova dåligt är ingen liten sak.",
    "q.m17#10.p" to "[Ordning] Vilken är en sund ordning för att anlägga och lämna ett läger?",
    "q.m17#10.o0" to "Innan du anländer, kontrollera omgivningen för lavin-, seracfalls- och skavelhot",
    "q.m17#10.o1" to "Fixera tältplatsen, jämna marken och säkra tältet",
    "q.m17#10.o2" to "Fördela förnödenheter, smält snö till vatten och planera morgondagens schema och sömn",
    "q.m17#10.o3" to "Före avfärd, inventera utrustning och skräp och återställ platsen",
    "q.m17#10.e" to "Det första steget är det som oftast hoppas över — särskilt när du är trött, då varje platt fläck ser ut som en tältplats. Men när lägret väl är byggt är det extremt dyrt att flytta, så att se sig omkring innan du väljer plats bör bli en fast vana.",
    "q.m17#11.p" to "Varför är ett läger också en vändpunkt för reträtten?",
    "q.m17#11.o0" to "För att läger har förnödenheter",
    "q.m17#11.o1" to "För att reträtt oftast innebär att först återvända till lägret och sedan avgöra om du fortsätter ner eller väntar på väder",
    "q.m17#11.o2" to "För att läger har kommunikationsutrustning",
    "q.m17#11.o3" to "För att guiden är i lägret",
    "q.m17#11.e" to "Nedstigning från höjd är sällan en enda sammanhängande färd; du återvänder till närmaste läger för att återhämta dig, observera och besluta. Det betyder att lägret självt måste vara ett pålitligt mål — inte någonstans du är rädd för att återvända till.",
    "q.m17#12.p" to "Varför måste ett tält vara ventilerat?",
    "q.m17#12.o0" to "För att hålla det svalt",
    "q.m17#12.o1" to "För att undvika kolmonoxidansamling och frost inuti, och för att förebygga kvävning och förgiftning",
    "q.m17#12.o2" to "För att det ska bli lättare att gå in och ut",
    "q.m17#12.o3" to "För att minska vindmotståndet",
    "q.m17#12.e" to "Matlagning med kök på höjd kan snabbt höja kolmonoxidnivån i ett stängt tält, och den förgiftningen sker oftast under sömnen med symtom — huvudvärk, trötthet — som nästan är omöjliga att skilja från höjdsjuka. Tillsammans gör det ventilationen till ett hårt krav.",
    "q.m17#13.p" to "Vad är den största farhågan vid köksanvändning inne i ett tält?",
    "q.m17#13.o0" to "Bränsleläckage",
    "q.m17#13.o1" to "Kolmonoxidförgiftning",
    "q.m17#13.o2" to "Att smälta tältet",
    "q.m17#13.o3" to "Ljud",
    "q.m17#13.e" to "Kolmonoxid är färglös och luktfri, och de tidiga symtomen — huvudvärk, dåsighet — överlappar kraftigt med höjdsjuka. Just det gör den farlig: folk somnar i tron att det bara är AMS. Köksanvändning kräver alltid ventilation.",
    "q.m17#14.p" to "[Flerval] Vilka hälsosaker bör aktivt upprätthållas i lägret?",
    "q.m17#14.o0" to "Dricka tillräckligt (smälta snö)",
    "q.m17#14.o1" to "Äta tillräckligt, även utan aptit",
    "q.m17#14.o2" to "Hålla kläderna torra",
    "q.m17#14.o3" to "Observera varandras tillstånd och gång",
    "q.m17#14.o4" to "Ersätta måltider med kaffe och energidryck",
    "q.m17#14.e" to "De tre första är egenvård, den fjärde är lagvård — och den är ofta effektivare än de tre första: tidiga tecken på höjdsjuka (ostadig gång, långsamma reaktioner) är svåra att märka hos sig själv men uppenbara för en partner.",
    "q.m17#15.p" to "Fyll i luckan: ovanför höglägret packas bränsle och mat vanligen per ( ) med en nödreserv avsatt.",
    "q.m17#15.a0" to "dag",
    "q.m17#15.a1" to "dagen",
    "q.m17#15.a2" to "dagar",
    "q.m17#15.a3" to "varje dag",
    "q.m17#15.e" to "Packat per dag. Det gör förbrukningen uppenbar vid en blick och låter dig se «hur många dagar är kvar» i samma stund som schemat glider — i stället för att upptäcka det först när det är slut.",
    "q.m18#0.p" to "Vilken höjd har Muztagh Ata?",
    "q.m18#0.o0" to "6 812 m",
    "q.m18#0.o1" to "7 126 m",
    "q.m18#0.o2" to "7 134 m",
    "q.m18#0.o3" to "7 509 m",
    "q.m18#0.e" to "Muztagh Ata är 7 509 m, i Akto härad i Xinjiang. Det är förstahandsvalet för ett kinesiskt 7 000 m-mål och det högsta av de fyra bergen i den här lektionen.",
    "q.m18#1.p" to "Varför kallas Muztagh Ata för «ismödernas fader»?",
    "q.m18#1.o0" to "För att det är världens högsta topp",
    "q.m18#1.o1" to "För att dess glaciärer och snömängder är enorma, så det på avstånd ser ut som en väldig inlandsis",
    "q.m18#1.o2" to "För att det var den första 7 000 m-toppen som bestegs",
    "q.m18#1.o3" to "För att det är ett heligt berg i den lokala sägnen",
    "q.m18#1.e" to "Namnet kommer från hur det ser ut: toppen täcks av en enorm iskappa och snösluttningarna går mycket brett, så på avstånd läses det som ett vitt massiv. Den bilden förklarar också dess klätterkaraktär — långa snösluttningar, måttlig lutning, men tidskrävande.",
    "q.m18#2.p" to "Vilka är de tekniska kännetecknen för att klättra Muztagh Ata?",
    "q.m18#2.o0" to "Mestadels vertikala isväggar, extremt tekniskt",
    "q.m18#2.o1" to "Oändliga snösluttningar med måttlig teknisk svårighet, men mycket krävande för acklimatisering och form",
    "q.m18#2.o2" to "Nästan ingen teknisk utrustning krävs",
    "q.m18#2.o3" to "Mestadels klätterterräng på klippa",
    "q.m18#2.e" to "Det här är en klassisk 7 000 m-profil: rutten i sig är kanske inte svår, men långa dagar med packning på höjd förstorar varje litet problem. Det verkliga förberedelsefokuset är därför acklimatisering och form, inte avancerad teknik.",
    "q.m18#3.p" to "Vilken är den faktiska höjden på Ama Dablam?",
    "q.m18#3.o0" to "6 812 m",
    "q.m18#3.o1" to "7 126 m",
    "q.m18#3.o2" to "7 509 m",
    "q.m18#3.o3" to "8 027 m",
    "q.m18#3.e" to "Ama Dablam är 6 812 m, i Khumbu i Nepal. Till höjden är det en 6 000 m-topp, men det ligger i 7 000 m-avsnittet eftersom dess tekniska svårighet är i nivå med toppar över 7 000 m.",
    "q.m18#4.p" to "Varför placeras Ama Dablam, med bara 6 812 m, i 7 000 m-avsnittet?",
    "q.m18#4.o0" to "För att det administrativt klassas som en 7 000 m-topp",
    "q.m18#4.o1" to "För att dess branta blandterräng av klippa och snö och kraftiga exponering gör svårigheten jämförbar med toppar över 7 000 m",
    "q.m18#4.o2" to "För att dess toppfrekvens är mycket låg",
    "q.m18#4.o3" to "För att det ligger i en bergskedja på 7 000 m",
    "q.m18#4.e" to "Det här är lektionens enskilt viktigaste punkt: ett bergs svårighet är inte dess höjd. Ama Dablam är det klassiska beviset — lägre än många 7 000 m-toppar, ändå kan dess tekniska tröskel och psykologiska belastning vara större. Att välja berg enbart efter höjd är farligt.",
    "q.m18#5.p" to "Vilken höjd och plats har Lenin Peak?",
    "q.m18#5.o0" to "7 126 m, Nepal",
    "q.m18#5.o1" to "7 134 m, Pamirplatån",
    "q.m18#5.o2" to "7 509 m, Xinjiang",
    "q.m18#5.o3" to "6 812 m, Khumbu i Nepal",
    "q.m18#5.e" to "Lenin Peak är 7 134 m på Pamirplatån. Det hör till de mildare 7 000 m-alternativen och används därför ofta som ett första 7 000 m-mål.",
    "q.m18#6.p" to "Vilken höjd har Himlung Himal?",
    "q.m18#6.o0" to "7 126 m",
    "q.m18#6.o1" to "7 134 m",
    "q.m18#6.o2" to "7 509 m",
    "q.m18#6.o3" to "6 812 m",
    "q.m18#6.e" to "Himlung Himal är 7 126 m, i Nepal. Rutten blandar snösluttningar och isväggar, vilket gör den populär bland nepalesiska 7 000 m-toppar.",
    "q.m18#7.p" to "[Ordning] Ordna dessa berg från lägst till högst höjd.",
    "q.m18#7.o0" to "Ama Dablam (6 812 m)",
    "q.m18#7.o1" to "Himlung Himal (7 126 m)",
    "q.m18#7.o2" to "Lenin Peak (7 134 m)",
    "q.m18#7.o3" to "Muztagh Ata (7 509 m)",
    "q.m18#7.e" to "Den här ordningen avslöjar ett vanligt misstag: rangordnar du efter höjd kommer Ama Dablam före Muztagh Ata — men den verkliga tekniska svårigheten kan vara den omvända. Återigen: höjden är bara en av många variabler.",
    "q.m18#8.p" to "[Flerval] Vad förändras i huvudsak på 7 000 m jämfört med 6 000 m?",
    "q.m18#8.o0" to "Längre acklimatisering, med fler höglägersrotationer",
    "q.m18#8.o1" to "Snävare väderfönster, så timingen spelar större roll",
    "q.m18#8.o2" to "Svårare reträtt, vilket gör självräddning till ett hårt krav",
    "q.m18#8.o3" to "I allmänhet mer teknisk terräng och mer exponering",
    "q.m18#8.o4" to "Extra syrgas blir standardutrustning",
    "q.m18#8.e" to "Dessa fyra multipliceras i stället för att adderas: dålig acklimatisering gör att du missar fönstret, missat fönster tvingar fram reträtt i sämre förhållanden, och reträtten förstärks av höjd och teknisk terräng. Därför kallas 7 000 m för vattendelaren.",
    "q.m18#9.p" to "Varför kallas 7 000 m för en «vattendelare»?",
    "q.m18#9.o0" to "För att isyxor bara behövs över 7 000 m",
    "q.m18#9.o1" to "För att härifrån verkar teknik, omdöme, form och logistik allt på en gång, och ingen enskild styrka kan kompensera",
    "q.m18#9.o2" to "För att glaciärer bara syns över 7 000 m",
    "q.m18#9.o3" to "För att kommersiella team bara arbetar över 7 000 m",
    "q.m18#9.e" to "Misslyckanden på 5 000 m har oftast en orsak (acklimatisering eller form), på 6 000 m börjar orsakerna staplas, och på 7 000 m måste allt sitta. Därför samlar det här avsnittet teknik, omdöme, väder, självräddning och lägerhantering — de var alltid ett system.",
    "q.m18#10.p" to "Vad väger tyngst när du väljer ett 7 000 m-mål?",
    "q.m18#10.o0" to "Höjden",
    "q.m18#10.o1" to "En god helhetsmatchning av rutt, logistik, acklimatiseringsschema och reträttmöjligheter",
    "q.m18#10.o2" to "Kostnaden",
    "q.m18#10.o3" to "Toppfrekvensen",
    "q.m18#10.e" to "Ingen enskild post räcker: högre är inte nödvändigtvis svårare, hög toppfrekvens är inte nödvändigtvis säkrare, billigt är inte nödvändigtvis prisvärt. Den verkliga bedömningen är om kombinationen av dessa fyra är något jag, som jag är nu, kan bära.",
    "q.m18#11.p" to "På Muztagh Ata, varför är de «oändliga snösluttningarna» i sig en risk?",
    "q.m18#11.o0" to "För att sluttningarna är för hala",
    "q.m18#11.o1" to "För att lång exponering på höjd successivt urholkar form och omdöme, och reträttavståndet är långt",
    "q.m18#11.o2" to "För att sluttningarna ofta lavinerar",
    "q.m18#11.o3" to "För att du inte kan gå i replag på snösluttningar",
    "q.m18#11.e" to "«Inte svårt men mycket långt» är den klassiska 7 000 m-riskmodellen: den erbjuder ingen enskild nyckelpassage utan tär på dig kontinuerligt. Lång exponering betyder att form, uppmärksamhet och besluts kvalitet glider långsamt — och den förlorade marginalen är precis din säkerhetsmarginal.",
    "q.m18#12.p" to "[Matchning] Matcha varje berg med dess typiska karaktär.",
    "q.m18#12.l0" to "Muztagh Ata",
    "q.m18#12.l1" to "Ama Dablam",
    "q.m18#12.l2" to "Lenin Peak",
    "q.m18#12.l3" to "Himlung Himal",
    "q.m18#12.r0" to "Ismödernas fader: oändliga snösluttningar, ett prov på acklimatisering och form",
    "q.m18#12.r1" to "Brant blandterräng av klippa och snö, kraftig exponering, en språngbräda mot 8 000 m",
    "q.m18#12.r2" to "Pamirplatån; jämförelsevis mild bland 7 000 m-topparna",
    "q.m18#12.r3" to "I Nepal; en blandning av snösluttningar och isväggar",
    "q.m18#12.e" to "Dessa fyra profiler motsvarar fyra olika förberedelseprioriteringar: Muztagh Ata för acklimatisering, Ama Dablam för teknik och psykologi, Lenin Peak som språngbräda, Himlung som allroundprov. Att se dem tillsammans låter dig välja efter din egen svaga punkt.",
    "q.m18#13.p" to "Om målet är en 8 000 m-topp, vad är det klokaste sättet att välja bland 7 000 m-alternativen?",
    "q.m18#13.o0" to "Välj det högsta",
    "q.m18#13.o1" to "Välj det som täcker din egen svaga punkt (teknik, acklimatisering eller exponering)",
    "q.m18#13.o2" to "Välj det billigaste",
    "q.m18#13.o3" to "Välj det med högst toppfrekvens",
    "q.m18#13.e" to "Att behandla 7 000 m som en träningsplats för dina svaga punkter är mer värt än att se det som en nivåuppflyttning. Svag på teknik — välj Ama Dablam; acklimatiserar dåligt — välj Muztagh Ata med långa sluttningar och etablerade höglägersrotationer.",
    "q.m18#14.p" to "Vilken syn på förberedelsetiden för en 7 000 m-topp är korrekt?",
    "q.m18#14.o0" to "Ungefär som för 6 000 m",
    "q.m18#14.o1" to "Klart längre, och kräver tillräckliga höglägersrotationer och acklimatiseringstid",
    "q.m18#14.o2" to "Bara formträning behövs",
    "q.m18#14.o3" to "Den kan börja direkt efter förra klättringen",
    "q.m18#14.e" to "Acklimatisering är kumulativ, och 7 000 m kräver vanligen flera höglägersrotationer. Att bygga ett tajt schema utan att budgetera acklimatiseringstid är den direkta orsaken till att många 7 000 m-lag inte når toppen — eller råkar ut för olyckor.",
    "q.m18#15.p" to "Varför lägger det här avsnittet «riskbedömning» efter tekniklektionerna?",
    "q.m18#15.o0" to "För att omdöme är lättare än teknik",
    "q.m18#15.o1" to "För att teknisk förmåga ger dig självförtroende att gå in i svårare terräng, vilket gör omdömet mer nödvändigt för att tygla det",
    "q.m18#15.o2" to "För att läroplanen har begränsat utrymme",
    "q.m18#15.o3" to "För att teknik inte spelar roll",
    "q.m18#15.e" to "Det är en realistisk konstruktion: ju skickligare du är, desto svårare rutter kan du försöka dig på, så behovet av att begränsa dig ökar faktiskt. Att lägga omdömet efter tekniken speglar den ordningen i verkligheten — förmåga först, sedan återhållsamhet.",
    "q.m19#0.p" to "«Dödszonen» syftar vanligen på:",
    "q.m19#0.o0" to "Över 7 000 m",
    "q.m19#0.o1" to "Över 8 000 m",
    "q.m19#0.o2" to "Över 5 500 m",
    "q.m19#0.o3" to "Över 6 000 m",
    "q.m19#0.e" to "Över 8 000 m kallas dödszonen av en enkel anledning: syrgastrycket är så lågt att ingen acklimatisering låter kroppen hålla balansen någon längre tid. Det är inte retorik utan fysiologiskt faktum — och den mest grundläggande skiljelinjen mellan 8 000 m och 7 000 m.",
    "q.m19#1.p" to "På 8 000 m är lufttrycket ungefär vilken andel av havsnivåns?",
    "q.m19#1.o0" to "Hälften",
    "q.m19#1.o1" to "Två tredjedelar",
    "q.m19#1.o2" to "En tredjedel",
    "q.m19#1.o3" to "En femtedel",
    "q.m19#1.e" to "Ungefär en tredjedel. Det betyder att varje andetag bara ger omkring trettio procent av syrgasmolekylerna som finns vid havsnivån — medan klättring kräver flera gånger så mycket syre som vila. Det glappet mellan tillgång och behov är källan till varje 8 000 m-risk.",
    "q.m19#2.p" to "Varför kan kroppen inte stanna länge över 8 000 m?",
    "q.m19#2.o0" to "För att det är för kallt",
    "q.m19#2.o1" to "För att syrgastrycket ligger under tröskeln som krävs för att upprätthålla ämnesomsättningen, så kroppen försämras successivt",
    "q.m19#2.o2" to "För att det inte finns tillräckligt med mat",
    "q.m19#2.o3" to "För att det blåser för mycket",
    "q.m19#2.e" to "Att stanna länge betyder att förbruka mer än du reparerar: även i vila tappar kroppen muskelmassa och vikt och den kognitiva förmågan försämras. Därför måste ett 8 000 m-schema vara snabbt in och snabbt ut — det finns inget alternativ att vänta på bättre förhållanden.",
    "q.m19#3.p" to "Vilken förmåga påverkar hypoxin vanligen först?",
    "q.m19#3.o0" to "Benstyrka",
    "q.m19#3.o1" to "Omdöme och kognition",
    "q.m19#3.o2" to "Synen",
    "q.m19#3.o3" to "Hörseln",
    "q.m19#3.e" to "Det är den farligaste mekanismen på 8 000 m: den vars omdöme försämrats kan inte bedöma att omdömet försämrats. Omvänt märker du svaga ben direkt, medan tanken «jag kan fortsätta» kan vara i sig själv en produkt av hypoxin.",
    "q.m19#4.p" to "Varför är ett försämrat omdöme särskilt farligt på 8 000 m?",
    "q.m19#4.o0" to "För att du kan gå vilse",
    "q.m19#4.o1" to "För att du måste använda ett redan försämrat omdöme för att avgöra om du ska fortsätta eller retirera",
    "q.m19#4.o2" to "För att det påverkar dina kamrater",
    "q.m19#4.o3" to "För att det gör dig långsammare",
    "q.m19#4.e" to "Det är en rekursiv fälla: just när ett kritiskt beslut behövs — fortsätta eller retirera — är ditt beslutsfattande som minst tillförlitligt. «Vi går lite till och ser» kan vara rimligt på 4 000 m; på 8 000 m kan det redan vara ett fel som hypoxin drivit fram.",
    "q.m19#5.p" to "[Flerval] Vilka är typiska tecken på hypoxidriven kognitiv nedgång?",
    "q.m19#5.o0" to "Långsammare reaktioner, sluddrigt tal",
    "q.m19#5.o1" to "Fel i huvudräkning och bedömning",
    "q.m19#5.o2" to "Riskbedömningen blir överdrivet optimistisk",
    "q.m19#5.o3" to "Humörsvängningar, irritabilitet eller apati",
    "q.m19#5.o4" to "Minskad känsel för frostskador i fingrar och tår",
    "q.m19#5.e" to "Alla fyra är typiska, och de har en sak gemensamt: den det gäller märker dem knappt själv. Därför är det tillförlitliga greppet att externalisera — checklistor i stället för minne, fasta tider i stället för «känns ungefär rätt», och kamrater som ser på varandra i stället för självbedömning.",
    "q.m19#6.p" to "Vad är det mest effektiva motmedlet mot ett försämrat omdöme?",
    "q.m19#6.o0" to "Att använda viljestyrka för att hålla sig alert",
    "q.m19#6.o1" to "Att externalisera besluten till förskrivna checklistor och fasta regler (tid, kvarvarande syre, trösklar för vädret)",
    "q.m19#6.o2" to "Att dricka mer varmt vatten",
    "q.m19#6.o3" to "Att sänka farten",
    "q.m19#6.e" to "Viljestyrka är just det som hypoxin urholkar först. Den tillförlitliga metoden är att skriva reglerna medan du fortfarande fungerar: vilken tid du måste vända, hur mycket syre som återstår innan nedstigning ska påbörjas — sedan behöver du bara verifiera fakta, inte ombedöma.",
    "q.m19#7.p" to "Varför betonar ett 8 000 m-schema «starta tidigt, var tillbaka tidigt»?",
    "q.m19#7.o0" to "För att undvika trängsel",
    "q.m19#7.o1" to "För att chansen att vädret försämras ökar på eftermiddagen, och kyla och vind dränerar energi och syre snabbt",
    "q.m19#7.o2" to "För att rutten är kortare på morgonen",
    "q.m19#7.o3" to "För att guiderna har den vanan",
    "q.m19#7.e" to "På 8 000 m förstoras kostnaden för «sent»: samma mark tar dubbelt så mycket kraft på eftermiddagen, och när mörkret faller sjunker både temperatur och omdöme. «Gick ner för sent» är nästan alltid den gemensamma startpunkten i den olyckskedjan.",
    "q.m19#8.p" to "Varför kräver 8 000 m «förenklat beslutsfattande»?",
    "q.m19#8.o0" to "För att spara tid",
    "q.m19#8.o1" to "För att de kognitiva resurserna är begränsade och bör sparas till de beslut som verkligen spelar roll",
    "q.m19#8.o2" to "För att du inte vill tänka på höjd",
    "q.m19#8.o3" to "För att kamraterna bestämmer åt dig",
    "q.m19#8.e" to "I praktiken: fasta platser och fast ordning för utrustningen, rutiner gjorda till checklistor, schemat fastställt i förväg. Att göra «vad ska jag ha på mig i dag, vad ska göras först» till en standard som inte kräver tanke bevarar omdömet för beslut som fortsätta eller retirera.",
    "q.m19#9.p" to "Varför behöver även erfarna klättrare checklistor på 8 000 m?",
    "q.m19#9.o0" to "För att minnet är opålitligt",
    "q.m19#9.o1" to "För att hypoxin skadar arbetsminnet först, och en checklista inte är beroende av minnet",
    "q.m19#9.o2" to "För att regelverket kräver det",
    "q.m19#9.o3" to "För att hjälpa nybörjare att lära",
    "q.m19#9.e" to "Logiken är densamma som i flyget: i miljöer med hög belastning och stora konsekvenser kan du inte lita på «jag glömmer säkert inte». En checklista är inte ett hjälpmedel för nybörjare utan en försäkring mot de fel även experter gör.",
    "q.m19#10.p" to "Vad orsakar i huvudsak en kontinuerlig viktnedgång på höjd?",
    "q.m19#10.o0" to "Att maten smakar illa",
    "q.m19#10.o1" to "Att kroppen fortsätter bryta ner sin egen vävnad under hypoxi, medan minskad aptit ger otillräckligt intag",
    "q.m19#10.o2" to "Att det rör sig för mycket",
    "q.m19#10.o3" to "Att du dricker för lite vatten",
    "q.m19#10.e" to "Två faktorer samverkar: hypoxin försätter kroppen i ett läge där nedbrytning överstiger uppbyggnad, och höjdsjukan i sig dämpar aptiten. Därför är förmågan att äta på höjd en kompetens, inte ett nöje.",
    "q.m19#11.p" to "Varför är sömnen dålig på 8 000 m?",
    "q.m19#11.o0" to "För att tältet är obekvämt",
    "q.m19#11.o1" to "För att lågt syre ger periodisk andning, med upprepade pauser som drar dig ur sömnen",
    "q.m19#11.o2" to "För att det blåser",
    "q.m19#11.o3" to "För att du sov för mycket på dagen",
    "q.m19#11.e" to "Periodisk andning är det klassiska höghöjdssömnen-fenomenet: en instabil andningsdrift ger upprepade cykler av andningsuppehåll och uppvaknande. Sömnkvaliteten påverkar sedan direkt nästa dags acklimatisering och energi — så att kunna sova är en kärnkompetens i höglägret.",
    "q.m19#12.p" to "[Ordning] Sätt hypoxins effekter på kroppsfunktionen i den vanliga ordningen de uppträder.",
    "q.m19#12.o0" to "Snabbare andning och förhöjd puls (kompensation)",
    "q.m19#12.o1" to "Försämrad uthållighet vid långvarig ansträngning",
    "q.m19#12.o2" to "Försämrat omdöme och försämrad räkneförmåga",
    "q.m19#12.o3" to "Förändrat medvetande, ataxi",
    "q.m19#12.e" to "De två första är kroppen som försöker kompensera; de två sista är kroppen som sviktar. Den farliga är den tredje — den kommer innan någon tydlig medvetandeförändring, så «ser normal ut» betyder inte «tänker klart».",
    "q.m19#13.p" to "Vad är det mest direkta och tillförlitliga sättet att motverka hypoxi på 8 000 m?",
    "q.m19#13.o0" to "Äta mer",
    "q.m19#13.o1" to "Använda bärbar syrgas",
    "q.m19#13.o2" to "Vila mer",
    "q.m19#13.o3" to "Sänka farten",
    "q.m19#13.e" to "De andra verkar genom att minska förbrukningen eller påskynda acklimatiseringen, medan bärbar syrgas direkt höjer syrgastrycket i inandningsluften — den ändrar rotvariabeln. Därför är syrgas standardutrustning för säkerhet på 8 000 m.",
    "q.m19#14.p" to "Vilken är rätt förståelse av «acklimatiseringens gräns»?",
    "q.m19#14.o0" to "Acklimatisering kan fortsätta i det oändliga",
    "q.m19#14.o1" to "Acklimatiseringen har ett tak; över en viss höjd kompenserar ingen mängd av den helt",
    "q.m19#14.o2" to "Acklimatisering tar en dag",
    "q.m19#14.o3" to "Acklimatisering har inget med höjd att göra",
    "q.m19#14.e" to "Acklimatisering är en process med en gräns, inte en kurva som bara stiger. Det är den grundläggande orsaken till att 8 000 m bygger på syrgas och snabbt-in-snabbt-ut — inte otillräcklig förberedelse, utan fysiologisk avsaknad av möjligheten att «acklimatisera och sedan stanna».",
    "q.m19#15.p" to "Varför är rotorsaken till 8 000 m-olyckor sällan en enskild händelse?",
    "q.m19#15.o0" to "På grund av otur",
    "q.m19#15.o1" to "För att hypoxin försvagar omdöme, energi och koordination samtidigt, så flera länkar blir sköra på en gång",
    "q.m19#15.o2" to "För att utrustningen är otillräcklig",
    "q.m19#15.o3" to "För att det är för många människor",
    "q.m19#15.e" to "På låg höjd lämnar ett misstag oftast marginal att återhämta sig; på 8 000 m sjunker omdöme, energi och motorik tillsammans, så små fel kedjar direkt in i en olycka. Säkerhetsstrategin på 8 000 m måste därför vara fler skyddslager, inte bara att vara mer försiktig.",
    "q.m19#16.p" to "[Flerval] Vilka är de huvudsakliga dödsorsakerna på 8 000 m?",
    "q.m19#16.o0" to "Lavin och seracfall",
    "q.m19#16.o1" to "Fall",
    "q.m19#16.o2" to "Nedkylning",
    "q.m19#16.o3" to "Höjdsjuka och dess följdsjukdomar",
    "q.m19#16.o4" to "Miljöskador som snöblindhet och solbränna",
    "q.m19#16.e" to "Alla fyra är vanliga, och de staplas ofta: ett fall gör att du inte kan rädda dig själv, sedan väntan i kyla, sedan nedkylning, sedan förvärrad höjdsjuka. Därför kan utbildning för 8 000 m inte bara fokusera på höjdsjuka utan måste omfatta teknik, omdöme och system.",
    "q.m19#17.p" to "Fyll i luckan: över 8 000 m kallas «( )».",
    "q.m19#17.a0" to "dödszonen",
    "q.m19#17.a1" to "död zon",
    "q.m19#17.e" to "Dödszonen. Termens praktiska värde är det hårda villkoret den förmedlar: här finns inget alternativ att vänta eller ta det lugnt. Varje plan, förnödenhetsberäkning och beslut måste utformas för att komma igenom så snabbt som möjligt.",
    "q.m19#18.p" to "På 8 000 m märker du att du «verkligen vill fortsätta mot toppen». Vad ska du göra?",
    "q.m19#18.o0" to "Lita på instinkten och fortsätt klättra",
    "q.m19#18.o1" to "Behandla det som ett möjligt tecken på hypoxidriven underskattning av risken och kontrollera omedelbart de vändvillkor som bestämdes i förväg",
    "q.m19#18.o2" to "Öka farten och ta dig till toppen",
    "q.m19#18.o3" to "Låt kamraterna bestämma",
    "q.m19#18.e" to "Det här är en mycket representativ situation: en stark lust att fortsätta kan vara bara vilja på låg höjd, men på 8 000 m kan den vara en signal om försämrat omdöme. Den enda tillförlitliga referensen då är inte hur du känner utan de objektiva villkor som skrevs ner före avfärd.",
    "q.m20#0.p" to "Vilken är bärbar syrgas huvudsakliga roll på 8 000 m?",
    "q.m20#0.o0" to "Att ersätta formträning",
    "q.m20#0.o1" to "Att höja syresättningen i blodet, sänka risken för höjdsjuka och förbättra rörlighet och omdöme",
    "q.m20#0.o2" to "Att hålla dig varm",
    "q.m20#0.o3" to "Att minska packningens vikt",
    "q.m20#0.e" to "Den post som oftast förbises — och som är mest avgörande för säkerheten — är ett förbättrat omdöme, eftersom det direkt motverkar den farligaste faktorn på 8 000 m. Därför är syrgas standardutrustning för säkerhet på den höjden, inte en arbetsbesparande apparat.",
    "q.m20#1.p" to "Vilka delar ingår i ett system för bärbar syrgas?",
    "q.m20#1.o0" to "Flaska, regulator, flödesmätare, mask eller näsgrimma",
    "q.m20#1.o1" to "Flaska och ryggsäck",
    "q.m20#1.o2" to "Mask och isoleringslager",
    "q.m20#1.o3" to "Regulator och hjälm",
    "q.m20#1.e" to "Varje del har sin uppgift: flaskan lagrar, regulatorn sänker högtrycket till ett säkert intervall, flödesmätaren ställer in utflödet och masken eller grimman levererar det. Ett fel någonstans gör att du andas in mindre än du tror — därför kontrolleras systemet på varje etapp.",
    "q.m20#2.p" to "Vilket flöde är typiskt vid klättring?",
    "q.m20#2.o0" to "0,5–1 L/min",
    "q.m20#2.o1" to "2–4 L/min",
    "q.m20#2.o2" to "8–10 L/min",
    "q.m20#2.o3" to "Över 15 L/min",
    "q.m20#2.e" to "2–4 L/min är det vanliga intervallet vid klättring; den exakta siffran beror på höjd, ansträngning och individuell respons. Högre flöde är bekvämare men förbrukar snabbare — en avvägning som direkt avgör hur länge du kan stanna på 8 000 m.",
    "q.m20#3.p" to "Varför måste en nödreserv beräknas separat i syrgasplaneringen?",
    "q.m20#3.o0" to "För att bära lite extra",
    "q.m20#3.o1" to "För att förseningar, stöd till en kamrat eller systemfel alla kan förbruka extra syrgas",
    "q.m20#3.o2" to "För att flaskor läcker",
    "q.m20#3.o3" to "För att regelverket kräver det",
    "q.m20#3.e" to "Det klassiska syrgasplaneringsfelet är «precis nog för att nå toppen». Verkliga scheman är nästan alltid långsammare än planerat, och kamrater kan få brist eller systemet läcka. Utan reserv lämnar varje avvikelse dig i ett hasardspel på den farligaste höjden.",
    "q.m20#4.p" to "Vad kan hända när syrgasen tar slut?",
    "q.m20#4.o0" to "Ingenting alls",
    "q.m20#4.o1" to "Tillståndet kan försämras snabbt, eftersom kroppen anpassat sig till en högre syrgashalt i inandningsluften",
    "q.m20#4.o2" to "Höjdsjuka slår till direkt",
    "q.m20#4.o3" to "Systemet växlar automatiskt till omgivningsluft",
    "q.m20#4.e" to "Att abrupt gå från anrikat syre tillbaka till omgivningens partialtryck motsvarar att vinna en bit höjd på ett ögonblick på 8 000 m. Är du långt från lägret och redan utmattad kan det snabbt bli farligt — därför måste syrgasmarginalen hållas konservativ.",
    "q.m20#5.p" to "[Flerval] Vilken disciplin gäller för användning av syrgassystemet?",
    "q.m20#5.o0" to "Kontrollera flöde och anslutningar på varje etapp",
    "q.m20#5.o1" to "Använd det planerade flödet; skruva inte upp det efter behag",
    "q.m20#5.o2" to "Anteckna hur mycket som återstår och den uppskattade tid det räcker",
    "q.m20#5.o3" to "Kom överens i förväg om vid vilken kvarvarande mängd du måste gå ner",
    "q.m20#5.o4" to "Ställ flödet på max när du känner dig dålig",
    "q.m20#5.e" to "Den fjärde är den viktigaste: gör «gå ner vid den här kvarvarande mängden» till en siffra som är fastställd i förväg i stället för en diskussion på plats. När det väl gäller kan den som behöver regeln redan ha förlorat förmågan att bedöma korrekt.",
    "q.m20#6.p" to "Varför är det inte «fusk» att använda syrgas?",
    "q.m20#6.o0" to "För att reglerna tillåter det",
    "q.m20#6.o1" to "För att kroppen över 8 000 m ligger utanför det fysiologiska intervall den kan kompensera långvarigt, så syrgas är det standardmässiga svaret på det faktumet",
    "q.m20#6.o2" to "För att alla gör det",
    "q.m20#6.o3" to "För att det höjer toppfrekvensen",
    "q.m20#6.e" to "Ordet fusk förutsätter att lite mer ansträngning låter dig slinka förbi gränsen — men gränsen på 8 000 m är fysik och fysiologi, inte en regel. Syrgas höjer det fysiologiska taket något; det ändrar inte faktumet att du inte kan stanna länge.",
    "q.m20#7.p" to "Vad är den huvudsakliga skillnaden mellan mask och näsgrimma?",
    "q.m20#7.o0" to "En mask ger en mer stabil koncentration men är instängd och begränsar sikten när du rör dig",
    "q.m20#7.o1" to "En grimma kan ge högre koncentration",
    "q.m20#7.o2" to "De är identiska",
    "q.m20#7.o3" to "En mask är lättare",
    "q.m20#7.e" to "En mask sluter tätare och håller en stabil koncentration, men ger andningsmotstånd, immar lätt igen och är obekväm under rörelse; en grimma är bekväm med fri sikt, men den faktiska inandningskoncentrationen beror starkt på hur du andas. Valet beror på terräng, intensitet och personlig tolerans — det är inte helt enkelt vilken som är bättre.",
    "q.m20#8.p" to "Vilken avvägning följer med att höja respektive sänka flödet?",
    "q.m20#8.o0" to "Komfort mot uthållighetstid",
    "q.m20#8.o1" to "Vikt mot pris",
    "q.m20#8.o2" to "Det finns ingen avvägning",
    "q.m20#8.o3" to "Höjd mot temperatur",
    "q.m20#8.e" to "Högre flöde ger en bekvämare kropp och ett bättre bevarat omdöme, men kortare tid innan det tar slut. En syrgasplan är därför i praktiken en budget för hur länge du kan vistas högt — vilket direkt sätter toppdagens fönster och vändtiden.",
    "q.m20#9.p" to "Varför blir flaskornas vikt ett logistikproblem?",
    "q.m20#9.o0" to "För att de är skrymmande",
    "q.m20#9.o1" to "För att både flaska och gas är tunga, och ovanför höglägret måste allt bäras av människor",
    "q.m20#9.o2" to "För att de inte får checkas in",
    "q.m20#9.o3" to "För att de lätt går sönder",
    "q.m20#9.e" to "På höjd förstoras kostnaden för varje kilogram, och en flaska är tung och okomprimerbar. Därför måste syrgasplaneringen utformas tillsammans med lägerplan och bemanning — det är ingen fristående utrustningsfråga.",
    "q.m20#10.p" to "Varför måste syrgas läggas ut i höglägret i förväg?",
    "q.m20#10.o0" to "För att lätta toppdagen och garantera att syrgas finns då",
    "q.m20#10.o1" to "För att förhindra stöld",
    "q.m20#10.o2" to "För att det är kallare där uppe",
    "q.m20#10.o3" to "För att spara pengar",
    "q.m20#10.e" to "Toppdagen är när du är som mest pressad och minst i form; du kan inte samtidigt bära upp syrgasen. Den måste därför fraktas upp lass för lass i förväg — vilket betyder att syrgasmängd, bemanning och väderfönster binds ihop redan i planeringen.",
    "q.m20#11.p" to "Vad ska du göra om syrgassystemet fallerar under vägen?",
    "q.m20#11.o0" to "Fortsätta klättra och laga det hemma",
    "q.m20#11.o1" to "Omedelbart bedöma kvarvarande syre och din höjd, och sedan följa planen: gå ner eller byt till backupsystemet",
    "q.m20#11.o2" to "Skruva upp flödet för att försöka fixa det",
    "q.m20#11.o3" to "Ta isär det och reparera",
    "q.m20#11.e" to "Ett syrgasfel betyder att du plötsligt arbetar under förhållandena på en högre höjd, oskyddad. Att hantera det går före allt annat: avgör först om backupen låter dig fortsätta, och om inte — gå ner. På 8 000 m är nedstigning ett meningsfullt val, inte ett misslyckande.",
    "q.m20#12.p" to "[Ordning] Vilken är kontrollordningen för syrgassystemet på toppdagen?",
    "q.m20#12.o0" to "Bekräfta flasktryck och den uppskattade tid det räcker",
    "q.m20#12.o1" to "Kontrollera regulator, slang och mask eller grimma för skador",
    "q.m20#12.o2" to "Öppna flödet och bekräfta att gas verkligen kommer igenom",
    "q.m20#12.o3" to "Anteckna kvarvarande mängd och meddela kamraterna och dem därhemma",
    "q.m20#12.e" to "De tre första är tekniska kontroller, den fjärde är lagkommunikation — och den senare spelar särskilt stor roll på höjd: om kamraterna känner till din syrgasmarginal kan de upptäcka en försämring hos dig innan du gör det själv.",
    "q.m20#13.p" to "Varför kan syrgas inte ersätta acklimatisering?",
    "q.m20#13.o0" to "För att syrgas är för dyrt",
    "q.m20#13.o1" to "För att acklimatisering är kroppens egen fysiologiska kompensation, medan syrgas bara höjer inandningskoncentrationen",
    "q.m20#13.o2" to "För att syrgas slutar verka",
    "q.m20#13.o3" to "För att syrgas bara hjälper mot höjdsjuka",
    "q.m20#13.e" to "Acklimatisering ändrar hur kroppen använder syret; syrgas ändrar hur mycket som kommer in. Du kan inte få det förra ur det senare. Nedstigning, gradvis uppstigning och tillräcklig acklimatiseringstid är därför fortfarande oumbärliga förutsättningar på 8 000 m.",
    "q.m20#14.p" to "[Flerval] Vilka är vanliga fel i syrgassystemet?",
    "q.m20#14.o0" to "Isbildning eller blockering vid anslutningen",
    "q.m20#14.o1" to "Läckande slang",
    "q.m20#14.o2" to "Regulatorfel som ger felaktigt flöde",
    "q.m20#14.o3" to "Svårighet att öppna flaskventilen",
    "q.m20#14.o4" to "Att flaskan väger mer än förväntat",
    "q.m20#14.e" to "Alla fyra hänger samman med kyla, isbildning och krånglig hantering — och de inträffar alla på höjd, i trötthet, när de är svårast att hantera. Därför räcker det inte med ett backupsystem; du behöver också en beslutsplan för fel.",
    "q.m20#15.p" to "Varför måste syrgasplanen skrivas in i turschemat?",
    "q.m20#15.o0" to "För syns skull",
    "q.m20#15.o1" to "För att syrgasmängden direkt avgör den möjliga vändtiden och den maximala vistelsen",
    "q.m20#15.o2" to "För att bokföra kostnader",
    "q.m20#15.o3" to "För att det ska vara lättare att få ersättning",
    "q.m20#15.e" to "Syrgas är inte «ta med lite så är det klart» — det är en kvantifierad budget: hur många flaskor, vid vilket flöde, som räcker hur många timmar. De siffrorna sätter i sin tur vändtiden, så de måste planeras tillsammans med schemat och inte som en separat lista.",
    "q.m20#16.p" to "Fyll i luckan: det typiska flödet vid klättring är cirka 2 till ( ) L/min.",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "fyra",
    "q.m20#16.e" to "2–4 L/min. Intervallet är balansen mellan att upprätthålla tillräcklig syresättning och att spara gas. Syrgashantering är i slutändan ett kontinuerligt resursfördelningsproblem.",
    "q.m20#17.p" to "Vad ska du göra om en kamrats syrgas börjar ta slut?",
    "q.m20#17.o0" to "Fortsätta mot toppen; var och en för sig",
    "q.m20#17.o1" to "Omedelbart dela information och kvarvarande mängder, och sedan följa planen: gå ner tillsammans eller fördela om syrgasen",
    "q.m20#17.o2" to "Låta dem lösa det själva",
    "q.m20#17.o3" to "Ge dem all din egen syrgas",
    "q.m20#17.e" to "Brist är en händelse på lagnivå, inte en personlig: den påverkar nedstigningshastighet och ömsesidigt skydd. De sämsta alternativen är de två ytterligheterna — att fortsätta mot toppen, eller att ge bort hela sin egen försörjning. Det rimliga svaret är att omfördela resurserna och prioritera att alla kommer ner.",
    "q.m20#18.p" to "En användbar flaska rymmer 1 200 liter. Vid ett flöde på 3 L/min, ungefär hur många minuter räcker den?",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "Cirka 400 minuter (ungefär 6,7 timmar): 1200 ÷ 3 = 400. Sådana beräkningar spelar direkt roll på toppdagen — de avgör hur länge du kan stanna på 8 000 m, och därmed vilken tid vändtiden måste sättas till.",
    "q.m20#19.p" to "Topplan: 5 timmar upp, 3 timmar ner, flöde 2 L/min, plus 60 minuters nödreserv. Hur stor total syrgasvolym krävs, i liter?",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 liter: (5 + 3) timmar × 60 min × 2 L/min = 960 liter, plus 60 × 2 = 120 liter reserv, totalt 1080. Att räkna uppstigning, nedstigning och reserv som tre separata delar är den mest grundläggande disciplinen i syrgasplanering — att bara räkna om det räcker uppåt är det vanligaste felet.",
    "q.m21#0.p" to "Hur många toppar över 8 000 m finns det i världen?",
    "q.m21#0.o0" to "10",
    "q.m21#0.o1" to "12",
    "q.m21#0.o2" to "14",
    "q.m21#0.o3" to "18",
    "q.m21#0.e" to "Fjorton, alla inom Himalaya och Karakoram. Den siffran är ursprunget till klättringsmålet «de fjorton 8 000-metrarna».",
    "q.m21#1.p" to "Vilka länder rymmer de fjorton 8 000 m-topparna?",
    "q.m21#1.o0" to "Kina, Nepal, Indien, Pakistan",
    "q.m21#1.o1" to "Kina, Nepal, Bhutan, Indien",
    "q.m21#1.o2" to "Nepal, Pakistan, Afghanistan, Tadzjikistan",
    "q.m21#1.o3" to "Kina, Indien, Pakistan, Myanmar",
    "q.m21#1.e" to "Fyra länder: Kina, Nepal, Indien och Pakistan. Att förstå den fördelningen spelar roll — den styr tillstånd, logistik, räddning och politisk risk, allt som är en del av planeringen på 8 000 m.",
    "q.m21#2.p" to "Vilken höjd har Everest?",
    "q.m21#2.o0" to "8 611 m",
    "q.m21#2.o1" to "8 848 m",
    "q.m21#2.o2" to "8 586 m",
    "q.m21#2.o3" to "8 516 m",
    "q.m21#2.e" to "8 848 m (den gemensamma kinesisk-nepalesiska mätningen 2020 gav 8 848,86 m). Som världens högsta har det också den mest utbyggda kommersiella infrastrukturen — men moget betyder mogen logistik och mogen rutt, inte låg risk: trängsel, kostnad och svårigheten att behålla ett gott omdöme är också verkliga faror.",
    "q.m21#3.p" to "Vilken plats har Annapurna I i 8 000 m-historien?",
    "q.m21#3.o0" to "Den sista som bestegs",
    "q.m21#3.o1" to "Den första 8 000 m-topp som någonsin bestegs",
    "q.m21#3.o2" to "Den lägsta dödligheten",
    "q.m21#3.o3" to "Den lättaste att klättra",
    "q.m21#3.e" to "Annapurna I är 8 091 m och bestegs första gången 1950 — den första 8 000 m-toppen i mänsklighetens historia. Dess dödlighet har länge varit bland de högsta. Att bli bestigen först har inget med lätthet att göra.",
    "q.m21#4.p" to "Vad utmärker Shishapangma?",
    "q.m21#4.o0" to "Den ligger i Nepal",
    "q.m21#4.o1" to "Det är den enda 8 000 m-toppen helt inom Kina, och den sista av de fjorton som bestegs",
    "q.m21#4.o2" to "Den är högst",
    "q.m21#4.o3" to "Den är lättast",
    "q.m21#4.e" to "Shishapangma är 8 027 m i Tibet, den enda 8 000 m-toppen som ligger helt inom Kina; den bestegs första gången 1964 av ett kinesiskt lag och är den sista av de fjorton som nåtts.",
    "q.m21#5.p" to "Hur förhåller sig Lhotse till Everest?",
    "q.m21#5.o0" to "De ligger långt ifrån varandra",
    "q.m21#5.o1" to "Lhotse gränsar till Everest och delar ofta samma ansatsväg",
    "q.m21#5.o2" to "Lhotse är högre än Everest",
    "q.m21#5.o3" to "De ligger i olika bergskedjor",
    "q.m21#5.e" to "Lhotse är 8 516 m, alldeles intill Everest, och från söder delar de två större delen av rutten och lägren. Därför behandlas de ofta inom en och samma turplan för logistik och acklimatisering.",
    "q.m21#6.p" to "Vilken är den vanliga bedömningen av Cho Oyu?",
    "q.m21#6.o0" to "Den mest tekniska 8 000 m-toppen",
    "q.m21#6.o1" to "Allmänt ansedd som en av de mindre tekniska 8 000 m-topparna",
    "q.m21#6.o2" to "8 000 m-toppen med högst dödlighet",
    "q.m21#6.o3" to "Inga kommersiella team klättrar den",
    "q.m21#6.e" to "Cho Oyu är 8 188 m och anses med relativt mild rutt och mogen logistik ofta vara en av de mindre tekniska 8 000 m-topparna. Men «relativt lätt» betyder fortfarande att vistas i dödszonen i dagar — storleken får inte underskattas.",
    "q.m21#7.p" to "Vad är Nanga Parbat känd för?",
    "q.m21#7.o0" to "Milda rutter",
    "q.m21#7.o1" to "Enorm höjdskillnad och allvarlig lavinfara",
    "q.m21#7.o2" to "De billigaste tillstånden",
    "q.m21#7.o3" to "Den bästa logistiken",
    "q.m21#7.e" to "Nanga Parbat är 8 126 m och känd som «det nakna berget» — det reser sig en enorm höjd rakt upp ur dalen, med påtaglig lavin- och stenfallsrisk. Dess historiska klättringskostnad är hög även med 8 000 m-mått mätt.",
    "q.m21#8.p" to "[Matchning] Matcha varje topp med dess höjd.",
    "q.m21#8.l0" to "Everest",
    "q.m21#8.l1" to "Kangchenjunga",
    "q.m21#8.l2" to "Lhotse",
    "q.m21#8.l3" to "Makalu",
    "q.m21#8.r0" to "8 848 m",
    "q.m21#8.r1" to "8 586 m",
    "q.m21#8.r2" to "8 516 m",
    "q.m21#8.r3" to "8 485 m",
    "q.m21#8.e" to "Det här är världens första, tredje, fjärde och femte högsta topp. Memorera inte bara siffrorna — minns ordningen och vilken kedja var och en hör till. Siffror går att slå upp; helhetsbilden måste sitta i huvudet.",
    "q.m21#9.p" to "Varför har «de fjorton» blivit ett erkänt klättringsmål?",
    "q.m21#9.o0" to "För att det är ett runt tal",
    "q.m21#9.o1" to "För att de råkar bilda en fullständig gräns för höghöjdsklättring, och antalet är inom räckhåll för ett liv",
    "q.m21#9.o2" to "För att kommersiella företag lanserade det",
    "q.m21#9.o3" to "För att UIAA kräver det",
    "q.m21#9.e" to "Det som gör de fjorton särskiljande är att de har en objektiv, entydig gräns (över 8 000 m), ett ändligt antal och kan listas en efter en. Det gör målet både tydligt och livslångt — därför blev det måttstocken.",
    "q.m21#10.p" to "[Flerval] Vad krävs normalt för att nå toppen på en 8 000 m-topp?",
    "q.m21#10.o0" to "En fullständig acklimatiseringscykel med höglägersrotationer",
    "q.m21#10.o1" to "Teknisk förmåga och erfarenhet av glaciärvandring",
    "q.m21#10.o2" to "Ett tillförlitligt syrgas- och logistiksystem",
    "q.m21#10.o3" to "Form och omdöme validerade på 7 000 m",
    "q.m21#10.o4" to "Ett professionellt filmteam",
    "q.m21#10.e" to "De fyra motsvarar fyra dimensioner: fysiologisk (acklimatisering), teknisk, logistisk och ackumulerad erfarenhet. De verkar alla samtidigt på 8 000 m — saknas en blir den en svag länk, och svaga länkar förstoras snabbt på höjd.",
    "q.m21#11.p" to "Dhaulagiri, Manaslu och Annapurna ligger alla i vilket land?",
    "q.m21#11.o0" to "Kina",
    "q.m21#11.o1" to "Nepal",
    "q.m21#11.o2" to "Pakistan",
    "q.m21#11.o3" to "Indien",
    "q.m21#11.e" to "Alla tre ligger i Nepal. Nepal har det största antalet 8 000 m-toppar, vilket är varför landets klätterindustri är så utvecklad — och också varför det möter ett ständigt tryck kring tillstånd, förvaltning och miljöskydd.",
    "q.m21#12.p" to "Varför är «mogna kommersiella rutter» på 8 000 m-toppar fortfarande farliga?",
    "q.m21#12.o0" to "För att de är dyra",
    "q.m21#12.o1" to "För att höjden i sig inte kan ändras, och trängsel, väntan och svår räddning skapar nya risker",
    "q.m21#12.o2" to "För att guiderna är oprofessionella",
    "q.m21#12.o3" to "För att utrustningen är dålig",
    "q.m21#12.e" to "Kommersialiseringen löser logistik och ruttkännedom, men den kan inte sänka höjden. Tvärtom skapar många team som går i samma fönster köbildning — och att vänta på 8 000 m betyder att förbränna extra syre och kroppsvärme.",
    "q.m21#13.p" to "[Ordning] Ordna dessa toppar från högst till lägst.",
    "q.m21#13.o0" to "Everest (8 848)",
    "q.m21#13.o1" to "Kangchenjunga (8 586)",
    "q.m21#13.o2" to "Makalu (8 485)",
    "q.m21#13.o3" to "Annapurna I (8 091)",
    "q.m21#13.e" to "Bakom ordningen ligger spannet från världens nummer ett till nummer tio. Att minnas ordningen är mer användbart än att minnas exakta siffror — när du diskuterar rutter, logistik och svårighet behöver du oftast den relativa positionen.",
    "q.m21#14.p" to "Varför studera förstabestigningarnas historia när man lär sig om 8 000 m-toppar?",
    "q.m21#14.o0" to "För tentor",
    "q.m21#14.o1" to "För att förstabestigningar tenderar att blottlägga toppens kärnsvårigheter och risktyper",
    "q.m21#14.o2" to "För att memorera namn",
    "q.m21#14.o3" to "Det har inget med klättring att göra",
    "q.m21#14.e" to "Tidiga teams misslyckanden och förluster pekar rakt på en topps huvudsakliga svårigheter — återkommande lavinpartier, våldsamma vindpartier, exponerade ruttsträckor. Att läsa förstabestigningshistorien som en riskfil är långt mer användbart än att läsa den som en berättelse.",
    "q.m21#15.p" to "[Flerval] Vilka av dessa är 8 000 m-toppar i Himalaya?",
    "q.m21#15.o0" to "Everest",
    "q.m21#15.o1" to "Annapurna I",
    "q.m21#15.o2" to "Shishapangma",
    "q.m21#15.o3" to "K2",
    "q.m21#15.e" to "De tre första ligger i Himalaya; K2 ligger i Karakoram. De två kedjorna gränsar geografiskt men är geologiskt åtskilda, och deras klättringssäsonger och vädermönster skiljer sig — därför diskuteras de fjorton ofta grupperade efter kedja.",
    "q.m21#16.p" to "Hur påverkar titeln «världens högsta topp» strategin?",
    "q.m21#16.o0" to "Inte alls",
    "q.m21#16.o1" to "Den innebär störst medie- och kommersiell uppmärksamhet, och därmed störst lagtäthet och trängselrisk",
    "q.m21#16.o2" to "Den innebär den lättaste rutten",
    "q.m21#16.o3" to "Den innebär den enklaste räddningen",
    "q.m21#16.e" to "Uppmärksamhet ger resurser och också trängsel. När stora mängder team samlas i ett fönster blir väntan, köbildning och den psykologiska pressen att inte vilja ge upp sin plats ytterligare riskkällor — ett strategiproblem som är särskilt för den högsta toppen.",
    "q.m21#17.p" to "Fyll i luckan: i världen finns ( ) toppar över 8 000 m.",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "fjorton",
    "q.m21#17.e" to "Fjorton. Ett litet antal, ändå definierar det hela gränsen för höghöjdsklättring — därför behandlas «de fjorton» fortfarande som ett mål värt ett helt liv.",
    "q.m22#0.p" to "Hur många 8 000 m-toppar finns i Karakoram?",
    "q.m22#0.o0" to "2",
    "q.m22#0.o1" to "4",
    "q.m22#0.o2" to "6",
    "q.m22#0.o3" to "10",
    "q.m22#0.e" to "Fyra: K2, Gasherbrum I, Gasherbrum II och Broad Peak. De kallas också K2, K4, K5 och K3 — K står för Karakoram.",
    "q.m22#1.p" to "Vilken höjd och ställning har K2?",
    "q.m22#1.o0" to "8 611 m, näst högst i världen, och bland de mest tekniska och dödligaste 8 000 m-topparna",
    "q.m22#1.o1" to "8 848 m, högst i världen",
    "q.m22#1.o2" to "8 586 m, tredje högst i världen",
    "q.m22#1.o3" to "8 051 m, en av de lättare",
    "q.m22#1.e" to "K2 är 8 611 m, näst högst i världen. Den anses allmänt vara en av de svåraste och farligaste 8 000 m-topparna, vilket är varför den kallas «klättrarens berg» — här väger teknik och omdöme långt tyngre än logistiskt stöd.",
    "q.m22#2.p" to "Varför har Karakoram och Himalaya ofta olika klättringssäsonger?",
    "q.m22#2.o0" to "På grund av olika latitud och longitud",
    "q.m22#2.o1" to "För att de påverkas av olika klimatsystem: Karakoram påverkas starkare av västvindarna",
    "q.m22#2.o2" to "På grund av olika höjder",
    "q.m22#2.o3" to "På grund av olika regelverk",
    "q.m22#2.e" to "Himalayas bästa säsong styrs främst av monsuncykeln, medan Karakoram påverkas mer av västvindarna och orografisk nederbörd. Det avgör när du ska åka — och väljer du fel säsong får även det bästa lag aldrig ett toppfönster.",
    "q.m22#3.p" to "Vad kallas Broad Peak också?",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "Broad Peak är också K3, 8 051 m. Terrängen är relativt öppen, men snöfallet är rikligt och starka vindar vanliga — historiskt har den sett ett antal olyckor efter att ha underskattats.",
    "q.m22#4.p" to "Vad kallas Gasherbrum I och II också?",
    "q.m22#4.o0" to "K4 och K5",
    "q.m22#4.o1" to "K5 och K4",
    "q.m22#4.o2" to "K2 och K3",
    "q.m22#4.o3" to "K3 och K4",
    "q.m22#4.e" to "Gasherbrum I är K5 (8 080 m) och Gasherbrum II är K4 (8 035 m) — numreringen följer inte höjdordningen, vilket är precis vad som gör den förvirrande. Kom ihåg att K-numren inte är sorterade efter höjd, så går det inte fel.",
    "q.m22#5.p" to "De fjorton 8 000 m-topparna ligger alla i vilka två kedjor?",
    "q.m22#5.o0" to "Himalaya och Tian Shan",
    "q.m22#5.o1" to "Himalaya och Karakoram",
    "q.m22#5.o2" to "Karakoram och Alperna",
    "q.m22#5.o3" to "Nyainqêntanglha och Himalaya",
    "q.m22#5.e" to "Alla ligger i Himalaya och Karakoram — geografiskt närliggande kedjor som lyder under olika klimatsystem. Vilket åter visar att geografin i sig är nyckelinformations på 8 000 m.",
    "q.m22#6.p" to "[Matchning] Matcha varje topp med dess höjd.",
    "q.m22#6.l0" to "K2",
    "q.m22#6.l1" to "Nanga Parbat",
    "q.m22#6.l2" to "Gasherbrum I",
    "q.m22#6.l3" to "Shishapangma",
    "q.m22#6.r0" to "8 611 m",
    "q.m22#6.r1" to "8 126 m",
    "q.m22#6.r2" to "8 080 m",
    "q.m22#6.r3" to "8 027 m",
    "q.m22#6.e" to "Det här är världens andra, nionde, elfte och fjortonde högsta topp. De spänner över ett brett intervall men delar samma status inom «över 8 000 m» — vilket är just det egna med den här klassen: en tydlig gräns med enorm inre variation.",
    "q.m22#7.p" to "Vilken är rätt syn på förhållandet mellan 8 000 m-rankning och svårighet?",
    "q.m22#7.o0" to "Högre betyder alltid svårare",
    "q.m22#7.o1" to "Svårigheten sätts i huvudsak av teknisk terräng, klimat och logistik, och följer inte höjdrankningen direkt",
    "q.m22#7.o2" to "Lägre betyder alltid lättare",
    "q.m22#7.o3" to "Svårighet går inte att jämföra alls",
    "q.m22#7.e" to "Det här är den viktigaste insikten från panoramavyn över de fjorton: Cho Oyu på 8 188 m anses relativt lätt, medan K2 på 8 611 m hör till de svåraste — under 500 m höjdskillnad, ändå är den verkliga tröskeln vitt skild.",
    "q.m22#8.p" to "[Flerval] Vad avgör den verkliga svårigheten hos en 8 000 m-topp?",
    "q.m22#8.o0" to "Teknisk terräng och exponering",
    "q.m22#8.o1" to "Klimat och väderfönster",
    "q.m22#8.o2" to "Logistik och ansats",
    "q.m22#8.o3" to "Möjligheten till räddning",
    "q.m22#8.o4" to "Toppens höjdrankning",
    "q.m22#8.e" to "Alla fyra spelar roll. Särskilt räddningsmöjligheten förbises ofta: ett berg där räddning nästan är omöjlig har en helt annan risknivå även om rutten inte är svår, eftersom det inte finns någon buffert när något går fel.",
    "q.m22#9.p" to "[Ordning] Ordna dessa toppar från högst till lägst.",
    "q.m22#9.o0" to "K2 (8 611)",
    "q.m22#9.o1" to "Nanga Parbat (8 126)",
    "q.m22#9.o2" to "Gasherbrum I (8 080)",
    "q.m22#9.o3" to "Shishapangma (8 027)",
    "q.m22#9.e" to "Den här ordningen täcker den bakre halvan av de fjorton. Tillsammans med förra lektionens ordning har du nu hela höjdsekvensen — vilket är grunden för att bedöma vilken nivå ett givet berg hör till.",
    "q.m22#10.p" to "Varför är «de fjorton» ett så krävande mål?",
    "q.m22#10.o0" to "För att det är extremt dyrt",
    "q.m22#10.o1" to "För att det kräver att teknik, form, acklimatisering och omdöme hålls uppe i många år, genom logistiksystem i flera länder",
    "q.m22#10.o2" to "För att det tar för lång tid",
    "q.m22#10.o3" to "För att tillstånd är svåra att få",
    "q.m22#10.e" to "De fjorton tar ofta mer än ett decennium, under vilket kroppen åldras och livsomständigheterna ändras. Det prövar inte bara klättringsförmåga utan uthålligheten i långsiktigt underhåll och riskhantering.",
    "q.m22#11.p" to "Varför hänger framgång på 8 000 m ofta på väderfönstret snarare än på tekniken?",
    "q.m22#11.o0" to "För att tekniken inte spelar roll",
    "q.m22#11.o1" to "För att lång väntan på höjd förbrukar din säkerhetsmarginal, även med tillräcklig teknik",
    "q.m22#11.o2" to "För att teknik kan läras på berget",
    "q.m22#11.o3" to "För att guiderna sköter allt",
    "q.m22#11.e" to "Det är verkligheten på 8 000 m: tekniken är bara inträdesbiljetten, medan fönstret avgör om du kan komma igenom medan du fortfarande har kapacitet. Därför budgeterar 8 000 m-scheman vanligen generösa reservdagar.",
    "q.m22#12.p" to "Om du bara fick välja en 8 000 m-topp som din första, vad är det klokare tillvägagångssättet?",
    "q.m22#12.o0" to "Gå direkt på K2 och bli klar med det",
    "q.m22#12.o1" to "Välj en med mogen rutt, tillförlitlig logistik och genomförbar räddning, och använd «första gången» till att samla erfarenhet",
    "q.m22#12.o2" to "Välj bara den lägsta",
    "q.m22#12.o3" to "Välj vilken som helst; de är likadana",
    "q.m22#12.e" to "Värdet av en första 8 000 m-topp är att lära känna ditt verkliga tillstånd i dödszonen: hur du använder syrgas, hur mycket omdömet sjunker, vilken takt du har. Att lägga den på ett svårare berg innebär att testa flera okända saker samtidigt.",
    "q.m22#13.p" to "[Flerval] Vilka av dessa är 8 000 m-toppar i Karakoram?",
    "q.m22#13.o0" to "K2",
    "q.m22#13.o1" to "Gasherbrum I",
    "q.m22#13.o2" to "Gasherbrum II",
    "q.m22#13.o3" to "Broad Peak",
    "q.m22#13.o4" to "Manaslu",
    "q.m22#13.e" to "Alla fyra är Karakoram — de är faktiskt alla 8 000 m-toppar i den kedjan. «Karakorams fyra» är därför ett fast uttryck, och tillsammans med Himalayas tio blir det precis fjorton.",
    "q.m22#14.p" to "Vad är den mest praktiska nyttan av att studera de fjorton som helhet?",
    "q.m22#14.o0" to "Att kunna rabbla alla höjder",
    "q.m22#14.o1" to "Att förstå varför svårighet och höjd inte är samma sak, och använda det för att bedöma sina egna mål",
    "q.m22#14.o2" to "Att kunna guida andra",
    "q.m22#14.o3" to "Att kunna skriva ruttguider",
    "q.m22#14.e" to "Det verkliga värdet är att bygga en flerdimensionell syn på svårighet: tekniska, klimatiska, logistiska och räddningsmässiga dimensioner avgör tillsammans ett bergs verkliga tröskel. Samma ramverk gäller vid val bland 5 000 m- och 6 000 m-toppar.",
    "q.m22#15.p" to "Varför kan ansatsen till en 8 000 m-topp i sig vara en riskfaktor?",
    "q.m22#15.o0" to "För att det tar lång tid",
    "q.m22#15.o1" to "För att ansatsen ofta korsar glaciärer och lavinterräng medan laget ännu inte är fullt acklimatiserat",
    "q.m22#15.o2" to "För att utsikten är dålig",
    "q.m22#15.o3" to "För att det kräver tillstånd",
    "q.m22#15.e" to "Ansatsen sker oftast under uppstigningsfasen, när acklimatiseringen är sämst och omdömet minst stabilt, samtidigt som du hanterar sprickor och lavinterräng. Det är under den här dubbelt utsatta perioden som många olyckor inträffar.",
    "q.m22#16.p" to "Om du skulle bygga din egen lista över 8 000 m-mål, vad bör du bestämma först?",
    "q.m22#16.o0" to "Namnen på bergen du vill ha",
    "q.m22#16.o1" to "Dina egna svaga punkter (teknik, acklimatisering, omdöme eller logistikerfarenhet), och sedan matcha toppar som täcker dem",
    "q.m22#16.o2" to "Budgeten",
    "q.m22#16.o3" to "Hur lång ledighet du har",
    "q.m22#16.e" to "Att välja efter svag punkt behandlar 8 000 m som en utvecklingsväg i stället för en samling bedrifter. Samma berg är värt olika saker för olika människor — beroende på vilken av dina luckor det fyller.",
    "q.m23#0.p" to "[Scenario] En kamrat på 4 500 m har huvudvärk och illamående och hävdar att «en dag till med acklimatisering så är jag redo att gå upp». Vad är rätt bedömning ur miljövetenskaplig synvinkel?",
    "q.m23#0.o0" to "En dag till löser det säkert — uppmuntra dem att fortsätta",
    "q.m23#0.o1" to "Symtom betyder att kompensationen är otillräcklig; fortsätt inte vinna höjd medan symtomen kvarstår",
    "q.m23#0.o2" to "Ge läkemedel och fortsätt uppåt",
    "q.m23#0.o3" to "Det räcker att gå ner 100 m",
    "q.m23#0.e" to "Kedjan börjar i den mest grundläggande orsakskedjan: lågt tryck → lågt syrgastryck → kroppen behöver tid. Symtomen är signalen att tiden inte räcker, och en dag till garanterar ingen förbättring — rätt drag är därför att sluta vinna höjd, inte att satsa på morgondagen.",
    "q.m23#1.p" to "[Flerval] En lagmedlem är på väg mot en hård snösluttning på 5 000 m. Vilka punkter måste bekräftas?",
    "q.m23#1.o0" to "Stegjärn strikt matchade mot kängorna",
    "q.m23#1.o1" to "En isyxa anpassad efter personens längd",
    "q.m23#1.o2" to "UV400-glaciärglasögon och solskydd med hög faktor",
    "q.m23#1.o3" to "Isolering och skal lager matchade mot lagerprincipen",
    "q.m23#1.o4" to "Kamera och extra batterier för toppbilder",
    "q.m23#1.e" to "De fyra motsvarar fyra risktyper: att halka (stegjärn), att stoppa fallet (isyxa), UV (glasögon och solskydd), nedkylning (lager). Rätt sätt att kontrollera utrustning är att bygga listan ur riskerna, inte att gripa saker av vana.",
    "q.m23#2.p" to "[Matchning] Matcha varje lager i klädsystemet med dess uppgift.",
    "q.m23#2.l0" to "Underställ",
    "q.m23#2.l1" to "Mellanlager",
    "q.m23#2.l2" to "Skal",
    "q.m23#2.l3" to "Dunlager (vid extrem kyla)",
    "q.m23#2.r0" to "Transporterar svett bort från huden och håller dig torr",
    "q.m23#2.r1" to "Fångar ett luftlager för värme (fleece isolerar även fuktigt)",
    "q.m23#2.r2" to "Vattentätt, vindtätt och andande; skyddar dig mot vädret",
    "q.m23#2.r3" to "Den mest effektiva värmen i torr miljö",
    "q.m23#2.e" to "Varje lager har en uppgift. När du ser den arbetsdelningen förstår du varför «fler lager är varmare» är fel: hoppar du över fukttransporten bär du ditt eget fuktiga mikroklimat, och ett icke-andande skal stänger in svettångan.",
    "q.m23#3.p" to "[Scenario] På väg uppför en snösluttning sparkar personen framför ojämna steg. Vad är den mest sannolika följden?",
    "q.m23#3.o0" to "Laget rör sig snabbare",
    "q.m23#3.o1" to "De bakom måste ständigt justera balansen, förbrukar mer energi och tappar stabilitet",
    "q.m23#3.o2" to "Sluttningen kollapsar",
    "q.m23#3.o3" to "Ingen effekt",
    "q.m23#3.e" to "Stegen är lagets fundament. Ojämna steg tvingar alla att fortsätta leta fotfäste, ovanpå den balanskapacitet som redan är knapp på höjd — ett skolexempel på att små problem ackumuleras till stor risk.",
    "q.m23#4.p" to "[Ordning] Sätt sekvensen för självstopp med isyxa i rätt ordning.",
    "q.m23#4.o0" to "Ta ett fast grepp om yxan och bekräfta att greppet är korrekt",
    "q.m23#4.o1" to "Rulla över på magen, vänd mot snön",
    "q.m23#4.o2" to "Driv in piggen i snön med kroppsvikten",
    "q.m23#4.o3" to "Lyft fötterna så att stegjärnen inte kan hugga tag och dra runt dig",
    "q.m23#4.e" to "Den här sekvensen är grunden för hela det tekniska systemet. Den måste gå utan att du tänker — vid ett verkligt fall har din tankekapacitet ett fönster på en eller två sekunder, och de sekunderna är helt upptagna av muskelminnet.",
    "q.m23#5.p" to "[Scenario] En klättrare faller på en hård snösluttning och självstoppet misslyckas. Vad är den mest sannolika orsaken vid genomgången?",
    "q.m23#5.o0" to "Yxan var för kort",
    "q.m23#5.o1" to "Piggen kunde inte bita i hård snö — och en hård snösluttning borde ha säkrats med fast rep",
    "q.m23#5.o2" to "Kängorna var fel",
    "q.m23#5.o3" to "De hade inga handskar",
    "q.m23#5.e" to "Självstoppets träffsäkerhet sjunker markant på hård snö och is; det är teknikens egen gräns. Den verkliga frågan ligger därför oftast tidigare — varför var vi på en brant hård snösluttning helt utan säkrat system?",
    "q.m23#6.p" to "[Flerval] Vilka risker förbises lätt under nedstigningen?",
    "q.m23#6.o0" to "Fallande ork som försvagar benkontrollen",
    "q.m23#6.o1" to "Vaksamheten sjunker när målet är nått",
    "q.m23#6.o2" to "Snöytan fryser eller blir mjuk, så förhållandena skiljer sig från uppstigningen",
    "q.m23#6.o3" to "Avtagande ljus minskar sikt och omdöme",
    "q.m23#6.o4" to "Nedstigningsrutter är vanligen kortare än uppstigningsrutter",
    "q.m23#6.e" to "Stapla de fyra och du har förklaringen till varför så många olyckor sker på väg ner. Nedstigningen är inte hemfärden efter avslutat arbete; det är en sträcka som kräver egen plan och bär jämförbar risk.",
    "q.m23#7.p" to "[Scenario] Bitventilen på vätskeslangen fryser snabbt i kylan. Vad ska du göra?",
    "q.m23#7.o0" to "Byt till en bredhalsad isolerad flaska, och blås tillbaka vattnet eller förvara den uppochner efter varje klunk",
    "q.m23#7.o1" to "Fortsätt använda den och vänta på att den tinar",
    "q.m23#7.o2" to "Bär vätskeblåsan utanpå ryggsäcken",
    "q.m23#7.o3" to "Sluta dricka",
    "q.m23#7.e" to "En liten men avgörande teknik: uttorkning på höjd beror oftast inte på «inget vatten med» utan på «vattnet frös och jag kunde inte dricka det». Att konstruera ett dryckessystem som inte kan frysa är vad som faktiskt räknas som att vara förberedd på att dricka.",
    "q.m23#8.p" to "Fyll i luckan: temperaturen sjunker med cirka ( ) °C per 1 000 m höjdökning.",
    "q.m23#8.a0" to "6,5",
    "q.m23#8.a1" to "sex komma fem",
    "q.m23#8.e" to "6,5 °C. Den siffran går genom hela kursen: den förklarar snögränsen, sätter hur tjock isolering du behöver och driver hur lavin- och isförhållanden förändras. Att förstå den betyder att kunna resonera med den.",
    "q.m23#9.p" to "[Scenario] På 5 000 m immar dina glasögon igen kraftigt och du kan inte längre läsa terrängen. Vilken är den viktigaste risken?",
    "q.m23#9.o0" to "Det är bara obehagligt",
    "q.m23#9.o1" to "Du förlorar grunden för terrängbedömning och kan hamna på en brant sluttning, en snöskavel eller ett sprickfält",
    "q.m23#9.o2" to "Du får snöblindhet",
    "q.m23#9.o3" to "Kamraterna kommer att klaga",
    "q.m23#9.e" to "«Kan inte se» betyder i verkligheten att du förlorar de bevis du bedömer efter. I komplex snöterräng kan ett eller två fel fotfästen bli mycket dyra. Så «ser jag klart» bör behandlas som ett hårt kriterium på utrustningens tillförlitlighet.",
    "q.m23#10.p" to "[Flerval] En lagmedlem har kraftigt minskad aptit på höjd. Vad ska göras?",
    "q.m23#10.o0" to "Ät aktivt i små mängder, ofta, och välj kolhydratrik och lättsmält mat",
    "q.m23#10.o1" to "Säkerställ ett jämnt och tillräckligt vätskeintag",
    "q.m23#10.o2" to "Behandla aptitlösheten som en möjlig acklimatiseringssignal att bevaka",
    "q.m23#10.o3" to "Ersätt måltiderna med stora mängder kaffe och energidryck",
    "q.m23#10.e" to "De tre första är rätt; den fjärde är fel på ett mycket representativt sätt: koffein ger en tillfällig känsla men kan inte ersätta energi. På höjd försvagar otillräckligt energiintag acklimatiseringen direkt och skapar en ond cirkel.",
    "q.m23#11.p" to "[Scenario] På en snösluttning på 5 000 m går din telefon från 40 % direkt till avstängning. Vad är det rimligaste svaret?",
    "q.m23#11.o0" to "Värm den mot kroppen och starta den igen",
    "q.m23#11.o1" to "Starta den upprepade gånger",
    "q.m23#11.o2" to "Ge upp elektroniken",
    "q.m23#11.o3" to "Använd det sista av batteriet till att skicka ett nödlarm",
    "q.m23#11.e" to "Det är typiskt litiumbeteende i kyla: kapaciteten kollapsar utan att laddningen är borta. Att värma den mot kroppen återställer oftast strömmen. Lärdomen: hantera elektronik som säkerhetsutrustning som kan svika utan förvarning.",
    "q.m23#12.p" to "[Ordning] Sätt en komplett utrustningskontroll i en vettig ordning.",
    "q.m23#12.o0" to "Bygg listan ur riskerna (vad terräng, väder och höjd kräver var för sig)",
    "q.m23#12.o1" to "Kontrollera varje del för fullständighet och funktion",
    "q.m23#12.o2" to "Ta på och provanvänd de kritiska delarna (stegjärn, sele, hjälm, pannlampa)",
    "q.m23#12.o3" to "Anteckna och berätta för kamraterna om din utrustningsstatus och din backup-plan",
    "q.m23#12.e" to "Nyckeln är steg tre, provanvändningen: komplett betyder inte fungerande. En stegjärnsbygel som inte sitter helt, eller ett gammalt batteri i pannlampan, visar sig först när du tar på och använder grejerna.",
    "q.m23#13.p" to "[Scenario] Laget beslutar att gå ner på grund av vädret, men en medlem insisterar på att fortsätta med argumentet «vi har ju kommit ända hit». Vad är det bästa sättet att hantera det?",
    "q.m23#13.o0" to "Respektera deras val och låt dem fortsätta ensam",
    "q.m23#13.o1" to "Hävda att hela laget går ner tillsammans — ensamfärd är inte tillåten på höjd, och envishet där uppe kan i sig vara hypoxi",
    "q.m23#13.o2" to "Låt det avgöras genom omröstning",
    "q.m23#13.o3" to "Låt dem vänta en timme och bestäm sedan",
    "q.m23#13.e" to "Två skäl: ensamfärd på höjd är extremt riskabelt, och «vi har kommit ända hit» är skolboksformuleringen för sunk cost — på höjd tenderar den känslan och ett försämrat omdöme att trassla ihop sig, så den kan inte behandlas som tillförlitlig input.",
    "q.m23#14.p" to "När det gäller om vältränade personer lättare drabbas av höjdsjuka, vad är korrekt?",
    "q.m23#14.o0" to "Ju bättre form, desto mindre risk",
    "q.m23#14.o1" to "Höjdsjuka har inget direkt samband med form; den hänger samman med uppstigningshastighet, sovhöjd och individuell respons",
    "q.m23#14.o2" to "Ju bättre form, desto större risk",
    "q.m23#14.o3" to "Bara otränade drabbas",
    "q.m23#14.e" to "Att blanda ihop form med acklimatisering är nybörjarens vanligaste fel. I själva verket kan vältränade få mer problem just för att de går snabbare och klättrar högre — en mycket verklig fälla.",
    "q.m23#15.p" to "[Flerval] Vilka förfaranden minskar fallrisken effektivt?",
    "q.m23#15.o0" to "Använda yxan som kontinuerligt självsäkring medan du rör dig",
    "q.m23#15.o1" to "Hålla ett hållbart jämnt tempo utan plötsliga kraftansträngningar",
    "q.m23#15.o2" to "Röra sig i den långsammaste lagmedlemmens takt",
    "q.m23#15.o3" to "Sätt fasta rep på hårda snö- och isluttningar",
    "q.m23#15.o4" to "Minska bromsningen och gå snabbare ner",
    "q.m23#15.e" to "De fyra motsvarar personlig teknik, tempokontroll, lagkoordinering och systemsäkring. Fallförebyggande är aldrig en enskild åtgärd utan ett helt lager av försäkringar ovanpå varandra.",
    "q.m23#16.p" to "[Scenario] Under en rast på en snösluttning lämnar en lagmedlem sin yxa i snön och går därifrån. Vilken risk skapar det?",
    "q.m23#16.o0" to "Yxan kan tappas bort",
    "q.m23#16.o1" to "Om hen faller har hen inget verktyg för självstopp alls",
    "q.m23#16.o2" to "Någon kan trampa på den",
    "q.m23#16.o3" to "Ingen risk",
    "q.m23#16.e" to "Fall går extremt snabbt, och yxan är ditt enda medel för självstopp. Att lämna den i snön är att tillfälligt ge upp den förmågan — och på en snösluttning är «tillfälligt» just det farligaste intervallet.",
    "q.m23#17.p" to "Vilken kärnförmåga prövar den här lektionen?",
    "q.m23#17.o0" to "Att memorera alla siffror",
    "q.m23#17.o1" to "Att kombinera kunskap om miljö, utrustning, klädsel och rörelse för att bedöma en konkret situation korrekt",
    "q.m23#17.o2" to "Att rabbla all terminologi",
    "q.m23#17.o3" to "Att kunna utrustningsmärken väl",
    "q.m23#17.e" to "Det är designlogiken i hela kursen: enskilda fakta är lätta att memorera, men på berget möter du kombinationsproblem. Att kunna trä flera kunskapsbitar på en tråd i en konkret situation är vad verklig behärskning betyder.",
    "q.m24#0.p" to "[Scenario] En kamrat har fallit i en spricka och din kropp håller deras vikt ensam. Vad kommer först?",
    "q.m24#0.o0" to "Börja dra omedelbart",
    "q.m24#0.o1" to "Bygg ett ankare och flytta över lasten först, tänk på dragningen sedan",
    "q.m24#0.o2" to "Larma hjälp först",
    "q.m24#0.o3" to "Ta ett foto för protokollet",
    "q.m24#0.e" to "Så länge vikten hänger på dig har du ingen kapacitet att manövrera systemet. Alltså: ankare, sedan överföring, sedan dragning — ordningen kan inte kastas om. Det är den mest praktiska regeln i hela räddningssystemet, och det steg som oftast hoppas över under press.",
    "q.m24#1.p" to "[Matchning] Matcha varje knop med dess användning.",
    "q.m24#1.l0" to "Åttaknut",
    "q.m24#1.l1" to "Dubbelt fiskarknop",
    "q.m24#1.l2" to "Prusik",
    "q.m24#1.l3" to "Pålstek",
    "q.m24#1.r0" to "Förbinder sele med ankare",
    "q.m24#1.r1" to "Sammanfogar två rep eller bildar en slinga av kordel",
    "q.m24#1.r2" to "Friktionsknop som greppar i en riktning",
    "q.m24#1.r3" to "Förbinder med ankare; vanlig inom båtlivet",
    "q.m24#1.e" to "De fyra täcker det mesta inom glaciärvandring och grundläggande säkring. Poängen med att pröva dem: du måste kunna knyta dem i mörker, med handskar.",
    "q.m24#2.p" to "[Scenario] Vinkeln mellan slingorna till två ankare är nära 100°. Vad betyder det?",
    "q.m24#2.o0" to "Lasten fördelas jämnare",
    "q.m24#2.o1" to "Lasten på varje ankare stiger markant (ju bredare vinkel, desto större last per ankare)",
    "q.m24#2.o2" to "Ingen effekt",
    "q.m24#2.o3" to "Repet balanserar sig själv automatiskt",
    "q.m24#2.e" to "Siffrorna är intuitiva: cirka 50 % per ankare vid 0°, cirka 58 % vid 60°, cirka 71 % vid 90°. Vid 100° bär varje ankare mycket — därför håller praxis vinkeln inom 60°.",
    "q.m24#3.p" to "[Flerval] Vad bör ett fullgott ankarsystem ha?",
    "q.m24#3.o0" to "Varje enskild placering solid",
    "q.m24#3.o1" to "Oberoende haveri mellan placeringarna (ingen falsk redundans)",
    "q.m24#3.o2" to "Rimlig lastfördelning, förspänd",
    "q.m24#3.o3" to "Snabb uppbyggnad, för att förkorta exponeringen",
    "q.m24#3.o4" to "Så få placeringar som möjligt för att spara utrustning",
    "q.m24#3.e" to "De tre första är säkerhetskrav, den fjärde är ett effektivitetskrav — och effektivitet är också säkerhet, eftersom byggprocessen i sig är tid exponerad för risk.",
    "q.m24#4.p" to "[Scenario] En kamrat blir ostadig på fötterna och förvirrad. Vad har prioritet?",
    "q.m24#4.o0" to "Ge syrgas och observera",
    "q.m24#4.o1" to "Gå ner omedelbart, och ge dexametason under medicinsk övervakning",
    "q.m24#4.o2" to "Fortsätt uppåt för att nå lägret snabbare",
    "q.m24#4.o3" to "Ge smärtstillande och vila",
    "q.m24#4.e" to "Ataxi och förändrat medvetande är kärntecknen på HACE, ett medicinskt akutläge. Nedstigning är den enda definitiva behandlingen; dexametason köper bara tid för nedstigningen — de två är inga alternativ till varandra.",
    "q.m24#5.p" to "[Flerval] Vilka påståenden om höjdläkemedel är korrekta?",
    "q.m24#5.o0" to "Dexametason påverkar inte acklimatiseringen och behandlar inte lungödem",
    "q.m24#5.o1" to "Acetazolamid påskyndar acklimatiseringen; börja dagen före uppstigning och sluta cirka två dagar efter",
    "q.m24#5.o2" to "Nifedipin kan ge ett snabbt blodtrycksfall",
    "q.m24#5.o3" to "Läkemedel kan inte ersätta nedstigning",
    "q.m24#5.o4" to "Acetazolamid kan ersätta kroppens egen acklimatiseringsprocess",
    "q.m24#5.e" to "Alla fyra är centrala punkter, och deras gemensamma slutsats är att läkemedel inte kan ersätta nedstigning: vad som än tas kvarstår nedstigningen som den grundläggande behandlingen. Läkemedel köper bara förutsättningarna för den.",
    "q.m24#6.p" to "[Scenario] En lagmedlem slutar huttra i kylan och sluddrar. Vad ska du INTE göra?",
    "q.m24#6.o0" to "Byt blöta kläder och isolera personen",
    "q.m24#6.o1" to "Låt dem gå omkring för att producera värme",
    "q.m24#6.o2" to "Värm bålen först",
    "q.m24#6.o3" to "Undvik hårdhänt hantering",
    "q.m24#6.e" to "«Slutade huttra» betyder måttlig nedkylning eller värre, och ett kallt hjärta är mycket känsligt för rytmrubbningar. Att låta patienten gå eller hantera dem hårdhänt kan direkt utlösa det — den mest kontraintuitiva regeln i första hjälpen vid nedkylning.",
    "q.m24#7.p" to "[Ordning] Sätt de fyra stegen i en replagsräddning i ordning.",
    "q.m24#7.o0" to "Gör självstopp och stabilisera dig",
    "q.m24#7.o1" to "Bygg ett oberoende ankare",
    "q.m24#7.o2" to "Flytta lasten till ankaret",
    "q.m24#7.o3" to "Dra med ett 3:1-system",
    "q.m24#7.e" to "De fyra kan inte kastas om. På en tentamen kan du kanske rabbla dem; i verkligheten måste du klara de tre första på tiotals sekunder — det är den verkliga tröskeln för det här kunskapsmomentet.",
    "q.m24#8.p" to "[Scenario] Prognosen säger «mulet» men du ser cumulus utvecklas snabbt vertikalt. Vad ska du göra?",
    "q.m24#8.o0" to "Lita på prognosen och följ planen",
    "q.m24#8.o1" to "Besluta utifrån att det kan försämras, och överväg att gå ner tidigt",
    "q.m24#8.o2" to "Vänta en timme och titta igen",
    "q.m24#8.o3" to "Fortsätt uppåt men snabbare",
    "q.m24#8.e" to "En prognos ger regional bakgrund; molnet framför dig är bevis för här och nu. När de krockar vinner marken. Så mycket mer som cumulusutveckling på höjd ofta mäts i minuter.",
    "q.m24#9.p" to "[Flerval] Vilka förfaranden är korrekta vid passage av lavinterräng?",
    "q.m24#9.o0" to "Passera en i taget med avstånd",
    "q.m24#9.o1" to "Sätt ut en spejare på en säker plats",
    "q.m24#9.o2" to "Planera flyktväg och mötesplats i förväg",
    "q.m24#9.o3" to "Skicka hela laget över snabbt tillsammans för att förkorta exponeringen",
    "q.m24#9.e" to "De tre första begränsar risken till en person; «alla över samtidigt» förstärker den till lagnivå — från att möjligen begrava en till att möjligen begrava alla, vilket är varför det är det minst acceptabla alternativet.",
    "q.m24#10.p" to "[Scenario] Laget är en timme från toppen men har passerat vändtiden. Vad är korrekt?",
    "q.m24#10.o0" to "Fortsätt till toppen, det är ju bara en timme",
    "q.m24#10.o1" to "Vänd omedelbart — hela poängen med en vändtid är att den fungerar just vid «bara lite till»",
    "q.m24#10.o2" to "Förläng den med en halvtimme",
    "q.m24#10.o3" to "Låt den starkaste fortsätta",
    "q.m24#10.e" to "Den här frågan prövar egentligen vad en vändtid är till för. Om den bara lyder när det är lätt, och kan töjas vid «bara lite till», har den aldrig funnits — och det är precis där olyckorna sker.",
    "q.m24#11.p" to "[Flerval] Vilka är korrekta lagbeslutspraktiker i miljöer med hög risk?",
    "q.m24#11.o0" to "Kvantifiera reträttsignalerna före avfärd",
    "q.m24#11.o1" to "Den mest konservativa åsikten vinner",
    "q.m24#11.o2" to "Bjud medvetet in oenighet (till exempel gå runt till var och en)",
    "q.m24#11.o3" to "Majoritetsbeslut",
    "q.m24#11.e" to "De tre första bildar tillsammans mekanismen mot kollektiva felbedömningar; majoritetsbeslut gör det motsatta — det tystar minoritetens berättigade oro, och det är ofta den minoriteten som först upptäckte farosignalen.",
    "q.m24#12.p" to "[Scenario] Kommunikationen är nere och du skulle ha checkat in hos dem därhemma för en timme sedan. Vad ska du göra?",
    "q.m24#12.o0" to "Fortsätt enligt planen och vänta på att signalen kommer tillbaka",
    "q.m24#12.o1" to "Följ den plan för kontaktbortfall som bestämdes före avfärd (till exempel vänta vid mötesplatsen)",
    "q.m24#12.o2" to "Dela upp er för att leta signal",
    "q.m24#12.o3" to "Låt alla gå ner omedelbart",
    "q.m24#12.e" to "Att tappa kommunikationen i bergen är normalt, inte en olycka — därför måste det finnas en plan före avfärd. Med en plan är kontaktbortfall en känd gren; utan en blir det förvirring på plats.",
    "q.m24#13.p" to "[Ordning] Sätt hela sekvensen för att hantera en allvarligt skadad person i ordning.",
    "q.m24#13.o0" to "Gör platsen säker och undvik en andra olycka",
    "q.m24#13.o1" to "Bedöm medvetande, andning och cirkulation; hantera livshotande tillstånd",
    "q.m24#13.o2" to "Larma hjälp och rapportera exakt position och skador",
    "q.m24#13.o3" to "Isolera, immobilisera och fortsätt observera medan ni väntar på evakuering eller professionell räddning",
    "q.m24#13.e" to "Ordningen förkroppsligar säkerhet först, sedan behandling, med larmet parallellt och underhållet efteråt. Det vanligaste felet i verkligheten är att hoppa över steg ett och rusa rakt till den skadade — den klassiska vägen till ett andra offer.",
    "q.m24#14.p" to "[Flerval] Vilka färdigheter i teknisk klättring måste övas i fält?",
    "q.m24#14.o0" to "Självstopp med isyxa",
    "q.m24#14.o1" to "Prusik och replagssystem",
    "q.m24#14.o2" to "Att bygga ankare",
    "q.m24#14.o3" to "Sekvensen för sprickräddning",
    "q.m24#14.o4" to "Att memorera namn och höjder för de fjorton 8 000 m-topparna",
    "q.m24#14.e" to "Ingen av de fyra kan förvärvas genom läsning. Gemensamt för dem: de måste utföras under press, de tillåter nästan ingen felmarginal och de är beroende av muskelminne. Därför markerar den här appen upprepade gånger att de kräver en instruktörs bedömning.",
    "q.m24#15.p" to "[Scenario] Du har klarat alla teoriprov. Hur ska du se på din förmåga nu?",
    "q.m24#15.o0" to "Du kan nu klättra 8 000 m självständigt",
    "q.m24#15.o1" to "Du har en teoretisk grund och ett bedömningsramverk, men varje teknisk färdighet kräver fortfarande en instruktörs fältbedömning innan den används",
    "q.m24#15.o2" to "Du kan arbeta som guide",
    "q.m24#15.o3" to "Att klara teorin betyder att förmågan finns",
    "q.m24#15.e" to "Det här är det viktigaste påståendet i hela kursen: teoretisk förståelse är inte fältförmåga. Den här appen bygger ett kognitivt ramverk och ett bedömningsramverk; det som faktiskt räddar dig på en isvägg är rörelsen du upprepat flera hundra gånger på säker mark.",
    "q.m24#16.p" to "När du har gått igenom hela kursen, vilken är den centrala tillgången du har byggt?",
    "q.m24#16.o0" to "En utrustningslista",
    "q.m24#16.o1" to "Ett tankeramverk: känna igen risk, bedöma risk, besluta — inklusive att veta när du inte ska fortsätta",
    "q.m24#16.o2" to "Ett klättercertifikat",
    "q.m24#16.o3" to "En hög med fakta",
    "q.m24#16.e" to "Från grunderna på 5 000 m till slutprovet på 8 000 m upprepar kursen en sak: säkerhet är inte en produkt av teknik utan av omdöme — och tekniken finns för att ge omdömet utrymme.",
    "q.m24#17.p" to "Fyll i luckan: när beslut fattas under osäkerhet bör den mest ( ) åsikten antas först.",
    "q.m24#17.a0" to "konservativa",
    "q.m24#17.e" to "«Konservativ först» är slutprincipen i hela kursen: enkel nog att tillämpa på plats, stark nog att motverka de flesta kognitiva biaser. Berget finns alltid kvar; du gör det inte.",
    "q.m25#0.p" to "Efter uppstigningen känner du tryck över huvudet och blir andfådd, medan laget fortsätter uppåt enligt planen. Vad ska du göra?",
    "q.m25#0.o0" to "Bit ihop — du har ju kommit ända hit",
    "q.m25#0.o1" to "Stanna och berätta ärligt för guiden eller kamraterna, och vila och observera sedan",
    "q.m25#0.o2" to "Ta något själv och håll lagets tempo",
    "q.m25#0.o3" to "Öka farten; att nå lägret snabbare löser det",
    "q.m25#0.e" to "Det finns två saker du aldrig får göra med kroppens signaler på höjd: dölja dem och självmedicinera. Rätt första steg är att säga hur du känner ärligt och sedan stanna för att vila och observera.\nDet är inte svaghet — guiden kan bara bedöma när hen vet, och du behöver själv en observationsperiod för att avgöra om det lättar eller förvärras.",
    "q.m25#1.p" to "Varför är frasen «vi har kommit ända hit» farlig på en höjdresa?",
    "q.m25#1.o0" to "För att det slösar tid",
    "q.m25#1.o1" to "För att den förvandlar redan investerad tid till ett skäl att fortsätta ta risk",
    "q.m25#1.o2" to "För att den påverkar lagstämningen",
    "q.m25#1.o3" to "För att den låter oprofessionell",
    "q.m25#1.e" to "Det här är skolbokstänkande i sunk cost: vi har gått så här långt, lagt så mycket, tagit så mycket ledigt — så det får inte ha varit förgäves.\nMen risken sjunker inte för hur mycket du investerat. Det som är förbrukat går inte att få tillbaka, medan kostnaden för att fortsätta kan bli mer som inte går att få tillbaka.",
    "q.m25#2.p" to "Du inser att du tydligt inte klarar lagets tempo och har pressat dig. Vad är det bästa tillvägagångssättet?",
    "q.m25#2.o0" to "Bit ihop och håll tempot för att inte hålla andra tillbaka",
    "q.m25#2.o1" to "Säg det ärligt och be laget gå i den långsammastes takt",
    "q.m25#2.o2" to "Sänk tempot i tysthet och låtsas som att allt är bra",
    "q.m25#2.o3" to "Säg inget och gå ner ensam",
    "q.m25#2.e" to "Att pressa tempot på höjd är en dold övertrassering: den omedelbara kostnaden är bara trötthet, men den ackumuleras till kollaps dagen därpå. Och ett lag som går i den snabbastes takt drar alla till gränsen.\nRätt drag är att sätta takten efter vad den långsammaste orkar — vilket skyddar både individen och laget.",
    "q.m25#3.p" to "En kamrat säger att hen känner sig lite konstig men insisterar «det är lugnt, jag kan gå». Vad ska du göra?",
    "q.m25#3.o0" to "Lita på deras bedömning och fortsätt gå",
    "q.m25#3.o1" to "Ta det på allvar och berätta för guiden",
    "q.m25#3.o2" to "Lägg dig inte i; låt dem bestämma",
    "q.m25#3.o3" to "Ta det inte på allvar — många säger så",
    "q.m25#3.e" to "Ob ehag på höjd har en grym egenskap: omdömet påverkas först, så «jag tror att jag är okej» är rabatterat där uppe.\nAtt rapportera kamratens tillstånd till guiden är det ansvarsfulla — om det verkligen är ingenting kostar det en extra kontroll; om det inte är det kan du vara den enda som upptäckte det i tid.",
    "q.m25#4.p" to "Före avfärd säger guiden att morgondagens rutt måste passeras i replag. Någon tycker «en så flack sluttning behöver inget rep». Vad är rätt förståelse?",
    "q.m25#4.o0" to "En flack sluttning behöver verkligen inget rep",
    "q.m25#4.o1" to "Om man ska gå i replag är guidens beslut; hen har informationen om terräng och snötäcke",
    "q.m25#4.o2" to "Replag är mest för att det ska se prydligt ut",
    "q.m25#4.o3" to "Den starkaste bör bestämma",
    "q.m25#4.e" to "Att se «flackt» på avstånd och att stå där och titta på fördelningen av sprickor, snöbryggor och dolda sprickor är två olika saker. Guiden har information du inte har — det är precis hens värde.\nI tekniska beslut är grundregeln för både effektivitet och säkerhet att låta den som har mest information bedöma.",
    "q.m25#5.p" to "När du går i mitten av laget upptäcker du att ditt vatten är slut, men nästa påfyllningsställe är två timmar bort. Vad ska du göra?",
    "q.m25#5.o0" to "Håll tyst och störa ingen",
    "q.m25#5.o1" to "Berätta omedelbart för ledaren och se om det kan koordineras",
    "q.m25#5.o2" to "Fråga närmaste kamrat om vatten men inte säga till ledaren",
    "q.m25#5.o3" to "Drick mindre och fortsätt",
    "q.m25#5.e" to "Brist på vatten eller mat är information på lagnivå, inte en personlig småsak — den formar ledarens bedömning av tempo och påfyllning.\nAtt fråga en kamrat i tysthet ser ut som att inte ställa till besvär, men det skär av informationen: ledaren tror fortfarande att laget är i gott skick och kan fortsätta enligt planen.",
    "q.m25#6.p" to "Vad betyder «långsamt är snabbt» egentligen på höjd?",
    "q.m25#6.o0" to "Att gå långsamt garanterar en topp",
    "q.m25#6.o1" to "Att ett hållbart jämnt tempo sparar mer tid, och är säkrare, än upprepade ryck",
    "q.m25#6.o2" to "Att långsamt är för att anpassa sig till de mindre starka",
    "q.m25#6.o3" to "Att hastigheten inte spelar roll på höjd",
    "q.m25#6.e" to "Syretillförseln är begränsad på höjd, och upprepade explosiva ansträngningar ackumulerar snabbt laktat och förvärrar hypoxin.\nEtt jämnt tempo är faktiskt snabbare: det tar bort behovet av täta återhämtningsstopp och sänker chansen att tvingas vända på grund av överförbrukning. Uttrycket beskriver ämnesomsättningen, inte en tröst.",
    "q.m25#7.p" to "Du når lägret två timmar senare än planerat och det är redan mörkt. Vad ska du göra?",
    "q.m25#7.o0" to "Fortsätt genom natten till nästa läger",
    "q.m25#7.o1" to "Slå läger där du är och meddela dem därhemma din position",
    "q.m25#7.o2" to "Gå tillbaka ensam för att leta efter någon som saknas",
    "q.m25#7.o3" to "Fortsätt gå tills du hinner ikapp gruppen framför",
    "q.m25#7.e" to "Att färdas genom natten på höjd kombinerar de sämsta faktorerna: mörker, trötthet, kyla och ingen förmåga att läsa terrängen. Att slå läger där du är är det sunda valet.\nMen det måste omfatta en sak till: meddela omvärlden din position. Då vet åtminstone någon var de ska leta om räddning behövs. Att agera ensam förlorar däremot laget två personer på en gång.",
    "q.m25#8.p" to "En kamrat blir tydligt dålig på vägen och saktar hela tiden in. Laget splittras i frågan om man ska vänta eller skicka några i förväg. Vad är det klokare tillvägagångssättet?",
    "q.m25#8.o0" to "Hela laget fortsätter i ursprungligt tempo",
    "q.m25#8.o1" to "Dela aldrig upp; hela laget sänker tempot",
    "q.m25#8.o2" to "Utse en erfaren person att följa med dem medan de andra fortsätter och håller kontakt",
    "q.m25#8.o3" to "Låt dem gå långsamt ensam och mötas i lägret",
    "q.m25#8.e" to "Att splittra bär sin egen risk på höjd, men med tillräckligt många är det ofta klokare att utse den mest erfarna att följa med den långsammare medan resten fortsätter, än att antingen sakta ner alla eller tvinga alla.\nTre saker är avgörande: någon stannar hos dem, kommunikationen upprätthålls, och gruppen framför informeras om läget och beräknad ankomsttid. Att vara helt ensam är det sämsta alternativet.",
    "q.m25#9.p" to "Vilken är rätt förståelse av toppens plats i hela resan?",
    "q.m25#9.o0" to "Toppen är resans slut",
    "q.m25#9.o1" to "Toppen är bara halva resan; nedstigningen är där risken koncentreras",
    "q.m25#9.o2" to "Toppen är allt som betyder något",
    "q.m25#9.o3" to "Ingen topp betyder att resan misslyckades",
    "q.m25#9.e" to "Många olyckor sker på nedstigningen, eftersom vaksamheten sjunker när målet är nått medan orken redan är nära gränsen.\nAtt behandla toppen som «hälften» betyder att budgetera lika mycket tid, energi och skydd för nedstigningen i planen — i stället för att spendera allt på att gå upp.",
    "q.m25#10.p" to "Scenario: det första dygnet på höjd",
    "q.m25#10.c" to "Det är din första 5 000 m-trekkingtopp. Efter att ha nått ett läger på 4 300 m händer flera saker under de kommande 24 timmarna.",
    "q.m25#10.e" to "Poängen med de här fyra stegen är inte medicinsk kunskap utan två vanor: säg det ärligt, och bedöm igen. Det som faktiskt knuffar människor i fara på en höjdresa är inte en enda dålig bedömning utan en kedja av små val — bit ihop, ställ inte till besvär — som staplas.",
    "q.m25#10.s0.p" to "Steg 1: på kvällen får du huvudvärk och tappar aptiten. En kamrat säger «det är normalt, sov bort det». Vad ska du göra?",
    "q.m25#10.s0.o0" to "Gör som de säger och sov bort det",
    "q.m25#10.s0.o1" to "Berätta ärligt för guiden hur du känner, och vila, ät och drick små mängder ofta enligt anvisning",
    "q.m25#10.s0.o2" to "Skaffa medicin själv och säg inget",
    "q.m25#10.s0.o3" to "Ta en drink för att sova bättre",
    "q.m25#10.s0.e" to "Huvudvärk och aptitlöshet är vanliga på höjd, men vanligt betyder inte försumbart. Ärlig rapportering plus grundåtgärder — vila, vätska, små mängder mat — är standardresponsen.\nDet avgörande är att guiden behöver veta i samma stund som ditt tillstånd förändras, inte upptäcka det nästa morgon.",
    "q.m25#10.s1.p" to "Steg 2: du sover knappt alls under natten. På morgonen förbereder laget sig för att fortsätta uppåt. Vad väljer du?",
    "q.m25#10.s1.o0" to "Säg inget och häng bara på",
    "q.m25#10.s1.o1" to "Rapportera hur du sovit och låt guiden bedöma om ni ska fortsätta",
    "q.m25#10.s1.o2" to "Bestäm själv att stanna kvar utan att säga det till laget",
    "q.m25#10.s1.o3" to "Be hela laget stanna och vänta på att du återhämtar dig",
    "q.m25#10.s1.e" to "Dålig sömn är en av de vanligaste höjdåkommorna; i sig rättfärdigar den oftast inte att stoppa uppstigningen — men den måste ingå i bedömningen i stället för att bäras i tysthet.\nGuiden väger den tillsammans med huvudvärk, aptit och hur du rör dig. Det är värdet av hens erfarenhet.",
    "q.m25#10.s2.p" to "Steg 3: laget fortsätter och du känner dig lite bättre än i går, men du går långsamt. Vilket tankesätt bör du vara mest vaksam på nu?",
    "q.m25#10.s2.o0" to "Oro för att bli utskrattad",
    "q.m25#10.s2.o1" to "Känslan av «det får inte ha varit förgäves» — den gör dig ovillig att stanna när du behöver",
    "q.m25#10.s2.o2" to "Lusten att ta bilder",
    "q.m25#10.s2.o3" to "Oro för vädret",
    "q.m25#10.s2.e" to "Sunk cost blossar upp mest under den andra dagen: du led hela natten, så att ge upp nu skulle göra lidandet meningslöst.\nDen logiken gör en redan betald kostnad till ett skäl att fortsätta, i stället för en signal att bedöma om.",
    "q.m25#10.s3.p" to "Steg 4: till slut når du inte toppen — du vänder en timme innan. Hur ska du se på den här resan?",
    "q.m25#10.s3.o0" to "Ett misslyckande; ingen idé att komma tillbaka",
    "q.m25#10.s3.o1" to "En nyttig acklimatiseringserfarenhet; att vända var omdöme, inte misslyckande",
    "q.m25#10.s3.o2" to "Det var kamraternas fel som saktade ner dig",
    "q.m25#10.s3.o3" to "Nästa gång ska toppen nås vad som än händer",
    "q.m25#10.s3.e" to "Acklimatisering byggs genom upprepad exponering; en första resa till 4 000–5 000 m var aldrig tänkt att ha toppen som enda mål.\nOch att kunna vända när det är rätt är den mest värderade förmågan i den här sporten. Den bär dig längre än en turlig topp någonsin gör.",
    "q.m25#11.p" to "Scenario: grupptryck",
    "q.m25#11.c" to "Dag fyra på resan; vädret börjar slå om och laget är delat. Din egen bedömning skiljer sig något från gruppens.",
    "q.m25#11.e" to "Det här scenariot handlar om att säga sin tvekan. Det är svårt i praktiken eftersom kostnaden ser social ut — förstöra stämningen, inte passa in — medan nyttan är osynlig: en olycka som inte hände. Minns de tre punkterna och du kommer att säga till tidigare nästa gång.",
    "q.m25#11.s0.p" to "Steg 1: några argumenterar «vi kör på, vädret kan bli bättre i morgon»; andra vill gå ner. Du lutar mot att gå ner men vill inte vara den som förstör. Vad ska du göra?",
    "q.m25#11.s0.o0" to "Håll tyst och följ med",
    "q.m25#11.s0.o1" to "Säg din bedömning och resonemanget bakom den",
    "q.m25#11.s0.o2" to "Klagar i tysthet och låter det vara",
    "q.m25#11.s0.o3" to "Låtsas stötta att fortsätta medan du behåller din tvekan",
    "q.m25#11.s0.e" to "Den tysta minoriteten är en återkommande figur i olycksutredningar. Att ha en tvekan och inte säga den betyder att laget beslutar på ofullständig information.\nKostnaden för att säga till är liten, kanske noll; kostnaden för tystnad kan vara mycket stor.",
    "q.m25#11.s1.p" to "Steg 2: efter diskussionen beslutar laget att fortsätta, men du känner dig fortfarande inte bra med det. Vad gör du nu?",
    "q.m25#11.s1.o0" to "Foga dig passivt och gör minimikraven",
    "q.m25#11.s1.o1" to "Säg din tvekan tydligt och bekräfta lagets vändvillkor och reträttplan",
    "q.m25#11.s1.o2" to "Gå ner ensam omedelbart",
    "q.m25#11.s1.o3" to "Säg inget mer men bär agg",
    "q.m25#11.s1.e" to "När beslutet är fattat återstår tre saker: lämna ett tydligt spår (jag var emot, eftersom…), bekräfta att reträttvillkoren är uttalade, och se till att du fortfarande vill och kan genomföra.\nEn tvekan är inte passivt fogande — när du sagt ditt gör du ändå din del ordentligt.",
    "q.m25#11.s2.p" to "Steg 3: det visar sig att din oro var berättigad och laget går ner tidigt. Vilket värde har den här erfarenheten?",
    "q.m25#11.s2.o0" to "Det bevisar att du är bättre än de andra",
    "q.m25#11.s2.o1" to "Det bekräftar att det är verkningsfullt att säga sin tvekan i förväg, och att det inte skadar relationerna",
    "q.m25#11.s2.o2" to "Det visar att du borde agera ensam i framtiden",
    "q.m25#11.s2.o3" to "Inte mycket, eftersom du inte nådde toppen",
    "q.m25#11.s2.e" to "Många oroar sig första gången de säger sin tvekan för att ses som någon som inte passar in. I verkligheten blir ett bra lag mer säkert på varandra av det, eftersom det bevisar att någon är villig att säga sanningen.\nHåll fast vid den erfarenheten; nästa gång säger du till tidigare.",
)
